def _mount_portal_static_assets() -> None:
    """Serve the portal's CSS, JS and self-hosted fonts from ``api/static``.

    The application serves them itself rather than through nginx so that the
    asset tree ships with the image and needs no production web-server change.
    The guard exists because the offline UI tests replace ``fastapi`` with a
    minimal stub that has no ``mount``; under the real framework a missing or
    unreadable asset directory must surface loudly, so nothing else is caught.
    """
    mount = getattr(app, "mount", None)
    if mount is None:
        return
    from fastapi.staticfiles import StaticFiles

    mount(
        portal_assets.STATIC_URL_PREFIX,
        StaticFiles(directory=str(portal_assets.STATIC_DIR)),
        name="static",
    )


_mount_portal_static_assets()

# ---------------- Auth ----------------
READ_TOKEN = os.getenv("API_READ_TOKEN", "")
WRITE_TOKEN = os.getenv("API_WRITE_TOKEN", "")
ARTIFACT_EXPLORER_SESSION_COOKIE = "artifact_explorer_session"
ARTIFACT_EXPLORER_SESSION_COOKIE_PATH = "/"
ARTIFACT_EXPLORER_SESSION_TTL_SECONDS = 12 * 60 * 60
_SESSION_SECRET_FROM_ENV = os.getenv("ARTIFACT_EXPLORER_SESSION_SECRET", "")
_EPHEMERAL_SESSION_SECRET = secrets.token_urlsafe(32)
_PASSWORD_HASH_ITERATIONS = 240_000
_PASSWORD_HASH_ALGORITHM = "pbkdf2_sha256"
UI_SESSION_NEXT_PATH_PREFIXES = ("/artifact-explorer", "/user", "/admin")

def require_token(auth: str | None, mode: Literal["read","write"]):
    if not auth or not auth.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Missing Bearer token")
    token = auth.split(" ", 1)[1].strip()
    if mode == "read" and token != READ_TOKEN:
        raise HTTPException(status_code=403, detail="Invalid read token")
    if mode == "write" and token != WRITE_TOKEN:
        raise HTTPException(status_code=403, detail="Invalid write token")


def _artifact_explorer_session_secret() -> str:
    return _SESSION_SECRET_FROM_ENV or _EPHEMERAL_SESSION_SECRET


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode((text + padding).encode("ascii"))


def hash_artifact_password(password: str, *, iterations: int = _PASSWORD_HASH_ITERATIONS) -> str:
    if not password:
        raise ValueError("password must not be empty")
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations)
    return f"{_PASSWORD_HASH_ALGORITHM}${iterations}${_b64url_encode(salt)}${_b64url_encode(digest)}"


def verify_artifact_password(password: str, stored_hash: str) -> bool:
    try:
        algorithm, iterations_text, salt_text, digest_text = str(stored_hash or "").split("$", 3)
        if algorithm != _PASSWORD_HASH_ALGORITHM:
            return False
        iterations = int(iterations_text)
        salt = _b64url_decode(salt_text)
        expected = _b64url_decode(digest_text)
    except Exception:
        return False
    actual = hashlib.pbkdf2_hmac("sha256", str(password or "").encode("utf-8"), salt, iterations)
    return hmac.compare_digest(actual, expected)


def _sign_artifact_session(payload: dict[str, Any]) -> str:
    payload_json = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    payload_b64 = _b64url_encode(payload_json)
    signature = hmac.new(
        _artifact_explorer_session_secret().encode("utf-8"),
        payload_b64.encode("ascii"),
        hashlib.sha256,
    ).hexdigest()
    return f"{payload_b64}.{signature}"


def _verify_artifact_session(token: str | None) -> dict[str, Any] | None:
    if not token or "." not in token:
        return None
    payload_b64, signature = token.rsplit(".", 1)
    expected = hmac.new(
        _artifact_explorer_session_secret().encode("utf-8"),
        payload_b64.encode("ascii"),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return None
    try:
        payload = json.loads(_b64url_decode(payload_b64).decode("utf-8"))
    except Exception:
        return None
    if int(payload.get("exp") or 0) < int(time.time()):
        return None
    return payload


def _safe_ui_next_path(next_path: str | None, *, default: str = "/artifact-explorer") -> str:
    candidate = str(next_path or "").strip()
    for prefix in UI_SESSION_NEXT_PATH_PREFIXES:
        if candidate == prefix or candidate.startswith(prefix + "/") or candidate.startswith(prefix + "?"):
            return candidate
    return default


def _artifact_explorer_login_url(next_path: str = "/artifact-explorer") -> str:
    safe_next = _safe_ui_next_path(next_path)
    return _artifact_explorer_url("/artifact-explorer/login", {"next": safe_next})


def _artifact_explorer_redirect(
    location: str,
    *,
    session_user_id: str | None = None,
    clear_session: bool = False,
) -> HTMLResponse:
    headers = {"Location": location}
    if session_user_id:
        token = _sign_artifact_session(
            {
                "user_id": str(session_user_id),
                "iat": int(time.time()),
                "exp": int(time.time()) + ARTIFACT_EXPLORER_SESSION_TTL_SECONDS,
            }
        )
        headers["Set-Cookie"] = (
            f"{ARTIFACT_EXPLORER_SESSION_COOKIE}={token}; "
            f"Max-Age={ARTIFACT_EXPLORER_SESSION_TTL_SECONDS}; Path={ARTIFACT_EXPLORER_SESSION_COOKIE_PATH}; "
            "HttpOnly; SameSite=Lax"
        )
    if clear_session:
        headers["Set-Cookie"] = (
            f"{ARTIFACT_EXPLORER_SESSION_COOKIE}=; Max-Age=0; Path={ARTIFACT_EXPLORER_SESSION_COOKIE_PATH}; "
            "HttpOnly; SameSite=Lax"
        )
    return HTMLResponse("", status_code=303, headers=headers)

