class PortalClientDatabaseConfigError(ValueError):
    pass


class PortalClientDatabaseConnectionError(RuntimeError):
    pass


def _connect_portal_client_database(database_name: str, *, statement_timeout: str = "15s", autocommit: bool = True):
    normalized_name = _normalize_portal_database_identifier(database_name)
    error = _validate_portal_client_database_name(normalized_name, required=True)
    if error:
        raise PortalClientDatabaseConfigError(error)
    try:
        conn = psycopg.connect(
            host=os.getenv("POSTGRES_HOST", "127.0.0.1"),
            port=os.getenv("POSTGRES_PORT", "5432"),
            dbname=normalized_name,
            user=os.getenv("POSTGRES_USER", "loguser"),
            password=os.getenv("POSTGRES_PASSWORD", ""),
            row_factory=dict_row,
            autocommit=autocommit,
        )
        conn = set_pg_session_timezone(conn)
        with conn.cursor() as cur:
            cur.execute("SELECT set_config('statement_timeout', %s, false)", (statement_timeout,))
            cur.execute("SET default_transaction_read_only = on")
        return conn
    except PortalClientDatabaseConfigError:
        raise
    except Exception as exc:
        print(f"portal client database connection failed: {type(exc).__name__}: database_name={normalized_name}")
        raise PortalClientDatabaseConnectionError("Client database is not available or the portal role lacks access.") from exc

