PORTAL_CLIENT_CODE_PATTERN = r"^[A-Z0-9_:-]{2,64}$"


def _normalize_portal_client_code(client_code: str | None) -> str:
    return str(client_code or "").strip().upper()


def _validate_portal_client_code(client_code: str) -> str | None:
    if not client_code:
        return "Client code is required."
    if not re.fullmatch(PORTAL_CLIENT_CODE_PATTERN, client_code):
        return "Client code must be 2-64 characters and use only A-Z, 0-9, underscore, colon, or hyphen."
    return None


def _validate_portal_client_database_name(database_name: str | None, *, required: bool = False) -> str | None:
    text = _normalize_portal_database_identifier(database_name)
    if not text:
        return "Client database name is required." if required else None
    if not PORTAL_DATABASE_IDENTIFIER_RE.fullmatch(text):
        return "Client database name must be a single PostgreSQL database name: letters, numbers, and underscores only, starting with a letter or underscore."
    return None


def _portal_client_database_name(client_code: str) -> str:
    normalized_code = _normalize_portal_client_code(client_code)
    if not normalized_code:
        raise PortalClientDatabaseConfigError("Select a portal client before loading database metadata.")
    client = _get_portal_client(normalized_code)
    if not client:
        raise PortalClientDatabaseConfigError("Client not found.")
    if not client.get("is_active"):
        raise PortalClientDatabaseConfigError("Client is inactive.")
    database_name = _normalize_portal_database_identifier(client.get("database_name"))
    error = _validate_portal_client_database_name(database_name, required=True)
    if error:
        if not database_name:
            raise PortalClientDatabaseConfigError("This client does not have a database name configured. Set the client database name before registering datasets.")
        raise PortalClientDatabaseConfigError(error)
    return database_name


def _portal_dataset_client_database_name(dataset: dict) -> str:
    database_name = _normalize_portal_database_identifier(dataset.get("client_database_name"))
    if database_name:
        error = _validate_portal_client_database_name(database_name, required=True)
        if error:
            raise PortalClientDatabaseConfigError(error)
        return database_name
    return _portal_client_database_name(str(dataset.get("client_code") or ""))


def _portal_client_exists(client_code: str) -> bool:
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM portal_clients WHERE client_code = %s LIMIT 1", (client_code,))
            return cur.fetchone() is not None


def _list_portal_clients() -> list[dict]:
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT pc.client_code, pc.display_name, pc.is_active, pc.description, pc.database_name,
                       pc.created_at, pc.updated_at,
                       count(puc.user_id) AS assigned_users
                FROM portal_clients pc
                LEFT JOIN portal_user_clients puc ON puc.client_code = pc.client_code
                GROUP BY pc.client_code
                ORDER BY pc.is_active DESC, pc.client_code ASC
                """
            )
            rows = cur.fetchall()
    clients = _rows_to_dicts(rows)
    for client in clients:
        client["assigned_users"] = int(client.get("assigned_users") or 0)
    return clients


def _get_portal_client(client_code: str) -> dict | None:
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT client_code, display_name, is_active, description, database_name, created_at, updated_at
                FROM portal_clients
                WHERE client_code = %s
                """,
                (client_code,),
            )
            row = cur.fetchone()
    return dict(row) if row else None


def _create_portal_client(*, client_code: str, display_name: str, description: str | None, database_name: str | None, is_active: bool) -> str:
    normalized_code = _normalize_portal_client_code(client_code)
    error = _validate_portal_client_code(normalized_code)
    if error:
        raise ValueError(error)
    normalized_name = str(display_name or "").strip()
    if not normalized_name:
        raise ValueError("Display name is required.")
    database_name_text = _normalize_portal_database_identifier(database_name)
    database_error = _validate_portal_client_database_name(database_name_text)
    if database_error:
        raise ValueError(database_error)
    if _portal_client_exists(normalized_code):
        raise ValueError("Client code already exists.")
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO portal_clients (client_code, display_name, description, database_name, is_active, updated_at)
                VALUES (%s, %s, %s, %s, %s, now())
                """,
                (normalized_code, normalized_name, str(description or "").strip() or None, database_name_text or None, is_active),
            )
    return normalized_code


def _update_portal_client(*, client_code: str, display_name: str, description: str | None, database_name: str | None, is_active: bool) -> str | None:
    if not _get_portal_client(client_code):
        return "Client not found."
    normalized_name = str(display_name or "").strip()
    if not normalized_name:
        return "Display name is required."
    database_name_text = _normalize_portal_database_identifier(database_name)
    database_error = _validate_portal_client_database_name(database_name_text)
    if database_error:
        return database_error
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE portal_clients
                SET display_name = %s,
                    description = %s,
                    database_name = %s,
                    is_active = %s,
                    updated_at = now()
                WHERE client_code = %s
                """,
                (normalized_name, str(description or "").strip() or None, database_name_text or None, is_active, client_code),
            )
    return None


def _list_portal_user_client_dashboard_rows() -> list[dict]:
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT u.user_id, u.username, u.display_name, u.is_active, u.is_admin,
                       COALESCE(
                         jsonb_agg(
                           jsonb_build_object(
                             'client_code', pc.client_code,
                             'display_name', pc.display_name,
                             'is_active', pc.is_active,
                             'can_view_database', puc.can_view_database,
                             'can_view_reports', puc.can_view_reports,
                             'can_export_database', puc.can_export_database
                           )
                           ORDER BY pc.client_code
                         ) FILTER (WHERE pc.client_code IS NOT NULL),
                         '[]'::jsonb
                       ) AS clients
                FROM artifact_users u
                LEFT JOIN portal_user_clients puc ON puc.user_id = u.user_id
                LEFT JOIN portal_clients pc ON pc.client_code = puc.client_code
                GROUP BY u.user_id
                ORDER BY lower(u.username) ASC
                """
            )
            rows = cur.fetchall()
    users = _rows_to_dicts(rows)
    for portal_user in users:
        portal_user["user_id"] = str(portal_user.get("user_id"))
        portal_user["clients"] = _json_roles(portal_user.get("clients"))
    return users


def _get_portal_user_client_assignments(user_id: str) -> dict | None:
    target_user = _get_portal_user(user_id)
    if not target_user:
        return None
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT pc.client_code, pc.display_name, pc.description, pc.is_active,
                       puc.can_view_database, puc.can_view_reports, puc.can_export_database,
                       puc.granted_at, puc.updated_at,
                       gu.username AS granted_by_username
                FROM portal_user_clients puc
                JOIN portal_clients pc ON pc.client_code = puc.client_code
                LEFT JOIN artifact_users gu ON gu.user_id = puc.granted_by
                WHERE puc.user_id = %s
                ORDER BY pc.client_code ASC
                """,
                (user_id,),
            )
            assigned = _rows_to_dicts(cur.fetchall())
            cur.execute(
                """
                SELECT pc.client_code, pc.display_name, pc.description, pc.is_active
                FROM portal_clients pc
                WHERE pc.is_active IS TRUE
                  AND NOT EXISTS (
                    SELECT 1 FROM portal_user_clients puc
                    WHERE puc.user_id = %s AND puc.client_code = pc.client_code
                  )
                ORDER BY pc.client_code ASC
                """,
                (user_id,),
            )
            available = _rows_to_dicts(cur.fetchall())
    return {"user": target_user, "assigned": assigned, "available": available}


