def _portal_group_row(row: dict) -> dict:
    return {
        "group_id": str(row.get("group_id")),
        "group_name": row.get("group_name"),
        "description": row.get("description"),
        "is_active": bool(row.get("is_active")),
        "created_by": str(row.get("created_by")) if row.get("created_by") else None,
        "updated_by": str(row.get("updated_by")) if row.get("updated_by") else None,
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
        "users_count": int(row.get("users_count") or 0),
        "clients_count": int(row.get("clients_count") or 0),
        "report_folders_count": int(row.get("report_folders_count") or 0),
        "datasets_count": int(row.get("datasets_count") or 0),
    }


def _normalize_portal_group_name(group_name: str | None) -> str:
    return str(group_name or "").strip()


def _portal_group_name_exists(group_name: str, *, exclude_group_id: str | None = None) -> bool:
    normalized = _normalize_portal_group_name(group_name)
    if not normalized:
        return False
    with db_conn() as conn:
        with conn.cursor() as cur:
            if exclude_group_id:
                cur.execute(
                    "SELECT 1 FROM portal_groups WHERE lower(group_name) = lower(%s) AND group_id <> %s LIMIT 1",
                    (normalized, exclude_group_id),
                )
            else:
                cur.execute("SELECT 1 FROM portal_groups WHERE lower(group_name) = lower(%s) LIMIT 1", (normalized,))
            return cur.fetchone() is not None


def _list_portal_groups() -> list[dict]:
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT pg.group_id, pg.group_name, pg.description, pg.is_active,
                       pg.created_by, pg.updated_by, pg.created_at, pg.updated_at,
                       count(DISTINCT pgu.user_id) AS users_count,
                       count(DISTINCT pgc.client_code) AS clients_count,
                       count(DISTINCT prfg.folder_id) AS report_folders_count,
                       count(DISTINCT pddg.dataset_id) AS datasets_count
                FROM portal_groups pg
                LEFT JOIN portal_group_users pgu ON pgu.group_id = pg.group_id
                LEFT JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                LEFT JOIN portal_report_folder_groups prfg ON prfg.group_id = pg.group_id
                LEFT JOIN portal_database_dataset_groups pddg ON pddg.group_id = pg.group_id
                GROUP BY pg.group_id
                ORDER BY pg.is_active DESC, lower(pg.group_name) ASC
                """
            )
            rows = cur.fetchall()
    return [_portal_group_row(row) for row in _rows_to_dicts(rows)]


def _list_active_portal_groups() -> list[dict]:
    return [group for group in _list_portal_groups() if group.get("is_active")]


def _get_portal_group(group_id: str) -> dict | None:
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT pg.group_id, pg.group_name, pg.description, pg.is_active,
                       pg.created_by, pg.updated_by, pg.created_at, pg.updated_at,
                       (SELECT count(*) FROM portal_group_users pgu WHERE pgu.group_id = pg.group_id) AS users_count,
                       (SELECT count(*) FROM portal_group_clients pgc WHERE pgc.group_id = pg.group_id) AS clients_count,
                       (SELECT count(*) FROM portal_report_folder_groups prfg WHERE prfg.group_id = pg.group_id) AS report_folders_count,
                       (SELECT count(*) FROM portal_database_dataset_groups pddg WHERE pddg.group_id = pg.group_id) AS datasets_count
                FROM portal_groups pg
                WHERE pg.group_id = %s
                """,
                (group_id,),
            )
            row = cur.fetchone()
    return _portal_group_row(row) if row else None


def _create_portal_group(*, group_name: str, description: str | None, is_active: bool, actor_user_id: str | None) -> str:
    normalized = _normalize_portal_group_name(group_name)
    if not normalized:
        raise ValueError("Group name is required.")
    if _portal_group_name_exists(normalized):
        raise ValueError("Group name already exists.")
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO portal_groups (group_name, description, is_active, created_by, updated_by, updated_at)
                VALUES (%s, %s, %s, %s, %s, now())
                RETURNING group_id
                """,
                (normalized, str(description or "").strip() or None, is_active, actor_user_id, actor_user_id),
            )
            row = cur.fetchone()
    return str(row["group_id"])


def _update_portal_group(*, group_id: str, group_name: str, description: str | None, is_active: bool, actor_user_id: str | None) -> str | None:
    if not _get_portal_group(group_id):
        return "Group not found."
    normalized = _normalize_portal_group_name(group_name)
    if not normalized:
        return "Group name is required."
    if _portal_group_name_exists(normalized, exclude_group_id=group_id):
        return "Group name already exists."
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE portal_groups
                SET group_name = %s,
                    description = %s,
                    is_active = %s,
                    updated_by = %s,
                    updated_at = now()
                WHERE group_id = %s
                """,
                (normalized, str(description or "").strip() or None, is_active, actor_user_id, group_id),
            )
    return None


