def _get_portal_group_detail_data(group_id: str) -> dict | None:
    group = _get_portal_group(group_id)
    if not group:
        return None
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT prf.folder_id, prf.folder_name, prf.client_code, pc.display_name AS client_display_name, prf.is_active
                FROM portal_report_folder_groups prfg
                JOIN portal_report_folders prf ON prf.folder_id = prfg.folder_id
                JOIN portal_clients pc ON pc.client_code = prf.client_code
                WHERE prfg.group_id = %s
                ORDER BY pc.display_name ASC, prf.folder_name ASC
                """,
                (group_id,),
            )
            folders = _rows_to_dicts(cur.fetchall())
            cur.execute(
                """
                SELECT pdd.dataset_id, pdd.dataset_name, pdd.client_code, pc.display_name AS client_display_name, pdd.is_active,
                       pddg.can_view_rows, pddg.can_filter_rows, pddg.can_export_rows
                FROM portal_database_dataset_groups pddg
                JOIN portal_database_datasets pdd ON pdd.dataset_id = pddg.dataset_id
                JOIN portal_clients pc ON pc.client_code = pdd.client_code
                WHERE pddg.group_id = %s
                ORDER BY pc.display_name ASC, pdd.dataset_name ASC
                """,
                (group_id,),
            )
            datasets = _rows_to_dicts(cur.fetchall())
    for folder in folders:
        folder["folder_id"] = str(folder.get("folder_id"))
    for dataset in datasets:
        dataset["dataset_id"] = str(dataset.get("dataset_id"))
    return {
        "group": group,
        "assigned_users": _list_portal_group_users(group_id),
        "available_users": _list_available_portal_group_users(group_id),
        "assigned_clients": _list_portal_group_clients(group_id),
        "available_clients": _list_available_portal_group_clients(group_id),
        "report_folders": folders,
        "database_datasets": datasets,
    }


