def _count_effective_report_folders_for_user(user_id: str) -> int:
    """Count of report folders visible to a user for the admin summary (Phase 2G).

    Centralizes the previously inline summary CTE verbatim, preserving its exact
    count semantics: ``count(DISTINCT folder_id)`` over active folders of active
    clients where the folder is assigned to the user directly OR via an active
    group, and the user has effective client ``can_view_reports`` (direct OR
    active group). Distinct dedup means a folder reached by both a direct and a
    group assignment is counted once. No folder-level capability flag
    (can_preview/can_download) gates this count. This matches the inline count
    exactly (it does not reuse the dataset set helper's stricter gating).
    """
    uid = str(user_id or "")
    if not uid:
        return 0
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                WITH effective_client_access AS (
                  SELECT user_id, client_code, bool_or(can_view_reports) AS can_view_reports
                  FROM (
                    SELECT puc.user_id, puc.client_code, puc.can_view_reports
                    FROM portal_user_clients puc
                    UNION ALL
                    SELECT pgu.user_id, pgc.client_code, pgc.can_view_reports
                    FROM portal_group_users pgu
                    JOIN portal_groups pg ON pg.group_id = pgu.group_id AND pg.is_active IS TRUE
                    JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                  ) grants
                  GROUP BY user_id, client_code
                ),
                effective_folder_access AS (
                  SELECT folder_id FROM portal_report_folder_users WHERE user_id = %s
                  UNION
                  SELECT prfg.folder_id
                  FROM portal_report_folder_groups prfg
                  JOIN portal_group_users pgu ON pgu.group_id = prfg.group_id AND pgu.user_id = %s
                  JOIN portal_groups pg ON pg.group_id = prfg.group_id AND pg.is_active IS TRUE
                )
                SELECT count(DISTINCT prf.folder_id) AS count
                FROM portal_report_folders prf
                JOIN effective_folder_access efa ON efa.folder_id = prf.folder_id
                JOIN effective_client_access eca ON eca.user_id = %s AND eca.client_code = prf.client_code
                JOIN portal_clients pc ON pc.client_code = prf.client_code AND pc.is_active IS TRUE
                WHERE prf.is_active IS TRUE
                  AND eca.can_view_reports IS TRUE
                """,
                (uid, uid, uid),
            )
            return int((cur.fetchone() or {}).get("count") or 0)


def _count_effective_database_datasets_for_user(user_id: str) -> int:
    """Count of database datasets visible to a user for the admin summary (Phase 2G).

    Centralizes the previously inline summary CTE verbatim, preserving its exact
    count semantics: ``count(DISTINCT dataset_id)`` over active datasets of active
    clients where the dataset is assigned to the user directly OR via an active
    group, and the user has effective client ``can_view_database`` (direct OR
    active group). Distinct dedup prevents direct+group overcount.

    IMPORTANT: this count gates on assignment existence only and intentionally
    does NOT require dataset ``can_view_rows`` — unlike
    ``_list_effective_dataset_access_for_user`` (which filters
    ``can_view_rows IS TRUE``). Reusing that set helper here would change the
    count, so the count SQL is centralized verbatim instead.
    """
    uid = str(user_id or "")
    if not uid:
        return 0
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                WITH effective_client_access AS (
                  SELECT user_id, client_code, bool_or(can_view_database) AS can_view_database
                  FROM (
                    SELECT puc.user_id, puc.client_code, puc.can_view_database
                    FROM portal_user_clients puc
                    UNION ALL
                    SELECT pgu.user_id, pgc.client_code, pgc.can_view_database
                    FROM portal_group_users pgu
                    JOIN portal_groups pg ON pg.group_id = pgu.group_id AND pg.is_active IS TRUE
                    JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                  ) grants
                  GROUP BY user_id, client_code
                ),
                effective_dataset_access AS (
                  SELECT dataset_id FROM portal_database_dataset_users WHERE user_id = %s
                  UNION
                  SELECT pddg.dataset_id
                  FROM portal_database_dataset_groups pddg
                  JOIN portal_group_users pgu ON pgu.group_id = pddg.group_id AND pgu.user_id = %s
                  JOIN portal_groups pg ON pg.group_id = pddg.group_id AND pg.is_active IS TRUE
                )
                SELECT count(DISTINCT pdd.dataset_id) AS count
                FROM portal_database_datasets pdd
                JOIN effective_dataset_access eda ON eda.dataset_id = pdd.dataset_id
                JOIN effective_client_access eca ON eca.user_id = %s AND eca.client_code = pdd.client_code
                JOIN portal_clients pc ON pc.client_code = pdd.client_code AND pc.is_active IS TRUE
                WHERE pdd.is_active IS TRUE
                  AND eca.can_view_database IS TRUE
                """,
                (uid, uid, uid),
            )
            return int((cur.fetchone() or {}).get("count") or 0)


def _portal_effective_access_summary_for_user(user_id: str) -> dict:
    # Per-source client lists (direct / active-group derived) come from the
    # centralized per-source helper (Phase 2F). It preserves the exact gating
    # (active client + (can_view_database OR can_view_reports)), non-deduplicated
    # group rows, and client_code ordering of the previous inline UNION. We map
    # back to the summary's original {client_code, display_name, source} shape so
    # the rendered output is unchanged. Folder/dataset counts below remain inline
    # (deferred — see ops/reports/platform_access_helper_rollout_phase2f.md).
    sources = _list_client_access_sources_for_user(user_id)
    direct_clients = [
        {"client_code": c.get("client_code"), "display_name": c.get("client_name"), "source": "direct"}
        for c in sources.get("direct_clients", [])
    ]
    group_clients = [
        {"client_code": c.get("client_code"), "display_name": c.get("client_name"), "source": "group"}
        for c in sources.get("group_clients", [])
    ]
    # Folder/dataset counts come from dedicated count helpers (Phase 2G). The SQL
    # is centralized verbatim from the previously inline CTEs, so counts are
    # byte-identical. See ops/reports/platform_access_helper_rollout_phase2g.md.
    return {
        "groups": _list_portal_user_groups(user_id),
        "direct_clients": direct_clients,
        "group_clients": group_clients,
        "report_folder_count": _count_effective_report_folders_for_user(user_id),
        "database_dataset_count": _count_effective_database_datasets_for_user(user_id),
    }


