def _portal_user_client_access_response(admin_user: dict, user_id: str, *, error: str | None = None, status_code: int = 200) -> HTMLResponse:
    data = _get_portal_user_client_assignments(user_id)
    if not data:
        return _portal_user_not_found_response(admin_user)
    target_user = data["user"]
    assigned = data["assigned"]
    available = data["available"]
    assigned_rows = []
    for assignment in assigned:
        code = str(assignment.get("client_code") or "")
        assigned_rows.append(
            '<tr>'
            f'<td><strong>{_html(code)}</strong><br><span class="portal-muted">{_html(assignment.get("display_name"))}</span></td>'
            f'<td>{_portal_status_badge(bool(assignment.get("is_active")))}</td>'
            '<td>'
            f'<form method="post" action="/admin/client-access/users/{_html(user_id)}/clients/{_html(code)}/permissions" class="portal-form">'
            '<label class="portal-checkbox"><input type="checkbox" name="can_view_database" value="1" '
            + ('checked' if assignment.get("can_view_database") else '')
            + '> <span>Database</span></label>'
            '<label class="portal-checkbox"><input type="checkbox" name="can_view_reports" value="1" '
            + ('checked' if assignment.get("can_view_reports") else '')
            + '> <span>Reports</span></label>'
            '<label class="portal-checkbox"><input type="checkbox" name="can_export_database" value="1" '
            + ('checked' if assignment.get("can_export_database") else '')
            + '> <span>Export database</span></label>'
            '<div class="portal-actions"><button class="portal-button secondary" type="submit">Save permissions</button></div></form>'
            '</td>'
            f'<td><form method="post" action="/admin/client-access/users/{_html(user_id)}/clients/{_html(code)}/remove"><button class="portal-button secondary" type="submit">Remove</button></form></td>'
            '</tr>'
        )
    assigned_table = (
        '<div class="portal-table-wrap"><table class="portal-table"><thead><tr>'
        '<th>Client</th><th>Active</th><th>Permissions</th><th>Actions</th>'
        '</tr></thead><tbody>' + ''.join(assigned_rows) + '</tbody></table></div>'
        if assigned_rows
        else '<div class="portal-callout">No clients assigned to this user.</div>'
    )
    options = ''.join(
        f'<option value="{_html(client.get("client_code"))}">{_html(client.get("client_code"))} - {_html(client.get("display_name"))}</option>'
        for client in available
    )
    assign_form = (
        f'<form class="portal-form" method="post" action="/admin/client-access/users/{_html(user_id)}/clients">'
        f'<div class="portal-field"><label for="client_code">Available active clients</label><select id="client_code" name="client_code" required>{options}</select></div>'
        '<div class="portal-actions"><button class="portal-button" type="submit">Assign client</button></div></form>'
        if available
        else '<div class="portal-callout">No available active clients to assign.</div>'
    )
    body = (
        _portal_message_html(error)
        + '<section class="portal-panel"><h2>User summary</h2>'
        f'<p class="portal-muted">User: <strong>{_html(target_user.get("username"))}</strong> {_portal_bool_badge(bool(target_user.get("is_admin")), "Admin", "Standard")}</p>'
        '<p class="portal-muted">Client access controls Reports Explorer and Client Database Explorer visibility. It does not grant Artifact Explorer access.</p>'
        '</section>'
        '<section class="portal-panel"><h2>Assigned clients</h2>'
        + assigned_table
        + '</section>'
        '<section class="portal-panel"><h2>Assign client</h2>'
        + assign_form
        + '</section>'
    )
    return _portal_layout(
        f'Client access for {target_user.get("username")}',
        body,
        user=admin_user,
        portal_label="Admin Portal",
        active_key="client-access",
        nav_items=_admin_portal_nav(),
        description="Assign portal clients and permission flags for this local UI user.",
        status_code=status_code,
    )


