# --------- Set-based effective-access helpers (Phase 2C) ---------
# These answer effective-access questions for MANY resources in a single query,
# so set/list/preview call sites can avoid per-resource N+1 helper calls. They
# preserve the exact additive direct-OR-active-group semantics (active groups
# only) used by the per-resource wrappers and the previously inline CTEs. Only
# `_list_effective_dataset_access_for_user` is wired into a call site in this
# phase (the `/user/database` list); the client helper is added as parity-tested
# infrastructure for later de-duplication.


def _list_effective_client_access_for_user(user_id: str, client_ids: list[str] | None = None) -> dict:
    """Set-based effective per-client capabilities for one user across clients.

    Returns a mapping keyed by ``client_code``. Mirrors the additive
    direct-OR-active-group semantics of the inline ``effective_client_access``
    CTE and the per-client ``_get_effective_client_access_for_user`` wrapper,
    computed for all (or the requested) clients in a single query to avoid N+1.
    Only clients the user has a grant on (direct or via active group) are
    included, exactly as the inline CTE produces. ``client_ids`` only narrows the
    result set; it never relaxes any gate.
    """
    result: dict[str, dict] = {}
    uid = str(user_id or "")
    if not uid:
        return result
    params: list = [uid]
    filter_sql = ""
    if client_ids is not None:
        codes = [str(c) for c in client_ids]
        if not codes:
            return result
        filter_sql = " AND eca.client_code = ANY(%s)"
        params.append(codes)
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                WITH effective_client_access AS (
                  SELECT user_id, client_code,
                         bool_or(can_view_reports) AS can_view_reports,
                         bool_or(can_view_database) AS can_view_database,
                         bool_or(can_export_database) AS can_export_database,
                         bool_or((NOT is_group) AND (can_view_reports OR can_view_database OR can_export_database)) AS source_direct,
                         bool_or(is_group AND (can_view_reports OR can_view_database OR can_export_database)) AS source_group
                  FROM (
                    SELECT puc.user_id, puc.client_code, puc.can_view_reports, puc.can_view_database, puc.can_export_database, FALSE AS is_group
                    FROM portal_user_clients puc
                    UNION ALL
                    SELECT pgu.user_id, pgc.client_code, pgc.can_view_reports, pgc.can_view_database, pgc.can_export_database, TRUE AS is_group
                    FROM portal_group_users pgu
                    JOIN portal_groups pg ON pg.group_id = pgu.group_id AND pg.is_active IS TRUE
                    JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                  ) grants
                  GROUP BY user_id, client_code
                )
                SELECT eca.client_code, pc.display_name AS client_name, pc.is_active AS client_active,
                       eca.can_view_reports, eca.can_view_database, eca.can_export_database,
                       eca.source_direct, eca.source_group
                FROM effective_client_access eca
                JOIN portal_clients pc ON pc.client_code = eca.client_code
                WHERE eca.user_id = %s{filter_sql}
                ORDER BY pc.display_name ASC, eca.client_code ASC
                """,
                tuple(params),
            )
            for row in cur.fetchall():
                code = str(row.get("client_code") or "")
                result[code] = {
                    "client_id": code,
                    "client_code": code,
                    "client_name": row.get("client_name"),
                    "client_active": bool(row.get("client_active")),
                    "can_view_reports": bool(row.get("can_view_reports")),
                    "can_view_database": bool(row.get("can_view_database")),
                    "can_export_database": bool(row.get("can_export_database")),
                    "source_direct": bool(row.get("source_direct")),
                    "source_group": bool(row.get("source_group")),
                }
    return result


def _list_client_access_sources_for_user(user_id: str, client_ids: list[str] | None = None) -> dict:
    """Per-source client access for one user (Phase 2F).

    Returns the per-source, non-deduplicated client lists the admin effective
    access summary displays, plus a derived merged/effective view:

    - ``direct_clients``: one row per active client the user holds a direct
      grant on (``portal_user_clients``), gated on the client being active and
      ``(can_view_database OR can_view_reports)`` — exactly as the summary's
      direct branch.
    - ``group_clients``: one row per (active group -> active client) grant
      (``portal_group_users`` + active ``portal_groups`` + ``portal_group_clients``),
      gated on ``(can_view_database OR can_view_reports)``. NOT deduplicated
      across groups, matching the summary.
    - ``effective_clients``: additive direct-OR-active-group merge of the same
      rows, keyed by ``client_code`` with ``source_direct`` / ``source_group``
      flags. Provided for reuse; the summary does not depend on it.

    Unlike ``_list_effective_client_access_for_user`` (merged, includes
    export-only and inactive clients), this helper reproduces the summary's
    active-client + view-gated, per-source semantics. ``client_ids`` only
    narrows the result; it never relaxes any gate.
    """
    empty = {"direct_clients": [], "group_clients": [], "effective_clients": {}}
    uid = str(user_id or "")
    if not uid:
        return empty
    direct_params: list = [uid]
    group_params: list = [uid]
    direct_filter = ""
    group_filter = ""
    if client_ids is not None:
        codes = [str(c) for c in client_ids]
        if not codes:
            return empty
        direct_filter = " AND pc.client_code = ANY(%s)"
        group_filter = " AND pc.client_code = ANY(%s)"
        direct_params.append(codes)
        group_params.append(codes)
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT pc.client_code, pc.display_name,
                       puc.can_view_reports, puc.can_view_database, puc.can_export_database
                FROM portal_user_clients puc
                JOIN portal_clients pc ON pc.client_code = puc.client_code
                WHERE puc.user_id = %s AND pc.is_active IS TRUE
                  AND (puc.can_view_database IS TRUE OR puc.can_view_reports IS TRUE){direct_filter}
                ORDER BY pc.client_code ASC
                """,
                tuple(direct_params),
            )
            direct_rows = _rows_to_dicts(cur.fetchall())
            cur.execute(
                f"""
                SELECT pc.client_code, pc.display_name, pg.group_id, pg.group_name,
                       pgc.can_view_reports, pgc.can_view_database, pgc.can_export_database
                FROM portal_group_users pgu
                JOIN portal_groups pg ON pg.group_id = pgu.group_id AND pg.is_active IS TRUE
                JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                JOIN portal_clients pc ON pc.client_code = pgc.client_code AND pc.is_active IS TRUE
                WHERE pgu.user_id = %s
                  AND (pgc.can_view_database IS TRUE OR pgc.can_view_reports IS TRUE){group_filter}
                ORDER BY pc.client_code ASC, pg.group_name ASC
                """,
                tuple(group_params),
            )
            group_rows = _rows_to_dicts(cur.fetchall())
    direct_clients: list[dict] = []
    for row in direct_rows:
        code = str(row.get("client_code") or "")
        direct_clients.append({
            "client_id": code,
            "client_code": code,
            "client_name": row.get("display_name"),
            "can_view_reports": bool(row.get("can_view_reports")),
            "can_view_database": bool(row.get("can_view_database")),
            "can_export_database": bool(row.get("can_export_database")),
            "source": "direct",
        })
    group_clients: list[dict] = []
    for row in group_rows:
        code = str(row.get("client_code") or "")
        group_clients.append({
            "client_id": code,
            "client_code": code,
            "client_name": row.get("display_name"),
            "group_id": str(row.get("group_id")) if row.get("group_id") else None,
            "group_name": row.get("group_name"),
            "can_view_reports": bool(row.get("can_view_reports")),
            "can_view_database": bool(row.get("can_view_database")),
            "can_export_database": bool(row.get("can_export_database")),
            "source": "group",
        })
    effective: dict[str, dict] = {}
    for row in direct_clients + group_clients:
        code = row["client_code"]
        entry = effective.setdefault(code, {
            "client_id": code,
            "client_code": code,
            "client_name": row.get("client_name"),
            "can_view_reports": False,
            "can_view_database": False,
            "can_export_database": False,
            "source_direct": False,
            "source_group": False,
        })
        entry["can_view_reports"] = entry["can_view_reports"] or row["can_view_reports"]
        entry["can_view_database"] = entry["can_view_database"] or row["can_view_database"]
        entry["can_export_database"] = entry["can_export_database"] or row["can_export_database"]
        if row["source"] == "direct":
            entry["source_direct"] = True
        else:
            entry["source_group"] = True
    return {
        "direct_clients": direct_clients,
        "group_clients": group_clients,
        "effective_clients": effective,
    }


def _list_effective_dataset_access_for_user(
    user_id: str,
    dataset_ids: list[str] | None = None,
    client_ids: list[str] | None = None,
) -> dict:
    """Set-based effective dataset access for one user across datasets.

    Single source of truth for user-facing database dataset visibility. Returns
    an ordered mapping keyed by ``dataset_id`` (display order: client name then
    dataset name); each value is the full dataset metadata row plus effective
    capability flags and direct/group source breakdown.

    Behavior is identical to the previously inline query in
    ``_list_accessible_portal_database_datasets_for_user``: a dataset is included
    only when the user has effective dataset ``can_view_rows`` (direct OR active
    group), the dataset and client are active, and the user has effective client
    ``can_view_database`` (direct OR active group). The optional ``dataset_ids`` /
    ``client_ids`` arguments only narrow the result; they never relax these gates.
    """
    result: dict[str, dict] = {}
    uid = str(user_id or "")
    if not uid:
        return result
    params: list = [uid, uid, uid]
    extra_sql = ""
    if dataset_ids is not None:
        ids = [str(d) for d in dataset_ids]
        if not ids:
            return result
        extra_sql += " AND pdd.dataset_id = ANY(%s)"
        params.append(ids)
    if client_ids is not None:
        codes = [str(c) for c in client_ids]
        if not codes:
            return result
        extra_sql += " AND pdd.client_code = ANY(%s)"
        params.append(codes)
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                WITH effective_client_access AS (
                  SELECT user_id, client_code,
                         bool_or(can_view_database) AS can_view_database,
                         bool_or(can_view_reports) AS can_view_reports,
                         bool_or(can_export_database) AS can_export_database
                  FROM (
                    SELECT puc.user_id, puc.client_code, puc.can_view_database, puc.can_view_reports, puc.can_export_database
                    FROM portal_user_clients puc
                    UNION ALL
                    SELECT pgu.user_id, pgc.client_code, pgc.can_view_database, pgc.can_view_reports, pgc.can_export_database
                    FROM portal_group_users pgu
                    JOIN portal_groups pg ON pg.group_id = pgu.group_id AND pg.is_active IS TRUE
                    JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                  ) grants
                  GROUP BY user_id, client_code
                ),
                effective_dataset_access AS (
                  SELECT dataset_id,
                         bool_or(can_view_rows) AS can_view_rows,
                         bool_or(can_filter_rows) AS can_filter_rows,
                         bool_or(can_export_rows) AS can_export_rows,
                         bool_or((NOT is_group) AND (can_view_rows OR can_filter_rows OR can_export_rows)) AS source_direct,
                         bool_or(is_group AND (can_view_rows OR can_filter_rows OR can_export_rows)) AS source_group
                  FROM (
                    SELECT pddu.dataset_id, pddu.can_view_rows, pddu.can_filter_rows, pddu.can_export_rows, FALSE AS is_group
                    FROM portal_database_dataset_users pddu
                    WHERE pddu.user_id = %s
                    UNION ALL
                    SELECT pddg.dataset_id, pddg.can_view_rows, pddg.can_filter_rows, pddg.can_export_rows, TRUE AS is_group
                    FROM portal_database_dataset_groups pddg
                    JOIN portal_group_users pgu ON pgu.group_id = pddg.group_id AND pgu.user_id = %s
                    JOIN portal_groups pg ON pg.group_id = pddg.group_id AND pg.is_active IS TRUE
                  ) grants
                  GROUP BY dataset_id
                )
                SELECT pdd.dataset_id, pdd.client_code, pc.display_name AS client_display_name,
                       pc.database_name AS client_database_name,
                       pdd.dataset_name, pdd.slug, pdd.description, pdd.schema_name, pdd.table_name,
                       pdd.default_date_column, pdd.is_active, pdd.created_by, pdd.created_at, pdd.updated_by, pdd.updated_at,
                       eda.can_view_rows, eda.can_filter_rows, eda.can_export_rows,
                       eda.source_direct, eda.source_group,
                       count(pddc.column_name) FILTER (WHERE pddc.is_visible IS TRUE AND pddc.is_row_identifier IS NOT TRUE) AS visible_columns,
                       1 AS assigned_users
                FROM portal_database_datasets pdd
                JOIN effective_dataset_access eda ON eda.dataset_id = pdd.dataset_id
                JOIN effective_client_access eca ON eca.user_id = %s AND eca.client_code = pdd.client_code
                JOIN portal_clients pc ON pc.client_code = pdd.client_code
                LEFT JOIN portal_database_dataset_columns pddc ON pddc.dataset_id = pdd.dataset_id
                WHERE eda.can_view_rows IS TRUE
                  AND pdd.is_active IS TRUE
                  AND pc.is_active IS TRUE
                  AND eca.can_view_database IS TRUE{extra_sql}
                GROUP BY pdd.dataset_id, pc.display_name, pc.database_name, eda.can_view_rows, eda.can_filter_rows, eda.can_export_rows, eda.source_direct, eda.source_group
                ORDER BY pc.display_name ASC, pdd.dataset_name ASC
                """,
                tuple(params),
            )
            for row in cur.fetchall():
                result[str(row.get("dataset_id"))] = row
    return result


def _list_accessible_portal_database_datasets_for_user(user_id: str) -> list[dict]:
    if not user_id:
        return []
    datasets = _list_effective_dataset_access_for_user(str(user_id))
    return [_portal_database_dataset_row(row) for row in datasets.values()]


def _portal_database_query_params(request: Request | None) -> dict[str, list[str]]:
    query = ""
    if request is not None and getattr(request, "url", None) is not None:
        query = str(getattr(request.url, "query", "") or "")
    params: dict[str, list[str]] = {}
    for key, value in parse_qsl(query, keep_blank_values=True):
        params.setdefault(key, []).append(value)
    return params


def _portal_database_first_param(params: dict[str, list[str]], key: str, default: str = "") -> str:
    values = params.get(key) or []
    return str(values[-1]) if values else default


def _portal_database_url(dataset_id: str, params: dict[str, list[str]], **overrides: str | int | None) -> str:
    next_params = {key: list(values) for key, values in params.items() if values}
    for key, value in overrides.items():
        if value is None:
            next_params.pop(key, None)
        else:
            next_params[key] = [str(value)]
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}" + (f"?{query}" if query else "")


def _portal_database_quote_identifier(identifier: str | None, label: str) -> str:
    text = str(identifier or "")
    if not text or not text.strip():
        raise ValueError(f"{label} is required.")
    if "\x00" in text:
        raise ValueError(f"{label} contains an invalid NUL byte.")
    return '"' + text.replace('"', '""') + '"'


def _portal_database_type_family(data_type: str | None) -> str:
    """Query family for a column: what it may be filtered, searched and sorted by.

    Separate from ``_portal_database_render_family``, which is presentation only.
    Boolean is its own family from S3 onward because the approved contract gives
    it a four-way control (`wszystko` / `tak` / `nie` / `puste`) with no substring
    or comparison semantics at all; leaving it in "text" would offer `zawiera` on
    a boolean and would put boolean columns inside the global text search, which
    the approved contract restricts to text columns. uuid and json deliberately
    stay in "text": the contract defines no separate operator set for them and
    `zawiera` over an identifier is genuinely useful.
    """
    text = str(data_type or "").strip().lower()
    if "bool" in text:
        return "boolean"
    if any(token in text for token in ("int", "numeric", "decimal", "double", "real", "float", "money")):
        return "numeric"
    if any(token in text for token in ("date", "time", "timestamp")):
        return "date"
    if any(token in text for token in ("char", "text", "uuid", "json")):
        return "text"
    return "text"


def _portal_database_allowed_operators(column: dict) -> list[str]:
    """Approved operator tokens for a column, in the approved presentation order."""
    family = _portal_database_type_family(column.get("data_type"))
    if family == "boolean":
        return ["is_true", "is_false", "blank"]
    if family == "numeric":
        return ["eq", "neq", "gt", "gte", "lt", "lte", "between", "blank"]
    if family == "date":
        # Date columns are filtered through the `dateop__` family in the UI. The
        # generic comparison operators remain accepted so existing links, saved
        # export snapshots and the date builder's own normalized records keep
        # resolving to the same conditions.
        return ["eq", "neq", "gt", "gte", "lt", "lte", "between", "blank"]
    return ["contains", "eq", "neq", "in", "blank"]


def _portal_database_parse_numeric_value(value: str, label: str) -> tuple[str | None, str | None]:
    """Validate that a value is a finite number, returning it unchanged.

    The text is passed to the driver untouched so the database performs the
    conversion exactly as it does today; this only rejects input that would
    otherwise reach the client database as a guaranteed type error.
    """
    text = str(value or "").strip()
    if not text:
        return None, None
    try:
        parsed = Decimal(text)
    except (InvalidOperation, ValueError, ArithmeticError):
        return None, f"{label} must be a number."
    if parsed.is_nan() or parsed.is_infinite():
        return None, f"{label} must be a number."
    return text, None


def _portal_database_parse_in_values(
    raw_values: list[str],
    label: str,
    *,
    exact: bool = False,
) -> tuple[list[str], str | None]:
    """Parse a multi-value `in (...)` list.

    Two input forms resolve to one semantic result:

    * **human** (``filter_in__``, or repeated ``filter__``) — one value per line.
      Entries are trimmed and blank lines dropped, because a person typing into
      a textarea cannot express a leading space or a trailing newline on
      purpose, and treating stray whitespace as data would filter to nothing.
    * **exact** (``filter_exact__``) — one value per parameter, taken verbatim.
      This is what the distinct-value picker submits. It must not trim and must
      not split, or a value the picker displayed and counted could not be
      filtered back to itself: whitespace-only text, leading or trailing
      whitespace, and embedded newlines are all real values a column can hold.

    Duplicates collapse in both forms, preserving first-seen order. Exceeding the
    cardinality bound is reported, never truncated.
    """
    values: list[str] = []
    seen: set[str] = set()
    for raw in raw_values:
        parts = [str(raw)] if exact else str(raw).splitlines()
        for part in parts:
            text = part if exact else part.strip()
            if not exact and not text:
                continue
            if text in seen:
                continue
            seen.add(text)
            values.append(text)
    if len(values) > PORTAL_DATABASE_MAX_IN_VALUES:
        return [], f"{label} accepts at most {PORTAL_DATABASE_MAX_IN_VALUES} values; {len(values)} were provided."
    return values, None


def _portal_database_parse_page_params(params: dict[str, list[str]]) -> tuple[int, int, str | None]:
    page_raw = _portal_database_first_param(params, "page", "1")
    limit_raw = _portal_database_first_param(params, "limit", str(PORTAL_DATABASE_DEFAULT_PAGE_SIZE))
    try:
        page = int(page_raw)
    except ValueError:
        return 1, PORTAL_DATABASE_DEFAULT_PAGE_SIZE, "Page must be a whole number."
    try:
        limit = int(limit_raw)
    except ValueError:
        return 1, PORTAL_DATABASE_DEFAULT_PAGE_SIZE, "Limit must be a whole number."
    if page < 1:
        page = 1
    if limit < PORTAL_DATABASE_MIN_PAGE_SIZE:
        limit = PORTAL_DATABASE_MIN_PAGE_SIZE
    if limit > PORTAL_DATABASE_MAX_PAGE_SIZE:
        limit = PORTAL_DATABASE_MAX_PAGE_SIZE
    return page, limit, None


def _portal_database_parse_iso(value: str | None, label: str) -> tuple[str | None, str | None]:
    text = str(value or "").strip()
    if not text:
        return None, None
    try:
        datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None, f"{label} must be an ISO date or datetime."
    return text, None


def _portal_database_parse_date_filter_value(value: str | None, label: str) -> tuple[str | None, datetime | None, str | None]:
    text = str(value or "").strip()
    if not text:
        return None, None, None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None, None, f"{label} must be an ISO date or datetime."
    return text, parsed, None


def _portal_database_compare_datetime(value: datetime) -> datetime:
    # Used only to validate from <= to. Query values are passed through unchanged.
    return value.replace(tzinfo=None)


def _portal_database_date_filter_column(params: dict[str, list[str]], column_name: str) -> dict | None:
    operator = _portal_database_first_param(params, f"dateop__{column_name}", "").strip().lower()
    single_value = _portal_database_first_param(params, f"date__{column_name}", "").strip()
    from_value = _portal_database_first_param(params, f"date_from__{column_name}", "").strip()
    to_value = _portal_database_first_param(params, f"date_to__{column_name}", "").strip()
    if not operator and not single_value and not from_value and not to_value:
        return None
    if not operator:
        operator = "range" if (from_value or to_value) else "older"
    return {"column_name": column_name, "operator": operator, "value": single_value, "from": from_value, "to": to_value}


def _get_portal_database_dataset_for_user(dataset_id: str, user_id: str) -> dict | None:
    if not dataset_id or not user_id:
        return None
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                WITH effective_client_access AS (
                  SELECT user_id, client_code,
                         bool_or(can_view_database) AS can_view_database,
                         bool_or(can_view_reports) AS can_view_reports,
                         bool_or(can_export_database) AS can_export_database
                  FROM (
                    SELECT puc.user_id, puc.client_code, puc.can_view_database, puc.can_view_reports, puc.can_export_database
                    FROM portal_user_clients puc
                    UNION ALL
                    SELECT pgu.user_id, pgc.client_code, pgc.can_view_database, pgc.can_view_reports, pgc.can_export_database
                    FROM portal_group_users pgu
                    JOIN portal_groups pg ON pg.group_id = pgu.group_id AND pg.is_active IS TRUE
                    JOIN portal_group_clients pgc ON pgc.group_id = pg.group_id
                  ) grants
                  GROUP BY user_id, client_code
                ),
                effective_dataset_access AS (
                  SELECT dataset_id,
                         bool_or(can_view_rows) AS can_view_rows,
                         bool_or(can_filter_rows) AS can_filter_rows,
                         bool_or(can_export_rows) AS can_export_rows
                  FROM (
                    SELECT pddu.dataset_id, pddu.can_view_rows, pddu.can_filter_rows, pddu.can_export_rows
                    FROM portal_database_dataset_users pddu
                    WHERE pddu.user_id = %s
                    UNION ALL
                    SELECT pddg.dataset_id, pddg.can_view_rows, pddg.can_filter_rows, pddg.can_export_rows
                    FROM portal_database_dataset_groups pddg
                    JOIN portal_group_users pgu ON pgu.group_id = pddg.group_id AND pgu.user_id = %s
                    JOIN portal_groups pg ON pg.group_id = pddg.group_id AND pg.is_active IS TRUE
                  ) grants
                  GROUP BY dataset_id
                )
                SELECT pdd.dataset_id, pdd.client_code, pc.display_name AS client_display_name,
                       pc.database_name AS client_database_name,
                       pdd.dataset_name, pdd.slug, pdd.description, pdd.schema_name, pdd.table_name,
                       pdd.default_date_column, pdd.is_active, pdd.created_by, pdd.created_at, pdd.updated_by, pdd.updated_at,
                       eda.can_view_rows, eda.can_filter_rows, eda.can_export_rows,
                       (SELECT count(*) FROM portal_database_dataset_columns pddc WHERE pddc.dataset_id = pdd.dataset_id AND pddc.is_visible IS TRUE AND pddc.is_row_identifier IS NOT TRUE) AS visible_columns,
                       1 AS assigned_users
                FROM portal_database_datasets pdd
                JOIN portal_clients pc ON pc.client_code = pdd.client_code
                JOIN effective_dataset_access eda ON eda.dataset_id = pdd.dataset_id
                JOIN effective_client_access eca ON eca.user_id = %s AND eca.client_code = pdd.client_code
                JOIN artifact_users u ON u.user_id = %s
                WHERE pdd.dataset_id = %s
                  AND u.is_active IS TRUE
                  AND pdd.is_active IS TRUE
                  AND pc.is_active IS TRUE
                  AND eca.can_view_database IS TRUE
                  AND eda.can_view_rows IS TRUE
                LIMIT 1
                """,
                (user_id, user_id, user_id, user_id, dataset_id),
            )
            row = cur.fetchone()
    if not row:
        return None
    dataset = _portal_database_dataset_row(row)
    # Phase 2B: resolve the three effective row capabilities through the central
    # access helper so capability semantics live in one place. The combined query
    # above still owns visibility gating, dataset metadata, and client-DB routing;
    # the helper returns parity-equal capability flags for an accessible dataset.
    # The accessibility guard keeps current behavior as a safety net if the helper
    # were ever to disagree with the gating query.
    access = _get_effective_dataset_access_details_for_user(str(user_id), str(dataset_id))
    if access.get("accessible"):
        dataset["can_view_rows"] = bool(access.get("can_view_rows"))
        dataset["can_filter_rows"] = bool(access.get("can_filter_rows"))
        dataset["can_export_rows"] = bool(access.get("can_export_rows"))
    return dataset


def _get_portal_database_visible_columns(dataset_id: str) -> list[dict]:
    """The approved user-visible business columns for a dataset.

    This is the single source every ordinary user surface derives from — the
    table, `cols`, the S5 layout parameters, filters, sort, the S4 aggregate
    endpoint, exports and the row-detail drawer — which is why the technical
    row identity is excluded **here** rather than at each of those call sites.

    `is_row_identifier` wins over `is_visible` (`docs/29` §2). A dataset whose
    catalog still carries the legacy `is_visible = true` on the column that has
    since been configured as the technical identifier therefore stops exposing
    it the moment the identifier is configured, with no second migration step
    and no window in which transitional configuration leaks it.
    """
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT dataset_id, column_name, display_name, data_type, is_visible, is_filterable,
                       is_sortable, is_default_date_column, is_row_identifier, display_order
                FROM portal_database_dataset_columns
                WHERE dataset_id = %s AND is_visible IS TRUE AND is_row_identifier IS NOT TRUE
                ORDER BY display_order ASC, display_name ASC, column_name ASC
                """,
                (dataset_id,),
            )
            rows = cur.fetchall()
    return [_portal_database_column_row(row) for row in rows]


def _get_portal_database_row_identity_column(dataset_id: str) -> dict | None:
    """The configured technical row identifier, independent of user visibility.

    Deliberately a separate query from `_get_portal_database_visible_columns`:
    the identity is authorized dataset *metadata*, not a member of the user's
    column universe, and the two must not be able to drift into each other.

    Returns the column only when the configuration is unambiguous. Zero
    configured identifiers is the ordinary "no linkable row detail" state; more
    than one is invalid configuration and is treated as none, so a dataset can
    never fall back to guessing which column is identity.
    """
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT dataset_id, column_name, display_name, data_type, is_visible, is_filterable,
                       is_sortable, is_default_date_column, is_row_identifier, display_order
                FROM portal_database_dataset_columns
                WHERE dataset_id = %s AND is_row_identifier IS TRUE
                ORDER BY display_order ASC, column_name ASC
                LIMIT 2
                """,
                (dataset_id,),
            )
            rows = cur.fetchall()
    resolved = [_portal_database_column_row(row) for row in rows]
    if len(resolved) == 1:
        return resolved[0]
    return None


def _validate_portal_database_sort(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
) -> tuple[str | None, str, str | None]:
    column_map = {str(column.get("column_name")): column for column in columns}
    sortable = {name: column for name, column in column_map.items() if column.get("is_sortable")}
    requested_sort = _portal_database_first_param(params, "sort", "").strip()
    requested_direction = _portal_database_first_param(params, "direction", "").strip().lower()
    if requested_direction and requested_direction not in {"asc", "desc"}:
        return None, "asc", "Sort direction must be asc or desc."
    if requested_sort:
        if requested_sort not in sortable:
            return None, "asc", "Sort column is not available for this dataset."
        return requested_sort, requested_direction or "asc", None
    default_date = str(dataset.get("default_date_column") or "").strip()
    if default_date and default_date in sortable:
        return default_date, "desc", None
    if sortable:
        first = next(iter(sortable.keys()))
        return first, "asc", None
    return None, "asc", None


def _portal_database_requested_filter_columns(params: dict[str, list[str]]) -> list[str]:
    """Columns the URL asks to filter, in a stable order.

    A column is requested when it carries a non-empty ``filter__`` value, a
    non-empty ``filter_to__`` bound, or an ``op__`` naming an operator that takes
    no value at all (`puste`, `tak`, `nie`). The last case is why this cannot be
    derived from ``filter__`` keys alone.
    """
    requested: list[str] = []
    seen: set[str] = set()

    def _add(name: str) -> None:
        if name and name not in seen:
            seen.add(name)
            requested.append(name)

    for key, values in params.items():
        if key.startswith("filter__") and any(str(value).strip() for value in values):
            _add(key.removeprefix("filter__"))
        elif key.startswith("filter_from__") and any(str(value).strip() for value in values):
            _add(key.removeprefix("filter_from__"))
        elif key.startswith("filter_to__") and any(str(value).strip() for value in values):
            _add(key.removeprefix("filter_to__"))
        elif key.startswith("filter_in__") and any(str(value).strip() for value in values):
            _add(key.removeprefix("filter_in__"))
        elif key.startswith("filter_exact__") and values:
            # Presence alone, not a stripped value: an exact entry may legally be
            # whitespace-only, and testing it with `strip()` would make exactly
            # the values this parameter exists to carry invisible.
            _add(key.removeprefix("filter_exact__"))
        elif key.startswith("op__"):
            operator = _portal_database_first_param(params, key, "").strip().lower()
            if operator in PORTAL_DATABASE_VALUELESS_OPERATORS:
                _add(key.removeprefix("op__"))
    return requested


def _portal_database_filter_param_keys(column_name: str) -> list[str]:
    """Every query parameter that carries one column filter, for clean removal.

    The variants exist so a single GET form can carry a value control per
    operator without them colliding on one parameter name: whichever control the
    user did not use submits an empty string, and the operator decides which one
    is read. That is what keeps the no-JavaScript path correct.
    """
    return [
        f"filter__{column_name}",
        f"filter_from__{column_name}",
        f"filter_to__{column_name}",
        f"filter_in__{column_name}",
        f"filter_exact__{column_name}",
        f"op__{column_name}",
    ]


def _portal_database_date_filter_param_keys(column_name: str) -> list[str]:
    return [
        f"dateop__{column_name}",
        f"date__{column_name}",
        f"date_from__{column_name}",
        f"date_to__{column_name}",
    ]


def _build_portal_database_filter_conditions(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    *,
    exclude_column: str | None = None,
) -> tuple[list[str], list[Any], list[dict], str | None, list[dict]]:
    """Translate validated URL state into SQL conditions.

    Returns ``(conditions, values, active_filters, error, filter_entries)``.

    ``exclude_column`` drops one constraint from the emitted scope — the faceted
    value distributions use it for the inspected column, and the `DB-010` culprit
    diagnostic uses it for each candidate in turn, including the global text
    search under the reserved name ``__search__``. It is applied **after** that
    constraint has been validated exactly like every other. Validating a reduced
    parameter set
    instead would mean a malformed filter on the inspected column vanished
    silently and the aggregate answered over a broader population than the rows
    — the one thing a distribution must never do. Exclusion is semantic: it
    matches the validated filter's target column, so it covers every parameter
    family that column can be filtered through, including the legacy
    default-date range.

    ``active_filters`` is the record of the conditions actually emitted, in the
    normalized shape the background-export snapshot round-trips through. It is
    also the only sound basis for "is this result filtered?".

    ``filter_entries`` is the user-facing view of the same validated state: one
    entry per filter the user set, which is what chips, the filter panel and the
    toolbar count badge render. A date range is two conditions but one filter, so
    the two lists deliberately differ in length.

    Nothing here interpolates a user value into SQL. Operator tokens select a
    fixed fragment through an explicit branch; identifiers come from the dataset
    catalog and are quoted; every value is a bound parameter.
    """
    filterable = {str(column.get("column_name")): column for column in columns if column.get("is_filterable")}
    column_map = {str(column.get("column_name")): column for column in columns}
    requested_filter_columns = _portal_database_requested_filter_columns(params)
    requested_date_keys = [
        key for key, values in params.items()
        if (key.startswith("date__") or key.startswith("date_from__") or key.startswith("date_to__"))
        and any(str(value).strip() for value in values)
    ]
    requested_date_ops = [
        key for key, values in params.items()
        if key.startswith("dateop__") and any(str(value).strip() for value in values)
    ]
    requested_legacy_date = bool(_portal_database_first_param(params, "date_from", "").strip() or _portal_database_first_param(params, "date_to", "").strip())
    search_value = _portal_database_first_param(params, "search", "").strip()
    requested_search = bool(search_value)
    if not dataset.get("can_filter_rows") and (
        requested_filter_columns or requested_date_keys or requested_date_ops or requested_legacy_date or requested_search
    ):
        # Fail closed: every operator, old or new, is refused for an account
        # without the filtering capability on this dataset.
        return [], [], [], "Filtering is not enabled for your access to this dataset.", []
    conditions: list[str] = []
    values: list[Any] = []
    active_filters: list[dict] = []
    filter_entries: list[dict] = []
    excluded = str(exclude_column) if exclude_column else ""

    def _emit(column_name: str, condition: str, *condition_values: Any) -> None:
        """Record one SQL condition unless its column is the excluded one.

        Conditions and their bound values are appended together, so skipping a
        pair keeps the two lists aligned.
        """
        if column_name == excluded:
            return
        conditions.append(condition)
        values.extend(condition_values)

    def _record(column_name: str, active: dict | None = None, entry: dict | None = None) -> None:
        if column_name == excluded:
            return
        if active is not None:
            active_filters.append(active)
        if entry is not None:
            filter_entries.append(entry)

    def _label_for(column_name: str) -> str:
        column = column_map.get(column_name) or {}
        return str(column.get("display_name") or column_name)

    for column_name in requested_filter_columns:
        column = filterable.get(column_name)
        if not column:
            return [], [], [], "Filter column is not available for this dataset.", []
        family = _portal_database_type_family(column.get("data_type"))
        label = _label_for(column_name)
        exact_values = [str(value) for value in (params.get(f"filter_exact__{column_name}") or [])]
        raw_values = [str(value) for value in (params.get(f"filter_in__{column_name}") or [])]
        if not any(str(item).strip() for item in raw_values):
            raw_values = [str(value) for value in (params.get(f"filter__{column_name}") or [])]
        value = _portal_database_first_param(params, f"filter__{column_name}", "").strip()
        lower_value = _portal_database_first_param(params, f"filter_from__{column_name}", "").strip() or value
        upper_value = _portal_database_first_param(params, f"filter_to__{column_name}", "").strip()
        operator = _portal_database_first_param(params, f"op__{column_name}", "").strip().lower()
        allowed = _portal_database_allowed_operators(column)
        if not operator:
            operator = "contains" if "contains" in allowed else "eq"
        if operator not in PORTAL_DATABASE_FILTER_OPERATORS or operator not in allowed:
            return [], [], [], f"Operator {operator or '(empty)'} is not allowed for {column_name}.", []
        if operator == "in":
            if not exact_values and not any(str(item).strip() for item in raw_values):
                continue
        elif operator in PORTAL_DATABASE_RANGE_OPERATORS:
            if not lower_value and not upper_value:
                continue
        elif operator not in PORTAL_DATABASE_VALUELESS_OPERATORS and not value:
            continue
        quoted = _portal_database_quote_identifier(column_name, "Filter column")
        clear_keys = _portal_database_filter_param_keys(column_name)

        if operator == "blank":
            # `puste` by data family. For text it is NULL **or** the empty string,
            # exactly as the column menu states. For every other family the empty
            # string is not a value the column can hold, so it is NULL alone.
            # Zero and false are values, never blanks, and no branch here touches
            # them.
            if family == "text":
                _emit(column_name, f"({quoted} IS NULL OR CAST({quoted} AS TEXT) = '')")
            else:
                _emit(column_name, f"{quoted} IS NULL")
            _record(
                column_name,
                {"column_name": column_name, "operator": "blank", "value": ""},
                {"column_name": column_name, "label": label, "operator": "blank",
                 "values": [], "value": "", "value_to": "", "clear_keys": clear_keys},
            )
            continue

        if operator in {"is_true", "is_false"}:
            _emit(column_name, f"{quoted} IS TRUE" if operator == "is_true" else f"{quoted} IS FALSE")
            _record(
                column_name,
                {"column_name": column_name, "operator": operator, "value": ""},
                {"column_name": column_name, "label": label, "operator": operator,
                 "values": [], "value": "", "value_to": "", "clear_keys": clear_keys},
            )
            continue

        if operator == "in":
            # The picker's exact parameters win when present; they are the only
            # form that can carry a value back to itself byte for byte.
            if exact_values:
                parsed_values, in_error = _portal_database_parse_in_values(exact_values, label, exact=True)
            else:
                parsed_values, in_error = _portal_database_parse_in_values(raw_values, label)
            if in_error:
                return [], [], [], in_error, []
            if not parsed_values:
                continue
            placeholders = ", ".join(["%s"] * len(parsed_values))
            _emit(column_name, f"CAST({quoted} AS TEXT) IN ({placeholders})", *parsed_values)
            _record(
                column_name,
                {"column_name": column_name, "operator": "in", "value": parsed_values[0], "values": list(parsed_values)},
                {"column_name": column_name, "label": label, "operator": "in",
                 "values": list(parsed_values), "value": "", "value_to": "", "clear_keys": clear_keys},
            )
            continue

        if operator == "between":
            lower, upper = lower_value, upper_value
            if family == "numeric":
                lower, lower_error = _portal_database_parse_numeric_value(lower_value, f"{label} from")
                if lower_error:
                    return [], [], [], lower_error, []
                upper, upper_error = _portal_database_parse_numeric_value(upper_value, f"{label} to")
                if upper_error:
                    return [], [], [], upper_error, []
                if lower is not None and upper is not None and Decimal(lower) > Decimal(upper):
                    return [], [], [], f"{label} from must be less than or equal to {label} to.", []
            elif family == "date":
                lower, parsed_lower, lower_error = _portal_database_parse_date_filter_value(lower_value, f"{label} from")
                if lower_error:
                    return [], [], [], lower_error, []
                upper, parsed_upper, upper_error = _portal_database_parse_date_filter_value(upper_value, f"{label} to")
                if upper_error:
                    return [], [], [], upper_error, []
                if parsed_lower and parsed_upper and _portal_database_compare_datetime(parsed_lower) > _portal_database_compare_datetime(parsed_upper):
                    return [], [], [], f"{label} from must be earlier than or equal to {label} to.", []
            if not lower and not upper:
                continue
            # `od–do` is inclusive at both ends and either bound may be left
            # blank for an open-ended range (TGS 3.3, TGS 3.4).
            if lower:
                _emit(column_name, f"{quoted} >= %s", lower)
            if upper:
                _emit(column_name, f"{quoted} <= %s", upper)
            # One record, not two. A two-sided range emits two conditions but is
            # one filter, and the background-export snapshot keys its records by
            # column: two records for one column would lose a bound.
            _record(
                column_name,
                {"column_name": column_name, "operator": "between",
                 "value": lower or "", "value_to": upper or ""},
                {"column_name": column_name, "label": label, "operator": "between",
                 "values": [], "value": lower or "", "value_to": upper or "", "clear_keys": clear_keys},
            )
            continue

        if family == "numeric" and operator in {"eq", "neq", "gt", "gte", "lt", "lte"}:
            checked, numeric_error = _portal_database_parse_numeric_value(value, label)
            if numeric_error:
                return [], [], [], numeric_error, []
            value = checked or value

        if operator == "contains":
            _emit(column_name, f"CAST({quoted} AS TEXT) ILIKE %s", f"%{value}%")
        elif operator == "eq":
            _emit(column_name, f"{quoted} = %s", value)
        elif operator == "neq":
            _emit(column_name, f"{quoted} <> %s", value)
        elif operator == "gt":
            _emit(column_name, f"{quoted} > %s", value)
        elif operator == "gte":
            _emit(column_name, f"{quoted} >= %s", value)
        elif operator == "lt":
            _emit(column_name, f"{quoted} < %s", value)
        elif operator == "lte":
            _emit(column_name, f"{quoted} <= %s", value)
        _record(
            column_name,
            {"column_name": column_name, "operator": operator, "value": value},
            {"column_name": column_name, "label": label, "operator": operator,
             "values": [], "value": value, "value_to": "", "clear_keys": clear_keys},
        )

    default_date = str(dataset.get("default_date_column") or "").strip()
    date_filters: list[dict] = []
    if requested_legacy_date:
        if not default_date:
            return [], [], [], "Date range filtering is not configured for this dataset.", []
        date_filters.append({
            "column_name": default_date,
            "operator": "range",
            "from": _portal_database_first_param(params, "date_from", "").strip(),
            "to": _portal_database_first_param(params, "date_to", "").strip(),
            "legacy": True,
        })
    seen_date_columns: set[str] = set()
    for column_name in sorted(
        {key.split("__", 1)[1] for key in requested_date_keys + requested_date_ops if "__" in key}
    ):
        if column_name in seen_date_columns:
            continue
        seen_date_columns.add(column_name)
        parsed = _portal_database_date_filter_column(params, column_name)
        if parsed:
            date_filters.append(parsed)

    for entry in date_filters:
        column_name = str(entry.get("column_name") or "")
        column = filterable.get(column_name)
        if not column or column_name not in column_map or _portal_database_type_family(column.get("data_type")) != "date":
            return [], [], [], "Date filter column is not available for this dataset.", []
        operator = str(entry.get("operator") or "").strip().lower()
        if operator not in PORTAL_DATABASE_DATE_FILTER_OPERATORS:
            return [], [], [], f"Date operator {operator or '(empty)'} is not allowed for {column_name}.", []
        quoted = _portal_database_quote_identifier(column_name, "Date filter column")
        label = str(column.get("display_name") or column_name)
        legacy = bool(entry.get("legacy"))
        clear_keys = (
            ["date_from", "date_to"] if legacy else _portal_database_date_filter_param_keys(column_name)
        )
        if operator == "blank":
            # A date column holds no empty string, so `puste` is SQL NULL.
            _emit(column_name, f"{quoted} IS NULL")
            _record(
                column_name,
                {"column_name": column_name, "operator": "blank", "value": ""},
                {"column_name": column_name, "label": label, "operator": "blank",
                 "values": [], "value": "", "value_to": "", "clear_keys": clear_keys},
            )
            continue
        if operator in {"older", "newer"}:
            raw_value = str(entry.get("value") or "").strip()
            value, _parsed, error = _portal_database_parse_date_filter_value(raw_value, label)
            if error:
                return [], [], [], error, []
            if not value:
                continue
            sql_operator = "<" if operator == "older" else ">"
            _emit(column_name, f"{quoted} {sql_operator} %s", value)
            _record(
                column_name,
                {"column_name": column_name, "operator": "lt" if operator == "older" else "gt", "value": value},
                {"column_name": column_name, "label": label, "operator": operator,
                 "values": [], "value": value, "value_to": "", "clear_keys": clear_keys},
            )
            continue
        from_value, parsed_from, from_error = _portal_database_parse_date_filter_value(str(entry.get("from") or ""), f"{label} from")
        if from_error:
            return [], [], [], from_error, []
        to_value, parsed_to, to_error = _portal_database_parse_date_filter_value(str(entry.get("to") or ""), f"{label} to")
        if to_error:
            return [], [], [], to_error, []
        if parsed_from and parsed_to and _portal_database_compare_datetime(parsed_from) > _portal_database_compare_datetime(parsed_to):
            return [], [], [], f"{label} from must be earlier than or equal to {label} to.", []
        if from_value:
            _emit(column_name, f"{quoted} >= %s", from_value)
        if to_value:
            _emit(column_name, f"{quoted} <= %s", to_value)
        if from_value or to_value:
            # `między` is one filter and therefore one chip, even though an
            # inclusive two-sided range emits two conditions. The legacy
            # default-date range arrives here too, under the default date
            # column's own name, which is what lets it be faceted out when that
            # column is the one being inspected.
            _record(
                column_name,
                {"column_name": column_name, "operator": "between",
                 "value": from_value or "", "value_to": to_value or ""},
                {"column_name": column_name, "label": label, "operator": "range",
                 "values": [], "value": from_value or "", "value_to": to_value or "", "clear_keys": clear_keys},
            )

    # Global search across visible, filterable text-like columns. Restricting to
    # filterable columns respects the admin's per-column filter configuration; the
    # search never touches hidden or non-text columns. All terms are parameterized.
    if requested_search:
        search_columns = _portal_database_search_columns(columns)
        if search_columns:
            search_conditions: list[str] = []
            search_values: list[Any] = []
            for column in search_columns:
                try:
                    quoted = _portal_database_quote_identifier(str(column.get("column_name") or ""), "Search column")
                except ValueError as exc:
                    return [], [], [], str(exc), []
                search_conditions.append(f"CAST({quoted} AS TEXT) ILIKE %s")
                search_values.append(f"%{search_value}%")
            # Emitted through the same helpers as every column filter, so the
            # semantic exclusion `exclude_column` performs covers the global
            # search too. `DB-010` needs that: search is one of the constraints
            # that can be the reason a result is empty, and testing it means
            # dropping exactly its predicate while every other one stands.
            _emit("__search__", "(" + " OR ".join(search_conditions) + ")", *search_values)
            # The approved contract keeps search out of the chip strip and out of
            # the `Filtry` count: it is its own visible toolbar field (PBC 2.6).
            # It is recorded here so `Wyczyść wszystkie` can clear it.
            _record(
                "__search__",
                {"column_name": "__search__", "operator": "search", "value": search_value},
                {"column_name": "__search__", "label": "", "operator": "search",
                 "values": [], "value": search_value, "value_to": "", "clear_keys": ["search"]},
            )
    return conditions, values, active_filters, None, filter_entries


def _build_portal_database_rows_query(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    *,
    count: bool = False,
    limit: int = PORTAL_DATABASE_DEFAULT_PAGE_SIZE,
    offset: int = 0,
    display_columns: list[dict] | None = None,
    unbounded: bool = False,
) -> tuple[str, list[Any], dict, str | None]:
    # `columns` is the allowed/permitted set and always governs sort, filter, search
    # and the "has visible columns" guard. `display_columns` (Phase 2B) optionally
    # narrows ONLY the SELECT list to a user-chosen subset of the permitted columns;
    # it can never widen access because it is intersected against `columns` upstream.
    #
    # The configured technical row identifier (S6) is dataset metadata rather
    # than a member of `columns`. The row browser appends it to `display_columns`
    # so it can mint opaque row references, and it is picked up from there for one
    # further purpose only: a deterministic ORDER BY tie-breaker. It never joins
    # the sortable, filterable or searchable universe, so `sort=record_id` stays
    # unavailable to a user even while the backend orders by it.
    select_source = columns if display_columns is None else display_columns
    try:
        schema_sql = _portal_database_quote_identifier(str(dataset.get("schema_name") or ""), "Schema name")
        table_sql = _portal_database_quote_identifier(str(dataset.get("table_name") or ""), "Table name")
        if not columns:
            return "", [], {}, "This dataset has no visible columns configured."
        select_columns = [
            _portal_database_quote_identifier(str(column.get("column_name") or ""), "Column name")
            for column in select_source
        ]
    except ValueError as exc:
        return "", [], {}, str(exc)
    if not select_columns:
        return "", [], {}, "This dataset has no visible columns configured."
    sort_column, sort_direction, sort_error = _validate_portal_database_sort(dataset, columns, params)
    if sort_error:
        return "", [], {}, sort_error
    try:
        conditions, condition_values, active_filters, filter_error, filter_entries = _build_portal_database_filter_conditions(dataset, columns, params)
    except ValueError as exc:
        return "", [], {}, str(exc)
    if filter_error:
        return "", [], {}, filter_error
    where_sql = (" WHERE " + " AND ".join(conditions)) if conditions else ""
    table_ref = f"{schema_sql}.{table_sql}"
    state = {
        "sort": sort_column,
        "direction": sort_direction,
        "active_filters": active_filters,
        # One entry per filter the user set — what chips, the panel and the
        # count badge render. Distinct from active_filters, which counts SQL
        # conditions and round-trips through the export snapshot.
        "filter_entries": filter_entries,
    }
    if count:
        return f"SELECT count(*) AS total FROM {table_ref}{where_sql}", condition_values, state, None
    order_sql = ""
    if sort_column:
        try:
            order_parts = [f"{_portal_database_quote_identifier(sort_column, 'Sort column')} {sort_direction.upper()}"]
            row_identifier = _portal_database_resolve_row_identifier(select_source)
            row_identifier_name = str(row_identifier.get("column_name") or "") if row_identifier else ""
            if row_identifier_name and row_identifier_name != sort_column:
                order_parts.append(f"{_portal_database_quote_identifier(row_identifier_name, 'Row identifier column')} ASC")
                state["secondary_sort"] = row_identifier_name
            order_sql = " ORDER BY " + ", ".join(order_parts)
        except ValueError as exc:
            return "", [], {}, str(exc)
    select_sql = ", ".join(select_columns)
    if unbounded:
        query = f"SELECT {select_sql} FROM {table_ref}{where_sql}{order_sql}"
        return query, condition_values, state, None
    query = f"SELECT {select_sql} FROM {table_ref}{where_sql}{order_sql} LIMIT %s OFFSET %s"
    return query, condition_values + [limit, offset], state, None


def _list_portal_database_rows(dataset: dict, columns: list[dict], params: dict[str, list[str]], *, limit: int, offset: int, display_columns: list[dict] | None = None) -> tuple[list[dict], dict, str | None]:
    query, values, state, error = _build_portal_database_rows_query(dataset, columns, params, limit=limit, offset=offset, display_columns=display_columns)
    if error:
        return [], state, error
    database_name = _portal_dataset_client_database_name(dataset)
    with _connect_portal_client_database(database_name) as conn:
        with conn.cursor() as cur:
            cur.execute(query, values)
            rows = cur.fetchall()
    return _rows_to_dicts(rows), state, None


def _count_portal_database_rows(dataset: dict, columns: list[dict], params: dict[str, list[str]]) -> tuple[int, dict, str | None]:
    query, values, state, error = _build_portal_database_rows_query(dataset, columns, params, count=True)
    if error:
        return 0, state, error
    database_name = _portal_dataset_client_database_name(dataset)
    with _connect_portal_client_database(database_name) as conn:
        with conn.cursor() as cur:
            cur.execute(query, values)
            row = cur.fetchone()
    return int(row.get("total") or 0), state, None


def _count_portal_database_rows_unfiltered(dataset: dict, columns: list[dict]) -> tuple[int, str | None]:
    """Total rows in the dataset, ignoring filters and search.

    The approved result counter distinguishes the filtered result from the size
    of the dataset (`1 274 z 48 213 wierszy`), which needs a second count.

    This deliberately reuses ``_count_portal_database_rows`` with an empty
    parameter map rather than building its own SQL: the dataset has already been
    resolved through the caller's permission check, and going through the same
    builder keeps identifier quoting, the read-only connection and the statement
    timeout identical. It cannot reach another dataset, and it cannot widen the
    permitted column set, because it passes the same authorized `columns`.
    """
    try:
        total, _state, error = _count_portal_database_rows(dataset, columns, {})
    except Exception as exc:
        # A failed secondary count must never break a page whose rows loaded.
        print(f"portal database total count failed: {type(exc).__name__}")
        return 0, "unavailable"
    if error:
        return 0, error
    return total, None


# ---------------------------------------------------------------------------
# Empty-result diagnosis (DB-010, stage S9)
#
# `DB-56` requires the zero-result message to name the filter that reduced the
# result to zero and to state the row count without it. That is a claim about
# the data, so it is answered with query evidence rather than with a guess from
# the order of the controls.
#
# The whole diagnostic is: for each ACTIVE VALIDATED constraint, count the same
# authorized query with exactly that one constraint semantically excluded. The
# cost is therefore bounded by the number of active constraints — never by the
# width of the dataset — and it is capped again by
# `PORTAL_DATABASE_CULPRIT_MAX_FILTERS`, above which the state degrades to the
# generic filtered-empty message instead of fanning out.
#
# It opens no new disclosure surface: same dataset, same approved columns, same
# canonical filter builder, same read-only connection and statement timeout, and
# the only fact it can produce is a row count for a query the user is already
# entitled to run by removing a filter in the UI.
# ---------------------------------------------------------------------------

# One count per active constraint, and nothing beyond this many constraints is
# analysed. The approved gap analysis anticipated roughly one count per active
# filter; a sheet carrying more constraints than this is past the point where
# naming one of them is useful, so it gets the generic state rather than a
# query fan-out.
PORTAL_DATABASE_CULPRIT_MAX_FILTERS = 6


def _count_portal_database_rows_excluding(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    exclude_column: str,
) -> tuple[int | None, str | None]:
    """`count(*)` for the current validated query with ONE constraint dropped.

    Exclusion is semantic, exactly as `S4` established it: the whole requested
    filter state is validated first and the candidate is removed from what that
    validation emitted. Removing its parameters before validating would let a
    malformed filter vanish silently and the count answer over a broader
    population than the user asked for — which here would mean blaming an
    innocent filter for a result an invalid one produced.

    ``exclude_column`` accepts ``__search__`` for the global text search, which
    the builder now emits through the same helper as every column filter.
    """
    try:
        schema_sql = _portal_database_quote_identifier(str(dataset.get("schema_name") or ""), "Schema name")
        table_sql = _portal_database_quote_identifier(str(dataset.get("table_name") or ""), "Table name")
        conditions, values, _active, error, _entries = _build_portal_database_filter_conditions(
            dataset, columns, params, exclude_column=exclude_column
        )
    except ValueError as exc:
        return None, str(exc)
    if error:
        return None, error
    where_sql = (" WHERE " + " AND ".join(conditions)) if conditions else ""
    query = f"SELECT count(*) AS total FROM {schema_sql}.{table_sql}{where_sql}"
    database_name = _portal_dataset_client_database_name(dataset)
    with _connect_portal_client_database(database_name) as conn:
        with conn.cursor() as cur:
            cur.execute(query, values)
            row = cur.fetchone()
    return int((row or {}).get("total") or 0), None


def _portal_database_empty_result_diagnosis(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    filter_entries: list[dict],
) -> dict:
    """Which active constraint, if any, is provably responsible for zero rows.

    Returns ``{"mode": ..., "column_name": ..., "restored": ...}`` where mode is:

    ``single``    exactly one constraint restores rows on its own — it may be named
    ``multiple``  several restore rows independently — no unique culprit exists
    ``joint``     none restores rows alone — the combination is the constraint
    ``generic``   not analysed (too many constraints, or a count failed)

    Only ``single`` licenses the approved culprit sentence. Anything else falls
    back to a message that claims no more than the evidence supports.
    """
    candidates: list[str] = []
    for entry in filter_entries or []:
        name = str(entry.get("column_name") or "")
        if name and name not in candidates:
            candidates.append(name)
    if not candidates or len(candidates) > PORTAL_DATABASE_CULPRIT_MAX_FILTERS:
        return {"mode": "generic", "column_name": "", "restored": None}
    restorers: list[tuple[str, int]] = []
    for name in candidates:
        try:
            restored, error = _count_portal_database_rows_excluding(dataset, columns, params, name)
        except Exception as exc:  # noqa: BLE001
            # A diagnostic must never turn a rendered empty state into a failed
            # page. The class name only, never the statement or the values.
            print(f"portal database culprit count failed: {type(exc).__name__}")
            return {"mode": "generic", "column_name": "", "restored": None}
        if error or restored is None:
            # The same validated state produced the rows query, so an error here
            # is not something the user can act on: degrade, do not accuse.
            return {"mode": "generic", "column_name": "", "restored": None}
        if restored > 0:
            restorers.append((name, restored))
    if len(restorers) == 1:
        return {"mode": "single", "column_name": restorers[0][0], "restored": restorers[0][1]}
    if len(restorers) > 1:
        return {"mode": "multiple", "column_name": "", "restored": None}
    return {"mode": "joint", "column_name": "", "restored": None}


# ---------------------------------------------------------------------------
# Value distributions (DB-005 section 4, stage S4)
#
# An aggregate over client data is a disclosure surface even though it returns
# no rows, so every request here goes through exactly the same effective
# authorization as row browsing: portal session, client grant, dataset grant,
# `can_view_rows`, `can_filter_rows`, and a column that the dataset catalog
# marks visible AND filterable. Nothing is inferred from the fact that the UI
# only renders a menu for eligible columns.
#
# The caller supplies one thing: which approved column. The aggregation mode,
# the bucket count and the row limit are all resolved server-side, so no part
# of the GROUP BY or the aggregate expression can come from the browser.
# ---------------------------------------------------------------------------


def _portal_database_distribution_mode(column: dict) -> str:
    """Which distribution the approved design gives this column.

    `TGS` 5.1 item 4: "distinct-value picker (text) or histogram (numeric);
    absent for boolean". Date columns are likewise given no distribution. Those
    families still get the identity summary, because `TGS` 5.1 item 1 requires a
    non-null count in every column menu.
    """
    family = _portal_database_type_family(column.get("data_type"))
    if family == "text":
        return "categorical"
    if family == "numeric":
        return "numeric"
    return "summary"


def _portal_database_distribution_scope_sql(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    column_name: str,
) -> tuple[str, list[Any], list[dict], str | None]:
    """`FROM <table> WHERE <effective filters>` for the faceted scope.

    Faceted semantics: the distribution answers "what else is in this column,
    given everything else I have filtered". Applying the column's own filter
    would make the picker show only the values already selected, so the approved
    multi-select `in (…)` interaction could never add a value, and would clip the
    histogram domain so the threshold marker could not be compared against the
    real distribution — which `TGS` 3.3 states is the whole point of showing it.

    The **whole** requested filter state is validated first, and the inspected
    column is excluded only from what that validation emits. Removing its
    parameters before validating would let a malformed filter on that column
    disappear silently and the aggregate answer over a broader population than
    the rows — the failure mode this endpoint most needs to avoid. Exclusion is
    therefore semantic, keyed on the validated filter's target column, which is
    also what makes it cover the legacy default-date range.

    The global text search is deliberately kept: it is a cross-column predicate,
    not this column's filter.
    """
    try:
        schema_sql = _portal_database_quote_identifier(str(dataset.get("schema_name") or ""), "Schema name")
        table_sql = _portal_database_quote_identifier(str(dataset.get("table_name") or ""), "Table name")
    except ValueError as exc:
        return "", [], [], str(exc)
    try:
        conditions, values, _active, error, entries = _build_portal_database_filter_conditions(
            dataset, columns, params, exclude_column=column_name
        )
    except ValueError as exc:
        return "", [], [], str(exc)
    if error:
        return "", [], [], error
    where_sql = (" WHERE " + " AND ".join(conditions)) if conditions else ""
    return f"{schema_sql}.{table_sql}{where_sql}", values, entries, None


def _build_portal_database_distribution_query(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    column: dict,
) -> tuple[str, list[Any], str, str | None, list[dict]]:
    """One statement per distribution.

    Returns ``(sql, values, mode, error, scope_entries)``; ``scope_entries`` is
    the validated filter record for the faceted scope, used by the audit so it
    names only columns the builder actually accepted.

    Every identifier is catalog-derived and quoted; every user value is a bound
    parameter; the limit and bucket count are module constants bound as
    parameters rather than formatted into the text.
    """
    column_name = str(column.get("column_name") or "")
    mode = _portal_database_distribution_mode(column)
    source_sql, values, entries, error = _portal_database_distribution_scope_sql(
        dataset, columns, params, column_name
    )
    if error:
        return "", [], mode, error, []
    try:
        quoted = _portal_database_quote_identifier(column_name, "Distribution column")
    except ValueError as exc:
        return "", [], mode, str(exc), []

    if mode == "categorical":
        # Grouping on CAST(... AS TEXT) is not cosmetic: `in (…)` compares
        # CAST(col AS TEXT), so grouping the same way guarantees that selecting
        # a value in the picker filters exactly the rows it was counted from.
        # It also lets json columns group at all. NULL stays NULL through the
        # cast, and '' stays '', so the S2/S3 three-way distinction between
        # NULL, empty text and whitespace survives into the picker.
        query = (
            f"WITH base AS (SELECT CAST({quoted} AS TEXT) AS value FROM {source_sql}), "
            "grouped AS (SELECT value, count(*) AS value_count FROM base GROUP BY value) "
            "SELECT g.value, g.value_count, "
            "(SELECT count(*) FROM grouped) AS distinct_count, "
            "(SELECT count(value) FROM base) AS non_null_count, "
            "(SELECT count(*) FROM base) AS scope_rows "
            "FROM grouped g "
            "ORDER BY g.value_count DESC, g.value ASC NULLS LAST "
            "LIMIT %s"
        )
        return query, values + [PORTAL_DATABASE_DISTINCT_VALUE_LIMIT], mode, None, entries

    if mode == "numeric":
        # CAST to numeric rather than float: bucket bounds are derived from these
        # values, and a double-precision round trip could move a boundary.
        # LEFT JOIN LATERAL keeps the bounds row even when there are no values to
        # bucket, so the empty and single-value domains return a defined answer
        # instead of an empty result set.
        query = (
            f"WITH base AS (SELECT CAST({quoted} AS numeric) AS value FROM {source_sql}), "
            "bounds AS (SELECT count(*) AS scope_rows, count(value) AS value_count, "
            "min(value) AS min_value, max(value) AS max_value FROM base) "
            "SELECT b.scope_rows, b.value_count, b.min_value, b.max_value, g.bucket, g.bucket_count "
            "FROM bounds b LEFT JOIN LATERAL ("
            "SELECT least(width_bucket(base.value, b.min_value, b.max_value, %s), %s) AS bucket, "
            "count(*) AS bucket_count FROM base "
            "WHERE base.value IS NOT NULL AND b.max_value > b.min_value GROUP BY 1"
            ") g ON TRUE "
            "ORDER BY g.bucket ASC NULLS LAST"
        )
        buckets = PORTAL_DATABASE_HISTOGRAM_BUCKETS
        return query, values + [buckets, buckets], mode, None, entries

    query = (
        f"SELECT count(*) AS scope_rows, count({quoted}) AS non_null_count FROM {source_sql}"
    )
    return query, values, mode, None, entries


def _portal_database_decimal_text(value: Any) -> str | None:
    """Render a numeric bound as exact decimal text, never through float.

    ``normalize`` drops trailing zeros and ``format(..., "f")`` expands any
    exponent, so a bound is always plain digits the browser can display and
    place a marker against without reparsing scientific notation.
    """
    if value is None:
        return None
    if isinstance(value, Decimal):
        return format(value.normalize(), "f")
    return str(value)


def _portal_database_histogram_bounds(minimum: Decimal, maximum: Decimal, buckets: int) -> list[tuple[str, str]]:
    """Bucket edges as exact decimal text.

    ``width_bucket`` divides ``[min, max]`` into equal-width buckets, so the same
    arithmetic is reproduced here with ``Decimal`` rather than float; a float
    round trip could report an edge the database did not use.
    """
    width = (maximum - minimum) / Decimal(buckets)
    edges: list[tuple[str, str]] = []
    for index in range(buckets):
        lower = minimum + width * Decimal(index)
        upper = maximum if index == buckets - 1 else minimum + width * Decimal(index + 1)
        edges.append((_portal_database_decimal_text(lower) or "", _portal_database_decimal_text(upper) or ""))
    return edges


def _portal_database_distribution_payload(dataset: dict, columns: list[dict], params: dict[str, list[str]], column: dict) -> tuple[dict, str | None, list[dict]]:
    """Execute one distribution query and shape the approved response.

    Nothing about the physical table, the client database, the SQL or the
    catalog beyond what the menu renders leaves this function.
    """
    column_name = str(column.get("column_name") or "")
    query, values, mode, error, scope_entries = _build_portal_database_distribution_query(
        dataset, columns, params, column
    )
    if error:
        return {}, error, []
    database_name = _portal_dataset_client_database_name(dataset)
    with _connect_portal_client_database(database_name) as conn:
        with conn.cursor() as cur:
            cur.execute(query, values)
            rows = _rows_to_dicts(cur.fetchall())

    payload: dict[str, Any] = {
        "column": column_name,
        "label": str(column.get("display_name") or column_name),
        "mode": mode,
        # Faceted: this column's own filter is excluded from the counts, and the
        # UI says so rather than letting the numbers look like the visible rows.
        "scope": "filtered_excluding_column",
    }

    if mode == "categorical":
        values_out = []
        for row in rows:
            raw = row.get("value")
            values_out.append({
                "value": None if raw is None else str(raw),
                "count": int(row.get("value_count") or 0),
            })
        first = rows[0] if rows else {}
        distinct_count = int(first.get("distinct_count") or 0)
        payload.update({
            "values": values_out,
            "distinct_count": distinct_count,
            "non_null_count": int(first.get("non_null_count") or 0),
            "scope_rows": int(first.get("scope_rows") or 0),
            "limit": PORTAL_DATABASE_DISTINCT_VALUE_LIMIT,
            "truncated": distinct_count > PORTAL_DATABASE_DISTINCT_VALUE_LIMIT,
        })
        return payload, None, scope_entries

    if mode == "numeric":
        first = rows[0] if rows else {}
        minimum = first.get("min_value")
        maximum = first.get("max_value")
        value_count = int(first.get("value_count") or 0)
        scope_rows = int(first.get("scope_rows") or 0)
        counts = {int(row["bucket"]): int(row.get("bucket_count") or 0) for row in rows if row.get("bucket") is not None}
        buckets: list[dict] = []
        if value_count and minimum is not None and maximum is not None and maximum > minimum:
            for index, (lower, upper) in enumerate(
                _portal_database_histogram_bounds(Decimal(minimum), Decimal(maximum), PORTAL_DATABASE_HISTOGRAM_BUCKETS),
                start=1,
            ):
                buckets.append({"index": index, "min": lower, "max": upper, "count": counts.get(index, 0)})
        payload.update({
            "buckets": buckets,
            "bucket_count": PORTAL_DATABASE_HISTOGRAM_BUCKETS,
            "min": _portal_database_decimal_text(minimum),
            "max": _portal_database_decimal_text(maximum),
            "non_null_count": value_count,
            "null_count": max(0, scope_rows - value_count),
            "scope_rows": scope_rows,
            # Three defined degenerate states, so the UI never has to guess:
            # nothing in scope, nothing but NULL, or every value identical.
            "domain": (
                "empty" if scope_rows == 0
                else "all_null" if value_count == 0
                else "single_value" if maximum == minimum
                else "range"
            ),
        })
        return payload, None, scope_entries

    first = rows[0] if rows else {}
    payload.update({
        "non_null_count": int(first.get("non_null_count") or 0),
        "scope_rows": int(first.get("scope_rows") or 0),
    })
    return payload, None, scope_entries


def _portal_json_response(payload: dict, *, status_code: int = 200) -> HTMLResponse:
    """JSON without importing another response class into every test stub.

    ``Response.media_type`` is overridable per instance, so the shared HTML
    response type serves this correctly; the alternative would be a new import
    that every existing FastAPI stub in the manual suites would have to grow.
    """
    return HTMLResponse(
        json.dumps(payload, ensure_ascii=False),
        status_code=status_code,
        media_type="application/json",
    )


# Deliberately generic across every AUTHENTICATED refusal: a dataset the account
# cannot open, a dataset it cannot filter, and a column outside the approved
# filterable set all return the same 404 and the same body, so the response
# cannot be used to probe which of them was true — or whether a column exists.
#
# An unauthenticated request is a different question and keeps the platform's
# normal 401. It reveals nothing about the dataset or its columns, because the
# route refuses before any dataset or column is resolved.
PORTAL_DATABASE_DISTRIBUTION_DENIED_MESSAGE = "Value distribution is not available for this column."
PORTAL_DATABASE_DISTRIBUTION_FAILED_MESSAGE = "Value distribution could not be loaded."


def _portal_database_distribution_response(user: dict, dataset_id: str, request: Request | None) -> HTMLResponse:
    """`DB-005` section 4 — an aggregate over one approved column.

    Authorization order matters and mirrors the row browser exactly:

      1. the session is resolved by the route (an unauthenticated request never
         reaches this function and is answered 401 before any dataset or column
         is looked at);
      2. ``_get_portal_database_dataset_for_user`` enforces the client grant,
         the dataset grant and ``can_view_rows`` in one gating query;
      3. ``can_filter_rows`` is required, because a value/count list is filter
         reconnaissance even though it returns no rows;
      4. the column must be in the dataset's approved visible set AND marked
         filterable.

    Only after all four does any client-database statement get built.
    """
    params = _portal_database_query_params(request)
    actor_user_id = str(user.get("user_id") or "") or None
    requested_column = _portal_database_first_param(params, "column", "").strip()

    def _denied(reason: str, *, client_code: str | None = None, dsid: str | None = None) -> HTMLResponse:
        _portal_audit_event_safe(
            event_type="database_distribution_denied",
            actor_user_id=actor_user_id,
            client_code=client_code,
            dataset_id=dsid,
            request=request,
            metadata=_portal_database_distribution_metadata(
                params=params,
                # Nothing resolved, so nothing may be written into the trusted
                # approved-column fields.
                column=None,
                requested_column=requested_column,
                mode=None,
                reason=reason,
                requested_dataset_id=None if dsid else dataset_id,
            ),
        )
        return _portal_json_response(
            {"error": PORTAL_DATABASE_DISTRIBUTION_DENIED_MESSAGE}, status_code=404
        )

    dataset = _get_portal_database_dataset_for_user(dataset_id, str(user.get("user_id") or ""))
    if not dataset:
        return _denied("dataset_unavailable")
    client_code = str(dataset.get("client_code") or "") or None
    dsid = str(dataset.get("dataset_id") or "") or None
    if not dataset.get("can_filter_rows"):
        return _denied("filtering_not_permitted", client_code=client_code, dsid=dsid)

    columns = _get_portal_database_visible_columns(dataset_id)
    column = next(
        (
            item
            for item in columns
            if str(item.get("column_name") or "") == requested_column and item.get("is_filterable")
        ),
        None,
    )
    if not column:
        return _denied("column_not_available", client_code=client_code, dsid=dsid)

    mode = _portal_database_distribution_mode(column)
    try:
        payload, error, scope_entries = _portal_database_distribution_payload(dataset, columns, params, column)
    except Exception as exc:
        exc_name = type(exc).__name__
        print(f"portal database distribution failed: {exc_name}: dataset_id={dataset_id} client_code={dataset.get('client_code')}")
        _portal_audit_event_safe(
            event_type="database_distribution_failed",
            actor_user_id=actor_user_id,
            client_code=client_code,
            dataset_id=dsid,
            request=request,
            metadata=_portal_database_distribution_metadata(
                params=params, column=column, requested_column=requested_column,
                mode=mode, reason=exc_name,
            ),
        )
        # The menu stays usable and manual filtering is unaffected; the database
        # error itself never reaches the browser.
        return _portal_json_response(
            {"error": PORTAL_DATABASE_DISTRIBUTION_FAILED_MESSAGE}, status_code=502
        )
    if error:
        # A rejected filter parameter in the surrounding view state. Reported as
        # a validation failure rather than a denial, and still without echoing
        # the offending value.
        _portal_audit_event_safe(
            event_type="database_distribution_failed",
            actor_user_id=actor_user_id,
            client_code=client_code,
            dataset_id=dsid,
            request=request,
            metadata=_portal_database_distribution_metadata(
                params=params, column=column, requested_column=requested_column,
                mode=mode, reason="filter_validation_failed",
            ),
        )
        return _portal_json_response(
            {"error": PORTAL_DATABASE_DISTRIBUTION_FAILED_MESSAGE}, status_code=400
        )

    _portal_audit_event_safe(
        event_type="database_distribution_viewed",
        actor_user_id=actor_user_id,
        client_code=client_code,
        dataset_id=dsid,
        request=request,
        metadata=_portal_database_distribution_metadata(
            params=params, column=column, requested_column=requested_column,
            mode=mode, reason=None, scope_entries=scope_entries,
        ),
    )
    return _portal_json_response(payload)


def _portal_database_distribution_metadata(
    *,
    params: dict[str, list[str]],
    column: dict | None,
    requested_column: str,
    mode: str | None,
    reason: str | None,
    scope_entries: list[dict] | None = None,
    requested_dataset_id: str | None = None,
) -> dict:
    """Audit record for one aggregate request.

    Two fields, two trust levels, and they must not be confused:

    * ``column`` and ``filter_keys`` are **approved dataset columns**. They are
      populated only from a catalog column the request actually resolved and
      from filters the canonical builder actually accepted. A denied request
      contributes nothing to them, so an attacker cannot write an invented field
      name into metadata that downstream readers treat as catalog truth.
    * ``requested_column`` is **caller input**, named as such, and mirrors the
      existing ``requested_dataset_id`` convention. It is still gated on the
      identifier shape so the audit trail cannot be used as a free text sink.

    No filter values, no operators and no aggregate results are logged: the
    aggregate reading business data is not a reason to start writing that data
    into the audit trail.
    """
    resolved_name = str((column or {}).get("column_name") or "")
    metadata: dict[str, Any] = {
        "column": resolved_name or None,
        "mode": mode,
        "search_present": True if _portal_database_first_param(params, "search", "").strip() else None,
    }
    if scope_entries is not None:
        # Validated targets only, and the faceted scope excludes the inspected
        # column, so it is named once under `column` rather than twice.
        metadata["filter_keys"] = sorted({
            str(entry.get("column_name") or "")
            for entry in scope_entries
            if str(entry.get("column_name") or "") not in ("", "__search__")
        })
    if not resolved_name and requested_column and PORTAL_DATABASE_IDENTIFIER_RE.fullmatch(requested_column):
        metadata["requested_column"] = requested_column
    if reason:
        metadata["reason"] = reason
    if requested_dataset_id:
        metadata["requested_dataset_id"] = requested_dataset_id
    return metadata


# ---------------------------------------------------------------------------
# Database Explorer system states (stage S9)
#
# Three failures the approved design keeps strictly apart (`PBC` 2.16/2.17,
# tone rule 3 — "separate 'you lack permission' from 'the system failed'"):
#
#   permission   the account may not open this dataset. Says nothing about the
#                dataset, so an unauthorized id and an unknown id look the same.
#   view         the account may open it, the source is fine, and the REQUESTED
#                VIEW is not one this dataset has. Never echoes the offending
#                value back; the URL is attacker-controlled input.
#   source       the account may open it, the view is valid, and the client
#                database could not answer. Carries the diagnostic trio.
#
# None of them renders a stack trace, an exception class, SQL, a DSN, or a
# physical schema/table. What the user gets for support is one server-generated
# reference which the audit trail carries too.
# ---------------------------------------------------------------------------

# The user-visible error classes. The value is what appears in the trio as
# `kod`; it names the failure class in the product's own terms, never the
# exception that produced it.
PORTAL_DATABASE_ERROR_CODES = {
    "timeout": "DB-TIMEOUT",
    "unavailable": "DB-UNAVAILABLE",
    "source": "DB-SOURCE",
}


def _portal_database_error_reference() -> str:
    """One server-generated support reference.

    Server-side only, so a reference can never be spoofed through the URL, and
    opaque, so it discloses nothing by itself. The same value goes into the
    audit event for the failure, which is what makes it correlatable without
    storing anything new about the query.
    """
    return uuid.uuid4().hex[:16]


def _portal_database_error_timestamp() -> str:
    """The trio's timestamp, in the business timezone the rest of the product uses."""
    # Through the shared module, not a local strftime. The format happened to
    # match, which is exactly how a second convention survives a standardisation.
    return portal_formats.format_datetime(now_business_tz())


def _portal_database_state_html(
    *,
    variant: str,
    badge: str = "",
    title: str = "",
    body_html: str = "",
    actions_html: str = "",
    diagnostics_html: str = "",
) -> str:
    """The approved empty/error state block.

    One component family for every state the sheet can be in, which is what the
    approved COMPONENT_CATALOG asks for: an empty state and an error state that
    differ in content and actions, not in structure.
    """
    # An empty result is a status, not an alert: nothing failed. Only the states
    # that report a failure interrupt (`ACCESSIBILITY_SPEC` §5).
    role = "status" if variant.startswith("empty") else "alert"
    badge_html = (
        f'<span class="db-state-badge lp-badge-technical">{_html(badge)}</span>' if badge else ""
    )
    return (
        f'<div class="db-state db-state-{_html(variant)}" role="{role}">'
        + badge_html
        + (f'<p class="db-state-title">{_html(title)}</p>' if title else "")
        + (f'<p class="db-state-body">{body_html}</p>' if body_html else "")
        + diagnostics_html
        + (f'<div class="db-state-actions">{actions_html}</div>' if actions_html else "")
        + "</div>"
    )


def _portal_database_state_action(label: str, href: str, *, primary: bool = False) -> str:
    classes = "db-state-action" + (" primary" if primary else "")
    return f'<a class="{classes}" href="{_html(href)}">{_html(label)}</a>'


def _portal_database_diagnostics_html(timestamp: str, reference: str, code: str) -> str:
    """The copyable diagnostic trio: timestamp, reference, code (`PBC` 2.16).

    Every part is server-generated. The copy button carries the reference and
    nothing else — no storage key, no identity, no query state.
    """
    return (
        f'<div class="db-state-diagnostics" aria-label="{_html(_tr("db.error.diagnostics_aria"))}">'
        f'<span class="db-state-diag lp-mono" data-db-error-timestamp>{_html(timestamp)}</span>'
        f'<span class="db-state-diag lp-mono" data-db-error-reference>'
        f'{_html(_tr("db.error.reference_label"))} {_html(reference)}</span>'
        f'<span class="db-state-diag lp-mono" data-db-error-code>'
        f'{_html(_tr("db.error.code_label"))} {_html(code)}</span>'
        "</div>"
    )


def _portal_database_catalogue_url() -> str:
    return "/user/database"


def _portal_database_unavailable_response(user: dict, *, status_code: int = 404) -> HTMLResponse:
    """`DB-61` / `PBC` 2.17 — a deep link the account may not open.

    Deliberately anonymous. It names no dataset, no client, no column count and
    no capability, because the caller supplied the identifier and an
    unauthorized id must stay indistinguishable from an unknown one. The status
    code is unchanged for the same reason: this is not the place to build an
    existence oracle so the copy can be more specific.
    """
    body = (
        '<section class="portal-panel db-state-panel">'
        + _portal_database_state_html(
            variant="access",
            badge=_tr("db.access.badge"),
            title=_tr("db.access.title"),
            body_html=_html(_tr("db.access.body")),
            actions_html=_portal_database_state_action(
                _tr("db.empty.back"), _portal_database_catalogue_url(), primary=True
            ),
        )
        + "</section>"
    )
    return _portal_layout(
        _tr("db.access.title"),
        body,
        user=user,
        portal_label="User Portal",
        active_key="database",
        nav_items=_portal_user_nav(),
        status_code=status_code,
        extra_assets=("css/data-grid.css",),
    )


def _portal_database_invalid_view_response(
    user: dict,
    dataset: dict,
    *,
    status_code: int = 400,
    reason: str = "view",
) -> HTMLResponse:
    """A malformed view of a dataset the account MAY open.

    Kept apart from both the permission state and the source error: the account
    has access and the source is healthy, so neither of those messages would be
    true. The rejected value is never echoed — it is attacker-controlled input,
    and the approved generic copy plus a route back to the canonical view is all
    the user can act on anyway. Validation itself is untouched: a rejected view
    is still rejected, never quietly widened into a broader query.
    """
    dataset_id = str(dataset.get("dataset_id") or "")
    if reason == "columns":
        # Nothing is wrong with the request: the catalog simply approves no
        # column yet. Saying "this view is invalid" here would be false.
        title = _tr("db.view.columns_title")
        badge = ""
        body_text = _tr("db.view.columns_body")
        actions = _portal_database_state_action(
            _tr("db.empty.back"), _portal_database_catalogue_url(), primary=True
        )
    else:
        title = _tr("db.view.title")
        badge = _tr("db.view.badge")
        body_text = _tr("db.view.body")
        actions = _portal_database_state_action(
            _tr("db.view.reset"), f"/user/database/datasets/{quote(dataset_id)}", primary=True
        ) + _portal_database_state_action(_tr("db.catalog.back"), _portal_database_catalogue_url())
    body = (
        '<section class="portal-panel db-state-panel">'
        + _portal_database_state_html(
            variant="view",
            badge=badge,
            title=title,
            body_html=_html(body_text),
            actions_html=actions,
        )
        + "</section>"
    )
    return _portal_layout(
        str(dataset.get("dataset_name") or title),
        body,
        user=user,
        portal_label="User Portal",
        active_key="database",
        nav_items=_portal_user_nav(),
        status_code=status_code,
        extra_assets=("css/data-grid.css",),
        context_client_name=str(dataset.get("client_display_name") or dataset.get("client_code") or ""),
        context_client_code=str(dataset.get("client_code") or ""),
        context_module_name=str(dataset.get("dataset_name") or ""),
        context_meta_html=f'<span class="lp-badge-technical">{_html(_tr("db.readonly"))}</span>',
    )


def _portal_database_classify_source_failure(exc: Exception) -> str:
    """Which user-visible failure class an exception belongs to.

    Only the class travels to the browser. An authorization failure never
    reaches here — it is refused before any query is built — so a source failure
    can never be presented as a permission problem or the other way round.
    """
    name = type(exc).__name__
    if name in {"QueryCanceled", "QueryCanceledError", "StatementTimeout"}:
        return "timeout"
    if name in {"PortalClientDatabaseConfigError", "PortalClientDatabaseConnectionError",
                "OperationalError", "InterfaceError", "ConnectionException",
                "CannotConnectNow", "AdminShutdown"}:
        return "unavailable"
    text = str(exc).lower()
    if "statement timeout" in text or "canceling statement" in text:
        return "timeout"
    return "source"


# The approved copy states the concrete cause where it is known, and the 15 s
# statement timeout on the client database is the one S9 can name. It mirrors
# the default in `_connect_portal_client_database`; S9 does not change it.
PORTAL_DATABASE_STATEMENT_TIMEOUT_LABEL = "15 s"


def _portal_database_source_error_html(
    failure_class: str,
    reference: str,
    *,
    retry_url: str,
    narrow_url: str = "",
) -> str:
    """`DB-011` — the data-source error state. The caller keeps the header rendered.

    Three actions, exactly as approved: `Ponów` re-requests the same canonical
    view (a link, never an automatic or background retry), `Zawęź filtrami`
    opens the filter panel on that same view, and `Skopiuj referencję` copies
    the server-generated reference. Nothing here is disabled: a state whose
    action set is empty would leave the user with no move at all.
    """
    if failure_class == "timeout":
        body_text = _tr("db.error.body.timeout", timeout=PORTAL_DATABASE_STATEMENT_TIMEOUT_LABEL)
    elif failure_class == "unavailable":
        body_text = _tr("db.error.body.unavailable")
    else:
        body_text = _tr("db.error.body.source")
    code = PORTAL_DATABASE_ERROR_CODES.get(failure_class, PORTAL_DATABASE_ERROR_CODES["source"])
    actions = _portal_database_state_action(_tr("db.error.retry"), retry_url, primary=True)
    if narrow_url:
        actions += _portal_database_state_action(_tr("db.error.narrow"), narrow_url)
    actions += (
        f'<button class="db-state-action" type="button" data-db-error-copy="{_html(reference)}">'
        f'{_html(_tr("db.error.copy_reference"))}</button>'
    )
    return _portal_database_state_html(
        variant="error",
        badge=_tr("db.error.badge"),
        title=_tr("db.error.title"),
        body_html=_html(body_text),
        diagnostics_html=_portal_database_diagnostics_html(
            _portal_database_error_timestamp(), reference, code
        ),
        actions_html=actions,
    )


def _portal_database_empty_state_html(
    *,
    dataset_id: str,
    params: dict[str, list[str]],
    chips: list[dict],
    search_value: str,
    reset_url: str,
    dataset_total: int | None,
    query_filtered: bool,
    diagnosis: dict | None,
) -> str:
    """`DB-010` / `DB-58` — the two zero-row states, which must never be confused.

    An unfiltered dataset with no rows is a fact about the dataset and blames
    nothing. A filtered result with no rows is a fact about the query, and the
    approved copy names the responsible constraint — but only when a count
    proved it responsible, and only when it is the ONLY one that restores rows.
    Every weaker evidence position gets a message that claims exactly as much as
    the evidence supports.
    """
    def _grouped(number: int) -> str:
        return _portal_database_group_digits(str(int(number)))

    if not query_filtered or dataset_total == 0:
        # Either nothing constrained the query, or the dataset itself is empty —
        # in which case no filter can be at fault however many are set.
        return _portal_database_state_html(
            variant="empty-dataset",
            title=_tr("db.empty.dataset.title"),
            body_html=_html(_tr("db.empty.dataset.body")),
            actions_html=_portal_database_state_action(
                _tr("db.empty.back"), _portal_database_catalogue_url(), primary=True
            ),
        )

    mode = str((diagnosis or {}).get("mode") or "generic")
    culprit_column = str((diagnosis or {}).get("column_name") or "")
    restored = (diagnosis or {}).get("restored")
    actions = ""
    body_html = ""

    if mode == "single" and restored is not None and dataset_total is not None:
        if culprit_column == "__search__":
            # The approved search terminology, never a parameter name. The term
            # is the user's own input and is escaped like every other value.
            filter_html = (
                f'<span class="db-state-filter lp-mono">{_html(_tr("db.empty.search_label"))} '
                f'{_html(search_value)}</span>'
            )
            body_html = _tr(
                "db.empty.filtered.body_search",
                total=_html(_grouped(dataset_total)),
                filter=filter_html,
                restored=_html(_grouped(int(restored))),
            )
            remove_url = _portal_database_url(dataset_id, params, search=None, page=1)
            actions = _portal_database_state_action(
                _tr("db.empty.filtered.remove_search"), remove_url, primary=True
            )
        else:
            chip = next((c for c in chips if str(c.get("column_name") or "") == culprit_column), None)
            if chip:
                # The chip text is the approved business label plus operator and
                # value — the same words the toolbar chip already shows, and never
                # a physical column or a `filter_exact__…` parameter name.
                filter_html = f'<span class="db-state-filter lp-mono">{_html(chip["text"])}</span>'
                body_html = _tr(
                    "db.empty.filtered.body",
                    total=_html(_grouped(dataset_total)),
                    filter=filter_html,
                    restored=_html(_grouped(int(restored))),
                )
                actions = _portal_database_state_action(
                    _tr("db.empty.filtered.remove", filter=chip["text"]),
                    str(chip["remove_url"]),
                    primary=True,
                )
            else:
                mode = "generic"

    if not body_html:
        if dataset_total is None:
            body_html = _html(_tr("db.empty.filtered.body_unknown"))
        elif mode == "multiple":
            body_html = _html(_tr("db.empty.filtered.body_multiple", total=_grouped(dataset_total)))
        elif mode == "joint":
            body_html = _html(_tr("db.empty.filtered.body_joint", total=_grouped(dataset_total)))
        else:
            body_html = _html(_tr("db.empty.filtered.body_generic", total=_grouped(dataset_total)))

    # `Wyczyść wszystkie` clears the query state only. The reset URL is built by
    # the same helper the toolbar uses, so column layout, density and page size
    # survive — removing a filter must not silently undo the user's S5 work.
    actions += _portal_database_state_action(_tr("db.clear_all"), reset_url)
    return _portal_database_state_html(
        variant="empty",
        title=_tr("db.empty.filtered.title"),
        body_html=body_html,
        actions_html=actions,
    )


def _portal_database_rows_error_response(user: dict, dataset: dict, message: str, *, status_code: int = 400) -> HTMLResponse:
    """Retained entry point for configuration failures of an accessible dataset.

    The caller's ``message`` is a server-side diagnosis (it can carry a column
    name, an operator the caller typed, or a validator sentence), so it is
    recorded in the audit trail by the caller and is deliberately NOT rendered.
    The user sees the approved generic state instead. The message is read for one
    thing only: whether this is the "no approved columns" case, which is a
    configuration fact rather than a bad request and must not be described as one.
    """
    reason = "columns" if "no visible columns" in str(message or "").lower() else "view"
    return _portal_database_invalid_view_response(user, dataset, status_code=status_code, reason=reason)


def _portal_database_export_error_response(user: dict, dataset: dict, message: str, *, status_code: int = 400) -> HTMLResponse:
    body = _portal_error_state("Export cannot be created", message)
    body += '<div class="portal-actions"><a class="portal-button secondary" href="/user/database">Back to datasets</a></div>'
    return _portal_layout(
        str(dataset.get("dataset_name") or "Database export"),
        body,
        user=user,
        portal_label="User Portal",
        active_key="database",
        nav_items=_portal_user_nav(),
        description="This export request cannot be completed with the current filters and export limits.",
        status_code=status_code,
    )


def _portal_database_row_browser_response(user: dict, dataset_id: str, request: Request | None, *, export_notice: str | None = None) -> HTMLResponse:
    params = _portal_database_query_params(request)
    actor_user_id = str(user.get("user_id") or "") or None
    dataset = _get_portal_database_dataset_for_user(dataset_id, str(user.get("user_id") or ""))
    if not dataset:
        _portal_audit_event_safe(
            event_type="database_dataset_access_denied",
            actor_user_id=actor_user_id,
            request=request,
            metadata=_portal_database_rows_metadata(page=None, limit=None, row_count=None, visible_column_count=None, params=params, reason="dataset_unavailable", requested_dataset_id=dataset_id),
        )
        return _portal_database_unavailable_response(user)
    columns = _get_portal_database_visible_columns(dataset_id)
    if not columns:
        _portal_audit_event_safe(
            event_type="database_rows_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata=_portal_database_rows_metadata(page=None, limit=None, row_count=None, visible_column_count=0, params=params, reason="no_visible_columns"),
        )
        return _portal_database_invalid_view_response(user, dataset, reason="columns")
    # `DB-008` panel intents, consumed here so they never ride into a generated
    # link. `colsel` marks a real selection submit, which is what makes an empty
    # selection refusable instead of indistinguishable from "no narrowing".
    selection_submitted = params.pop("colsel", None) is not None
    selection_refused = selection_submitted and not [
        value for value in (params.get("cols") or []) if str(value).strip()
    ]
    column_panel_open = params.pop("colpanel", None) is not None or selection_refused
    # `DB-011`'s `Zawęź filtrami` action. Consumed exactly like `colpanel`: it is
    # a one-shot panel intent, popped here so it never rides into a generated
    # link and never becomes part of the canonical view state.
    filter_panel_open = params.pop("dbfilters", None) is not None
    # Approved stage S13 outcome marker, consumed exactly like the panel
    # intents so it is shown once and never rides into a generated link.
    saved_notice_html = _portal_database_saved_notice_html(params)
    # ------------------------------------------------- saved objects (S13) --
    # Owner-scoped and dataset-scoped in the query, so `saved_views` can only
    # ever contain this account's views for this dataset. The `view` parameter
    # is resolved AGAINST THAT LIST: an id belonging to another account, to
    # another dataset, or to nothing at all simply fails to match and is dropped
    # from the canonical parameters, so it can neither be confirmed nor ride
    # into a generated link.
    saved_objects_available = _portal_preferences_schema_available()
    saved_views: list[dict] = []
    column_sets: list[dict] = []
    active_saved_view: dict | None = None
    if saved_objects_available:
        saved_views = _list_portal_saved_views_for_user(str(user.get("user_id") or ""), dataset_id)
        column_sets = _list_portal_column_sets_for_user(str(user.get("user_id") or ""), dataset_id)
        requested_view = _portal_database_first_param(params, PORTAL_DATABASE_SAVED_VIEW_PARAM, "").strip()
        if requested_view:
            active_saved_view = next(
                (view for view in saved_views if str(view.get("saved_view_id") or "") == requested_view),
                None,
            )
    if active_saved_view is None:
        params.pop(PORTAL_DATABASE_SAVED_VIEW_PARAM, None)
    else:
        params[PORTAL_DATABASE_SAVED_VIEW_PARAM] = [str(active_saved_view.get("saved_view_id") or "")]
    # Column narrowing, canonicalization and the S5 layout, all through the one
    # shared resolver (`_portal_database_resolve_display_state`): `cols` is
    # normalized to the resolved selection, column-scoped filter parameters are
    # intersected with the approved set so a crafted `filter__record_id=...`
    # cannot ride into a generated link, and order/width/pin state may only
    # rearrange what the narrowing already permitted. A saved view and a column
    # set resolve through the same function, so what is stored and what renders
    # can never be two different answers.
    (
        visible_columns,
        display_columns,
        layout,
        cols_fell_back,
        cols_active,
    ) = _portal_database_resolve_display_state(columns, params)
    # Approved stage S6. The configured technical row identifier is dataset
    # metadata, not a user column: it is read from its own authorized lookup and
    # is absent from `columns`, so it cannot be selected through `cols`, ordered
    # through `colorder`, sized, pinned, sorted, filtered or aggregated. It is
    # appended to the SELECT for one purpose — minting the opaque row reference
    # that makes a row linkable — and its value never reaches the response.
    try:
        row_identifier = _get_portal_database_row_identity_column(dataset_id)
    except Exception as exc:  # noqa: BLE001
        # Fail closed. If the identity cannot be established the sheet simply
        # offers no linkable row detail, which is the ordinary state for a
        # dataset without one — never a guessed identity and never a leak.
        print(f"portal database row identity lookup failed: {type(exc).__name__}")
        row_identifier = None
    identifier_name = str(row_identifier.get("column_name") or "") if row_identifier else ""
    query_columns = display_columns
    if row_identifier:
        query_columns = display_columns + [row_identifier]
    page, limit, page_error = _portal_database_parse_page_params(params)
    if page_error:
        _portal_audit_event_safe(
            event_type="database_rows_validation_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata=_portal_database_rows_metadata(page=None, limit=None, row_count=None, visible_column_count=len(columns), params=params, reason=page_error),
        )
        return _portal_database_invalid_view_response(user, dataset)
    offset = (page - 1) * limit
    # `DB-011` is rendered INSIDE the sheet rather than as a replacement page:
    # the approved contract keeps the table header, the client context and the
    # active filters visible through a source failure, so the user can still see
    # the shape of the data and act on the view they asked for.
    source_error = ""
    source_reference = ""
    rows: list[dict] = []
    total = 0
    state: dict = {}
    try:
        total, state, count_error = _count_portal_database_rows(dataset, columns, params)
        if count_error:
            _portal_audit_event_safe(
                event_type="database_rows_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata=_portal_database_rows_metadata(page=page, limit=limit, row_count=None, visible_column_count=len(columns), params=params, state=state, reason=count_error),
            )
            return _portal_database_rows_error_response(user, dataset, count_error)
        rows, row_state, row_error = _list_portal_database_rows(dataset, columns, params, limit=limit, offset=offset, display_columns=query_columns)
        state.update(row_state)
        if row_error:
            _portal_audit_event_safe(
                event_type="database_rows_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata=_portal_database_rows_metadata(page=page, limit=limit, row_count=None, visible_column_count=len(columns), params=params, state=state, reason=row_error),
            )
            return _portal_database_rows_error_response(user, dataset, row_error)
    except Exception as exc:
        exc_name = type(exc).__name__
        source_error = _portal_database_classify_source_failure(exc)
        source_reference = _portal_database_error_reference()
        print(f"portal database row query failed: {exc_name}: dataset_id={dataset_id} client_code={dataset.get('client_code')} ref={source_reference}")
        _portal_audit_event_safe(
            event_type="database_rows_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            # The reference the user is shown, so support can correlate it to
            # this event. The exception class stays here, in the audit trail —
            # it is never rendered.
            metadata=_portal_database_rows_metadata(page=page, limit=limit, row_count=None, visible_column_count=len(columns), params=params, reason=exc_name, extra={"error_reference": source_reference, "error_class": source_error}),
        )
        rows = []
        total = 0
        # The filter state is validated without touching the client database, so
        # it survives a source failure: the chips, the sort summary and the
        # filtered column headers stay exactly as the user left them.
        try:
            _query, _values, recovered_state, recovery_error = _build_portal_database_rows_query(
                dataset, columns, params, count=True
            )
            if not recovery_error:
                state = recovered_state
        except Exception as recovery_exc:  # noqa: BLE001
            print(f"portal database state recovery failed: {type(recovery_exc).__name__}")
    if not source_error:
        _portal_audit_event_safe(
            event_type="database_rows_viewed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata=_portal_database_rows_metadata(page=page, limit=limit, row_count=len(rows), visible_column_count=len(columns), params=params, state=state),
        )
    # --------------------------------------------------- open row (S6) --
    # `row` is resolved only after the ordinary authorization above has already
    # succeeded, so possession of a reference is never sufficient by itself. A
    # reference that does not open — tampered, malformed, minted for another
    # dataset or client, or pointing at a row that has since gone — produces one
    # generic unavailable state and is dropped from the canonical parameters so
    # it cannot ride into a generated link.
    open_row_reference = ""
    open_row_identity = None
    row_detail_unavailable = False
    requested_row_reference = _portal_database_first_param(params, PORTAL_DATABASE_ROW_PARAM, "").strip()
    if source_error:
        # The drawer reads one row from the same failing source. Attempting it
        # would only produce a second failure and a misleading "this row is
        # unavailable" panel on top of a state that already says why.
        requested_row_reference = ""
        params.pop(PORTAL_DATABASE_ROW_PARAM, None)
        params.pop(PORTAL_DATABASE_ROW_FIELDS_PARAM, None)
    if requested_row_reference:
        if not row_identifier:
            row_detail_unavailable = True
        else:
            open_row_identity = _portal_database_resolve_row_reference(
                dataset, identifier_name, requested_row_reference
            )
            if open_row_identity is None:
                row_detail_unavailable = True
                _portal_audit_event_safe(
                    event_type="database_rows_validation_failed",
                    actor_user_id=actor_user_id,
                    client_code=str(dataset.get("client_code") or "") or None,
                    dataset_id=str(dataset.get("dataset_id") or "") or None,
                    request=request,
                    # A safe category only: never the token, never the identity.
                    metadata=_portal_database_rows_metadata(page=page, limit=limit, row_count=None, visible_column_count=len(columns), params=params, reason="row_reference_invalid", extra={"row_detail": True, "row_reference_valid": False}),
                )
            else:
                open_row_reference = requested_row_reference
    if row_detail_unavailable:
        params.pop(PORTAL_DATABASE_ROW_PARAM, None)
        params.pop(PORTAL_DATABASE_ROW_FIELDS_PARAM, None)
    row_reference_open = bool(open_row_reference)
    # Canonicalize the field-scope mode against its allowlist. This runs whether
    # or not a row is open, so a crafted value cannot survive in the parameters
    # of a page that has no drawer at all; with no open row the parameter is
    # detail-only state and is dropped entirely rather than left stale.
    show_all_fields = _portal_database_resolve_row_fields_mode(params)
    if not row_reference_open:
        params.pop(PORTAL_DATABASE_ROW_FIELDS_PARAM, None)
        show_all_fields = False
    sort_column = state.get("sort")
    direction = state.get("direction") or "asc"
    # Normalize the sort parameters to the state the server actually validated,
    # exactly as `cols` is normalized above. Every link, form and export URL on
    # this page is built from `params`, so without this a sort identifier the
    # validator did not accept could keep riding along in generated URLs, and a
    # defaulted sort would stay invisible in a bookmarked link. Rejection is
    # unchanged and still happens in the query builder: this only decides what
    # the page emits after validation succeeded.
    if sort_column:
        params["sort"] = [str(sort_column)]
        params["direction"] = [str(direction)]
    else:
        params.pop("sort", None)
        params.pop("direction", None)
    density, density_locked = _portal_database_density(params)
    filter_entries = list(state.get("filter_entries") or [])
    chips = _portal_database_active_filter_chips(dataset, params, filter_entries)
    search_value = _portal_database_first_param(params, "search", "").strip()
    reset_url = _portal_database_reset_url(dataset_id, params)
    entry_by_column = {
        str(entry.get("column_name") or ""): entry
        for entry in filter_entries
        if str(entry.get("column_name") or "") != "__search__"
    }
    column_names = {
        str(column.get("column_name")): (column.get("display_name") or column.get("column_name"))
        for column in columns
    }

    # Two different questions, and they must not be conflated:
    #
    #   query_filtered   — did the VALIDATED query actually constrain the result?
    #                      This is the only sound basis for the row counts, the
    #                      empty state and the export scope.
    #   controls_active  — did the user TYPE something that the controls should
    #                      offer to clear? Raw input, so a value that turned out
    #                      to be a no-op can still be reset.
    #
    # `state["active_filters"]` is the query builder's own record of the
    # conditions it emitted. A search term against a dataset with no approved
    # searchable text columns produces no condition and no entry, so it must not
    # be treated as filtering — the result already IS the whole dataset.
    query_filtered = bool(state.get("active_filters"))
    controls_active = bool(chips) or bool(search_value)
    # The badge counts effective column filters only. Search is its own toolbar
    # field in the approved contract, not a chip, so it does not inflate it.
    active_filter_count = len(chips)

    # The approved counter distinguishes the filtered result from the size of the
    # dataset. When the query applied no conditions the two are the same number
    # and the second count would be pure waste.
    dataset_total: int | None = total
    if source_error:
        # Nothing about the size of this dataset is known while its source is
        # failing, and `0` is the one answer that must never be rendered: an
        # operational failure presented as "no rows" is a wrong answer, not a
        # degraded one.
        dataset_total = None
    elif query_filtered:
        dataset_total, total_error = _count_portal_database_rows_unfiltered(dataset, columns)
        if total_error:
            # The dataset size is genuinely unknown. Substituting the filtered
            # count here would render `1 274 z 1 274 wierszy` and assert that
            # the filters matched everything, which is false and is exactly the
            # kind of claim a data-verification tool must never make. Degrade to
            # an explicit unknown instead.
            dataset_total = None

    # ------------------------------------------- empty-result diagnosis (S9) --
    # `DB-010` only. It runs when the authorized query succeeded and returned
    # nothing while at least one validated constraint was active, so it costs
    # nothing on a populated sheet, nothing on an unfiltered one, and nothing at
    # all when the source failed.
    empty_diagnosis: dict | None = None
    if (
        not source_error
        and not rows
        and query_filtered
        and dataset_total not in (None, 0)
    ):
        empty_diagnosis = _portal_database_empty_result_diagnosis(
            dataset, columns, params, filter_entries
        )

    # ---------------------------------------------------------------- header --
    pins = layout["pins"]
    pin_offsets = layout["pin_offsets"]
    effective_widths = layout["effective_widths"]
    last_pin = pins[-1] if pins else ""

    def _layout_cell_attrs(column_name: str) -> tuple[list[str], str]:
        """Classes and the inline sticky offset for one column's cells.

        Pinning targets the column IDENTITY, never a DOM index: the same name
        decides the header cell, every body cell and the `<col>`, so reordering
        cannot leave a pin behind on whatever now occupies an old position.
        """
        classes: list[str] = []
        style = ""
        if column_name in pin_offsets:
            classes.append("db-sticky-col")
            if column_name == last_pin:
                classes.append("db-pin-edge")
            style = f' style="left:{pin_offsets[column_name]}px"'
        return classes, style

    header_cells = []
    for column in display_columns:
        column_name = str(column.get("column_name") or "")
        label = _html(column.get("display_name") or column_name)
        family = _portal_database_render_family(column)
        cell_classes, cell_style = _layout_cell_attrs(column_name)
        if family in {"integer", "decimal"}:
            cell_classes.append("db-num")
        elif family == "boolean":
            cell_classes.append("db-bool")
        entry = entry_by_column.get(column_name)
        if entry:
            # Non-colour marker as well as the tint, per ACCESSIBILITY_SPEC 3.
            cell_classes.append("db-col-filtered")
        class_attr = f' class="{" ".join(cell_classes)}"' if cell_classes else ""
        # `aria-sort` exposes the state to assistive technology; the caret and the
        # toolbar sentence are its visual and lexical carriers (`AC-6`). Only a
        # sortable column carries the attribute at all: `aria-sort="none"` on a
        # column that cannot be sorted advertises an affordance that does not
        # exist, so a non-sortable header states nothing rather than something
        # false. Exactly one header can own a non-`none` value, because the
        # canonical sort state holds exactly one column (`DB-23`).
        if not column.get("is_sortable"):
            aria_sort = ""
        elif sort_column == column_name:
            aria_sort = "descending" if direction == "desc" else "ascending"
        else:
            aria_sort = "none"
        aria_sort_attr = f' aria-sort="{aria_sort}"' if aria_sort else ""
        menu_html = _portal_database_column_menu_html(
            dataset, column, params, sort_column=sort_column, direction=direction, entry=entry,
            layout=layout, visible_columns=visible_columns, allowed_columns=columns, rows=rows,
        )
        resize_html = _portal_database_column_resize_handle_html(
            dataset_id, column, params, layout, visible_columns, rows
        )
        body_html = menu_html or f'<span class="db-col-label">{label}</span>'
        header_cells.append(
            f'<th scope="col" data-db-column="{_html(column_name)}"{class_attr}{cell_style}'
            f'{aria_sort_attr}>{body_html}{resize_html}</th>'
        )
    if row_identifier:
        header_cells.append(
            f'<th scope="col" class="db-detail-col">{_html(_tr("db.row.detail_column"))}</th>'
        )
    header_html = "<thead><tr>" + "".join(header_cells) + "</tr></thead>"

    # `table-layout: fixed` semantics (grid spec §1.7): the declared table width
    # is the sum of the column widths. A mismatch silently drops the last column
    # out of view, so the `<colgroup>` and the table width are built from one
    # number. The widths ship in the server response, which is what makes an S5
    # URL reconstruct its layout with no previous JavaScript session.
    col_tags = [
        f'<col data-db-column="{_html(name)}" style="width:{effective_widths[name]}px" '
        f'data-db-default-width="{_portal_database_column_render_width(column)}">'
        for name, column in zip(layout["display_names"], display_columns)
    ]
    table_width = layout["table_width"]
    if row_identifier:
        col_tags.append(
            f'<col class="db-detail-col" style="width:{PORTAL_DATABASE_DETAIL_COLUMN_WIDTH_PX}px">'
        )
        table_width += PORTAL_DATABASE_DETAIL_COLUMN_WIDTH_PX
    colgroup_html = "<colgroup>" + "".join(col_tags) + "</colgroup>"

    # ------------------------------------------------------------------ body --
    body_rows = []
    # Traversal (`DB-37`) walks the references already minted for the rendered
    # page, so `↑`/`↓` move between real row identities and never between array
    # positions or offsets.
    page_row_references: list[str] = []
    open_row_position = -1
    for row in rows:
        cells = []
        for column in display_columns:
            column_name = str(column.get("column_name") or "")
            cell = _portal_database_cell_html(row.get(column_name), column)
            # Every body cell carries its column identity and, when pinned, the
            # same cumulative offset the header uses. Reordering therefore moves
            # a whole column: header, cells and sticky geometry together.
            cell_classes, cell_style = _layout_cell_attrs(column_name)
            marker = f' data-db-column="{_html(column_name)}"{cell_style}'
            if cell_classes:
                if cell.startswith('<td class="'):
                    cell = cell.replace('<td class="', f'<td{marker} class="{" ".join(cell_classes)} ', 1)
                else:
                    cell = cell.replace("<td", f'<td{marker} class="{" ".join(cell_classes)}"', 1)
            else:
                cell = cell.replace("<td", f"<td{marker}", 1)
            cells.append(cell)
        row_reference = ""
        row_is_open = False
        if row_identifier:
            # The raw identity is consumed here and goes no further. What the
            # response carries is the AES-GCM reference bound to this dataset,
            # client and identifier column; the identity itself never enters the
            # markup, a data attribute, a label or the URL.
            #
            # Each reference carries a fresh nonce, so two references for the same
            # row are not equal. The open row is therefore recognised by comparing
            # the resolved identity, never by comparing tokens — and it re-uses the
            # token the URL already carries, so the address bar and the rendered
            # drawer name the same reference.
            identity_value = row.get(identifier_name)
            row_is_open = (
                open_row_identity is not None
                and identity_value is not None
                and str(identity_value) == open_row_identity
            )
            row_reference = (
                open_row_reference
                if row_is_open
                else _portal_database_build_row_reference(dataset, identifier_name, identity_value)
            )
            if not row_reference:
                cells.append('<td class="db-detail-col"><span class="db-v db-v-null">' + _html(_tr("db.value.null")) + "</span></td>")
            else:
                detail_href = _portal_database_row_url(dataset_id, params, row_reference)
                open_label = _tr("db.row.open")
                cells.append(
                    f'<td class="db-detail-col"><a class="portal-link db-row-open" '
                    f'href="{_html(detail_href)}" data-db-row-open>{_html(open_label)}</a></td>'
                )
        row_attrs = ""
        if row_reference:
            if row_is_open:
                open_row_position = len(page_row_references)
            page_row_references.append(row_reference)
            selected = " db-row-selected" if row_is_open else ""
            row_attrs = (
                f' data-db-row="{_html(row_reference)}"'
                + (f' class="db-row{selected}"' if selected else ' class="db-row"')
                + (' aria-selected="true"' if selected else "")
            )
        body_rows.append(f"<tr{row_attrs}>" + "".join(cells) + "</tr>")

    table_caption = _tr(
        "db.table.aria_label",
        dataset=str(dataset.get("dataset_name") or ""),
        client=str(dataset.get("client_display_name") or dataset.get("client_code") or ""),
    )
    if body_rows:
        table_body = "<tbody>" + "".join(body_rows) + "</tbody>"
        empty_html = ""
    elif source_error:
        # The header stays rendered through the failure too (`TGS` §6): the user
        # keeps the shape of the data and the view they asked for, and the state
        # says plainly that the permissions are not the problem.
        table_body = "<tbody></tbody>"
        empty_html = _portal_database_source_error_html(
            source_error,
            source_reference,
            retry_url=_portal_database_url(dataset_id, params),
            narrow_url=(
                _portal_database_url(dataset_id, params, dbfilters=1) + "#db-filters"
                if dataset.get("can_filter_rows")
                else ""
            ),
        )
    else:
        # The header stays rendered with no rows: keeping the shape of the data
        # is what separates "nothing matched" from "something is broken".
        table_body = "<tbody></tbody>"
        empty_html = _portal_database_empty_state_html(
            dataset_id=dataset_id,
            params=params,
            chips=chips,
            search_value=search_value,
            reset_url=reset_url,
            dataset_total=dataset_total,
            query_filtered=query_filtered,
            diagnosis=empty_diagnosis,
        )
    # ------------------------------------------------- row detail (DB-006) --
    # The drawer is server-rendered from the resolved reference, so a copied URL
    # reconstructs it with no previous JavaScript session and the browser never
    # has to decode anything. Its fields come from `columns` — the approved
    # user-visible set the technical identity is already excluded from — so the
    # identifier cannot appear here even when it is what addressed the row.
    row_detail_html = ""
    if row_detail_unavailable:
        row_detail_html = _portal_database_row_unavailable_html()
    elif open_row_reference and open_row_identity is not None:
        record, detail_failure = _portal_database_fetch_row_by_identity(
            dataset, columns, identifier_name, open_row_identity
        )
        if detail_failure or record is None:
            # Not found, non-unique, or an unavailable source: one generic state,
            # and the sheet behind it stays usable.
            row_detail_html = _portal_database_row_unavailable_html()
            params.pop(PORTAL_DATABASE_ROW_PARAM, None)
            params.pop(PORTAL_DATABASE_ROW_FIELDS_PARAM, None)
            _portal_audit_event_safe(
                event_type="database_rows_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata=_portal_database_rows_metadata(page=page, limit=limit, row_count=None, visible_column_count=len(columns), params=params, reason=f"row_detail_{detail_failure or 'unavailable'}", extra={"row_detail": True, "row_found": False}),
            )
        else:
            row_detail_html = _portal_database_row_detail_panel_html(
                dataset_id=dataset_id,
                params=params,
                columns=columns,
                visible_columns=display_columns,
                record=record,
                row_reference=open_row_reference,
                page_row_references=page_row_references,
                position=open_row_position,
                show_all_fields=show_all_fields,
            )
            _portal_audit_event_safe(
                event_type="database_rows_viewed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                # No identity, no token, no business values — only that one row
                # was disclosed through the detail surface.
                metadata=_portal_database_rows_metadata(page=page, limit=1, row_count=1, visible_column_count=len(columns), params=params, extra={"row_detail": True, "row_identifier_configured": True, "row_found": True}),
            )

    table_html = (
        '<div class="db-sheet' + (" has-row-detail" if row_detail_html else "") + '">'
        '<div class="db-table-viewport">'
        '<div class="db-table-scroll" data-db-scroll>'
        f'<table class="db-table" style="width:{table_width}px" '
        f'aria-label="{_html(table_caption)}">{colgroup_html}{header_html}{table_body}</table>'
        f"{empty_html}"
        "</div>"
        '<span class="db-scroll-fade" aria-hidden="true"></span>'
        "</div>"
        f"{row_detail_html}"
        "</div>"
    )

    # --------------------------------------------------------------- toolbar --
    search_columns = _portal_database_search_columns(columns)
    search_html = ""
    if dataset.get("can_filter_rows") and search_columns:
        search_hidden = _portal_database_hidden_param_inputs(params, exclude={"search", "page"})
        placeholder = _tr("db.search.placeholder", count=len(search_columns))
        search_html = (
            '<form class="db-toolbar-search" method="get" role="search">'
            + search_hidden
            + f'<label class="lp-visually-hidden" for="db-toolbar-search">{_html(placeholder)}</label>'
            f'<input id="db-toolbar-search" name="search" type="search" value="{_html(search_value)}" '
            f'placeholder="{_html(placeholder)}">'
            f'<button class="db-tool-button" type="submit">{_html(_tr("db.search.submit"))}</button>'
            "</form>"
        )

    # `Filtry n` is the filter panel's own <summary>: collapsed, only the toolbar
    # button remains; expanded, the panel docks beside the table. A <details>
    # carries that with no script at all, which is what keeps the panel usable
    # when JavaScript is unavailable.
    filters_badge = (
        f'<span class="db-count-badge">{active_filter_count}</span>' if active_filter_count else ""
    )
    filter_panel_html = _portal_database_filter_panel(
        dataset, columns, params, filter_entries, chips,
        menu_columns={str(column.get("column_name") or "") for column in display_columns},
    )
    filters_button = ""
    if filter_panel_html:
        filters_button = (
            '<details class="db-filters" id="db-filters" data-db-filters'
            + (" open" if filter_panel_open else "")
            + ">"
            f'<summary class="db-tool-button db-filters-trigger">{_html(_tr("db.filters"))}{filters_badge}</summary>'
            f"{filter_panel_html}</details>"
        )
    columns_button = _portal_database_column_panel(
        dataset, columns, visible_columns, layout, params,
        open_panel=column_panel_open, selection_refused=selection_refused,
        column_sets=column_sets if saved_objects_available else None,
    )

    # Density is a link so it works without scripting; data-grid.js intercepts
    # the click and switches in place, which is what keeps filters, sort, page
    # and scroll position intact.
    density_options = []
    for mode, label_key in (("compact", "db.density.compact"), ("comfortable", "db.density.comfortable")):
        pressed = "true" if mode == density else "false"
        href = _portal_database_url(dataset_id, params, density=mode)
        density_options.append(
            f'<a class="db-density-option" href="{_html(href)}" data-density-option="{mode}" '
            f'aria-pressed="{pressed}">{_html(_tr(label_key))}</a>'
        )
    density_html = (
        f'<div class="db-density" role="group" aria-label="{_html(_tr("db.density.group"))}">'
        + "".join(density_options)
        + "</div>"
    )

    def _grouped(number: int) -> str:
        return _portal_database_group_digits(str(int(number)))

    if source_error:
        # Both counts are unknown, and they are rendered as unknown. The sheet
        # must not assert a number it did not get.
        counter_text = (
            f'<span class="db-counter-unknown" '
            f'title="{_html(_tr("db.counter.total_unavailable"))}">'
            f'{_html(_tr("db.counter.unknown"))}</span> '
            f"{_html(_tr('db.counter.rows'))}"
        )
    elif query_filtered and dataset_total is None:
        # Honest degradation: the match count is known, the dataset size is not.
        counter_text = (
            f'<strong>{_html(_grouped(total))}</strong> {_html(_tr("db.counter.of"))} '
            f'<span class="db-counter-unknown" '
            f'title="{_html(_tr("db.counter.total_unavailable"))}">'
            f'{_html(_tr("db.counter.unknown"))}</span> '
            f"{_html(_tr('db.counter.rows'))}"
        )
    elif query_filtered:
        counter_text = (
            f'<strong>{_html(_grouped(total))}</strong> {_html(_tr("db.counter.of"))} '
            f"{_html(_grouped(dataset_total))} {_html(_tr('db.counter.rows'))}"
        )
    else:
        counter_text = f'<strong>{_html(_grouped(total))}</strong> {_html(_tr("db.counter.rows"))}'
    counter_html = f'<span class="db-counter" role="status">{counter_text}</span>'

    sort_summary_html = ""
    if sort_column:
        glyph = "\u2193" if direction == "desc" else "\u2191"
        sort_summary_html = (
            f'<span class="db-sort-summary">{_html(_tr("db.sort.summary"))} '
            f"{_html(column_names.get(sort_column, sort_column))} {_html(glyph)}</span>"
        )

    # The chips ride inside the toolbar band rather than in a strip below it.
    # An extra band would push the table header past the approved 168 px the
    # moment a filter was applied, so the sheet would change shape exactly when
    # the user started working (`DB-1`). The strip scrolls horizontally instead.
    chip_strip_html = _portal_database_chip_strip_html(chips)
    toolbar_html = (
        f'<div class="db-toolbar" role="group" aria-label="{_html(_tr("db.toolbar.aria_label"))}">'
        + f'<div class="db-toolbar-group">{search_html}{filters_button}{columns_button}{density_html}</div>'
        + (chip_strip_html or '<div class="db-toolbar-spacer"></div>')
        + f'<div class="db-toolbar-group">{counter_html}{sort_summary_html}</div>'
        + "</div>"
    )

    # ---------------------------------------------------------------- footer --
    # With no answer from the source there is no page count either; the pager
    # keeps the page the user asked for rather than claiming a total.
    total_pages = max(1, page) if source_error else max(1, (total + limit - 1) // limit)
    pager_parts = []
    if page > 1:
        prev_link = _portal_database_url(dataset_id, params, page=page - 1, limit=limit)
        pager_parts.append(
            f'<a class="db-page-button" href="{_html(prev_link)}" '
            f'aria-label="{_html(_tr("db.page.previous"))}">\u2039</a>'
        )
    pager_parts.append(
        f'<span class="db-page-indicator">{_html(_tr("db.page.indicator", page=page, pages=total_pages))}</span>'
    )
    if page < total_pages:
        next_link = _portal_database_url(dataset_id, params, page=page + 1, limit=limit)
        pager_parts.append(
            f'<a class="db-page-button" href="{_html(next_link)}" '
            f'aria-label="{_html(_tr("db.page.next"))}">\u203a</a>'
        )
    size_links = []
    for size in _portal_database_page_size_options(limit):
        href = _portal_database_url(dataset_id, params, limit=size, page=1)
        current = ' aria-current="true"' if size == limit else ""
        size_links.append(f'<a class="db-size" href="{_html(href)}"{current}>{size}</a>')
    # Selection state supplements the footer; it never replaces the row count,
    # the pager or the page-size controls (`COMPONENT_CATALOG.md`: the selection
    # counter is hidden at zero). The count element ships empty and hidden — a
    # cold page has no selection, and S7 state is deliberately never persisted.
    selection_html = (
        f'<span class="db-select-count" data-db-select-count hidden></span>'
        + f'<span class="db-select-hint">{_html(_tr("db.select.hint"))}</span>'
        + f'<span class="lp-visually-hidden" role="status" aria-live="polite" '
        + f'aria-label="{_html(_tr("db.select.status_aria"))}" data-db-select-status></span>'
    )
    # THE ZONE THIS GRID'S TIMES ARE IN, stated rather than assumed.
    #
    # Rendered timestamps carry no offset, and this grid shows arbitrary client
    # timestamps -- around 300 of them on a full page. During the autumn DST
    # fold two instants an hour apart render identically, which the owner
    # accepted on 2026-08-20; what makes that acceptable is that the surface
    # says which zone it means. Since the clipboard now carries the displayed
    # value rather than the source, this note and the cell's own `title` are
    # where the exact instant remains available.
    #
    # The zone is READ FROM CONFIGURATION, never written into the sentence, so
    # this cannot quietly become false the way a hardcoded one would.
    timezone_note_html = (
        '<p class="db-scope-note">'
        + _html(
            "Znaczniki czasu są podane w formacie dd.mm.rrrr gg:mm:ss "
            f"w strefie czasowej {portal_formats.timezone_label()}. "
            "Dokładna wartość źródłowa (z przesunięciem strefy) jest dostępna "
            "w podpowiedzi komórki."
        )
        + "</p>"
    )
    footer_html = (
        f'<div class="db-footer" aria-label="{_html(_tr("db.footer.aria_label"))}">'
        + f'<div class="db-pager">{"".join(pager_parts)}</div>'
        + '<div class="db-toolbar-spacer"></div>'
        + selection_html
        + '<div class="db-page-size">'
        + f'<span class="db-page-size-label">{_html(_tr("db.rows_per_page"))}</span>'
        + "".join(size_links)
        + "</div></div>"
    )

    # ------------------------------------------------------- demoted controls --
    # The column picker and export controls still work unchanged; they simply do
    # not sit between the user and the data. Filtering no longer appears here at
    # all: it lives in the column menus and the filter panel.
    async_export_schema_available = _database_export_schema_available()

    if source_error:
        # No count from the source means no truthful scope count either, and an
        # export panel that says `0 wierszy` would restate an operational
        # failure as an empty dataset. The panel is absent for this render only.
        secondary_html = ""
    elif dataset.get("can_export_rows"):
        # `DB-54`: the panel exists only where the grant allows export. Where it
        # does not, the action is absent from the page — not disabled — and the
        # server still refuses a forged POST independently.
        secondary_html = _portal_database_export_panel_html(
            dataset,
            params,
            columns=columns,
            display_columns=display_columns,
            filtered_total=total,
            dataset_total=dataset_total,
            row_identifier=row_identifier,
            async_available=async_export_schema_available,
        )
    else:
        # `DB-54`: the export *action* is absent, not disabled. The demoted
        # section still states why, because a silently missing capability is
        # indistinguishable from a broken page — but it carries no form, no
        # submit and no scope choice, and the server refuses a forged POST
        # regardless of what this renders.
        secondary_html = (
            '<div class="db-secondary">'
            '<div class="db-secondary-body">'
            '<p class="db-export-note portal-muted">'
            f'{_html(_tr("db.export.absent"))}</p>'
            "</div></div>"
        )

    # --------------------------------------------------------------- notices --
    queued_notice = ""
    if export_notice:
        queued_notice = f'<div class="portal-callout">{_html(export_notice)}</div>'
    queued_job_id = _portal_database_first_param(params, "export_job_queued", "").strip()
    if not queued_notice and queued_job_id and async_export_schema_available:
        job = _get_database_export_job_for_user(queued_job_id, str(user.get("user_id") or ""))
        if job:
            queued_notice = (
                '<div class="portal-callout success">Background export queued. Track it in '
                '<a class="portal-link" href="/user/database/exports">My background exports</a>.</div>'
            )
    fallback_notice = ""
    if cols_fell_back:
        fallback_notice = (
            '<div class="portal-callout">The requested columns were not recognised, '
            "so all approved columns are shown.</div>"
        )

    # ----------------------------------------------------------- context bar --
    physical_table = ".".join(
        part for part in (str(dataset.get("schema_name") or ""), str(dataset.get("table_name") or "")) if part
    )
    context_meta_parts = [
        f'<span class="lp-badge-technical">{_html(_tr("db.readonly"))}</span>',
    ]
    if physical_table:
        # RESPONSIVE_SPEC "Client context bar": the physical table name and the
        # approved-column count are hidden below 1280 px. The classes are what
        # the stylesheet keys on; the client name, the client code and
        # `TYLKO ODCZYT` carry no such class and never degrade.
        context_meta_parts.append(
            f'<span class="lp-mono lp-context-physical" lang="en">{_html(physical_table)}</span>'
        )
    context_meta_parts.append(
        f'<span class="lp-context-colcount">{len(columns)} {_html(_tr("db.approved_columns"))}</span>'
    )
    context_meta_html = "".join(context_meta_parts)

    header_action_parts = []
    if saved_objects_available:
        # `DB-003`: the saved-view selector belongs to the client context bar,
        # beside `Zapisz zmiany` and `Eksport`. `modified` is derived by
        # comparing the CURRENT canonical document with the stored one, so it
        # reports an actual difference in view state rather than a click count.
        saved_view_modified = False
        if active_saved_view is not None:
            stored_document = _portal_saved_state_document(active_saved_view.get("view_state_json"))
            current_document, _current_error = _portal_database_canonical_view_state(
                dataset, columns, params, layout, visible_columns
            )
            saved_view_modified = (
                stored_document is None
                or current_document is None
                or json.dumps(stored_document, sort_keys=True, ensure_ascii=False)
                != json.dumps(current_document, sort_keys=True, ensure_ascii=False)
            )
        header_action_parts.append(
            _portal_database_saved_view_panel_html(
                dataset_id,
                params,
                saved_views,
                active_view=active_saved_view,
                modified=saved_view_modified,
            )
        )
    if controls_active:
        header_action_parts.append(
            f'<a class="portal-button secondary" href="{_html(reset_url)}">{_html(_tr("db.clear_all"))}</a>'
        )
    if cols_active or layout["canonical_order"] or layout["widths"] or layout["pin_explicit"]:
        header_action_parts.append(
            f'<a class="portal-button secondary" '
            f'href="{_html(_portal_database_reset_columns_url(dataset_id, params))}">'
            f'{_html(_tr("db.cols.reset"))}</a>'
        )
    if async_export_schema_available:
        header_action_parts.append(
            f'<a class="portal-button secondary" href="/user/database/exports">{_html(_tr("db.catalog.exports"))}</a>'
        )
    header_action_parts.append(
        f'<a class="portal-button secondary" href="/user/database">{_html(_tr("db.catalog.back"))}</a>'
    )
    header_actions = "".join(header_action_parts)

    # ------------------------------------------------------------------ body --
    locked_attr = " data-density-locked" if density_locked else ""
    # The approved default is stated explicitly: when the URL pins a density the
    # rendered value is not the default, so the script cannot infer it from the
    # DOM, and it needs it to resolve a history entry that carries no density.
    # `RSP-003` (<768 px). Server-rendered but shipped `hidden`: the viewport is
    # a client fact, and `data-grid-responsive.js` is what reveals it. With
    # scripting unavailable nothing changes — the table renders as it always
    # has, which is honest, rather than an advisory whose escape hatch is dead.
    # The advisory carries no dataset rows and no business values.
    narrow_advisory_html = (
        '<section class="db-narrow-advisory" data-db-narrow-advisory hidden '
        'aria-labelledby="db-narrow-title">'
        f'<p class="db-narrow-eyebrow">{_html(_tr("db.narrow.eyebrow"))}</p>'
        f'<h2 class="db-narrow-title" id="db-narrow-title" tabindex="-1">'
        f'{_html(_tr("db.narrow.title"))}</h2>'
        f'<p class="db-narrow-body">{_html(_tr("db.narrow.body", count=len(columns)))}</p>'
        '<div class="db-narrow-actions">'
        f'<a class="db-narrow-action primary" href="/user/reports">'
        f'{_html(_tr("db.narrow.to_reports"))}</a>'
        f'<button class="db-narrow-action" type="button" data-db-narrow-accept>'
        f'{_html(_tr("db.narrow.open_anyway"))}</button>'
        "</div>"
        f'<p class="db-narrow-footnote">{_html(_tr("db.narrow.footnote"))}</p>'
        "</section>"
    )

    body = (
        saved_notice_html
        + queued_notice
        + fallback_notice
        + narrow_advisory_html
        + f'<div class="db-browser db-sheet db-density-{density}" data-db-sheet data-density="{density}"'
        + f' data-density-default="{PORTAL_DATABASE_DEFAULT_DENSITY}"'
        + f' data-col-catalog="{_html(",".join(str(column.get("column_name") or "") for column in visible_columns))}"'
        + f' data-db-page-size="{limit}"'
        + f' data-col-min-width="{PORTAL_DATABASE_COLUMN_MIN_WIDTH_PX}"'
        + f' data-col-max-width="{PORTAL_DATABASE_COLUMN_MAX_WIDTH_PX}"'
        + f' data-col-max-pins="{PORTAL_DATABASE_MAX_PINNED_COLUMNS}"'
        + f' data-col-pin-fraction="{PORTAL_DATABASE_PINNED_VIEWPORT_FRACTION}"'
        + f' data-col-pin-max-width="{PORTAL_DATABASE_MAX_PINNED_WIDTH_PX}"'
        + f' data-col-autofit-char="{PORTAL_DATABASE_COLUMN_AUTOFIT_CHAR_PX}"'
        + f' data-col-autofit-padding="{PORTAL_DATABASE_COLUMN_AUTOFIT_PADDING_PX}"'
        + f' data-db-strings="{_html(_portal_database_column_strings())}"'
        + f' data-db-select-min-width="{PORTAL_DATABASE_SELECTION_MIN_WIDTH_PX}"'
        + f' data-db-select-strings="{_html(_portal_database_selection_strings())}"{locked_attr}>'
        + toolbar_html
        + table_html
        + footer_html
        + timezone_note_html
        + "</div>"
        + secondary_html
    )
    return _portal_layout(
        str(dataset.get("dataset_name") or "Database dataset"),
        body,
        user=user,
        portal_label="User Portal",
        active_key="database",
        nav_items=_portal_user_nav(include_database_exports=async_export_schema_available),
        description="Browse approved rows for this dataset. Only administrator-approved columns are visible. Filters and sorting are restricted to approved fields.",
        extra_assets=(
            "css/data-grid.css",
            "css/grid-selection.css",
            "js/data-grid.js",
            "js/data-grid-filters.js",
            "js/data-grid-daterange.js",
            "js/data-grid-distribution.js",
            "js/data-grid-columns.js",
            "js/data-grid-row-detail.js",
            "js/data-grid-selection.js",
            "js/data-grid-export.js",
            "js/data-grid-states.js",
            "js/data-grid-responsive.js",
        ),
        content_class="lp-work-flush",
        # A source failure is still a failed request. The approved state is
        # rendered in the body — header, context and filters intact — but the
        # status keeps saying that the upstream did not answer.
        status_code=502 if source_error else 200,
        header_actions=header_actions,
        context_client_name=str(dataset.get("client_display_name") or dataset.get("client_code") or ""),
        context_client_code=str(dataset.get("client_code") or ""),
        context_module_name=str(dataset.get("dataset_name") or ""),
        context_meta_html=context_meta_html,
    )


# Approved operator vocabulary (COPY_AND_TERMINOLOGY.md 3.1). Resolved through
# the translation catalogue so the labels live where every other user-facing
# string does.
PORTAL_DATABASE_OPERATOR_TOKENS = (
    "contains", "eq", "neq", "gt", "gte", "lt", "lte", "between", "blank", "in",
    "is_true", "is_false", "older", "newer", "range", "search",
)

PORTAL_DATABASE_PAGE_SIZE_OPTIONS = (25, 50, 100, 200, 500)


def _portal_database_operator_label(operator: str | None) -> str:
    text = str(operator or "").strip().lower()
    if text not in PORTAL_DATABASE_OPERATOR_TOKENS:
        return text or _tr("db.op.eq")
    return _tr(f"db.op.{text}")


def _portal_database_filter_value_text(entry: dict) -> str:
    """Human-readable value for one validated filter, as chips and panel show it."""
    operator = str(entry.get("operator") or "")
    if operator in PORTAL_DATABASE_VALUELESS_OPERATORS:
        return ""
    if operator == "in":
        # Approved chip form: `Kierowca in (3)` — the count, not the list.
        return f"({len(entry.get('values') or [])})"
    if operator in {"between", "range"}:
        low = str(entry.get("value") or "").strip()
        high = str(entry.get("value_to") or "").strip()
        # An open-ended bound is stated as an ellipsis rather than omitted, so a
        # one-sided range never reads as an exact value.
        return f"{low or '…'} – {high or '…'}"
    return str(entry.get("value") or "")


def _portal_database_filter_chip_text(entry: dict) -> str:
    """`<column> <operator> <value>` — the chip's own words, reused as its name."""
    parts = [str(entry.get("label") or entry.get("column_name") or ""), _portal_database_operator_label(entry.get("operator"))]
    value_text = _portal_database_filter_value_text(entry)
    if value_text:
        parts.append(value_text)
    return " ".join(part for part in parts if part)


def _portal_database_date_input_type(column: dict) -> str:
    return "datetime-local" if _portal_database_is_timestamp_column(column) else "date"


def _portal_database_is_timestamp_column(column: dict) -> bool:
    text = str(column.get("data_type") or "").strip().lower()
    return "timestamp" in text or text.startswith("time")


def _portal_database_search_columns(columns: list[dict]) -> list[dict]:
    # Search only spans visible, filterable, text-family columns; this respects the
    # admin filter configuration and never reaches hidden or non-text columns.
    return [
        column
        for column in columns
        if column.get("is_filterable") and _portal_database_type_family(column.get("data_type")) == "text"
    ]


PORTAL_DATABASE_DENSITIES = ("compact", "comfortable")
# The approved default is `Zwarta` (32 px rows): the product is an operational
# data sheet, and the dense mode is what makes a screenful of rows scannable.
PORTAL_DATABASE_DEFAULT_DENSITY = "compact"


def _portal_database_density(params: dict[str, list[str]]) -> tuple[str, bool]:
    """Resolve row density, and report whether the URL pinned it.

    Precedence, in this order:

      1. an explicit ``density`` in the URL — a shared or bookmarked link keeps
         showing what its author saw, so existing deep links do not change
         meaning;
      2. the browser-local preference — applied by ``data-grid.js``, because
         only the browser knows it;
      3. the approved default, ``Zwarta``.

    The server can only decide between (1) and (3); it returns ``locked=True``
    for case (1) so the script knows not to override an explicit choice.
    """
    raw = _portal_database_first_param(params, "density", "").strip().lower()
    if raw in PORTAL_DATABASE_DENSITIES:
        return raw, True
    return PORTAL_DATABASE_DEFAULT_DENSITY, False


def _portal_database_reset_url(dataset_id: str, params: dict[str, list[str]]) -> str:
    # "Reset filters" intentionally PRESERVES sort, direction, page size, density and
    # column selection; it only clears column filters, the date range and search and
    # returns to page 1.
    keep: dict[str, list[str]] = {}
    # Column layout rides along untouched: visibility, order, width and pin state
    # are presentation, and clearing filters must not rearrange the sheet the
    # user built. `colpin` is copied even when empty, because a present-but-empty
    # value is the explicit "nothing pinned" state.
    for key in ("sort", "direction", "limit", "density", "colorder", "colw", "colpin"):
        if key in ("colpin",) and key in params:
            keep[key] = [_portal_database_first_param(params, key, "")]
            continue
        value = _portal_database_first_param(params, key, "")
        if value:
            keep[key] = [value]
    # `cols` is repeated, one parameter per visible column, so it must be copied
    # as a list. Reading it as a scalar kept only the last entry and silently
    # hid every other column the user had chosen — clearing filters must not
    # change the column selection at all.
    selected_columns = [str(value) for value in (params.get("cols") or []) if str(value).strip()]
    if selected_columns:
        keep["cols"] = selected_columns
    query = urlencode(keep, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}" + (f"?{query}" if query else "")


# Non-breaking space: the approved thousands separator. A normal space would
# let a number wrap mid-value at a column edge.
PORTAL_DATABASE_GROUP_SEPARATOR = "\u00a0"


def _portal_database_render_family(column: dict | None) -> str:
    """Presentation-only data family for a column.

    Deliberately separate from ``_portal_database_type_family``, which drives
    filter operator selection and the searchable-column set. That function maps
    uuid/json/boolean all onto "text"; correcting it here would silently change
    which operators a column offers and which columns the global search reaches,
    and query semantics are explicitly out of scope for this stage.
    """
    text = str((column or {}).get("data_type") or "").strip().lower()
    if not text:
        return "text"
    if "bool" in text:
        return "boolean"
    if "uuid" in text:
        return "uuid"
    if "json" in text:
        return "json"
    # timestamp before date: "timestamp with time zone" must not read as a date.
    if "timestamp" in text or text.startswith("time"):
        return "timestamp"
    if "date" in text:
        return "date"
    if any(token in text for token in ("smallint", "integer", "bigint", "int2", "int4", "int8", "serial")):
        return "integer"
    if any(token in text for token in ("numeric", "decimal", "double", "real", "float", "money")):
        return "decimal"
    return "text"


def _portal_database_group_digits(digits: str) -> str:
    """Group an integer digit string in threes with the approved separator."""
    sign = ""
    if digits.startswith("-"):
        sign, digits = "-", digits[1:]
    grouped = ""
    while len(digits) > 3:
        grouped = PORTAL_DATABASE_GROUP_SEPARATOR + digits[-3:] + grouped
        digits = digits[:-3]
    return sign + digits + grouped


def _portal_database_format_integer(value: Any) -> str | None:
    try:
        return _portal_database_group_digits(str(int(value)))
    except (TypeError, ValueError):
        return None


def _portal_database_format_decimal(value: Any) -> str | None:
    """Polish decimal presentation without changing precision.

    The source text is reused rather than reformatted through a float, so a
    value stored as ``28.40`` keeps its trailing zero and nothing is rounded
    away. Only the separators change.
    """
    text = str(value).strip()
    if not text:
        return None
    if text.lower() in {"nan", "inf", "-inf", "infinity", "-infinity"}:
        return text
    if "e" in text.lower():
        # Exponent notation: regrouping it would misrepresent the magnitude.
        return text.replace(".", ",")
    if not re.fullmatch(r"-?\d+(\.\d+)?", text):
        return None
    if "." in text:
        whole, fraction = text.split(".", 1)
        return _portal_database_group_digits(whole) + "," + fraction
    return _portal_database_group_digits(text)


def _portal_database_polish_plural(count: int, one: str, few: str, many: str) -> str:
    """Polish plural selection: 1, 2-4, and everything else.

    The teens are the exception the simple rule gets wrong: 12 takes the same
    form as 25, not the same form as 2.
    """
    if count == 1:
        return one
    last_two = count % 100
    if 12 <= last_two <= 14:
        return many
    return few if 2 <= count % 10 <= 4 else many


def _portal_database_format_structured(value: Any) -> str | None:
    """Collapsed one-line preview of a structured value.

    Raw JSON in a cell is unreadable at 32 px, so the cell states the shape and
    the full value stays available by copy. Pretty-printing belongs to the row
    detail panel, which is a later stage.
    """
    data = value
    if isinstance(data, (str, bytes)):
        try:
            data = json.loads(data)
        except (ValueError, TypeError):
            return None
    if isinstance(data, dict):
        count = len(data)
        return "{ " + f"{count} " + _portal_database_polish_plural(count, "pole", "pola", "pól") + " }"
    if isinstance(data, list):
        count = len(data)
        return "[ " + f"{count} " + _portal_database_polish_plural(count, "element", "elementy", "elementów") + " ]"
    return None


def _portal_database_truncate_identifier(text: str) -> str:
    """Mid-truncate a long identifier, keeping the leading 8 and trailing 4.

    Both ends carry meaning for an operator comparing identifiers; cutting only
    the tail would make a column of UUIDs look identical.
    """
    if len(text) <= 14:
        return text
    return f"{text[:8]}\u2026{text[-4:]}"


def _portal_database_cell_html(value: Any, column: dict | None = None) -> str:
    """Render one table cell according to the approved value contract.

    Presentation only: the underlying value is never altered.

    WHAT A COPY YIELDS, decided by the owner on 2026-08-27. ``data-db-copy``
    carries the value AS DISPLAYED, so this grid and the Eco tables no longer
    disagree about what the same gesture produces, and so a rectangle copied out
    of a table matches what the person was looking at when they selected it.
    It previously carried the raw source text, which meant the screen said
    ``24.04.2026 10:51:00`` and the clipboard said ``2026-04-24T10:51:00+02:00``.

    THE RAW VALUE IS NOT LOST: ``title`` still carries it, unchanged, on every
    cell. That is deliberate and load-bearing. A rendered time carries no offset,
    so on this grid -- which shows arbitrary client timestamps, and where the
    autumn DST fold makes two instants an hour apart render identically -- the
    tooltip is the only place the exact instant remains visible. Removing it
    would have made the ambiguity unresolvable rather than merely accepted.

    A LOSSY DISPLAY IS THE EXCEPTION AND KEEPS ITS RAW VALUE. A UUID is
    mid-elided and a structured value is replaced by a shape preview, so copying
    what those cells display would put ``7f03c4e1…0021`` or ``{ 4 pola }`` on the
    clipboard. Truncated data is worse than either convention: it looks like a
    value and is not one. Those two families therefore still copy their source.

    ``column`` is optional so existing callers that render a value without
    catalog metadata keep working; without it a value falls back to text.
    """
    # NULL and empty string MUST stay distinguishable. Collapsing them, as the
    # pre-redesign single str() path did, makes data verification unreliable:
    # a missing value and a present-but-empty one are different facts.
    if value is None:
        return (
            '<td class="db-cell-empty">'
            f'<span class="db-v db-v-null">{_html(_tr("db.value.null"))}</span></td>'
        )
    if isinstance(value, str) and value == "":
        return (
            '<td class="db-cell-empty">'
            f'<span class="db-v db-v-blank">{_html(_tr("db.value.blank"))}</span></td>'
        )

    family = _portal_database_render_family(column)
    if isinstance(value, (datetime, date)):
        raw = value.isoformat()
    elif isinstance(value, (dict, list)):
        # A structured value arrives already decoded, so str() would yield a
        # Python repr with single quotes. Copy must give back real JSON.
        try:
            raw = json.dumps(value, ensure_ascii=False, default=str)
        except (TypeError, ValueError):
            raw = str(value)
    else:
        raw = str(value)
    copy_attr = _html(raw)
    classes = ["db-v", "db-copyable"]
    cell_classes: list[str] = []
    text = raw
    # What the clipboard gets, when it is not simply `text`. Set by the integer
    # family, whose displayed grouping no spreadsheet parses.
    copy_text = None
    # Set by the two families whose rendering discards information. Everything
    # else copies what it shows.
    lossy_display = False

    if family == "boolean" and isinstance(value, bool):
        # A word, not a bare colour or glyph, so the state survives with colour
        # vision disabled.
        label = _tr("db.value.true") if value else _tr("db.value.false")
        state = "is-true" if value else "is-false"
        return (
            '<td class="db-bool">'
            f'<span class="db-badge-bool {state}" title="{copy_attr}" '
            f'data-db-copy="{_html(label)}">{_html(label)}</span></td>'
        )

    if family in {"integer", "decimal"}:
        formatted = (
            _portal_database_format_integer(value)
            if family == "integer"
            else _portal_database_format_decimal(value)
        )
        if formatted is not None:
            text = formatted
            # THE THOUSANDS SEPARATOR IS FOR THE EYE, NOT THE CLIPBOARD.
            # The grouped form is what the column should read as; it is not a
            # number any spreadsheet will parse, because the separator is
            # U+00A0. Copying the displayed value therefore means copying what
            # it displays MINUS its grouping -- the same answer the Eco ranking
            # reached for its own integers, which display `2 640` and copy
            # `2640`. Two grids, one gesture, one result.
            #
            # BOTH numeric families, not just integers. A decimal groups its
            # whole part exactly as an integer does, so `1 234 567,891` had the
            # identical defect; it was invisible only because it takes a value
            # above 999 to show it. The DECIMAL COMMA STAYS -- it is the Polish
            # decimal mark a spreadsheet expects, where the grouping separator
            # is decoration. Nothing displayed changes.
            copy_text = text.replace(PORTAL_DATABASE_GROUP_SEPARATOR, "")
            classes.append(f"db-v-{family}")
            cell_classes.append("db-num")
            # Zero is data, not absence: dimmer than a value, never faint.
            try:
                if float(str(value)) == 0.0:
                    classes.append("db-v-zero")
            except (TypeError, ValueError):
                pass
        else:
            classes.append("db-v-text")
    elif family == "timestamp":
        if isinstance(value, datetime):
            # Seconds are kept: this grid is evidence like the Eco tables, and
            # the minute precision this used to show collapsed distinct rows.
            # The full value still goes to the clipboard via `data-db-copy`.
            text = portal_formats.format_datetime(value, empty=text)
        classes.append("db-v-timestamp")
    elif family == "date":
        if isinstance(value, (datetime, date)):
            text = portal_formats.format_date(value, empty=text)
        classes.append("db-v-date")
    elif family == "uuid":
        text = _portal_database_truncate_identifier(raw)
        # LOSSY: the display is mid-elided, so it copies its source.
        lossy_display = text != raw
        classes.append("db-v-uuid")
    elif family == "json":
        preview = _portal_database_format_structured(value)
        if preview is not None:
            text = preview
            # LOSSY: the display states the SHAPE, not the value. `{ 4 pola }`
            # on a clipboard is not a structured value; it is a description of
            # one. This family copies its source.
            lossy_display = True
            classes.append("db-v-json")
        else:
            classes.append("db-v-text")
    else:
        classes.append("db-v-text")

    cell_attr = f' class="{" ".join(cell_classes)}"' if cell_classes else ""
    # `title` is always the source value; `data-db-copy` is what the cell shows,
    # except where showing it would truncate.
    copy_value = copy_attr if lossy_display else _html(
        text if copy_text is None else copy_text)
    return (
        f"<td{cell_attr}>"
        f'<span class="{" ".join(classes)}" title="{copy_attr}" data-db-copy="{copy_value}">'
        f"{_html(text)}</span></td>"
    )


def _portal_database_active_filter_chips(
    dataset: dict,
    params: dict[str, list[str]],
    filter_entries: list[dict] | None,
) -> list[dict]:
    """Chips for the effective, validated filters — one per filter, never per condition.

    The source is the query builder's own record of what it applied, not the raw
    query string. A filter-shaped parameter the builder rejected or ignored (an
    empty value, an unsearchable search term) therefore produces no chip and does
    not inflate the count badge.

    The global search is deliberately excluded: the approved contract keeps it as
    its own toolbar field rather than a chip (`PBC` 2.6).
    """
    dataset_id = str(dataset.get("dataset_id") or "")
    chips: list[dict] = []
    for entry in filter_entries or []:
        if str(entry.get("column_name") or "") == "__search__":
            continue
        overrides: dict[str, Any] = {key: None for key in entry.get("clear_keys") or []}
        overrides["page"] = 1
        text = _portal_database_filter_chip_text(entry)
        chips.append({
            "column_name": str(entry.get("column_name") or ""),
            "label": str(entry.get("label") or entry.get("column_name") or ""),
            "op": _portal_database_operator_label(entry.get("operator")),
            "operator": str(entry.get("operator") or ""),
            "value": _portal_database_filter_value_text(entry),
            "text": text,
            "remove_url": _portal_database_url(dataset_id, params, **overrides),
            "remove_label": _tr("db.chip.remove", filter=text),
        })
    return chips


def _portal_database_chip_strip_html(chips: list[dict]) -> str:
    """The toolbar chip strip: one chip per active filter, each removable at once."""
    if not chips:
        return ""
    chip_html = []
    for chip in chips:
        value_html = (
            f'<span class="db-chip-value">{_html(chip["value"])}</span>' if chip["value"] else ""
        )
        chip_html.append(
            '<span class="db-chip">'
            f'<span class="db-chip-label">{_html(chip["label"])}</span>'
            f'<span class="db-chip-op">{_html(chip["op"])}</span>'
            f"{value_html}"
            f'<a class="db-chip-remove" href="{_html(chip["remove_url"])}" '
            f'aria-label="{_html(chip["remove_label"])}" title="{_html(chip["remove_label"])}">×</a>'
            "</span>"
        )
    return '<div class="db-chips" role="group" aria-label="' + _html(_tr("db.panel.active", count=len(chips))) + '">' + "".join(chip_html) + "</div>"


def _portal_database_date_preset_links(dataset: dict, columns: list[dict], params: dict[str, list[str]]) -> str:
    default_date = str(dataset.get("default_date_column") or "").strip()
    if not default_date:
        return ""
    column = next(
        (c for c in columns if str(c.get("column_name")) == default_date and c.get("is_filterable")),
        None,
    )
    if not column or _portal_database_type_family(column.get("data_type")) != "date":
        return ""
    dataset_id = str(dataset.get("dataset_id") or "")
    today = datetime.now().date()
    first_this = today.replace(day=1)
    last_prev = first_this - timedelta(days=1)
    first_prev = last_prev.replace(day=1)
    presets = [
        ("Today", today, today),
        ("Yesterday", today - timedelta(days=1), today - timedelta(days=1)),
        ("Last 7 days", today - timedelta(days=6), today),
        ("Last 30 days", today - timedelta(days=29), today),
        ("This month", first_this, today),
        ("Previous month", first_prev, last_prev),
    ]
    is_ts = _portal_database_is_timestamp_column(column)
    current_from = _portal_database_first_param(params, "date_from", "")
    current_to = _portal_database_first_param(params, "date_to", "")
    links = []
    for label, start, end in presets:
        date_from = start.isoformat()
        date_to = (end.isoformat() + "T23:59:59") if is_ts else end.isoformat()
        active = " active" if current_from == date_from and current_to == date_to else ""
        href = _portal_database_url(dataset_id, params, date_from=date_from, date_to=date_to, page=1)
        links.append(f'<a class="db-preset{active}" href="{_html(href)}">{_html(label)}</a>')
    return (
        '<div class="db-presets"><span class="db-presets-label">Quick ranges</span>'
        + ''.join(links)
        + '</div>'
    )


def _portal_database_page_size_options(current_limit: int) -> list[int]:
    """Offered page sizes, always including whatever the URL currently asks for.

    A deep link carrying a size outside the standard set still renders its own
    size as a selectable option, so the footer never silently disagrees with the
    page the user is looking at.
    """
    options = [
        size
        for size in PORTAL_DATABASE_PAGE_SIZE_OPTIONS
        if PORTAL_DATABASE_MIN_PAGE_SIZE <= size <= PORTAL_DATABASE_MAX_PAGE_SIZE
    ]
    if current_limit not in options:
        options = sorted(set(options + [current_limit]))
    return options


def _portal_database_parse_cols(params: dict[str, list[str]], allowed_columns: list[dict]) -> tuple[list[dict], bool]:
    """Resolve the on-screen display column subset from the `cols` query param.

    Returns (display_columns, fell_back). Only columns already present in
    `allowed_columns` (the permitted/visible set) can be selected; unknown, hidden
    or unpermitted names are silently ignored. When `cols` is absent the full
    permitted set is returned (legacy behavior). When `cols` is present but every
    requested name is invalid we fall back to the full permitted set and flag it so
    the UI can show a non-sensitive notice. Catalog order is always preserved.
    """
    allowed_names = {str(column.get("column_name")) for column in allowed_columns}
    requested: list[str] = []
    for raw in params.get("cols", []) or []:
        for part in str(raw).split(","):
            name = part.strip()
            if name:
                requested.append(name)
    if not requested:
        return list(allowed_columns), False
    selected = {name for name in requested if name in allowed_names}
    if not selected:
        return list(allowed_columns), True
    display = [column for column in allowed_columns if str(column.get("column_name")) in selected]
    return display, False


def _portal_database_cols_active(params: dict[str, list[str]], allowed_columns: list[dict], display_columns: list[dict]) -> bool:
    if not (params.get("cols") or []):
        return False
    return len(display_columns) != len(allowed_columns)


# ---------------------------------------------------------------------------
# Column management and layout state (approved stage S5, `DB-008`, `DB-26`-`DB-29`)
#
# Presentation only. Nothing in this section reaches SQL: the approved-column
# catalog resolved by `_get_portal_database_visible_columns` remains the whole
# universe, `cols` still only narrows it, and order, width and pin state can
# merely rearrange what that narrowing already permitted. Every identifier that
# arrives through a layout parameter is intersected with the approved set before
# it is used or re-emitted, so a crafted URL can rearrange a view and nothing
# else.
#
# Canonical URL representation, all bounded and all reproducible:
#
#   cols     repeated, one per visible column   — unchanged S2/S3 contract
#   colorder `a,b,c`  the shortest prefix that reproduces the resolved order
#   colw     `a:180,b:96`  explicit user widths only, in pixels
#   colpin   `a,b`  pinned columns in pin order; present-but-empty means none
#
# `colorder` and `colw` carry only what cannot be derived: the fill rule (§ the
# resolver below) appends every unnamed visible column in catalog order, and a
# width equal to its family default is dropped rather than serialized.
# ---------------------------------------------------------------------------

# Grid spec §1.7. Below the minimum a header label cannot be read; above the
# maximum an identifier or address column would push the rest of the sheet off
# screen instead of truncating.
PORTAL_DATABASE_COLUMN_MIN_WIDTH_PX = 64
PORTAL_DATABASE_COLUMN_MAX_WIDTH_PX = 480
# Default width per presentation family, "derived from the column's data family"
# (grid spec §1.7). Numeric columns size to their widest expected value, not to
# the space a text column needs.
PORTAL_DATABASE_COLUMN_DEFAULT_WIDTHS = {
    "identifier": 200,
    "text": 200,
    "integer": 120,
    "decimal": 120,
    "boolean": 96,
    "date": 120,
    "timestamp": 168,
    "structured": 200,
}
PORTAL_DATABASE_COLUMN_FALLBACK_WIDTH_PX = 200
# The row-detail link column is not an approved data column and is never part of
# layout state, but `table-layout: fixed` requires a declared width for it too.
PORTAL_DATABASE_DETAIL_COLUMN_WIDTH_PX = 96

# Autofit (grid spec §1.7, `DB-29`): the widest value on the CURRENT PAGE, never
# a fresh scan of the dataset. The estimate is a deterministic function of the
# rendered text, implemented identically here and in data-grid-columns.js so the
# no-script path and the in-place path agree on the same pixel value.
PORTAL_DATABASE_COLUMN_AUTOFIT_CHAR_PX = 7
PORTAL_DATABASE_COLUMN_AUTOFIT_PADDING_PX = 52

# Grid spec §1.3: total pinned width must not exceed 40 % of the table viewport.
# The server does not know the viewport, so it enforces a bounded absolute
# fallback — 40 % of a 1440 px reference — and data-grid-columns.js enforces the
# real proportional rule against the live viewport when the user pins.
PORTAL_DATABASE_MAX_PINNED_COLUMNS = 4
PORTAL_DATABASE_MAX_PINNED_WIDTH_PX = 576
PORTAL_DATABASE_PINNED_VIEWPORT_FRACTION = 0.4

# A hard bound on how much layout state one URL may describe, so a crafted
# parameter cannot make the resolver do unbounded work or emit unbounded CSS.
PORTAL_DATABASE_MAX_LAYOUT_ENTRIES = 128

PORTAL_DATABASE_LAYOUT_PARAM_KEYS = ("colorder", "colw", "colpin")
PORTAL_DATABASE_COLUMN_WIDTH_PARAM_PREFIX = "colw__"

# ---------------------------------------------------------------------------
# Approved stage S6 — opaque row references
# ---------------------------------------------------------------------------
# The user-facing row parameter. Its value is always an AES-GCM row reference
# (`api/row_reference.py`), never a technical identifier.
PORTAL_DATABASE_ROW_PARAM = "row"
# The row-detail drawer defaults to the fields currently visible on the sheet and
# can switch to the whole approved column set (`DB-39`).
PORTAL_DATABASE_ROW_FIELDS_PARAM = "rowfields"
PORTAL_DATABASE_ROW_FIELDS_ALL = "all"
# `rowfields` is MODE state, never a column selector. The whole accepted
# vocabulary is "absent" (the visible fields) and `all` (every approved field);
# there is deliberately no syntax by which it could name a physical column.
PORTAL_DATABASE_ROW_FIELDS_VALUES = (PORTAL_DATABASE_ROW_FIELDS_ALL,)


def _portal_database_resolve_row_fields_mode(params: dict[str, list[str]]) -> bool:
    """Canonicalize `rowfields` to the approved enum, in place.

    Anything outside the allowlist is **discarded** rather than carried: an
    unrecognised value used to survive in `params` and ride into every generated
    link and hidden input, so a crafted `rowfields=record_id` could reflect the
    internal column label into ordinary markup even though it never selected
    anything. Repeated values collapse to the first valid one.

    Returns whether the drawer should show every approved field.
    """
    raw_values = params.get(PORTAL_DATABASE_ROW_FIELDS_PARAM) or []
    accepted = next(
        (
            value
            for value in (str(raw).strip().lower() for raw in raw_values)
            if value in PORTAL_DATABASE_ROW_FIELDS_VALUES
        ),
        "",
    )
    if accepted:
        params[PORTAL_DATABASE_ROW_FIELDS_PARAM] = [accepted]
    else:
        params.pop(PORTAL_DATABASE_ROW_FIELDS_PARAM, None)
    return accepted == PORTAL_DATABASE_ROW_FIELDS_ALL


def _portal_database_row_reference_secret() -> str:
    """The stable key material row references are derived from.

    Reuses the application's existing session secret rather than introducing a
    second one to deploy. `ARTIFACT_EXPLORER_SESSION_SECRET` is already required
    for sessions to survive a restart, and HKDF's purpose-separating `info`
    label keeps a row reference cryptographically unrelated to a session cookie.

    When the secret is unset the process falls back to the same ephemeral
    development value sessions already use, so a developer instance still works
    and row links simply stop resolving after a restart — exactly as sessions do.
    """
    return _artifact_explorer_session_secret()


def _portal_database_build_row_reference(dataset: dict, identifier_column: str, identity_value: Any) -> str:
    """Mint the opaque reference for one row, or "" when it cannot be minted.

    A row whose technical identity is NULL or empty simply gets no reference and
    therefore no detail link, rather than a guessed or positional one.
    """
    if identity_value is None:
        return ""
    value = str(identity_value)
    if not value:
        return ""
    try:
        return build_row_reference(
            secret=_portal_database_row_reference_secret(),
            dataset_id=str(dataset.get("dataset_id") or ""),
            client_code=str(dataset.get("client_code") or ""),
            identifier_column=str(identifier_column or ""),
            identity_value=value,
        )
    except RowReferenceError:
        return ""
    except Exception as exc:  # noqa: BLE001 - a missing key must not break the sheet
        print(f"portal database row reference could not be built: {type(exc).__name__}")
        return ""


def _portal_database_resolve_row_reference(dataset: dict, identifier_column: str, token: str) -> str | None:
    """Recover a technical row identity from a reference, or None.

    Every failure — malformed, tampered, unsupported version, or minted for a
    different dataset/client/identifier column — collapses to None so the caller
    renders one indistinguishable state.
    """
    try:
        return resolve_row_reference(
            secret=_portal_database_row_reference_secret(),
            token=token,
            dataset_id=str(dataset.get("dataset_id") or ""),
            client_code=str(dataset.get("client_code") or ""),
            identifier_column=str(identifier_column or ""),
        )
    except RowReferenceError:
        return None
    except Exception as exc:  # noqa: BLE001
        print(f"portal database row reference could not be resolved: {type(exc).__name__}")
        return None


def _portal_database_row_url(dataset_id: str, params: dict[str, list[str]], row_reference: str) -> str:
    """The current view plus one open row.

    Built from the already-canonicalized `params`, so every valid filter, search,
    sort, page, page size and S5 layout parameter rides along and the address
    reconstructs the same working sheet with the drawer open.
    """
    next_params = {key: list(values) for key, values in params.items() if values and key != PORTAL_DATABASE_ROW_PARAM}
    next_params[PORTAL_DATABASE_ROW_PARAM] = [row_reference]
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}" + (f"?{query}" if query else "")


def _portal_database_row_fields_url(
    dataset_id: str, params: dict[str, list[str]], row_reference: str, *, show_all: bool
) -> str:
    """`Widoczne n` / `Wszystkie m` — the `DB-39` field-scope toggle."""
    next_params = {
        key: list(values)
        for key, values in params.items()
        if values and key not in (PORTAL_DATABASE_ROW_PARAM, PORTAL_DATABASE_ROW_FIELDS_PARAM)
    }
    next_params[PORTAL_DATABASE_ROW_PARAM] = [row_reference]
    if show_all:
        next_params[PORTAL_DATABASE_ROW_FIELDS_PARAM] = [PORTAL_DATABASE_ROW_FIELDS_ALL]
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}" + (f"?{query}" if query else "")


def _portal_database_row_detail_panel_html(
    *,
    dataset_id: str,
    params: dict[str, list[str]],
    columns: list[dict],
    visible_columns: list[dict],
    record: dict,
    row_reference: str,
    page_row_references: list[str],
    position: int,
    show_all_fields: bool,
) -> str:
    """The approved `DB-006` docked row-detail panel.

    Docked and **not** modal: the approved catalog states the design contains no
    modal dialog, and the accessibility contract lists the docked row panel as
    explicitly *not* focus-trapped. It is therefore a labelled `region`, not a
    `dialog`, and the table behind it stays operable.

    The technical row identity is absent by construction — the panel renders
    `columns`, which is the approved user-visible set the identity was already
    excluded from.
    """
    close_url = _portal_database_row_close_url(dataset_id, params)
    field_columns = columns if show_all_fields else visible_columns
    sections = _portal_database_row_field_sections(field_columns)

    # Traversal targets come from the references minted for this page.
    # `position` is the open row's index within them, established by identity
    # while the body was rendered — not by searching for a token, which would be
    # unreliable because every reference carries a fresh nonce.
    previous_reference = page_row_references[position - 1] if position > 0 else ""
    next_reference = (
        page_row_references[position + 1]
        if 0 <= position < len(page_row_references) - 1
        else ""
    )

    def _traverse(label_key: str, glyph: str, target: str, direction: str) -> str:
        label = _tr(label_key)
        if not target:
            # Disabled traversal is communicated semantically, not by colour.
            return (
                f'<span class="db-row-traverse is-disabled" aria-disabled="true" '
                f'data-db-row-traverse="{direction}">'
                f'<span class="lp-visually-hidden">{_html(label)}</span>'
                f'<span aria-hidden="true">{glyph}</span></span>'
            )
        href = _portal_database_row_url(dataset_id, params, target)
        return (
            f'<a class="db-row-traverse" href="{_html(href)}" '
            f'data-db-row-traverse="{direction}" data-db-row-target="{_html(target)}" '
            f'aria-label="{_html(label)}"><span aria-hidden="true">{glyph}</span></a>'
        )

    section_html = []
    for key, section_columns in sections:
        rows_html = []
        for column in section_columns:
            column_name = str(column.get("column_name") or "")
            label = str(column.get("display_name") or column_name)
            # Reuse the S2 typed rendering — the NULL/empty distinction, the
            # grouped numbers, the collapsed structured preview — but wrapped in
            # the panel's own element rather than a table cell: the panel is the
            # escape hatch for truncated values, so it wraps instead of clipping.
            value_cell = _portal_database_cell_html(record.get(column_name), column)
            inner = value_cell
            if inner.startswith("<td"):
                inner = inner[inner.index(">") + 1:]
            if inner.endswith("</td>"):
                inner = inner[: -len("</td>")]
            value_html = f'<div class="db-row-field-value">{inner}</div>'

            rows_html.append(
                '<div class="db-row-field">'
                f'<div class="db-row-field-label">{_html(label)}</div>'
                f'<div class="db-row-field-physical lp-mono">{_html(column_name)}</div>'
                f'{value_html}'
                "</div>"
            )
        section_html.append(
            '<section class="db-row-section">'
            f'<h4 class="db-row-section-head">{_html(_tr(key))} '
            f'<span class="db-row-section-count lp-mono">{len(section_columns)}</span></h4>'
            + "".join(rows_html)
            + "</section>"
        )

    visible_url = _portal_database_row_fields_url(dataset_id, params, row_reference, show_all=False)
    all_url = _portal_database_row_fields_url(dataset_id, params, row_reference, show_all=True)
    scope_html = (
        '<div class="db-row-scope" role="group" aria-label="' + _html(_tr("db.row.fields_scope")) + '">'
        + f'<a class="db-row-scope-option{"" if show_all_fields else " is-active"}" '
        + f'href="{_html(visible_url)}" data-db-row-fields="visible"'
        + ("" if show_all_fields else ' aria-current="true"')
        + f'>{_html(_tr("db.row.fields_visible"))} <span class="lp-mono">{len(visible_columns)}</span></a>'
        + f'<a class="db-row-scope-option{" is-active" if show_all_fields else ""}" '
        + f'href="{_html(all_url)}" data-db-row-fields="all"'
        + (' aria-current="true"' if show_all_fields else "")
        + f'>{_html(_tr("db.row.fields_all"))} <span class="lp-mono">{len(columns)}</span></a>'
        + "</div>"
    )

    heading = _tr("db.row.detail_heading")
    return (
        '<aside class="db-row-detail" data-db-row-detail '
        f'data-db-row-current="{_html(row_reference)}" '
        f'role="region" aria-label="{_html(heading)}" tabindex="-1">'
        '<header class="db-row-detail-head">'
        f'<h3 class="db-row-detail-title" tabindex="-1" data-db-row-heading>{_html(heading)}</h3>'
        '<div class="db-row-detail-actions">'
        + _traverse("db.row.previous", "&#8593;", previous_reference, "previous")
        + _traverse("db.row.next", "&#8595;", next_reference, "next")
        + f'<a class="db-row-close" href="{_html(close_url)}" data-db-row-close '
        + f'aria-label="{_html(_tr("db.row.close"))}"><span aria-hidden="true">&#215;</span></a>'
        + "</div></header>"
        + scope_html
        + '<div class="db-row-detail-body">'
        + "".join(section_html)
        + "</div></aside>"
    )


def _portal_database_row_unavailable_html() -> str:
    """One generic state for every unresolvable row reference.

    Deliberately says nothing about which failure occurred: a tampered token, a
    token for another dataset and a row that has since been deleted are
    indistinguishable from outside, and the table behind stays usable.
    """
    return (
        '<aside class="db-row-detail db-row-detail-empty" data-db-row-detail '
        f'role="region" aria-label="{_html(_tr("db.row.detail_heading"))}" tabindex="-1">'
        '<header class="db-row-detail-head">'
        f'<h3 class="db-row-detail-title" tabindex="-1" data-db-row-heading>{_html(_tr("db.row.detail_heading"))}</h3>'
        "</header>"
        f'<p class="db-row-unavailable">{_html(_tr("db.row.unavailable"))}</p>'
        "</aside>"
    )


def _portal_database_fetch_row_by_identity(
    dataset: dict, columns: list[dict], identifier_column: str, identity_value: str
) -> tuple[dict | None, str | None]:
    """Fetch one row by its technical identity.

    Returns `(record, failure)`. The identifier comes from the authorized
    catalog and is quoted as an identifier; the value is always a bound
    parameter. `LIMIT 2` is kept so a non-unique identifier is detected instead
    of silently yielding an arbitrary row.
    """
    try:
        schema_sql = _portal_database_quote_identifier(str(dataset.get("schema_name") or ""), "Schema name")
        table_sql = _portal_database_quote_identifier(str(dataset.get("table_name") or ""), "Table name")
        identifier_sql = _portal_database_quote_identifier(identifier_column, "Row identifier column")
        select_columns = [
            _portal_database_quote_identifier(str(column.get("column_name") or ""), "Column name")
            for column in columns
        ]
    except ValueError:
        return None, "misconfigured"
    if not select_columns:
        return None, "misconfigured"
    query = (
        f"SELECT {', '.join(select_columns)} FROM {schema_sql}.{table_sql} "
        f"WHERE {identifier_sql} = %s LIMIT 2"
    )
    try:
        database_name = _portal_dataset_client_database_name(dataset)
        with _connect_portal_client_database(database_name) as conn:
            with conn.cursor() as cur:
                cur.execute(query, [str(identity_value)])
                fetched = cur.fetchall()
    except Exception as exc:  # noqa: BLE001
        # The class name only: no SQL, no driver text, no identity, no token.
        print(f"portal database row detail query failed: {type(exc).__name__}: dataset_id={dataset.get('dataset_id')}")
        return None, "query_failed"
    detail_rows = _rows_to_dicts(fetched)
    if not detail_rows:
        return None, "not_found"
    if len(detail_rows) > 1:
        return None, "duplicate"
    return detail_rows[0], None


def _portal_database_row_field_sections(columns: list[dict]) -> list[tuple[str, list[dict]]]:
    """Group approved fields into the labelled sections `DB-39` requires.

    The approved design names four dataset-specific sections for the Telematics
    trips dataset. The column catalog carries no section metadata, so inventing
    that membership would be a fabricated business grouping. The honest
    design-compatible fallback groups by the presentation family the catalog
    *does* know, which keeps the section-with-count structure the criterion is
    about without asserting a semantic the repository cannot back.
    """
    buckets: dict[str, list[dict]] = {}
    for column in columns:
        family = _portal_database_render_family(column)
        key = {
            "identifier": "db.row.section.identity",
            "text": "db.row.section.identity",
            "date": "db.row.section.time",
            "timestamp": "db.row.section.time",
            "integer": "db.row.section.metrics",
            "decimal": "db.row.section.metrics",
            "boolean": "db.row.section.classification",
            "structured": "db.row.section.classification",
        }.get(family, "db.row.section.classification")
        buckets.setdefault(key, []).append(column)
    order = (
        "db.row.section.identity",
        "db.row.section.time",
        "db.row.section.metrics",
        "db.row.section.classification",
    )
    return [(key, buckets[key]) for key in order if buckets.get(key)]


def _portal_database_row_close_url(dataset_id: str, params: dict[str, list[str]]) -> str:
    """The same view with the drawer closed — the `Esc` / `×` destination."""
    next_params = {
        key: list(values)
        for key, values in params.items()
        if values and key not in (PORTAL_DATABASE_ROW_PARAM, PORTAL_DATABASE_ROW_FIELDS_PARAM)
    }
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}" + (f"?{query}" if query else "")


def _portal_database_layout_tokens(params: dict[str, list[str]], key: str) -> list[str]:
    """Every comma-separated token supplied for one layout parameter, in order.

    Repeated parameters are concatenated rather than last-wins, so a form that
    emits one input per column and a hand-written link that comma-joins them
    mean the same thing. Bounded, because the caller may be an attacker.
    """
    tokens: list[str] = []
    for raw in params.get(key) or []:
        for part in str(raw).split(","):
            token = part.strip()
            if token:
                tokens.append(token)
            if len(tokens) >= PORTAL_DATABASE_MAX_LAYOUT_ENTRIES:
                return tokens
    return tokens


def _portal_database_column_render_width(column: dict) -> int:
    return PORTAL_DATABASE_COLUMN_DEFAULT_WIDTHS.get(
        _portal_database_render_family(column), PORTAL_DATABASE_COLUMN_FALLBACK_WIDTH_PX
    )


def _portal_database_clamp_column_width(value: Any) -> int | None:
    """A width parameter turned into a usable pixel value, or nothing.

    Rejects rather than guesses: a negative, zero, fractional, malformed or
    non-finite value is not a width. Anything numeric but out of range is
    clamped to the approved bounds, so an absurd value produces a wide column
    and never unbounded CSS.
    """
    text = str(value if value is not None else "").strip()
    if not text or len(text) > 9 or not text.isdigit():
        return None
    number = int(text)
    if number <= 0:
        return None
    return max(
        PORTAL_DATABASE_COLUMN_MIN_WIDTH_PX,
        min(PORTAL_DATABASE_COLUMN_MAX_WIDTH_PX, number),
    )


def _portal_database_parse_column_widths(
    params: dict[str, list[str]], allowed_names: set[str]
) -> dict[str, int]:
    """`colw=a:180,b:96` -> validated explicit widths for approved columns only.

    Unknown or unapproved identifiers are dropped and never re-emitted. A
    duplicate definition keeps the first VALID one, so the canonical form of a
    crafted `a:64,a:480` is stable rather than dependent on scan direction, and
    a malformed leading entry does not veto a well-formed later one.
    """
    widths: dict[str, int] = {}
    for token in _portal_database_layout_tokens(params, "colw"):
        name, separator, raw_width = token.partition(":")
        if not separator:
            continue
        name = name.strip()
        if name not in allowed_names or name in widths:
            continue
        width = _portal_database_clamp_column_width(raw_width)
        if width is not None:
            widths[name] = width
    return widths


def _portal_database_apply_column_width_inputs(
    params: dict[str, list[str]], allowed_names: set[str], widths: dict[str, int]
) -> dict[str, int]:
    """Merge the column menu's explicit width field into the width map.

    The accessible equivalent of pointer resize (`ACCESSIBILITY_SPEC` §4) is a
    plain number input, so it arrives as `colw__<column>` and is folded into
    `colw` here. Consuming it makes the operation idempotent: reloading the
    submitted URL merges the same value again and produces the same layout.
    """
    merged = dict(widths)
    for key in [key for key in params if key.startswith(PORTAL_DATABASE_COLUMN_WIDTH_PARAM_PREFIX)]:
        raw_values = params.pop(key)
        name = key[len(PORTAL_DATABASE_COLUMN_WIDTH_PARAM_PREFIX):]
        if name not in allowed_names:
            continue
        raw = str((raw_values or [""])[-1]).strip()
        if not raw:
            # An emptied field clears the explicit width and returns the column
            # to its family default, which is what "no explicit width" means.
            merged.pop(name, None)
            continue
        width = _portal_database_clamp_column_width(raw)
        if width is not None:
            merged[name] = width
    return merged


def _portal_database_effective_column_width(column: dict, widths: dict[str, int]) -> int:
    name = str(column.get("column_name") or "")
    return widths.get(name) or _portal_database_column_render_width(column)


def _portal_database_fill_column_order(
    requested: list[str], visible_columns: list[dict]
) -> list[dict]:
    """The documented deterministic fill rule for a partial order.

    Named approved columns first, in the order given; then every visible column
    the order did not name, in catalog order. A missing name can therefore never
    drop a column out of the sheet, and an unknown one can never add anything.
    """
    by_name = {str(column.get("column_name") or ""): column for column in visible_columns}
    ordered: list[dict] = []
    taken: set[str] = set()
    for name in requested:
        column = by_name.get(name)
        if column is not None and name not in taken:
            taken.add(name)
            ordered.append(column)
    for column in visible_columns:
        name = str(column.get("column_name") or "")
        if name not in taken:
            taken.add(name)
            ordered.append(column)
    return ordered


def _portal_database_compact_column_order(
    resolved: list[str], visible_columns: list[dict]
) -> list[str]:
    """The shortest prefix of `resolved` that the fill rule expands back to it.

    Moving one column to the front of a 42-column dataset then costs one token
    in the URL instead of forty-two, with no loss of determinism: the value is
    only ever read back through `_portal_database_fill_column_order`.
    """
    for length in range(len(resolved) + 1):
        expanded = [
            str(column.get("column_name") or "")
            for column in _portal_database_fill_column_order(resolved[:length], visible_columns)
        ]
        if expanded == resolved:
            return resolved[:length]
    return list(resolved)


def _portal_database_resolve_column_layout(
    params: dict[str, list[str]], allowed_columns: list[dict], visible_columns: list[dict]
) -> dict:
    """Resolve order, widths and pin state for the approved visible columns.

    `allowed_columns` is the approved catalog (the maximum universe);
    `visible_columns` is what `cols` already narrowed it to. The result is
    presentation state only and is the single source the header, the body, the
    `<colgroup>`, the column menu and the `DB-008` panel all render from.
    """
    allowed_names = {str(column.get("column_name") or "") for column in allowed_columns}

    requested_order = [
        name for name in _portal_database_layout_tokens(params, "colorder") if name in allowed_names
    ]
    ordered = _portal_database_fill_column_order(requested_order, visible_columns)

    widths = _portal_database_parse_column_widths(params, allowed_names)
    widths = _portal_database_apply_column_width_inputs(params, allowed_names, widths)

    ordered_names = [str(column.get("column_name") or "") for column in ordered]
    ordered_by_name = {name: column for name, column in zip(ordered_names, ordered)}

    # Pinning. An absent `colpin` is the transitional default described in
    # `docs/26`: the first displayed column is pinned because the approved
    # sticky pair — the selection checkbox and a configured row identifier —
    # does not exist yet and inventing one would surface an unapproved key. A
    # `colpin` that is present but empty is an explicit "nothing pinned", which
    # is how the user unpins that default.
    if "colpin" in params:
        requested_pins = [
            name
            for name in _portal_database_layout_tokens(params, "colpin")
            if name in ordered_by_name
        ]
        pin_explicit = True
    else:
        requested_pins = ordered_names[:1]
        pin_explicit = False

    pins: list[str] = []
    pinned_width = 0
    pins_truncated = False
    for name in requested_pins:
        if name in pins:
            continue
        if len(pins) >= PORTAL_DATABASE_MAX_PINNED_COLUMNS:
            pins_truncated = True
            break
        width = _portal_database_effective_column_width(ordered_by_name[name], widths)
        if pins and pinned_width + width > PORTAL_DATABASE_MAX_PINNED_WIDTH_PX:
            # Viewport safety (grid spec §1.3). The first pin is always honoured
            # so the sheet cannot end up with an unreachable pinned column; every
            # further pin must fit inside the bounded pinned region.
            pins_truncated = True
            break
        pins.append(name)
        pinned_width += width

    # Pinned columns accumulate to the left in pin order (grid spec §1.3), and
    # the panel refuses to drag an unpinned column above a pinned one, so the
    # rendered order hoists the pins. Doing it here rather than in CSS is what
    # keeps the sticky offsets, the header and every body cell describing one
    # order.
    pin_set = set(pins)
    display_columns = [ordered_by_name[name] for name in pins]
    display_columns.extend(column for column in ordered if str(column.get("column_name") or "") not in pin_set)

    display_names = [str(column.get("column_name") or "") for column in display_columns]
    effective_widths = {
        name: _portal_database_effective_column_width(column, widths)
        for name, column in zip(display_names, display_columns)
    }
    offsets: dict[str, int] = {}
    running = 0
    for name in pins:
        offsets[name] = running
        running += effective_widths.get(name, PORTAL_DATABASE_COLUMN_FALLBACK_WIDTH_PX)

    # Canonical parameters. Only state that cannot be derived survives, and only
    # for columns that are still approved and still displayed.
    canonical_order = _portal_database_compact_column_order(display_names, visible_columns)
    canonical_widths = {
        name: width
        for name, width in widths.items()
        if name in effective_widths and width != _portal_database_column_render_width(ordered_by_name[name])
    }
    return {
        "display_columns": display_columns,
        "display_names": display_names,
        "ordered_columns": ordered,
        "widths": canonical_widths,
        "effective_widths": effective_widths,
        "pins": pins,
        "pin_offsets": offsets,
        "pinned_width": running,
        "pins_truncated": pins_truncated,
        "pin_explicit": pin_explicit,
        "canonical_order": canonical_order,
        "table_width": sum(effective_widths.get(name, 0) for name in display_names),
    }


def _portal_database_encode_column_widths(widths: dict[str, int]) -> str:
    return ",".join(f"{name}:{widths[name]}" for name in sorted(widths))


def _portal_database_apply_layout_params(params: dict[str, list[str]], layout: dict) -> None:
    """Rewrite the layout parameters to exactly what the server resolved.

    Every link, form and export URL on the page is built from `params`, so this
    is what stops a rejected, duplicated or unapproved identifier from riding
    along into a generated URL, and what makes a copied address reproduce the
    layout the user is actually looking at.
    """
    if layout["canonical_order"]:
        params["colorder"] = [",".join(layout["canonical_order"])]
    else:
        params.pop("colorder", None)

    if layout["widths"]:
        params["colw"] = [_portal_database_encode_column_widths(layout["widths"])]
    else:
        params.pop("colw", None)

    default_pins = layout["display_names"][:1]
    if not layout["pin_explicit"] and layout["pins"] == default_pins:
        # The transitional default is derivable, so it is not serialized. Every
        # generated link stays free of pin state until the user chooses one.
        params.pop("colpin", None)
    elif layout["pins"]:
        params["colpin"] = [",".join(layout["pins"])]
    elif layout["pin_explicit"] and default_pins:
        # An explicit "nothing pinned" is not the same as saying nothing, so it
        # has to survive the round trip as a present-but-empty parameter.
        params["colpin"] = [""]
    else:
        params.pop("colpin", None)


def _portal_database_autofit_width(column: dict, rows: list[dict]) -> int:
    """`DB-29`: fit a column to the widest value on the current page.

    Deterministic and bounded — the same estimate data-grid-columns.js applies in
    place — and it reads only the rows already fetched for this page, so autofit
    never issues a query and a single extreme value cannot produce an absurdly
    wide column.
    """
    name = str(column.get("column_name") or "")
    longest = len(str(column.get("display_name") or name))
    for row in rows or []:
        text = _portal_database_autofit_cell_text(row.get(name), column)
        if len(text) > longest:
            longest = len(text)
            if longest * PORTAL_DATABASE_COLUMN_AUTOFIT_CHAR_PX >= PORTAL_DATABASE_COLUMN_MAX_WIDTH_PX:
                break
    estimate = PORTAL_DATABASE_COLUMN_AUTOFIT_PADDING_PX + longest * PORTAL_DATABASE_COLUMN_AUTOFIT_CHAR_PX
    return max(
        PORTAL_DATABASE_COLUMN_MIN_WIDTH_PX,
        min(PORTAL_DATABASE_COLUMN_MAX_WIDTH_PX, estimate),
    )


def _portal_database_autofit_cell_text(value: Any, column: dict) -> str:
    """The text a cell actually shows, for autofit measurement only.

    Autofit must fit what is on screen, so it measures the rendered
    representation — the truncated identifier, the grouped integer, the
    collapsed `{ 4 pola }` preview — and never the underlying value behind it.
    """
    markup = _portal_database_cell_html(value, column)
    return html.unescape(re.sub(r"<[^>]*>", "", markup)).strip()


def _portal_database_column_layout_url(
    dataset_id: str,
    params: dict[str, list[str]],
    layout: dict,
    *,
    order: list[str] | None = None,
    widths: dict[str, int] | None = None,
    pins: list[str] | None = None,
    visible_columns: list[dict] | None = None,
    extra: dict[str, Any] | None = None,
) -> str:
    """A link that changes one part of the layout and nothing else.

    Layout is presentation, so these never touch filters, search, sort, density
    or page size. `page` is left alone as well: rearranging columns does not
    change which rows the page holds.
    """
    overrides: dict[str, Any] = {}
    if order is not None:
        compact = (
            _portal_database_compact_column_order(order, visible_columns)
            if visible_columns is not None
            else order
        )
        overrides["colorder"] = ",".join(compact) if compact else None
    if widths is not None:
        overrides["colw"] = _portal_database_encode_column_widths(widths) or None
    if pins is not None:
        overrides["colpin"] = ",".join(pins)
    if extra:
        overrides.update(extra)
    return _portal_database_url(dataset_id, params, **overrides)


def _portal_database_reset_columns_url(dataset_id: str, params: dict[str, list[str]]) -> str:
    """`Domyślne kolumny` — the dataset's default visible set, order, widths and pins.

    Grid spec §5.3: resetting columns does **not** clear filters or sort. Search,
    density, page size and the date range are equally untouched — this is the
    column-layout domain only, deliberately narrower than `Wyczyść wszystkie`.
    The page returns to 1 exactly as any other column-visibility change does.
    """
    return _portal_database_url(
        dataset_id, params, cols=None, colorder=None, colw=None, colpin=None, page=1
    )


def _portal_database_hidden_param_inputs(params: dict[str, list[str]], *, exclude: set[str]) -> str:
    parts = []
    for key, values in params.items():
        if key in exclude:
            continue
        for value in values:
            parts.append(f'<input type="hidden" name="{_html(key)}" value="{_html(value)}">')
    return ''.join(parts)


def _portal_database_column_panel(
    dataset: dict,
    allowed_columns: list[dict],
    visible_columns: list[dict],
    layout: dict,
    params: dict[str, list[str]],
    *,
    open_panel: bool,
    selection_refused: bool,
    column_sets: list[dict] | None = None,
) -> str:
    """`DB-008` — visibility, order and pin state for the approved columns.

    One GET form over the same validated parameter contract the rest of the
    sheet uses, so it works with scripting unavailable: checkboxes carry
    visibility, `▲`/`▼` links carry order, pin checkboxes carry pin state and
    `Zastosuj` commits visibility and order together (`INT` §4). The `⠿` drag
    handle, the search field and the tab filters are enhancements
    data-grid-columns.js adds on top of that; they are shipped hidden so a
    scriptless page never offers a control that would do nothing.

    Named column sets (`Zestawy ▾`, `DB-30`) are rendered when the S13
    persistence schema is present and are absent — not faked and not disabled —
    when it is not. They sit OUTSIDE this panel's own form, because saving and
    deleting a set are their own POSTs and forms cannot nest.
    """
    dataset_id = str(dataset.get("dataset_id") or "")
    display_names = list(layout["display_names"])
    display_set = set(display_names)
    pins = set(layout["pins"])
    ordered_names = display_names + [
        str(column.get("column_name") or "")
        for column in allowed_columns
        if str(column.get("column_name") or "") not in display_set
    ]
    by_name = {str(column.get("column_name") or ""): column for column in allowed_columns}

    rows_html: list[str] = []
    for position, name in enumerate(ordered_names):
        column = by_name.get(name)
        if column is None:
            continue
        label = str(column.get("display_name") or name)
        visible = name in display_set
        pinned = name in pins
        state = "visible" if visible else "hidden"
        move_links = ""
        if visible:
            # Order is only meaningful among displayed columns, so the move
            # controls act on the displayed order and never on a hidden column.
            index = display_names.index(name)
            for offset, glyph, key in ((-1, "▲", "db.cols.move_up"), (1, "▼", "db.cols.move_down")):
                target = index + offset
                if target < 0 or target >= len(display_names):
                    continue
                moved = list(display_names)
                moved.insert(target, moved.pop(index))
                href = _portal_database_column_layout_url(
                    dataset_id, params, layout, order=moved, visible_columns=visible_columns,
                    extra={"colpanel": 1},
                )
                move_links += (
                    f'<a class="db-cols-move" href="{_html(href)}" data-db-move="{"up" if offset < 0 else "down"}" '
                    f'data-db-column="{_html(name)}" '
                    f'aria-label="{_html(_tr(key, column=label))}">{glyph}</a>'
                )
        rows_html.append(
            f'<li class="db-cols-row" data-db-col-row data-db-column="{_html(name)}" '
            f'data-db-state="{state}" data-db-label="{_html(label.lower())}">'
            f'<span class="db-cols-handle" data-db-handle draggable="true" '
            f'role="button" tabindex="0" '
            f'aria-label="{_html(_tr("db.cols.reorder", column=label))}" hidden>⠿</span>'
            f'<label class="db-cols-visible">'
            f'<input type="checkbox" name="cols" value="{_html(name)}"{" checked" if visible else ""}>'
            f'<span class="db-cols-label">{_html(label)}</span></label>'
            f'<span class="db-cols-type lp-mono">{_html(str(column.get("data_type") or ""))}</span>'
            f'<label class="db-cols-pin">'
            f'<input type="checkbox" name="colpin" value="{_html(name)}"{" checked" if pinned else ""}'
            f'{"" if visible else " disabled"}>'
            f'<span>{_html(_tr("db.cols.pin_short"))}</span></label>'
            f'<span class="db-cols-moves">{move_links}</span>'
            "</li>"
        )

    hidden = _portal_database_hidden_param_inputs(
        params, exclude={"cols", "colpin", "colorder", "page", "colpanel"}
    )
    notices = ""
    if selection_refused:
        notices += (
            f'<p class="db-cols-warning" role="alert">{_html(_tr("db.cols.min_one"))}</p>'
        )
    if layout["pins_truncated"]:
        notices += (
            f'<p class="db-cols-warning" role="note">{_html(_tr("db.col.pin_refused"))}</p>'
        )
    summary = (
        f'{_html(_tr("db.columns"))} '
        f'<span class="lp-mono">{len(display_names)}/{len(allowed_columns)}</span>'
    )
    column_sets_html = (
        _portal_database_column_sets_html(
            dataset_id,
            params,
            list(column_sets or []),
            reset_url=_portal_database_reset_columns_url(dataset_id, params),
        )
        if column_sets is not None
        else ""
    )
    tabs = "".join(
        f'<button class="db-cols-tab" type="button" data-db-cols-tab="{key}" '
        f'aria-pressed="{"true" if key == "all" else "false"}">{_html(_tr(label_key))}</button>'
        for key, label_key in (
            ("all", "db.cols.tab_all"),
            ("visible", "db.cols.tab_visible"),
            ("hidden", "db.cols.tab_hidden"),
        )
    )
    return (
        f'<details class="db-columns" id="db-columns" data-db-columns{" open" if open_panel else ""}>'
        f'<summary class="db-tool-button db-columns-trigger">{summary}</summary>'
        f'<div class="db-columns-panel" role="group" aria-label="{_html(_tr("db.cols.aria"))}">'
        + column_sets_html
        + f'<form class="db-columns-form" method="get" data-db-columns-form>'
        + hidden
        # Marks a real selection submit, so an empty selection is distinguishable
        # from "no narrowing requested" and can be refused instead of silently
        # restoring every approved column (`DB-28`).
        + '<input type="hidden" name="colsel" value="1">'
        # Present-but-empty is the explicit "nothing pinned" state; without this
        # marker unpinning the last column would be indistinguishable from never
        # having said anything about pins.
        + '<input type="hidden" name="colpin" value="">'
        + f'<input type="hidden" name="colorder" value="{_html(",".join(display_names))}" data-db-order-field>'
        + f'<div class="db-cols-search" data-db-cols-search hidden>'
        + f'<label class="lp-visually-hidden" for="db-cols-search">{_html(_tr("db.cols.search"))}</label>'
        + f'<input id="db-cols-search" type="search" autocomplete="off" '
        + f'placeholder="{_html(_tr("db.cols.search"))}" data-db-cols-query></div>'
        + f'<div class="db-cols-tabs" role="group" aria-label="{_html(_tr("db.cols.tabs_aria"))}" '
        + f'data-db-cols-tabs hidden>{tabs}</div>'
        + f'<p class="db-help">{_html(_tr("db.cols.help"))}</p>'
        + '<ul class="db-cols-list" data-db-cols-list>' + "".join(rows_html) + "</ul>"
        # Reorder must be understandable without watching the list move.
        + '<p class="lp-visually-hidden" role="status" aria-live="polite" data-db-cols-status></p>'
        + notices
        + '<div class="portal-actions db-columns-actions">'
        + f'<button class="portal-button" type="submit">{_html(_tr("db.apply"))}</button>'
        + f'<a class="portal-button secondary" href="{_html(_portal_database_reset_columns_url(dataset_id, params))}" '
        + f'data-db-columns-reset>{_html(_tr("db.cols.reset"))}</a>'
        + "</div></form></div></details>"
    )


# `RESPONSIVE_SPEC.md`: cell range selection is disabled at 768 px and below,
# because a touch drag across cells conflicts with scrolling the table. The
# cutoff ships as data, not as a user-agent test, and the module resolves it
# with `matchMedia` against the same number the CSS uses.
PORTAL_DATABASE_SELECTION_MIN_WIDTH_PX = 769


def _portal_database_selection_strings() -> str:
    """Polish vocabulary for the grid-selection module (approved stage S7).

    Same mechanism as the column module: the sheet carries the words so the
    shipped JavaScript holds none, and the translation catalogue stays the one
    source of every user-facing string (`D-010`). Plural forms travel as the
    three Polish categories; the module selects between them.
    """
    catalogue = {
        "summary": _tr("db.select.summary"),
        "copied": _tr("db.select.copied"),
        "copyFailed": _tr("db.select.copy_failed"),
        "row": [_tr("db.select.row.one"), _tr("db.select.row.few"), _tr("db.select.row.many")],
        "column": [_tr("db.select.column.one"), _tr("db.select.column.few"), _tr("db.select.column.many")],
        "cell": [_tr("db.select.cell.one"), _tr("db.select.cell.few"), _tr("db.select.cell.many")],
    }
    return json.dumps(catalogue, ensure_ascii=False)


def _portal_database_column_strings() -> str:
    """Translated strings for the column-management script, as one JSON attribute.

    The row sheet ships no inline ``<script>``; handing the vocabulary down on
    the sheet element keeps the translation catalogue the single source of every
    user-facing word while leaving the module free of Polish.
    """
    catalogue = {
        "pin_refused": _tr("db.col.pin_refused"),
        "min_one": _tr("db.cols.min_one"),
        "resize_aria": _tr("db.col.resize_aria"),
        "no_matches": _tr("db.cols.no_matches"),
        "moved": _tr("db.cols.moved"),
    }
    return json.dumps(catalogue, ensure_ascii=False)


# ---------------------------------------------------------------------------
# Column-centric filtering and sorting (DB-005)
#
# One canonical server contract, two presentation paths.
#
#   * the column header menu — applies immediately on confirmation (`D-005`);
#   * the filter panel — stages its edits until `Zastosuj`.
#
# Both submit the same GET parameters to the same validator and the same query
# builder, so there is exactly one filter-state model. Every control here is a
# plain form or link and therefore works without JavaScript; `data-grid-filters.js`
# only adds focus management, dismissal and operator-aware field switching.
# ---------------------------------------------------------------------------

# Query parameters that a filter form owns and must therefore not re-emit as
# hidden state. `page` is dropped because any filter change returns to page 1.
PORTAL_DATABASE_FILTER_PARAM_PREFIXES = (
    "filter__", "filter_from__", "filter_to__", "filter_in__", "op__",
    "dateop__", "date__", "date_from__", "date_to__",
)


def _portal_database_drop_unapproved_column_params(
    params: dict[str, list[str]], allowed_names: set[str]
) -> None:
    """Remove column-scoped parameters that do not name an approved column.

    Filters keyed to an unknown column were already inert — the filter builder
    validates every column against the approved set before it reaches SQL — but
    they still rode along into every generated link and hidden input, which meant
    a crafted `filter__record_id=...` was echoed back inside the page.

    Since S6 the technical row identifier must not appear in any filter control
    at all, so the parameters are canonicalized away here, at the same point
    `cols` and the layout state are normalized. The effect is general: no
    caller-supplied column name that the catalog does not approve survives into
    the response.
    """
    for key in [key for key in params if key.startswith(PORTAL_DATABASE_FILTER_PARAM_PREFIXES)]:
        for prefix in PORTAL_DATABASE_FILTER_PARAM_PREFIXES:
            if key.startswith(prefix):
                if key[len(prefix):] not in allowed_names:
                    params.pop(key, None)
                break


def _portal_database_column_menu_id(column_name: str) -> str:
    return "dbcol-" + str(column_name)


def _portal_database_distribution_strings() -> str:
    """Translated strings for the distribution script, as one JSON attribute.

    The row sheet ships no inline ``<script>`` and must not start; handing the
    vocabulary down on the element keeps the translation catalogue the single
    source of every user-facing word while leaving the script free of Polish.
    """
    catalogue = {
        "loading": _tr("db.dist.loading"),
        "error": _tr("db.dist.error"),
        "empty": _tr("db.dist.empty"),
        "allNull": _tr("db.dist.all_null"),
        "singleValue": _tr("db.dist.single_value", value="{value}"),
        "truncated": _tr("db.dist.truncated", shown="{shown}", total="{total}"),
        "scope": _tr("db.dist.scope"),
        "distinct": _tr("db.dist.distinct", count="{count}"),
        "nonNull": _tr("db.dist.non_null", count="{count}"),
        "range": _tr("db.dist.range", min="{min}", max="{max}"),
        "bucket": _tr("db.dist.bucket", min="{min}", max="{max}", count="{count}"),
        "selectValue": _tr("db.dist.select_value", value="{value}", count="{count}"),
        "selectBlank": _tr("db.dist.select_blank", count="{count}"),
        "search": _tr("db.dist.search"),
        "searchHint": _tr("db.dist.search_hint"),
        "noMatches": _tr("db.dist.no_matches"),
        "offList": _tr("db.dist.off_list", count="{count}"),
        "limitReached": _tr("db.dist.limit_reached", limit="{limit}"),
        "nullMarker": _tr("db.value.null"),
        "blankMarker": _tr("db.value.blank"),
        "maxValues": str(PORTAL_DATABASE_MAX_IN_VALUES),
    }
    return json.dumps(catalogue, ensure_ascii=False)


def _portal_database_distribution_url(dataset_id: str, params: dict[str, list[str]], column_name: str) -> str:
    """On-demand aggregate URL for one column.

    Carries only the parameters that define the scope — the active filters and
    the search. Paging, density, sort and the column selection are deliberately
    absent: none of them changes which rows the aggregate covers, and leaving
    them out keeps that obvious. The column's own filter is left in and stripped
    server-side, so the faceting rule lives in exactly one place.
    """
    scope: dict[str, list[str]] = {}
    for key, values in params.items():
        if key == "search" or key.startswith(PORTAL_DATABASE_FILTER_PARAM_PREFIXES) or key in {"date_from", "date_to"}:
            kept = [value for value in values if str(value).strip()]
            if kept:
                scope[key] = kept
    scope["column"] = [str(column_name)]
    return (
        f"/user/database/datasets/{quote(str(dataset_id))}/distribution?"
        + urlencode(scope, doseq=True)
    )


def _portal_database_hidden_inputs_except(params: dict[str, list[str]], *, exclude_keys: set[str], exclude_prefixes: tuple[str, ...] = ()) -> str:
    parts = []
    for key, values in params.items():
        if key in exclude_keys:
            continue
        if exclude_prefixes and key.startswith(exclude_prefixes):
            continue
        for value in values:
            parts.append(f'<input type="hidden" name="{_html(key)}" value="{_html(value)}">')
    return "".join(parts)


def _portal_database_operator_options(operators: list[str], selected: str) -> str:
    return "".join(
        f'<option value="{_html(op)}"{" selected" if op == selected else ""}>'
        f"{_html(_portal_database_operator_label(op))}</option>"
        for op in operators
    )


def _portal_database_date_operator_options(selected: str) -> str:
    return "".join(
        f'<option value="{_html(op)}"{" selected" if op == selected else ""}>'
        f"{_html(_portal_database_operator_label(op))}</option>"
        for op in ("older", "newer", "range", "blank")
    )


def _portal_database_date_strings(input_type: str) -> str:
    """Vocabulary for the date-range script, as one JSON attribute.

    Same mechanism as `_portal_database_distribution_strings`: the page ships no
    inline `<script>`, so the catalogue travels on the element and the script
    itself stays free of Polish.
    """
    catalogue = {
        "formatHint": _tr(
            "db.date.format_hint_time" if input_type == "datetime-local" else "db.date.format_hint"
        ),
        "singleLabel": _tr("db.date.single_label", column="{column}"),
        "openCalendar": _tr("db.date.open_calendar"),
        "closeCalendar": _tr("db.date.close_calendar"),
        "invalid": _tr("db.date.invalid"),
        "calendarLabel": _tr("db.date.calendar_label"),
        "prevMonth": _tr("db.date.prev_month"),
        "nextMonth": _tr("db.date.next_month"),
        "pickStart": _tr("db.date.pick_start"),
        "pickEnd": _tr("db.date.pick_end"),
        "rangeSelected": _tr("db.date.range_selected", **{"from": "{from}", "to": "{to}"}),
        "inRange": _tr("db.date.in_range"),
        "rangeStart": _tr("db.date.range_start"),
        "rangeEnd": _tr("db.date.range_end"),
        "clearRange": _tr("db.date.clear_range"),
        "months": _tr("db.date.months"),
        "weekdays": _tr("db.date.weekdays"),
    }
    return json.dumps(catalogue, ensure_ascii=False)


def _portal_database_filter_value_controls(
    column: dict,
    *,
    entry: dict | None,
    id_prefix: str,
) -> str:
    """The value control(s) for one column's filter, matched to its data family.

    Rendered for every operator the family allows; the operator select decides
    which ones matter, and the script hides the irrelevant ones. Server-side the
    unused fields are simply ignored, so the no-script path stays correct.
    """
    column_name = str(column.get("column_name") or "")
    label = str(column.get("display_name") or column_name)
    family = _portal_database_type_family(column.get("data_type"))
    entry = entry or {}
    operator = str(entry.get("operator") or "")
    value = str(entry.get("value") or "")
    value_to = str(entry.get("value_to") or "")
    values = [str(item) for item in (entry.get("values") or [])]
    value_id = f"{id_prefix}filter__{column_name}"
    to_id = f"{id_prefix}filter_to__{column_name}"

    if family == "boolean":
        # Boolean has no value control at all: the operator IS the value
        # (`wszystko` / `tak` / `nie` / `puste`).
        return ""

    if family == "date":
        input_type = _portal_database_date_input_type(column)
        placeholder = "YYYY-MM-DDTHH:MM" if input_type == "datetime-local" else "YYYY-MM-DD"
        single = value if operator in {"older", "newer"} else ""
        from_value = value if operator == "range" else ""
        to_value = value_to if operator == "range" else ""
        # data-grid-daterange.js turns each of these into a hidden carrier of the
        # wire value behind one visible `dd.mm.rrrr gg:mm` field, and hangs one
        # collapsed calendar off the group. All of it is progressive: the values
        # written back are these exact names and formats, so the request and the
        # no-script path are byte-identical with or without the script.
        return (
            f'<div class="db-filter-value" data-db-value-single{"" if operator in {"older", "newer", ""} else " hidden"}>'
            f'<label class="lp-visually-hidden" for="{_html(value_id)}">{_html(_tr("db.menu.value_label", column=label))}</label>'
            f'<input id="{_html(value_id)}" name="date__{_html(column_name)}" type="{_html(input_type)}" '
            f'value="{_html(single)}" placeholder="{_html(placeholder)}" data-db-date-input="single"></div>'
            f'<div class="db-filter-value db-filter-range" data-db-value-range{"" if operator == "range" else " hidden"}'
            f' data-db-date-range data-db-column="{_html(column_name)}">'
            f'<label for="{_html(to_id)}-from">{_html(_tr("db.menu.value_from"))}</label>'
            f'<input id="{_html(to_id)}-from" name="date_from__{_html(column_name)}" type="{_html(input_type)}" '
            f'value="{_html(from_value)}" placeholder="{_html(placeholder)}" data-db-date-input="from">'
            f'<label for="{_html(to_id)}-to">{_html(_tr("db.menu.value_to"))}</label>'
            f'<input id="{_html(to_id)}-to" name="date_to__{_html(column_name)}" type="{_html(input_type)}" '
            f'value="{_html(to_value)}" placeholder="{_html(placeholder)}" data-db-date-input="to"></div>'
        )

    placeholder = "0" if family == "numeric" else ""
    single_value = value if operator not in {"in", "between"} else ""
    parts = [
        f'<div class="db-filter-value" data-db-value-single{"" if operator not in {"in", "between", "blank"} else " hidden"}>'
        f'<label class="lp-visually-hidden" for="{_html(value_id)}">{_html(_tr("db.menu.value_label", column=label))}</label>'
        f'<input id="{_html(value_id)}" name="filter__{_html(column_name)}" type="text" '
        f'value="{_html(single_value)}" placeholder="{_html(placeholder)}"></div>'
    ]
    allowed = _portal_database_allowed_operators(column)
    if "between" in allowed:
        parts.append(
            f'<div class="db-filter-value db-filter-range" data-db-value-range{"" if operator == "between" else " hidden"}>'
            f'<label for="{_html(to_id)}-from">{_html(_tr("db.menu.value_from"))}</label>'
            f'<input id="{_html(to_id)}-from" name="filter_from__{_html(column_name)}" type="text" '
            f'value="{_html(value if operator == "between" else "")}" placeholder="{_html(placeholder)}">'
            f'<label for="{_html(to_id)}-to">{_html(_tr("db.menu.value_to"))}</label>'
            f'<input id="{_html(to_id)}-to" name="filter_to__{_html(column_name)}" type="text" '
            f'value="{_html(value_to)}" placeholder="{_html(placeholder)}"></div>'
        )
    if "in" in allowed:
        # `data-db-selected` is the authoritative current selection: the exact
        # values the builder validated, JSON-encoded so whitespace-only text,
        # leading or trailing spaces and embedded newlines survive. The textarea
        # is the human, no-script form and cannot represent those, so the script
        # seeds itself from the attribute and writes back through
        # `filter_exact__`, which the server prefers when present. With no
        # script only the textarea exists, and S3 behaviour is unchanged.
        parts.append(
            f'<div class="db-filter-value db-filter-multi" data-db-value-multi{"" if operator == "in" else " hidden"}'
            f' data-db-selected="{_html(json.dumps(values, ensure_ascii=False))}">'
            f'<label for="{_html(value_id)}-in">{_html(_tr("db.menu.values_label", column=label))}</label>'
            f'<textarea id="{_html(value_id)}-in" name="filter_in__{_html(column_name)}" rows="4">'
            f'{_html(chr(10).join(values))}</textarea>'
            f'<div class="db-filter-exact" data-db-exact-values data-db-exact-name="filter_exact__{_html(column_name)}"></div>'
            "</div>"
        )
    return "".join(parts)


def _portal_database_filter_fieldset(
    column: dict,
    *,
    entry: dict | None,
    id_prefix: str,
) -> str:
    """Operator select plus value controls for one column, used by menu and panel."""
    column_name = str(column.get("column_name") or "")
    label = str(column.get("display_name") or column_name)
    family = _portal_database_type_family(column.get("data_type"))
    entry = entry or {}
    operator = str(entry.get("operator") or "")
    if family == "date":
        operator_name = f"dateop__{column_name}"
        selected = operator if operator in PORTAL_DATABASE_DATE_FILTER_OPERATORS else "range"
        options = _portal_database_date_operator_options(selected)
    else:
        operator_name = f"op__{column_name}"
        allowed = _portal_database_allowed_operators(column)
        selected = operator if operator in allowed else allowed[0]
        if family == "boolean":
            # `wszystko` is the absence of a filter, so it submits an empty
            # operator and the builder simply never sees this column.
            options = f'<option value=""{"" if operator else " selected"}>{_html(_tr("db.op.all"))}</option>' + _portal_database_operator_options(allowed, selected if operator else "")
        else:
            options = _portal_database_operator_options(allowed, selected)
    operator_id = f"{id_prefix}{operator_name}"
    note = ""
    if "blank" in (_portal_database_allowed_operators(column) if family != "date" else ["blank"]):
        note_key = "db.menu.blank_text_note" if family == "text" else "db.menu.blank_note"
        note = f'<p class="db-col-note" data-db-blank-note>{_html(_tr(note_key))}</p>'
    # `data-db-date-*` sits on the GROUP, not on one of the value divs: the
    # operator select switches between the single and the range control, and
    # data-grid-daterange.js gives both the same field treatment and one shared
    # calendar. Identical markup reaches the column menu (`m-`) and the aggregate
    # filter drawer (`p-`), so the two surfaces cannot drift apart.
    date_group_attrs = ""
    if family == "date":
        date_input_type = _portal_database_date_input_type(column)
        date_group_attrs = (
            f' data-db-date-group data-db-date-type="{_html(date_input_type)}"'
            f' data-db-date-column="{_html(label)}"'
            f' data-db-strings="{_html(_portal_database_date_strings(date_input_type))}"'
        )
    return (
        '<div class="db-filter-controls" data-db-filter-controls '
        f'data-db-family="{_html(family)}"{date_group_attrs}>'
        f'<label class="lp-visually-hidden" for="{_html(operator_id)}">{_html(_tr("db.menu.operator_label", column=label))}</label>'
        f'<select class="db-op-select" id="{_html(operator_id)}" name="{_html(operator_name)}" data-db-op>{options}</select>'
        + _portal_database_filter_value_controls(column, entry=entry, id_prefix=id_prefix)
        + note
        + "</div>"
    )


def _portal_database_visibility_url(
    dataset_id: str,
    params: dict[str, list[str]],
    names: list[str],
    allowed_columns: list[dict],
    *,
    extra: dict[str, Any] | None = None,
) -> str:
    """A link that changes only which approved columns are displayed.

    `cols` keeps its narrowing-only meaning: the value written here is always a
    subset of the approved catalog, in catalog order, and it is dropped entirely
    when the subset is the whole set, so the "all approved columns" state stays
    representable as the absence of the parameter rather than as a list that a
    later catalog change would silently freeze.
    """
    allowed = [str(column.get("column_name") or "") for column in allowed_columns]
    wanted = [name for name in allowed if name in set(names)]
    next_params = {key: list(values) for key, values in params.items() if values}
    if wanted and len(wanted) < len(allowed):
        next_params["cols"] = wanted
    else:
        next_params.pop("cols", None)
    next_params["page"] = ["1"]
    for key, value in (extra or {}).items():
        if value is None:
            next_params.pop(key, None)
        else:
            next_params[key] = [str(value)]
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}" + (f"?{query}" if query else "")


def _portal_database_column_resize_handle_html(
    dataset_id: str,
    column: dict,
    params: dict[str, list[str]],
    layout: dict,
    visible_columns: list[dict],
    rows: list[dict],
) -> str:
    """The header's right-edge resize affordance (`DB-29`).

    Pointer drag and double-click autofit are added by data-grid-columns.js. The
    element is still meaningful without it: it is a real link to the column's
    autofitted width, so the one affordance the approved design calls
    pointer-first (`ACCESSIBILITY_SPEC` §4) still does something on `Enter` with
    no script at all, and it carries an accessible name that includes the column.
    """
    column_name = str(column.get("column_name") or "")
    label = str(column.get("display_name") or column_name)
    width = layout["effective_widths"].get(column_name)
    if width is None:
        return ""
    autofit = _portal_database_autofit_width(column, rows)
    widths = dict(layout["widths"])
    widths[column_name] = autofit
    href = _portal_database_column_layout_url(
        dataset_id, params, layout, widths=widths, visible_columns=visible_columns
    )
    return (
        f'<a class="db-col-resize" href="{_html(href)}" data-db-resize '
        f'data-db-column="{_html(column_name)}" data-db-width="{width}" '
        f'data-db-autofit="{autofit}" '
        f'aria-label="{_html(_tr("db.col.resize_aria", column=label, width=width))}"></a>'
    )


def _portal_database_column_actions_html(
    dataset: dict,
    column: dict,
    params: dict[str, list[str]],
    layout: dict,
    visible_columns: list[dict],
    allowed_columns: list[dict],
    rows: list[dict],
) -> str:
    """`TGS` §5.1 section 5 — pin, hide and fit, for one column.

    Every control is a link or a plain form, so the whole section works with
    scripting unavailable and is reachable by keyboard. The explicit width field
    is the approved accessible equivalent of pointer resize.
    """
    dataset_id = str(dataset.get("dataset_id") or "")
    column_name = str(column.get("column_name") or "")
    label = str(column.get("display_name") or column_name)
    pins = list(layout["pins"])
    display_names = list(layout["display_names"])
    rows_html: list[str] = []

    if column_name in pins:
        unpinned = [name for name in pins if name != column_name]
        href = _portal_database_column_layout_url(
            dataset_id, params, layout, pins=unpinned, visible_columns=visible_columns
        )
        rows_html.append(
            f'<a class="db-col-action" href="{_html(href)}" data-db-pin="off" '
            f'data-db-column="{_html(column_name)}">{_html(_tr("db.col.unpin"))}</a>'
        )
    else:
        candidate = pins + [column_name]
        # Viewport safety (grid spec §1.3) is stated before the user acts rather
        # than discovered afterwards: an offer that the resolver would refuse is
        # replaced by the reason it would refuse it.
        width = layout["effective_widths"].get(column_name, PORTAL_DATABASE_COLUMN_FALLBACK_WIDTH_PX)
        would_exceed = (
            len(candidate) > PORTAL_DATABASE_MAX_PINNED_COLUMNS
            or (pins and layout["pinned_width"] + width > PORTAL_DATABASE_MAX_PINNED_WIDTH_PX)
        )
        if would_exceed:
            rows_html.append(
                f'<p class="db-col-note db-col-refusal" role="note">{_html(_tr("db.col.pin_refused"))}</p>'
            )
        else:
            href = _portal_database_column_layout_url(
                dataset_id, params, layout, pins=candidate, visible_columns=visible_columns
            )
            rows_html.append(
                f'<a class="db-col-action" href="{_html(href)}" data-db-pin="on" '
                f'data-db-column="{_html(column_name)}">{_html(_tr("db.col.pin"))}</a>'
            )

    # At least one data column must remain visible (`DB-28`). The action is
    # absent rather than disabled when it would empty the sheet, which is the
    # approved treatment for a permanently unavailable control.
    if len(display_names) > 1:
        remaining = [name for name in display_names if name != column_name]
        href = _portal_database_visibility_url(dataset_id, params, remaining, allowed_columns)
        rows_html.append(
            f'<a class="db-col-action" href="{_html(href)}">{_html(_tr("db.col.hide"))}</a>'
        )

    autofit = _portal_database_autofit_width(column, rows)
    widths = dict(layout["widths"])
    widths[column_name] = autofit
    fit_href = _portal_database_column_layout_url(
        dataset_id, params, layout, widths=widths, visible_columns=visible_columns
    )
    rows_html.append(
        f'<a class="db-col-action" href="{_html(fit_href)}" data-db-autofit-action '
        f'data-db-column="{_html(column_name)}" data-db-autofit="{autofit}">'
        f'{_html(_tr("db.col.autofit"))}</a>'
    )

    current_width = layout["effective_widths"].get(column_name, PORTAL_DATABASE_COLUMN_FALLBACK_WIDTH_PX)
    field_id = f"dbw-{column_name}"
    own_keys = {PORTAL_DATABASE_COLUMN_WIDTH_PARAM_PREFIX + column_name, "page"}
    rows_html.append(
        '<form class="db-col-width" method="get" data-db-width-form>'
        + _portal_database_hidden_inputs_except(params, exclude_keys=own_keys)
        + f'<label for="{_html(field_id)}">{_html(_tr("db.col.width_label", column=label))}</label>'
        + f'<input id="{_html(field_id)}" type="number" inputmode="numeric" '
        + f'name="{_html(PORTAL_DATABASE_COLUMN_WIDTH_PARAM_PREFIX + column_name)}" '
        + f'value="{current_width}" min="{PORTAL_DATABASE_COLUMN_MIN_WIDTH_PX}" '
        + f'max="{PORTAL_DATABASE_COLUMN_MAX_WIDTH_PX}" step="8">'
        + f'<button class="db-col-apply" type="submit">{_html(_tr("db.col.width_apply"))}</button>'
        + "</form>"
    )
    return (
        '<div class="db-col-section db-col-actions-section">'
        f'<p class="db-col-section-head">{_html(_tr("db.col.actions_heading"))}</p>'
        + "".join(rows_html)
        + "</div>"
    )


def _portal_database_column_menu_html(
    dataset: dict,
    column: dict,
    params: dict[str, list[str]],
    *,
    sort_column: str | None,
    direction: str,
    entry: dict | None,
    layout: dict | None = None,
    visible_columns: list[dict] | None = None,
    allowed_columns: list[dict] | None = None,
    rows: list[dict] | None = None,
) -> str:
    """`DB-005` for one column: identity, sort, filter, distribution and actions.

    Sort rows are links, so they apply immediately. The filter is a GET form
    whose submit applies immediately too — the approved column-menu semantics.
    The S5 column-actions section (pin, hide, autofit, explicit width) is links
    and one plain form for the same reason.
    """
    dataset_id = str(dataset.get("dataset_id") or "")
    column_name = str(column.get("column_name") or "")
    label = str(column.get("display_name") or column_name)
    family = _portal_database_type_family(column.get("data_type"))
    sortable = bool(column.get("is_sortable"))
    can_filter = bool(dataset.get("can_filter_rows")) and bool(column.get("is_filterable"))
    has_actions = layout is not None and column_name in layout.get("effective_widths", {})
    if not sortable and not can_filter and not has_actions:
        return ""

    # `TGS` 5.1 item 1 asks for a non-null count "for the current result set",
    # which is an aggregate. The slot is rendered empty and filled by the same
    # on-demand request that fills the distribution, so opening the sheet still
    # costs no aggregate query at all.
    sections = [
        '<p class="db-col-identity">'
        f'<span class="db-col-identity-name lp-mono">{_html(column_name)}</span>'
        f'<span class="db-col-identity-type">{_html(str(column.get("data_type") or ""))}</span>'
        '<span class="db-col-identity-count" data-db-nonnull></span></p>'
    ]

    if sortable:
        asc_label = _tr("db.menu.sort_asc_text") if family == "text" else _tr("db.menu.sort_asc")
        desc_label = _tr("db.menu.sort_desc_text") if family == "text" else _tr("db.menu.sort_desc")
        sort_rows = []
        for label_text, wanted in ((asc_label, "asc"), (desc_label, "desc")):
            active = sort_column == column_name and direction == wanted
            href = _portal_database_url(dataset_id, params, sort=column_name, direction=wanted, page=1)
            current = ' aria-current="true"' if active else ""
            sort_rows.append(
                f'<a class="db-col-action{" active" if active else ""}" href="{_html(href)}"{current}>{_html(label_text)}</a>'
            )
        sections.append(
            '<div class="db-col-section">'
            f'<p class="db-col-section-head">{_html(_tr("db.menu.sort_heading"))}</p>'
            + "".join(sort_rows)
            + f'<p class="db-col-note">{_html(_tr("db.menu.nulls_last"))}</p>'
            "</div>"
        )

    if can_filter:
        own_keys = set(_portal_database_filter_param_keys(column_name)) | set(
            _portal_database_date_filter_param_keys(column_name)
        )
        hidden = _portal_database_hidden_inputs_except(params, exclude_keys=own_keys | {"page"})
        clear_overrides: dict[str, Any] = {key: None for key in sorted(own_keys)}
        clear_overrides["page"] = 1
        clear_url = _portal_database_url(dataset_id, params, **clear_overrides)
        clear_html = (
            f'<a class="db-col-clear" href="{_html(clear_url)}">{_html(_tr("db.clear_one"))}</a>'
            if entry
            else ""
        )
        sections.append(
            '<form class="db-col-section db-col-filter" method="get" data-db-col-form>'
            f'<p class="db-col-section-head">{_html(_tr("db.menu.filter_heading"))}</p>'
            + hidden
            + _portal_database_filter_fieldset(column, entry=entry, id_prefix="m-")
            + '<div class="db-col-actions">'
            + f'<button class="db-col-apply" type="submit">{_html(_tr("db.apply"))}</button>'
            + clear_html
            + "</div>"
            + f'<p class="db-col-hint">{_html(_tr("db.menu.keyboard_hint"))}</p>'
            "</form>"
        )

        # Distribution placeholder (`TGS` 5.1 item 4): the distinct-value picker
        # for text, the histogram for numeric, and nothing for boolean or date —
        # the approved contract gives those families no distribution.
        #
        # Only the container ships in the initial HTML. Rendering values or
        # buckets for every approved column up front would put thousands of
        # nodes on a page for menus the user may never open, so the body is
        # fetched when the menu opens and never before.
        mode = _portal_database_distribution_mode(column)
        heading_key = (
            "db.dist.values_heading" if mode == "categorical"
            else "db.dist.distribution_heading" if mode == "numeric"
            else ""
        )
        distribution_url = _portal_database_distribution_url(dataset_id, params, column_name)
        if heading_key:
            sections.append(
                '<div class="db-col-section db-distribution" data-db-distribution '
                f'data-db-distribution-url="{_html(distribution_url)}" '
                f'data-db-distribution-mode="{_html(mode)}" '
                f'data-db-strings="{_html(_portal_database_distribution_strings())}" '
                f'data-db-column="{_html(column_name)}">'
                f'<p class="db-col-section-head">{_html(_tr(heading_key))}</p>'
                '<div class="db-distribution-body" data-db-distribution-body '
                'role="status" aria-live="polite" aria-busy="false"></div>'
                "</div>"
            )
        else:
            # No distribution for this family, but the identity count still
            # needs its one cheap aggregate.
            sections.append(
                '<div class="db-distribution-summary" data-db-distribution '
                f'data-db-distribution-url="{_html(distribution_url)}" '
                f'data-db-distribution-mode="{_html(mode)}" '
                f'data-db-strings="{_html(_portal_database_distribution_strings())}" '
                f'data-db-column="{_html(column_name)}" hidden></div>'
            )

    if has_actions:
        sections.append(
            _portal_database_column_actions_html(
                dataset, column, params, layout, visible_columns or [], allowed_columns or [], rows or []
            )
        )

    if entry:
        trigger_label = _tr("db.menu.aria_filtered", column=label, filter=_portal_database_filter_chip_text(entry))
    elif sort_column == column_name:
        trigger_label = _tr(
            "db.menu.aria_sorted_desc" if direction == "desc" else "db.menu.aria_sorted_asc",
            column=label,
        )
    else:
        trigger_label = _tr("db.menu.aria", column=label)

    caret = ""
    if sort_column == column_name:
        glyph = "↓" if direction == "desc" else "↑"
        caret = f'<span class="db-sort-caret" aria-hidden="true">{glyph}</span>'
    marker = '<span class="db-col-filtered-mark" aria-hidden="true">≡</span>' if entry else ""

    return (
        f'<details class="db-col-menu" id="{_html(_portal_database_column_menu_id(column_name))}" '
        f'data-db-col-menu data-db-column="{_html(column_name)}">'
        f'<summary class="db-col-trigger" aria-label="{_html(trigger_label)}">'
        f'<span class="db-col-label">{_html(label)}</span>{caret}{marker}'
        '<span class="db-col-caret" aria-hidden="true">▾</span>'
        "</summary>"
        f'<div class="db-col-panel" role="group" aria-label="{_html(trigger_label)}">'
        + "".join(sections)
        + "</div></details>"
    )


def _portal_database_filter_panel(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    filter_entries: list[dict] | None,
    chips: list[dict],
    *,
    menu_columns: set[str] | None = None,
) -> str:
    """The aggregate filter surface: `Aktywne — n`, `Dodaj filtr`, date presets.

    Edits here are **staged**. The whole section is one GET form and nothing
    reaches the server until `Zastosuj` is submitted, so closing or abandoning the
    panel cannot apply a half-finished change (`D-005`, `DB-14`).

    It deliberately renders inputs only for filters that are already active, plus
    a way to reach any other column's menu. The pre-redesign form rendered a
    field for all 42 approved columns at once and is not reinstated.
    """
    if not dataset.get("can_filter_rows"):
        # Approved contract: an unavailable capability is absent, never a
        # disabled control (`DB-62`).
        return ""
    dataset_id = str(dataset.get("dataset_id") or "")
    filterable = [column for column in columns if column.get("is_filterable")]
    if not filterable:
        return ""
    by_name = {str(column.get("column_name") or ""): column for column in filterable}
    entries = [
        entry for entry in (filter_entries or [])
        if str(entry.get("column_name") or "") != "__search__" and str(entry.get("column_name") or "") in by_name
    ]

    active_rows = []
    for entry in entries:
        column_name = str(entry.get("column_name") or "")
        column = by_name[column_name]
        chip = next((item for item in chips if item.get("column_name") == column_name), None)
        remove_html = ""
        if chip:
            remove_html = (
                f'<a class="db-panel-remove" href="{_html(chip["remove_url"])}" '
                f'aria-label="{_html(chip["remove_label"])}" title="{_html(chip["remove_label"])}">×</a>'
            )
        active_rows.append(
            '<div class="db-panel-filter">'
            '<div class="db-panel-filter-head">'
            f'<span class="db-panel-filter-label">{_html(str(entry.get("label") or column_name))}</span>'
            f"{remove_html}</div>"
            + _portal_database_filter_fieldset(column, entry=entry, id_prefix="p-")
            + "</div>"
        )
    if active_rows:
        active_html = "".join(active_rows)
    else:
        active_html = f'<p class="db-panel-empty">{_html(_tr("db.panel.none_active"))}</p>'

    active_names = {str(entry.get("column_name") or "") for entry in entries}
    add_links = []
    for column in filterable:
        column_name = str(column.get("column_name") or "")
        if column_name in active_names:
            continue
        if menu_columns is not None and column_name not in menu_columns:
            # A column the user has hidden from the table has no header menu to
            # open, and an anchor to a menu that is not on the page is a dead
            # control. It reappears here as soon as the column is shown again.
            continue
        href = "#" + _portal_database_column_menu_id(column_name)
        add_links.append(
            f'<a class="db-panel-add-item" href="{_html(href)}" data-db-add-column="{_html(column_name)}">'
            f'{_html(str(column.get("display_name") or column_name))}</a>'
        )
    add_html = ""
    if add_links:
        add_html = (
            '<div class="db-panel-section">'
            f'<h3 class="db-panel-heading">{_html(_tr("db.panel.add"))}</h3>'
            '<label class="lp-visually-hidden" for="db-panel-find">'
            f'{_html(_tr("db.panel.find_column"))}</label>'
            f'<input class="db-panel-find" id="db-panel-find" type="search" '
            f'placeholder="{_html(_tr("db.panel.find_column"))}" data-db-column-search>'
            '<div class="db-panel-add-list">' + "".join(add_links) + "</div></div>"
        )

    presets = _portal_database_date_preset_links(dataset, columns, params)
    presets_html = ""
    if presets:
        presets_html = (
            '<div class="db-panel-section">'
            f'<h3 class="db-panel-heading">{_html(_tr("db.panel.presets"))}</h3>{presets}</div>'
        )

    # The staged form owns every filter parameter it renders; the rest of the
    # view state rides along as hidden inputs so applying filters preserves sort,
    # density, page size and the column selection.
    hidden = _portal_database_hidden_inputs_except(
        params,
        exclude_keys={"page"},
        exclude_prefixes=PORTAL_DATABASE_FILTER_PARAM_PREFIXES,
    )
    reset_url = _portal_database_reset_url(dataset_id, params)
    # `RSP-002`: below 1024 px this exact markup is relocated by CSS into an
    # overlay drawer over a scrim. It is relocated, never duplicated — there is
    # one panel, one form and one staged state at every width, so a breakpoint
    # change can neither apply, discard nor double-submit a staged edit, and no
    # filter parameter is ever carried by two successful controls at once.
    #
    # The drawer head and the scrim are inert at the docked widths: the
    # stylesheet removes them with `display: none`, which takes the close button
    # out of the tab order as well as off the screen.
    return (
        '<div class="db-filter-scrim" data-db-filter-scrim></div>'
        '<div class="db-filter-panel" role="group" '
        f'aria-label="{_html(_tr("db.panel.aria"))}" data-db-filter-panel>'
        '<div class="db-filter-drawer-head">'
        f'<span class="db-filter-drawer-title" data-db-filter-drawer-title>{_html(_tr("db.panel.aria"))}</span>'
        f'<button class="db-filter-drawer-close" type="button" data-db-filter-close '
        f'aria-label="{_html(_tr("db.panel.close"))}">&#215;</button>'
        "</div>"
        '<form class="db-panel-form" method="get" data-db-panel-form>'
        + hidden
        + '<div class="db-panel-scroll">'
        + '<div class="db-panel-section">'
        + f'<h3 class="db-panel-heading">{_html(_tr("db.panel.active", count=len(entries)))}</h3>'
        + active_html
        + "</div>"
        + add_html
        + presets_html
        + f'<p class="db-col-hint">{_html(_tr("db.menu.keyboard_hint"))}</p>'
        + "</div>"
        + '<div class="db-panel-actions">'
        + f'<button class="portal-button db-panel-apply" type="submit">{_html(_tr("db.apply"))}</button>'
        + f'<a class="portal-button secondary db-panel-clear" href="{_html(reset_url)}">{_html(_tr("db.clear_all"))}</a>'
        + "</div>"
        + "</form></div>"
    )


def _portal_request_ip(request: Request | None) -> str | None:
    client = getattr(request, "client", None)
    host = getattr(client, "host", None)
    return str(host) if host else None


def _portal_request_user_agent(request: Request | None) -> str | None:
    headers = getattr(request, "headers", None)
    if headers is None:
        return None
    try:
        value = headers.get("user-agent")
    except AttributeError:
        value = None
    return str(value) if value else None


def _portal_uuid_or_none(value: Any) -> str | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return str(uuid.UUID(text))
    except ValueError:
        return None


def _portal_audit_filter_keys(params: dict[str, list[str]]) -> list[str]:
    keys = []
    # Column names only — never operators or values, which may carry business
    # data. The S3 value-variant parameters are included so the audit record
    # keeps naming every filtered column.
    value_prefixes = ("filter__", "filter_from__", "filter_to__", "filter_in__")
    date_prefixes = ("date__", "date_from__", "date_to__")
    for key, values in params.items():
        if key.startswith(value_prefixes) and any(str(value).strip() for value in values):
            column = key.split("__", 1)[1] if "__" in key else ""
            if PORTAL_DATABASE_IDENTIFIER_RE.fullmatch(column):
                keys.append(column)
            continue
        # A value-less operator (`puste`, `tak`, `nie`) filters a column while
        # carrying no value parameter at all, so the column name has to come
        # from the operator key or the audit record would omit it.
        if key.startswith(("op__", "dateop__")) and _portal_database_first_param(params, key, "").strip().lower() in PORTAL_DATABASE_VALUELESS_OPERATORS:
            column = key.split("__", 1)[1] if "__" in key else ""
            if PORTAL_DATABASE_IDENTIFIER_RE.fullmatch(column):
                keys.append(column)
            continue
        if key.startswith(date_prefixes) and any(str(value).strip() for value in values):
            column = key.split("__", 1)[1] if "__" in key else ""
            if PORTAL_DATABASE_IDENTIFIER_RE.fullmatch(column):
                keys.append(column)
    return sorted(set(keys))


def _portal_database_export_metadata(
    *,
    format_name: str,
    row_limit: int | None,
    row_count: int | None,
    params: dict[str, list[str]],
    state: dict | None = None,
    reason: str | None = None,
    requested_dataset_id: str | None = None,
    extra: dict[str, Any] | None = None,
) -> dict:
    state = state or {}
    metadata = {
        "format": format_name,
        "row_limit": row_limit,
        "row_count": row_count,
        "sort": state.get("sort") or _portal_database_first_param(params, "sort", "") or None,
        "direction": state.get("direction") or _portal_database_first_param(params, "direction", "") or None,
        "filter_keys": _portal_audit_filter_keys(params),
        "date_from": _portal_database_first_param(params, "date_from", "") or None,
        "date_to": _portal_database_first_param(params, "date_to", "") or None,
        "search_present": True if _portal_database_first_param(params, "search", "").strip() else None,
    }
    if reason:
        metadata["reason"] = reason
    if requested_dataset_id:
        metadata["requested_dataset_id"] = requested_dataset_id
    if extra:
        # Internal structured export metadata only; canonical audit fields win.
        for key, value in extra.items():
            metadata.setdefault(key, value)
    return {key: value for key, value in metadata.items() if value not in (None, "")}


def _portal_database_rows_metadata(
    *,
    page: int | None,
    limit: int | None,
    row_count: int | None,
    visible_column_count: int | None,
    params: dict[str, list[str]],
    state: dict | None = None,
    reason: str | None = None,
    requested_dataset_id: str | None = None,
    extra: dict | None = None,
) -> dict:
    state = state or {}
    metadata = {
        "page": page,
        "limit": limit,
        "row_count": row_count,
        "visible_column_count": visible_column_count,
        "sort": state.get("sort") or _portal_database_first_param(params, "sort", "") or None,
        "direction": state.get("direction") or _portal_database_first_param(params, "direction", "") or None,
        "filter_keys": _portal_audit_filter_keys(params),
        "date_from": _portal_database_first_param(params, "date_from", "") or None,
        "date_to": _portal_database_first_param(params, "date_to", "") or None,
        "search_present": True if _portal_database_first_param(params, "search", "").strip() else None,
        "cols_selected": True if (params.get("cols") or []) else None,
    }
    if reason:
        metadata["reason"] = reason
    if requested_dataset_id:
        metadata["requested_dataset_id"] = requested_dataset_id
    if extra:
        # Presence-only flags (e.g. row_detail/row_found/duplicate_identifier); never raw row values.
        metadata.update(extra)
    return {key: value for key, value in metadata.items() if value not in (None, "")}


def _portal_audit_key_is_unsafe(key: Any) -> bool:
    normalized = str(key or "").strip().lower()
    return any(pattern in normalized for pattern in PORTAL_AUDIT_UNSAFE_KEY_PATTERNS)


def _sanitize_portal_audit_metadata(value: Any, *, depth: int = 0) -> Any:
    if depth > 4:
        return "[truncated]"
    if isinstance(value, dict):
        clean = {}
        for key, item in value.items():
            key_text = str(key or "")[:100]
            if _portal_audit_key_is_unsafe(key_text):
                clean[key_text] = "[redacted]"
            else:
                sanitized = _sanitize_portal_audit_metadata(item, depth=depth + 1)
                if sanitized not in (None, "", [], {}):
                    clean[key_text] = sanitized
        return clean
    if isinstance(value, (list, tuple, set)):
        return [_sanitize_portal_audit_metadata(item, depth=depth + 1) for item in list(value)[:50]]
    if isinstance(value, (str, int, float, bool)) or value is None:
        if isinstance(value, str):
            return value[:500]
        return value
    return str(value)[:500]


def _create_portal_audit_event(
    *,
    event_type: str,
    actor_user_id: str | None = None,
    client_code: str | None = None,
    dataset_id: str | None = None,
    report_folder_id: str | None = None,
    artifact_id: str | None = None,
    request: Request | None = None,
    metadata_json: dict | None = None,
) -> None:
    if event_type not in PORTAL_AUDIT_EVENT_TYPES:
        raise ValueError("Unsupported portal audit event type.")
    metadata = _sanitize_portal_audit_metadata(metadata_json or {})
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO portal_audit_events
                    (event_type, actor_user_id, client_code, dataset_id, report_folder_id, artifact_id,
                     ip_address, user_agent, metadata_json)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb)
                """,
                (
                    event_type,
                    _portal_uuid_or_none(actor_user_id),
                    client_code or None,
                    _portal_uuid_or_none(dataset_id),
                    _portal_uuid_or_none(report_folder_id),
                    _portal_uuid_or_none(artifact_id),
                    _portal_request_ip(request),
                    _portal_request_user_agent(request),
                    json.dumps(metadata or {}, ensure_ascii=False),
                ),
            )


def _log_portal_audit_event(
    *,
    event_type: str,
    actor_user_id: str | None = None,
    client_code: str | None = None,
    dataset_id: str | None = None,
    report_folder_id: str | None = None,
    artifact_id: str | None = None,
    request: Request | None = None,
    metadata: dict | None = None,
) -> None:
    try:
        _create_portal_audit_event(
            event_type=event_type,
            actor_user_id=actor_user_id,
            client_code=client_code,
            dataset_id=dataset_id,
            report_folder_id=report_folder_id,
            artifact_id=artifact_id,
            request=request,
            metadata_json=metadata,
        )
    except Exception as exc:
        print(f"portal audit write failed: {type(exc).__name__}: {exc}")


def _portal_audit_event_safe(
    *,
    event_type: str,
    actor_user_id: str | None = None,
    client_code: str | None = None,
    dataset_id: str | None = None,
    report_folder_id: str | None = None,
    artifact_id: str | None = None,
    request: Request | None = None,
    metadata_json: dict | None = None,
    metadata: dict | None = None,
) -> None:
    _log_portal_audit_event(
        event_type=event_type,
        actor_user_id=actor_user_id,
        client_code=client_code,
        dataset_id=dataset_id,
        report_folder_id=report_folder_id,
        artifact_id=artifact_id,
        request=request,
        metadata=metadata if metadata is not None else metadata_json,
    )


def _portal_audit_user_metadata(user: dict | None, *, prefix: str = "target") -> dict:
    if not user:
        return {}
    return {
        f"{prefix}_user_id": str(user.get("user_id") or ""),
        f"{prefix}_username": str(user.get("username") or ""),
    }


def _portal_audit_user_metadata_by_id(user_id: str | None, *, prefix: str = "target") -> dict:
    text = str(user_id or "").strip()
    if not text:
        return {}
    try:
        user = _get_portal_user(text)
    except Exception as exc:
        print(f"portal audit user metadata lookup failed: {type(exc).__name__}: {exc}")
        user = None
    metadata = _portal_audit_user_metadata(user, prefix=prefix)
    metadata.setdefault(f"{prefix}_user_id", text)
    return metadata


def _portal_changed_fields(before: dict, after: dict, fields: list[str]) -> list[str]:
    return [field for field in fields if before.get(field) != after.get(field)]


def _portal_database_audit_metadata(dataset: dict | None, **extra: Any) -> dict:
    metadata = dict(extra)
    if dataset:
        metadata.setdefault("dataset_id", str(dataset.get("dataset_id") or ""))
        metadata.setdefault("dataset_name", str(dataset.get("dataset_name") or ""))
        metadata.setdefault("client_code", str(dataset.get("client_code") or ""))
    return metadata


def _portal_report_audit_metadata(folder: dict | None, **extra: Any) -> dict:
    metadata = dict(extra)
    if folder:
        metadata.setdefault("folder_id", str(folder.get("folder_id") or ""))
        metadata.setdefault("folder_name", str(folder.get("folder_name") or ""))
        metadata.setdefault("client_code", str(folder.get("client_code") or ""))
    return metadata


def _portal_database_export_url(dataset_id: str, params: dict[str, list[str]], *, format_name: str) -> str:
    # Export carries the active filters/sort/search but NOT the on-screen page size.
    # The direct export cap is fixed at 20,000 data rows. Larger exports require
    # the explicit background-export form action; this direct GET never queues jobs.
    next_params = {key: list(values) for key, values in params.items() if values and key not in ("page", "limit", "density", "cols", *PORTAL_DATABASE_LAYOUT_PARAM_KEYS)}
    next_params["format"] = [format_name]
    next_params["limit"] = [str(PORTAL_DATABASE_DEFAULT_EXPORT_LIMIT)]
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}/export" + (f"?{query}" if query else "")


def _portal_database_parse_export_limit(params: dict[str, list[str]]) -> tuple[int, int, str | None]:
    limit_raw = _portal_database_first_param(params, "limit", str(PORTAL_DATABASE_DEFAULT_EXPORT_LIMIT))
    try:
        requested_limit = int(limit_raw)
    except ValueError:
        return 1, PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP, "Limit must be a whole number."
    if requested_limit < 1:
        return 1, PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP, "Limit must be at least 1."
    if requested_limit > PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP:
        return 1, PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP, f"Direct export limit cannot exceed {PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP:,} rows."
    return 1, PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP, None


def _portal_database_safe_filename_part(value: Any, *, fallback: str = "export") -> str:
    text = str(value or "").strip().lower()
    text = re.sub(r"[^a-z0-9_.:-]+", "-", text).strip("-._:")
    return text[:80] or fallback


def _portal_database_export_filename(dataset: dict, extension: str) -> str:
    client = _portal_database_safe_filename_part(dataset.get("client_code"), fallback="client")
    slug = _portal_database_safe_filename_part(dataset.get("slug") or dataset.get("dataset_name"), fallback="dataset")
    stamp = utcnow().strftime("%Y%m%d_%H%M%S")
    return f"{client}__{slug}__{stamp}__export.{extension}"


def _portal_database_spreadsheet_safe_text(value: str) -> str:
    formula_prefixes = ("=", "+", "-", "@")
    if value.startswith(formula_prefixes) or value.lstrip("�").startswith(formula_prefixes):
        return "'" + value
    return value


def _portal_database_export_display_value(value: Any) -> Any:
    if value is None:
        return ""
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    if isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            return ""
        return value
    if isinstance(value, Decimal):
        if not value.is_finite():
            return ""
        return value
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, uuid.UUID):
        return str(value)
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value).hex()
    return str(value)


def _portal_database_export_cell_value(value: Any) -> Any:
    normalized = _portal_database_export_display_value(value)
    if isinstance(normalized, str):
        return _portal_database_spreadsheet_safe_text(_portal_database_xlsx_xml10_text(normalized))
    return normalized


def _portal_database_export_row(columns: list[dict], row: dict) -> list[Any]:
    return [_portal_database_export_cell_value(row.get(str(column.get("column_name") or ""))) for column in columns]


def _portal_database_rows_to_csv(columns: list[dict], rows: list[dict]) -> bytes:
    output = io.StringIO(newline="")
    writer = csv.writer(output)
    writer.writerow([_portal_database_spreadsheet_safe_text(str(column.get("display_name") or column.get("column_name") or "")) for column in columns])
    for row in rows:
        writer.writerow(_portal_database_export_row(columns, row))
    return output.getvalue().encode("utf-8-sig")


def _portal_database_xlsx_column_name(index: int) -> str:
    name = ""
    while index:
        index, remainder = divmod(index - 1, 26)
        name = chr(65 + remainder) + name
    return name or "A"


def _portal_database_xlsx_xml10_text(value: str) -> str:
    replacement = "\ufffd"
    cleaned: list[str] = []
    for char in value:
        codepoint = ord(char)
        if codepoint in (0x09, 0x0A, 0x0D) or 0x20 <= codepoint <= 0xD7FF or 0xE000 <= codepoint <= 0xFFFD or 0x10000 <= codepoint <= 0x10FFFF:
            cleaned.append(char)
        else:
            cleaned.append(replacement)
    return "".join(cleaned)


def _portal_database_xlsx_text_cell(ref: str, value: str) -> str:
    safe_value = _portal_database_spreadsheet_safe_text(_portal_database_xlsx_xml10_text(value))
    text = xml_escape(safe_value, {'"': "&quot;"})
    space = ' xml:space="preserve"' if safe_value[:1].isspace() or safe_value[-1:].isspace() else ""
    return f'<c r="{ref}" t="inlineStr"><is><t{space}>{text}</t></is></c>'


def _portal_database_xlsx_cell(ref: str, value: Any) -> str:
    if isinstance(value, bool):
        return f'<c r="{ref}" t="b"><v>{1 if value else 0}</v></c>'
    if isinstance(value, int) and not isinstance(value, bool):
        return f'<c r="{ref}"><v>{value}</v></c>'
    if isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            return _portal_database_xlsx_text_cell(ref, "")
        return f'<c r="{ref}"><v>{value!r}</v></c>'
    if isinstance(value, Decimal):
        if not value.is_finite():
            return _portal_database_xlsx_text_cell(ref, "")
        return f'<c r="{ref}"><v>{format(value, "f")}</v></c>'
    return _portal_database_xlsx_text_cell(ref, str(value))


def _portal_database_rows_sheet_xml(columns: list[dict], rows: list[dict]) -> bytes:
    header = [str(column.get("display_name") or column.get("column_name") or "") for column in columns]
    row_xml: list[str] = []
    all_rows = [
        header,
        *[
            [_portal_database_export_display_value(row.get(str(column.get("column_name") or ""))) for column in columns]
            for row in rows
        ],
    ]
    for row_index, row_values in enumerate(all_rows, start=1):
        cells = []
        for col_index, value in enumerate(row_values, start=1):
            ref = f"{_portal_database_xlsx_column_name(col_index)}{row_index}"
            cells.append(_portal_database_xlsx_cell(ref, value))
        row_xml.append(f'<row r="{row_index}">{"".join(cells)}</row>')
    max_col = max(1, len(columns))
    max_row = max(1, len(all_rows))
    dimension = f"A1:{_portal_database_xlsx_column_name(max_col)}{max_row}"
    xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        f'<dimension ref="{dimension}"/><sheetViews><sheetView workbookViewId="0"/></sheetViews>'
        f'<sheetData>{"".join(row_xml)}</sheetData>'
        '</worksheet>'
    )
    return xml.encode("utf-8")


def _portal_database_rows_to_xlsx(columns: list[dict], rows: list[dict]) -> bytes:
    output = io.BytesIO()
    with zipfile.ZipFile(output, mode="w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
</Types>""")
        archive.writestr("_rels/.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>""")
        archive.writestr("xl/workbook.xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheets><sheet name="Export" sheetId="1" r:id="rId1"/></sheets>
</workbook>""")
        archive.writestr("xl/_rels/workbook.xml.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
</Relationships>""")
        archive.writestr("xl/worksheets/sheet1.xml", _portal_database_rows_sheet_xml(columns, rows))
    return output.getvalue()


def _portal_database_xlsx_row_xml(row_index: int, row_values: list[Any]) -> str:
    cells = []
    for col_index, value in enumerate(row_values, start=1):
        ref = f"{_portal_database_xlsx_column_name(col_index)}{row_index}"
        cells.append(_portal_database_xlsx_cell(ref, value))
    return f'<row r="{row_index}">{"".join(cells)}</row>'


# ---------------------------------------------------------------------------
# Export scopes and column scopes (DB-009, DB-47) — approved stage S8
#
# The panel offers three row scopes and two column scopes. Every one of them is
# resolved **server-side** from state the server already validated: the browser
# names a scope, never a row set, a column list or a count it wants honoured.
#
#   * `view`      — the whole validated current result set. Filters, search and
#                   sort ride along; `page` and `limit` deliberately do not,
#                   because the export is of the result, not of the page.
#   * `dataset`   — the whole authorized dataset. Filters and search are
#                   dropped; the validated sort is kept, because ordering is a
#                   separate dimension from narrowing and dropping it would make
#                   the file order arbitrary.
#   * `selection` — the unique rows an S7 rectangle touches, addressed by their
#                   opaque S6 references and re-resolved here. Bounded by the
#                   page size, therefore always inside the direct-export cap.
#
# Column scope is orthogonal to row scope: `screen` is the resolved S5 display
# set in display order, `approved` is the whole approved user-visible catalog.
# Neither can contain the technical row identity, because both are derived from
# `_get_portal_database_visible_columns`, which excludes it.
# ---------------------------------------------------------------------------

PORTAL_DATABASE_EXPORT_ROW_SCOPES = ("view", "dataset", "selection")
PORTAL_DATABASE_EXPORT_COLUMN_SCOPES = ("screen", "approved")
PORTAL_DATABASE_EXPORT_DEFAULT_ROW_SCOPE = "view"
PORTAL_DATABASE_EXPORT_DEFAULT_COLUMN_SCOPE = "screen"
# The S7 rectangle cannot cross a pagination boundary, so a selection can never
# hold more rows than one page. Stating the bound here is what lets the selected
# scope stay a direct download: it is structurally below the direct cap.
PORTAL_DATABASE_EXPORT_MAX_SELECTED_ROWS = PORTAL_DATABASE_MAX_PAGE_SIZE
# The form field carrying one opaque S6 row reference per selected row.
PORTAL_DATABASE_EXPORT_ROW_FIELD = "row_ref"


def _portal_database_export_panel_action(dataset_id: str, params: dict[str, list[str]]) -> str:
    """Where the export panel submits.

    Unlike the pre-S8 background-export URL, this keeps `cols` and the S5 layout
    parameters: `Jak na ekranie` is defined by exactly that state, and stripping
    it would silently turn every "as on screen" export into an all-columns one.
    Pagination is still dropped — an export is of the result, not of the page.
    """
    next_params = {
        key: list(values)
        for key, values in params.items()
        if values and key not in ("page", "limit", "density", "format", PORTAL_DATABASE_ROW_PARAM)
    }
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}/exports" + (f"?{query}" if query else "")


def _portal_database_export_panel_html(
    dataset: dict,
    params: dict[str, list[str]],
    *,
    columns: list[dict],
    display_columns: list[dict],
    filtered_total: int,
    dataset_total: int | None,
    row_identifier: dict | None,
    async_available: bool,
) -> str:
    """The approved export panel (`DB-009`).

    One canonical export interaction: three row scopes with their own counts,
    two column scopes with their own counts, two formats, and a path notice that
    states — before the user commits — whether the file downloads immediately or
    is prepared in the background, together with the retention and the hard
    ceiling.

    It is an ordinary GET-less POST form. Without JavaScript the two
    server-countable scopes work exactly as rendered; the selected-row scope is
    the one part that needs the browser, because an S7 selection is client-side
    by construction, and it stays disabled-with-a-reason until a selection
    exists. `can_export_rows` is never a JavaScript boundary: the caller renders
    nothing at all without the grant, and the submit handler re-checks it.
    """
    dataset_id = str(dataset.get("dataset_id") or "")
    action = _portal_database_export_panel_action(dataset_id, params)
    grouped = lambda value: _portal_database_group_digits(str(int(value)))
    direct_cap = grouped(PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP)
    ceiling = grouped(PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP)

    # ------------------------------------------------------------- scopes --
    # Counts come from state the server already established for this page: the
    # filtered count it rendered in the toolbar and the dataset total it counted
    # for the same counter. Neither is re-derived from anything the browser sent,
    # and an unavailable total stays unavailable rather than borrowing the
    # filtered count — the S2 defect this must not repeat.
    scope_rows: list[str] = []
    for key, count, extra_attr, note in (
        ("view", filtered_total, "", ""),
        ("dataset", dataset_total, "", ""),
        (
            "selection",
            0,
            " data-db-export-selection" + ("" if row_identifier else " disabled"),
            "" if row_identifier else _tr("db.export.selection.unavailable"),
        ),
    ):
        checked = " checked" if key == PORTAL_DATABASE_EXPORT_DEFAULT_ROW_SCOPE else ""
        if count is None:
            count_html = (
                f'<span class="db-export-count is-unknown" '
                f'title="{_html(_tr("db.export.count_unavailable"))}">'
                f'{_html(_tr("db.export.count_unknown"))}</span>'
            )
        else:
            count_html = (
                f'<span class="db-export-count" data-db-export-count="{_html(key)}">'
                f'{_html(grouped(count))}</span> '
                f'<span class="db-export-unit">{_html(_tr("db.export.rows"))}</span>'
            )
        scope_rows.append(
            f'<label class="db-export-option">'
            f'<input type="radio" name="row_scope" value="{_html(key)}"{checked}{extra_attr}>'
            f'<span class="db-export-option-label">{_html(_tr("db.export.scope." + key))}</span>'
            f"{count_html}"
            + (f'<span class="db-export-option-note">{_html(note)}</span>' if note else "")
            + "</label>"
        )

    column_rows: list[str] = []
    for key, count in (("screen", len(display_columns)), ("approved", len(columns))):
        checked = " checked" if key == PORTAL_DATABASE_EXPORT_DEFAULT_COLUMN_SCOPE else ""
        column_rows.append(
            f'<label class="db-export-option">'
            f'<input type="radio" name="column_scope" value="{_html(key)}"{checked}>'
            f'<span class="db-export-option-label">{_html(_tr("db.export.columns." + key))}</span>'
            f'<span class="db-export-count">{_html(grouped(count))}</span></label>'
        )

    format_rows: list[str] = []
    for key in ("xlsx", "csv"):
        checked = " checked" if key == "xlsx" else ""
        format_rows.append(
            f'<label class="db-export-option is-inline">'
            f'<input type="radio" name="format_name" value="{_html(key)}"{checked} data-db-export-format>'
            f'<span class="db-export-option-label">{_html(_tr("db.export.format." + key))}</span></label>'
        )

    # -------------------------------------------------------- path notice --
    # Stated for the default scope from the count the server already has. The
    # browser updates the wording as the user switches scope; the submit handler
    # re-derives the path from its own authoritative count regardless, so this is
    # information and never a promise the server is bound by.
    path = _portal_database_export_path_for(filtered_total)
    notice_text = _portal_database_export_path_text(path)
    submit_label = _portal_database_export_submit_label(path, "xlsx")
    threshold_note = _tr("db.export.path.threshold", limit=direct_cap)
    ceiling_note = _tr("db.export.path.over_ceiling", ceiling=ceiling)

    strings = json.dumps(
        {
            "direct": _tr("db.export.path.direct"),
            "background": _tr("db.export.path.background", days=PORTAL_DATABASE_ASYNC_EXPORT_RETENTION_DAYS),
            "refused": ceiling_note,
            "unknown": _tr("db.export.path.unknown"),
            "submitDirect": _tr("db.export.submit_direct", format="{format}"),
            "submitBackground": _tr("db.export.submit_background"),
            "selectionEmpty": _tr("db.export.selection.empty"),
            "rows": _tr("db.export.rows"),
            "directCap": PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP,
            "ceiling": PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
            "maxSelected": PORTAL_DATABASE_EXPORT_MAX_SELECTED_ROWS,
            "rowField": PORTAL_DATABASE_EXPORT_ROW_FIELD,
            "copied": _tr("db.exports.reference_copied"),
            "copyFailed": _tr("db.exports.reference_copy_failed"),
        },
        ensure_ascii=False,
    )

    background_link = ""
    background_notice = ""
    if async_available:
        background_link = (
            '<a class="portal-link db-export-link" href="/user/database/exports">'
            + _html(_tr("db.exports.link"))
            + "</a>"
        )
    else:
        # Honest degradation: without the background-export schema the panel can
        # still offer every scope, but a scope above the direct cap has nowhere
        # to run. Saying so here is better than letting the user choose and only
        # find out after submitting.
        background_notice = (
            f'<p class="db-export-note portal-muted">{_html(ASYNC_DATABASE_EXPORT_SCHEMA_UNAVAILABLE_MESSAGE)}</p>'
        )

    return (
        '<div class="db-secondary">'
        + '<details id="db-export" class="db-export-panel" data-db-export-panel '
        + f'data-db-export-strings="{_html(strings)}">'
        + f'<summary>{_html(_tr("db.export.title"))}</summary>'
        + '<div class="db-secondary-body">'
        + f'<form class="db-export-form" method="post" action="{_html(action)}" data-db-export-form>'
        + f'<fieldset class="db-export-group"><legend>{_html(_tr("db.export.scope_heading"))}</legend>'
        + "".join(scope_rows)
        + "</fieldset>"
        + f'<fieldset class="db-export-group"><legend>{_html(_tr("db.export.columns_heading"))}</legend>'
        + "".join(column_rows)
        + "</fieldset>"
        + f'<fieldset class="db-export-group"><legend>{_html(_tr("db.export.format_heading"))}</legend>'
        + "".join(format_rows)
        + "</fieldset>"
        + f'<p class="db-export-path is-{_html(path)}" role="status" data-db-export-path>{_html(notice_text)}</p>'
        + f'<p class="db-export-threshold portal-muted">{_html(threshold_note)}</p>'
        + background_notice
        + '<div class="db-export-submit">'
        + f'<button class="portal-button" type="submit" data-db-export-submit>{_html(submit_label)}</button>'
        + background_link
        + "</div>"
        + '<div data-db-export-rows hidden></div>'
        + "</form></div></details></div>"
    )


def _portal_database_export_path_text(path: str) -> str:
    return {
        "direct": _tr("db.export.path.direct"),
        "background": _tr("db.export.path.background", days=PORTAL_DATABASE_ASYNC_EXPORT_RETENTION_DAYS),
        "refused": _tr(
            "db.export.path.over_ceiling",
            ceiling=_portal_database_group_digits(str(PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP)),
        ),
    }.get(path, _tr("db.export.path.unknown"))


def _portal_database_export_submit_label(path: str, format_name: str) -> str:
    if path in {"background", "refused"}:
        return _tr("db.export.submit_background")
    return _tr("db.export.submit_direct", format=str(format_name or "xlsx").upper())


def _portal_database_narrow_columns_for_export(
    params: dict[str, list[str]], columns: list[dict]
) -> list[dict]:
    """The S5 display set and display order, resolved exactly as the sheet does.

    This runs the same two steps the row browser runs — `cols` narrowing, then
    the S5 layout resolver for order and pinning — against a **copy** of the
    parameters, so an export never mutates the caller's canonicalized state.
    Because both steps start from the authorized `columns`, the result is always
    a subset of the approved user-visible catalog: an unknown, unapproved or
    hidden name in `cols`/`colorder` is dropped, and the technical row identity
    is not in the input at all.
    """
    scratch = {key: list(values) for key, values in params.items()}
    try:
        display_columns, fell_back = _portal_database_parse_cols(scratch, columns)
        if fell_back or not display_columns:
            display_columns = list(columns)
        layout = _portal_database_resolve_column_layout(scratch, columns, display_columns)
        resolved = layout.get("display_columns") or display_columns
    except Exception as exc:  # noqa: BLE001 - a layout problem must not widen the export
        print(f"portal database export column layout failed: {type(exc).__name__}")
        return list(columns)
    return list(resolved)


def _portal_database_export_row_scope(value: Any) -> str:
    text = str(value or "").strip().lower()
    return text if text in PORTAL_DATABASE_EXPORT_ROW_SCOPES else PORTAL_DATABASE_EXPORT_DEFAULT_ROW_SCOPE


def _portal_database_export_column_scope(value: Any) -> str:
    text = str(value or "").strip().lower()
    return text if text in PORTAL_DATABASE_EXPORT_COLUMN_SCOPES else PORTAL_DATABASE_EXPORT_DEFAULT_COLUMN_SCOPE


def _portal_database_export_scope_params(row_scope: str, params: dict[str, list[str]]) -> dict[str, list[str]]:
    """The query parameters one row scope is allowed to carry.

    `dataset` keeps only the sort: an unfiltered export that silently inherited
    the view's filters would be the most damaging possible misunderstanding of
    `Cały zbiór danych`. `view` and `selection` keep the validated query state;
    the pagination keys are dropped in every case, because an export is of the
    result set and not of the page the user happens to be looking at.
    """
    dropped = {"page", "limit", "density", "format", PORTAL_DATABASE_ROW_PARAM}
    if row_scope == "dataset":
        keep = {"sort", "direction"}
        return {key: list(values) for key, values in params.items() if values and key in keep}
    return {key: list(values) for key, values in params.items() if values and key not in dropped}


def _portal_database_export_columns(
    column_scope: str,
    columns: list[dict],
    display_columns: list[dict] | None,
) -> list[dict]:
    """The columns one column scope exports, in the order it exports them.

    `screen` reuses the S5 layout the sheet itself resolved, so the file matches
    what the user was looking at, in the same order. That resolution has already
    intersected the requested layout with the approved catalog, which is why a
    forged `cols`/`colorder` can only ever narrow or rearrange approved columns —
    never widen them and never reach the technical identity.
    """
    if column_scope == "screen" and display_columns:
        return list(display_columns)
    return list(columns)


def _portal_database_export_selected_identities(
    dataset: dict,
    params: dict[str, list[str]],
    identifier_column: dict | None,
) -> tuple[list[str], str | None]:
    """Resolve posted opaque row references into internal identities.

    The browser never holds, posts or receives a raw `record_id`: it posts the
    same AES-GCM references S6 already renders, and they are re-resolved here
    against this dataset, client and identifier column. A token that is
    malformed, tampered with, or minted for another dataset fails the AEAD
    binding and takes the whole request down with it — a partially honoured
    selection would silently export a different row set than the one the user
    selected.

    The identities never leave this process: they become bound parameters of one
    query and are not logged, audited or persisted.
    """
    tokens = [str(value or "").strip() for value in (params.get(PORTAL_DATABASE_EXPORT_ROW_FIELD) or [])]
    tokens = [token for token in tokens if token]
    if not tokens:
        return [], "selection_empty"
    if not identifier_column:
        # No configured row identity. There is no positional fallback: a page
        # offset or a business field would be a different row set the moment the
        # data moved, and S6 exists precisely so identity is never guessed.
        return [], "selection_identity_unavailable"
    if len(tokens) > PORTAL_DATABASE_EXPORT_MAX_SELECTED_ROWS:
        return [], "selection_too_many"
    identifier_name = str(identifier_column.get("column_name") or "")
    identities: list[str] = []
    seen: set[str] = set()
    for token in tokens:
        identity = _portal_database_resolve_row_reference(dataset, identifier_name, token)
        if identity is None:
            return [], "selection_invalid"
        # One touched row is one exported row however many of its cells the
        # rectangle covered, so the same identity twice is not two rows.
        if identity in seen:
            continue
        seen.add(identity)
        identities.append(identity)
    if not identities:
        return [], "selection_empty"
    return identities, None


def _portal_database_export_selection_message(reason: str) -> str:
    """Approved refusal copy for one selected-row failure.

    Deliberately coarse: `selection_invalid` covers malformed, tampered and
    foreign-dataset references alike, because telling the two apart would make
    the reference an oracle.
    """
    return {
        "selection_empty": _tr("db.export.selection.empty"),
        "selection_identity_unavailable": _tr("db.export.selection.unavailable"),
        "selection_too_many": _tr(
            "db.export.selection.too_many",
            limit=_portal_database_group_digits(str(PORTAL_DATABASE_EXPORT_MAX_SELECTED_ROWS)),
        ),
        "selection_invalid": _tr("db.export.selection.invalid"),
    }.get(reason, _tr("db.export.selection.invalid"))


def _portal_database_fetch_rows_by_identities(
    dataset: dict,
    columns: list[dict],
    identifier_column: str,
    identities: list[str],
    params: dict[str, list[str]],
) -> tuple[list[dict], dict, str | None]:
    """Fetch the selected rows, ordered as the sheet orders them, or refuse.

    Same safety shape as the single-row lookup S6 already uses: identifiers come
    from the authorized catalog and are quoted as identifiers, the identity list
    is one bound array parameter, and the connection is the read-only client
    connection with its statement timeout.

    **All or nothing.** The export succeeds only if every requested identity
    matches exactly one physical row. Returning whatever happened to match would
    silently drop a row deleted since the user selected it, and a non-unique
    identifier would add rows the rectangle never covered — the same reason the
    S6 single-row lookup keeps `LIMIT 2` rather than taking the first match.

    Cardinality is proven from the *same* result set that is exported, inside one
    read transaction, so nothing can change between validating and fetching. The
    technical identity is selected only to count multiplicity and is stripped
    from every row before this function returns: it never reaches a file, a
    header, the browser, a log, the audit trail or an error message.
    """
    if not identities:
        return [], {}, "This export request selected no rows."
    sort_column, sort_direction, sort_error = _validate_portal_database_sort(dataset, columns, params)
    if sort_error:
        return [], {}, sort_error
    try:
        schema_sql = _portal_database_quote_identifier(str(dataset.get("schema_name") or ""), "Schema name")
        table_sql = _portal_database_quote_identifier(str(dataset.get("table_name") or ""), "Table name")
        identifier_sql = _portal_database_quote_identifier(identifier_column, "Row identifier column")
        select_columns = [
            _portal_database_quote_identifier(str(column.get("column_name") or ""), "Column name")
            for column in columns
        ]
    except ValueError as exc:
        return [], {}, str(exc)
    if not select_columns:
        return [], {}, "This dataset has no visible columns configured."
    order_parts = []
    if sort_column:
        try:
            order_parts.append(
                f"{_portal_database_quote_identifier(sort_column, 'Sort column')} {sort_direction.upper()}"
            )
        except ValueError as exc:
            return [], {}, str(exc)
    # The identity is always the last ordering term so the file order is stable
    # between two runs of the same selection. It is an ORDER BY term only; it is
    # never selected and therefore never exported.
    if sort_column != identifier_column:
        order_parts.append(f"{identifier_sql} ASC")
    order_sql = (" ORDER BY " + ", ".join(order_parts)) if order_parts else ""
    # The identity rides in the SELECT list purely so multiplicity can be
    # counted. It is not among `columns` — S6 keeps it out of the user-visible
    # universe — so adding it here cannot collide with an exported field, and it
    # is removed again below.
    identity_alias = str(identifier_column)
    validation_columns = list(select_columns) + [identifier_sql]
    # One row above the selection bound, so an identity that matches more rows
    # than it should is observable rather than silently truncated into looking
    # correct.
    fetch_limit = PORTAL_DATABASE_EXPORT_MAX_SELECTED_ROWS + 1
    query = (
        f"SELECT {', '.join(validation_columns)} FROM {schema_sql}.{table_sql} "
        f"WHERE {identifier_sql} = ANY(%s){order_sql} LIMIT %s"
    )
    state = {"sort": sort_column, "direction": sort_direction, "active_filters": [], "filter_entries": []}
    requested = [str(value) for value in identities]
    database_name = _portal_dataset_client_database_name(dataset)
    with _connect_portal_client_database(database_name) as conn:
        with conn.cursor() as cur:
            cur.execute(query, [requested, fetch_limit])
            fetched = cur.fetchall()
        rows = _rows_to_dicts(fetched)
        # Counted inside the same read transaction as the fetch, from the very
        # rows that would be exported.
        seen: dict[str, int] = {}
        for row in rows:
            key = str(row.get(identity_alias))
            seen[key] = seen.get(key, 0) + 1
    if not _portal_database_selection_is_exact(requested, seen, len(rows), fetch_limit):
        return [], state, _tr("db.export.selection.invalid")
    for row in rows:
        row.pop(identity_alias, None)
    return rows, state, None


def _portal_database_selection_is_exact(
    requested: list[str],
    seen: dict[str, int],
    row_count: int,
    fetch_limit: int,
) -> bool:
    """Whether every requested identity matched exactly one row.

    Deliberately not `len(rows) == len(requested)`: requesting `A, B` and
    matching `A, A` also yields two rows and is wrong. The check is on identity
    multiplicity, so a missing identity and a duplicated one cancelling out in
    the row total is still caught.
    """
    if row_count >= fetch_limit:
        # The bound was reached, so the result set is not provably complete.
        return False
    wanted = set(requested)
    if set(seen) != wanted:
        return False
    return all(count == 1 for count in seen.values())


def _portal_database_export_path_for(total: int | None) -> str:
    """Which execution path a row count resolves to.

    `direct` up to the direct cap inclusive, `background` above it up to the
    global ceiling inclusive, `refused` beyond it, `unknown` when the count could
    not be established. The submit handler re-derives this from its own
    authoritative count; the panel only states it.
    """
    if total is None:
        return "unknown"
    if total > PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:
        return "refused"
    if total > PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP:
        return "background"
    return "direct"


def _portal_database_canonical_export_snapshot(
    dataset: dict,
    columns: list[dict],
    params: dict[str, list[str]],
    *,
    format_name: str,
    row_scope: str | None = None,
    column_scope: str | None = None,
    expected_rows: int | None = None,
) -> tuple[dict | None, dict, str | None]:
    fmt = str(format_name or "").strip().lower()
    if fmt not in {"csv", "xlsx"}:
        return None, {}, "Export format must be csv or xlsx."
    if not columns:
        return None, {}, "This dataset has no visible columns configured."
    _query, _values, state, error = _build_portal_database_rows_query(
        dataset,
        columns,
        params,
        count=True,
    )
    if error:
        return None, state, error
    # ONE record grammar, shared with saved views. A background export and a
    # saved view must describe the same filter with the same record, or the same
    # displayed sheet could resolve to two different populations depending on
    # which path replayed it.
    filters, search = _portal_database_canonical_filter_records(state)
    snapshot = {
        "snapshot_version": 1,
        "format": fmt,
        "columns": [str(column.get("column_name") or "") for column in columns],
        "sort": state.get("sort"),
        "direction": state.get("direction") or "asc",
        "filters": filters,
    }
    if search:
        snapshot["search"] = search
    # Scope provenance. The worker does not read these — the scope was already
    # resolved into `columns` and into the filter set above, which is what keeps
    # the worker free of scope logic — but a job whose stored state cannot say
    # which scope produced it is not auditable, and `Zleć ponownie` needs the
    # column scope to re-resolve `Jak na ekranie` against today's catalog.
    if row_scope:
        snapshot["row_scope"] = str(row_scope)
    if column_scope:
        snapshot["column_scope"] = str(column_scope)
    if expected_rows is not None:
        # The determinate progress bar `DB-007` asks for needs a denominator, and
        # the count is only knowable at request time.
        snapshot["expected_rows"] = int(expected_rows)
    return snapshot, state, None


# One user-safe refusal for every way a stored export snapshot can fail to
# replay with EXACTLY its stored meaning. It names no column, no operator and no
# value: an export refusal must not become a filter oracle.
PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL = (
    "The filters saved with this export can no longer be applied exactly. Please queue a new export."
)


def _portal_database_merge_legacy_range(first: dict, second: dict) -> dict | None:
    """Two pre-`between` records for one column, merged into today's record.

    Snapshots written before the `between` record existed stored a two-sided
    range as separate `gte` and `lte` records for the SAME column. The request
    grammar is keyed by column, so replaying them one after the other used to
    overwrite the first and silently drop a bound. Anything else that produces
    two records for one column is NOT representable and is refused, never
    partially honoured.
    """
    ops = (str(first.get("operator") or ""), str(second.get("operator") or ""))
    if ops not in {("gte", "lte"), ("lte", "gte")}:
        return None
    if first.get("values") or second.get("values") or first.get("value_to") or second.get("value_to"):
        return None
    lower = str((first if ops[0] == "gte" else second).get("value") or "")
    upper = str((first if ops[0] == "lte" else second).get("value") or "")
    if not lower or not upper:
        return None
    return {
        "column_name": str(first.get("column_name") or ""),
        "operator": "between",
        "value": lower,
        "value_to": upper,
    }


def _portal_database_export_snapshot_filters(stored: list) -> list[dict] | None:
    """A stored snapshot's filter records in TODAY's canonical record shape.

    The only normalisation performed is the legacy two-record range merge above.
    Nothing is trimmed, split, reordered or dropped: a record that cannot be
    expressed as one canonical record is `None`, which the caller turns into a
    refusal of the whole export.
    """
    records: list[dict] = []
    index_by_column: dict[str, int] = {}
    for entry in stored:
        if not isinstance(entry, dict):
            return None
        column_name = entry.get("column_name")
        operator = entry.get("operator")
        if not isinstance(column_name, str) or not isinstance(operator, str) or not column_name:
            return None
        previous = index_by_column.get(column_name)
        if previous is None:
            index_by_column[column_name] = len(records)
            records.append(dict(entry))
            continue
        merged = _portal_database_merge_legacy_range(records[previous], dict(entry))
        if merged is None:
            return None
        records[previous] = merged
    return records


def _portal_database_export_snapshot_params(
    dataset: dict,
    columns: list[dict],
    snapshot: dict,
) -> tuple[dict[str, list[str]] | None, str | None]:
    """A stored export snapshot as canonical request parameters, or a refusal.

    THE INVARIANT. For any state accepted for export, the exported query
    semantics equal the visible query semantics. The earlier converter here
    rebuilt a request by hand — it trimmed every value, dropped the ones that
    trimmed to nothing, and emitted `in` lists through `filter__`, the HUMAN
    textarea parameter — so an exact filter carrying a leading space, a trailing
    space, whitespace only, or an embedded newline reached the worker as a
    DIFFERENT and always BROADER constraint than the one on screen.

    The replay is therefore the same one saved views already prove lossless:
    validated against today's approved column universe, `can_filter_rows` and
    operator vocabulary, emitted through `filter_exact__` for `in` values — the
    one parameter the S3 parser takes verbatim — and then put BACK through the
    real parser, whose canonical records must EQUAL the stored ones. Any drift
    is a refusal here, before a single row is read, rather than a quietly
    broader export.
    """
    stored = snapshot.get("filters")
    if stored is not None and not isinstance(stored, list):
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    records = _portal_database_export_snapshot_filters(list(stored or []))
    if records is None:
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    raw_search = snapshot.get("search", "")
    if not isinstance(raw_search, str) or raw_search != raw_search.strip():
        # The live parser trims `search`, so a stored value that is not its own
        # trimmed form cannot be replayed with its stored meaning.
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    search = raw_search
    if (records or search) and not dataset.get("can_filter_rows"):
        # The capability was revoked after the job was queued. A queued export is
        # not a grant, and a filtered scope is never widened into an unfiltered
        # one.
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    filter_params, _refusal = _portal_database_saved_filter_params(columns, records)
    if filter_params is None:
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    # Filter parameters first, so the order the S3 scan sees is the order the
    # snapshot stores and the replayed records line up position for position.
    params: dict[str, list[str]] = dict(filter_params)
    sort_column = str(snapshot.get("sort") or "").strip()
    if sort_column:
        params["sort"] = [sort_column]
    direction = str(snapshot.get("direction") or "").strip().lower()
    if direction:
        params["direction"] = [direction]
    if search:
        params["search"] = [search]
    _query, _values, state, error = _build_portal_database_rows_query(
        dataset,
        columns,
        params,
        count=True,
    )
    if error:
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    replayed, replayed_search = _portal_database_canonical_filter_records(state)
    if replayed != records or replayed_search != search:
        return None, PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL
    return params, None


def _portal_database_columns_from_snapshot(columns: list[dict], snapshot: dict) -> tuple[list[dict], str | None]:
    requested = [str(name or "") for name in snapshot.get("columns") or []]
    if not requested:
        return [], "The export request no longer has any approved columns."
    by_name = {str(column.get("column_name") or ""): column for column in columns}
    missing = [name for name in requested if name not in by_name]
    if missing:
        return [], "The dataset column policy changed before this export could run. Please queue a new export."
    return [by_name[name] for name in requested], None


def _portal_database_iter_export_rows(
    dataset: dict,
    columns: list[dict],
    snapshot: dict,
    *,
    fetch_size: int = 1000,
):
    # FAIL CLOSED BEFORE THE FIRST ROW. The snapshot is re-validated against
    # today's columns, capability and operator vocabulary, and must replay to
    # exactly its stored filter meaning. A snapshot that cannot is an error
    # here, never a broader query executed against the client database.
    params, replay_error = _portal_database_export_snapshot_params(dataset, columns, snapshot)
    if replay_error or params is None:
        raise ValueError(replay_error or PORTAL_DATABASE_EXPORT_REPLAY_REFUSAL)
    query, values, _state, error = _build_portal_database_rows_query(
        dataset,
        columns,
        params,
        unbounded=True,
    )
    if error:
        raise ValueError(error)
    database_name = _portal_dataset_client_database_name(dataset)
    conn = _connect_portal_client_database(database_name, statement_timeout="0", autocommit=False)
    try:
        cursor_name = "portal_database_export_" + uuid.uuid4().hex
        with conn.cursor(name=cursor_name) as cur:
            cur.itersize = max(1, int(fetch_size or 1000))
            cur.execute(query, values)
            while True:
                batch = cur.fetchmany(fetch_size)
                if not batch:
                    break
                for row in _rows_to_dicts(batch):
                    yield row
    finally:
        conn.close()


def _portal_database_write_csv_file(
    columns: list[dict],
    rows_iter,
    output_path: str,
    *,
    max_rows: int,
    heartbeat=None,
) -> int:
    row_count = 0
    with open(output_path, "w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow([_portal_database_spreadsheet_safe_text(str(column.get("display_name") or column.get("column_name") or "")) for column in columns])
        for row in rows_iter:
            row_count += 1
            if row_count > max_rows:
                raise ValueError("ASYNC_EXPORT_ROW_CAP_EXCEEDED")
            writer.writerow(_portal_database_export_row(columns, row))
            if heartbeat and row_count % 1000 == 0:
                heartbeat(row_count)
    return row_count


def _portal_database_write_xlsx_file(
    columns: list[dict],
    rows_iter,
    output_path: str,
    *,
    max_rows: int,
    heartbeat=None,
) -> int:
    row_count = 0
    with zipfile.ZipFile(output_path, mode="w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
</Types>""")
        archive.writestr("_rels/.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>""")
        archive.writestr("xl/workbook.xml", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheets><sheet name="Export" sheetId="1" r:id="rId1"/></sheets>
</workbook>""")
        archive.writestr("xl/_rels/workbook.xml.rels", """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
</Relationships>""")
        with archive.open("xl/worksheets/sheet1.xml", "w") as sheet:
            sheet.write(b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>')
            sheet.write(b'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetData>')
            header = [str(column.get("display_name") or column.get("column_name") or "") for column in columns]
            sheet.write(_portal_database_xlsx_row_xml(1, header).encode("utf-8"))
            for row in rows_iter:
                row_count += 1
                if row_count > max_rows:
                    raise ValueError("ASYNC_EXPORT_ROW_CAP_EXCEEDED")
                values = [_portal_database_export_display_value(row.get(str(column.get("column_name") or ""))) for column in columns]
                sheet.write(_portal_database_xlsx_row_xml(row_count + 1, values).encode("utf-8"))
                if heartbeat and row_count % 1000 == 0:
                    heartbeat(row_count)
            sheet.write(b"</sheetData></worksheet>")
    return row_count


def _database_export_system_folder_row(row: dict) -> dict:
    return {
        "folder_id": str(row.get("folder_id")),
        "owner_user_id": str(row.get("owner_user_id")) if row.get("owner_user_id") else None,
        "system_key": row.get("system_key") or DATABASE_EXPORT_SYSTEM_FOLDER_KEY,
        "folder_name": row.get("folder_name") or DATABASE_EXPORT_SYSTEM_FOLDER_NAME,
        "slug": row.get("slug") or DATABASE_EXPORT_SYSTEM_FOLDER_SLUG,
        "description": row.get("description") or DATABASE_EXPORT_SYSTEM_FOLDER_DESCRIPTION,
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def _ensure_database_export_system_folder(owner_user_id: str, *, cur=None) -> str | None:
    if not owner_user_id or not _database_export_system_folder_schema_available():
        return None
    sql = """
        INSERT INTO database_export_system_folders
            (owner_user_id, system_key, folder_name, slug, description)
        VALUES (%s, %s, %s, %s, %s)
        ON CONFLICT (owner_user_id, system_key) DO UPDATE
        SET folder_name = EXCLUDED.folder_name,
            slug = EXCLUDED.slug,
            description = EXCLUDED.description,
            updated_at = now()
        RETURNING folder_id
    """
    params = (
        owner_user_id,
        DATABASE_EXPORT_SYSTEM_FOLDER_KEY,
        DATABASE_EXPORT_SYSTEM_FOLDER_NAME,
        DATABASE_EXPORT_SYSTEM_FOLDER_SLUG,
        DATABASE_EXPORT_SYSTEM_FOLDER_DESCRIPTION,
    )
    if cur is not None:
        cur.execute(sql, params)
        row = cur.fetchone()
        return str(row["folder_id"]) if row else None
    with db_conn() as conn:
        with conn.cursor() as local_cur:
            local_cur.execute(sql, params)
            row = local_cur.fetchone()
        conn.commit()
    return str(row["folder_id"]) if row else None


def _get_database_export_system_folder_for_user(user_id: str) -> dict | None:
    if not user_id or not _database_export_system_folder_schema_available():
        return None
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT folder_id, owner_user_id, system_key, folder_name, slug, description, created_at, updated_at
                FROM database_export_system_folders
                WHERE owner_user_id = %s AND system_key = %s
                LIMIT 1
                """,
                (user_id, DATABASE_EXPORT_SYSTEM_FOLDER_KEY),
            )
            row = cur.fetchone()
    return _database_export_system_folder_row(row) if row else None


def _get_database_export_system_folder_for_user_by_id(user_id: str, folder_id: str) -> dict | None:
    if not user_id or not folder_id or not _database_export_system_folder_schema_available():
        return None
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT folder_id, owner_user_id, system_key, folder_name, slug, description, created_at, updated_at
                FROM database_export_system_folders
                WHERE folder_id = %s AND owner_user_id = %s AND system_key = %s
                LIMIT 1
                """,
                (folder_id, user_id, DATABASE_EXPORT_SYSTEM_FOLDER_KEY),
            )
            row = cur.fetchone()
    return _database_export_system_folder_row(row) if row else None


def _database_export_folder_url(folder: dict | None = None) -> str:
    if folder and folder.get("folder_id"):
        return f"/user/reports/database-exports/{quote(str(folder.get('folder_id')), safe='')}"
    return "/user/reports/database-exports"


def _database_export_job_is_downloadable(job: dict) -> bool:
    if str(job.get("status") or "") != "completed" or not job.get("artifact_id"):
        return False
    if job.get("artifact_expired_at"):
        return False
    expires_at = _artifact_expiry_dt(job.get("artifact_expires_at") or job.get("expires_at"))
    return not (expires_at and expires_at <= utcnow())


def _database_export_safe_status_message(job: dict) -> str:
    status = str(job.get("status") or "")
    if status == "failed":
        return DATABASE_EXPORT_GENERIC_FAILURE_MESSAGE
    if status == "expired":
        return "Expired; the downloadable result has been removed."
    if status == "queued":
        return "Queued for background generation."
    if status == "running":
        return "Generating in the background."
    if status == "completed" and not _database_export_job_is_downloadable(job):
        return "The downloadable result is no longer available."
    return ""


def _portal_database_async_export_url(dataset_id: str, params: dict[str, list[str]]) -> str:
    next_params = {key: list(values) for key, values in params.items() if values and key not in ("page", "limit", "density", "cols", "format", *PORTAL_DATABASE_LAYOUT_PARAM_KEYS)}
    query = urlencode(next_params, doseq=True)
    return f"/user/database/datasets/{quote(str(dataset_id))}/exports" + (f"?{query}" if query else "")


def _enqueue_database_export_job(user: dict, dataset: dict, snapshot: dict, *, format_name: str) -> str:
    job_id = uuid.uuid4()
    owner_user_id = str(user.get("user_id") or "")
    with db_conn() as conn:
        with conn.cursor() as cur:
            system_folder_id = _ensure_database_export_system_folder(owner_user_id, cur=cur)
            if system_folder_id:
                cur.execute(
                    """
                    INSERT INTO database_export_jobs
                        (job_id, requested_by_user_id, dataset_id, requested_format, request_snapshot_json, status, system_folder_id)
                    VALUES (%s, %s, %s, %s, %s::jsonb, 'queued', %s)
                    RETURNING job_id
                    """,
                    (
                        job_id,
                        owner_user_id,
                        dataset.get("dataset_id"),
                        format_name,
                        json.dumps(snapshot, ensure_ascii=False, sort_keys=True),
                        system_folder_id,
                    ),
                )
            else:
                cur.execute(
                    """
                    INSERT INTO database_export_jobs
                        (job_id, requested_by_user_id, dataset_id, requested_format, request_snapshot_json, status)
                    VALUES (%s, %s, %s, %s, %s::jsonb, 'queued')
                    RETURNING job_id
                    """,
                    (
                        job_id,
                        owner_user_id,
                        dataset.get("dataset_id"),
                        format_name,
                        json.dumps(snapshot, ensure_ascii=False, sort_keys=True),
                    ),
                )
        conn.commit()
    return str(job_id)


def _database_export_int_or_none(value: Any) -> int | None:
    try:
        return int(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def _database_export_presentation_state(job: dict) -> str:
    """Which of the four approved `DB-007` states one job is in.

    The approved list has exactly four states — `W toku`, `Gotowy`,
    `Pliki wygasły`, `Błąd` — each with its own action set. Two internal
    statuses map onto one presented state in each direction:

      * `queued` and `running` are both "being prepared"; the distinction is
        worker scheduling, not something the user can act on differently;
      * a `completed` job whose artifact is past retention is presented as
        expired, because the file is what `Gotowy` promises and it is gone.

    A `cancelled` job maps to no approved state and is therefore not listed —
    the user stopped it, it produced nothing, and inventing a fifth badge would
    add a user-facing state the design does not have.
    """
    status = str(job.get("status") or "")
    if status in DATABASE_EXPORT_ACTIVE_STATUSES:
        return "running"
    if status == "cancelled":
        return "cancelled"
    if status == "failed":
        return "failed"
    if status == "expired":
        return "expired"
    if status == "completed":
        return "ready" if _database_export_job_is_downloadable(job) else "expired"
    return "failed"


def _database_export_state_label(state: str) -> str:
    return {
        "running": _tr("db.exports.state.running"),
        "ready": _tr("db.exports.state.ready"),
        "expired": _tr("db.exports.state.expired"),
        "failed": _tr("db.exports.state.failed"),
    }.get(state, _tr("db.exports.state.failed"))


def _database_export_job_row(row: dict) -> dict:
    return {
        "job_id": str(row.get("job_id")),
        "requested_by_user_id": str(row.get("requested_by_user_id")) if row.get("requested_by_user_id") else None,
        "dataset_id": str(row.get("dataset_id")) if row.get("dataset_id") else None,
        "dataset_name": row.get("dataset_name"),
        "client_code": row.get("client_code"),
        "requested_format": row.get("requested_format"),
        "status": row.get("status"),
        "queued_at": row["queued_at"].isoformat() if row.get("queued_at") else None,
        "started_at": row["started_at"].isoformat() if row.get("started_at") else None,
        "completed_at": row["completed_at"].isoformat() if row.get("completed_at") else None,
        "expires_at": row["expires_at"].isoformat() if row.get("expires_at") else None,
        "attempt_count": int(row.get("attempt_count") or 0),
        "row_count": int(row.get("row_count")) if row.get("row_count") is not None else None,
        "artifact_id": str(row.get("artifact_id")) if row.get("artifact_id") else None,
        "safe_error_code": row.get("safe_error_code"),
        "safe_error_message": row.get("safe_error_message"),
        "system_folder_id": str(row.get("system_folder_id")) if row.get("system_folder_id") else None,
        "artifact_expires_at": row["artifact_expires_at"].isoformat() if row.get("artifact_expires_at") else None,
        "artifact_expired_at": row["artifact_expired_at"].isoformat() if row.get("artifact_expired_at") else None,
        # The determinate progress bar's denominator, recorded at request time.
        # Absent on jobs queued before S8, which simply render indeterminate.
        "expected_rows": _database_export_int_or_none(row.get("expected_rows")),
    }


def _list_database_export_jobs_for_user(user_id: str, *, limit: int = 100) -> list[dict]:
    system_folder_col = "dej.system_folder_id" if _database_export_system_folder_schema_available() else "NULL::UUID AS system_folder_id"
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT dej.job_id, dej.requested_by_user_id, dej.dataset_id, pdd.dataset_name, pdd.client_code,
                       dej.requested_format, dej.status, dej.queued_at, dej.started_at, dej.completed_at,
                       dej.expires_at, dej.attempt_count, dej.row_count, dej.artifact_id,
                       dej.safe_error_code, dej.safe_error_message, {system_folder_col},
                       (dej.request_snapshot_json ->> 'expected_rows') AS expected_rows,
                       artifacts.expires_at AS artifact_expires_at,
                       artifacts.expired_at AS artifact_expired_at
                FROM database_export_jobs dej
                JOIN portal_database_datasets pdd ON pdd.dataset_id = dej.dataset_id
                LEFT JOIN artifacts ON artifacts.artifact_id = dej.artifact_id
                WHERE dej.requested_by_user_id = %s
                ORDER BY dej.queued_at DESC, dej.job_id DESC
                LIMIT %s
                """,
                (user_id, limit),
            )
            rows = cur.fetchall()
    return [_database_export_job_row(row) for row in rows]


def _get_database_export_job_for_user(job_id: str, user_id: str) -> dict | None:
    system_folder_col = "dej.system_folder_id" if _database_export_system_folder_schema_available() else "NULL::UUID AS system_folder_id"
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT dej.job_id, dej.requested_by_user_id, dej.dataset_id, pdd.dataset_name, pdd.client_code,
                       dej.requested_format, dej.status, dej.queued_at, dej.started_at, dej.completed_at,
                       dej.expires_at, dej.attempt_count, dej.row_count, dej.artifact_id,
                       dej.safe_error_code, dej.safe_error_message, {system_folder_col},
                       (dej.request_snapshot_json ->> 'expected_rows') AS expected_rows,
                       artifacts.expires_at AS artifact_expires_at,
                       artifacts.expired_at AS artifact_expired_at
                FROM database_export_jobs dej
                JOIN portal_database_datasets pdd ON pdd.dataset_id = dej.dataset_id
                LEFT JOIN artifacts ON artifacts.artifact_id = dej.artifact_id
                WHERE dej.job_id = %s AND dej.requested_by_user_id = %s
                LIMIT 1
                """,
                (job_id, user_id),
            )
            row = cur.fetchone()
    return _database_export_job_row(row) if row else None


# ---------------------------------------------------------------------------
# Background export lifecycle actions (DB-007, DB-50..DB-52) — approved stage S8
#
# `Anuluj` and `Zleć ponownie` are the only two state-changing actions the user
# has over a background export, and both are POST forms so neither can be
# triggered by a link preview or a crafted GET.
#
# Cancellation is race-safe **without changing a single worker fence**, because
# every worker transition is already conditional on the status it expects:
#
#   claim            WHERE status = 'queued'
#   refresh_lease    WHERE status = 'running' AND claim_token = <its own>
#   mark_failed      WHERE status = 'running' AND claim_token = <its own>
#   publish          WHERE status = 'running' AND claim_token = <its own>
#                      AND lease_expires_at > now() AND attempt_object_key = <its own>
#   stale recovery   WHERE status = 'running' AND lease_expires_at <= now()
#
# Moving a job to the terminal `cancelled` status therefore means: a queued job
# can never be claimed, and a running job's worker loses its fence at the next
# lease refresh or at publication — where the existing code already marks the
# uploaded attempt object for cleanup and deletes it. The reverse race is
# equally settled: if the worker commits publication first, the cancel UPDATE
# matches no row and the user is told the export is already ready.
# ---------------------------------------------------------------------------

DATABASE_EXPORT_ACTIVE_STATUSES = ("queued", "running")
DATABASE_EXPORT_CANCELLABLE_STATUSES = ("queued", "running")
# `Zleć ponownie` exists only where the approved state matrix puts it: on a
# failed export and on an expired one. A ready export has `Pobierz`; an
# in-progress one has `Anuluj`. No state shows an action it cannot perform.
DATABASE_EXPORT_REQUEUEABLE_STATUSES = ("failed", "expired")


def _count_active_database_export_jobs_for_user(user_id: str) -> int:
    """How many of this user's exports are still being prepared.

    Owner-scoped by the WHERE clause, and read from the platform database only —
    the app-bar indicator never touches a client business database. A failure
    degrades to "no indicator" rather than breaking every page in the portal.
    """
    if not user_id:
        return 0
    try:
        with db_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT count(*) AS active
                    FROM database_export_jobs
                    WHERE requested_by_user_id = %s
                      AND status IN ('queued', 'running')
                    """,
                    (user_id,),
                )
                row = cur.fetchone()
        return int((row or {}).get("active") or 0)
    except Exception as exc:  # noqa: BLE001
        print(f"portal database export indicator failed: {type(exc).__name__}")
        return 0


def _cancel_database_export_job_for_user(job_id: str, user_id: str) -> str:
    """Cancel one owned export. Returns `cancelled`, `not_cancellable` or `not_found`.

    The row is locked first so this and the worker's publication cannot both
    believe they won. When the job was already `running`, its attempt-object
    ledger row is moved to `cleanup_pending` in the same transaction, which is
    what stops a partially uploaded object from surviving as an unauthorized
    orphan: the worker's existing cleanup sweep deletes it, and the publication
    fence it lost means it can never be attached to an artifact.
    """
    if not job_id or not user_id:
        return "not_found"
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT job_id, status, claim_token, attempt_object_key
                FROM database_export_jobs
                WHERE job_id = %s AND requested_by_user_id = %s
                FOR UPDATE
                """,
                (job_id, user_id),
            )
            target = cur.fetchone()
            if not target:
                conn.rollback()
                return "not_found"
            previous_status = str(target.get("status") or "")
            if previous_status not in DATABASE_EXPORT_CANCELLABLE_STATUSES:
                conn.rollback()
                return "not_cancellable"
            cur.execute(
                """
                UPDATE database_export_jobs
                SET status = 'cancelled',
                    completed_at = now(),
                    lease_expires_at = NULL,
                    claim_token = NULL,
                    attempt_object_key = NULL,
                    safe_error_code = NULL,
                    safe_error_message = NULL,
                    updated_at = now()
                WHERE job_id = %s
                  AND requested_by_user_id = %s
                  AND status IN ('queued', 'running')
                """,
                (job_id, user_id),
            )
            if cur.rowcount != 1:
                conn.rollback()
                return "not_cancellable"
            if previous_status == "running" and target.get("claim_token") and target.get("attempt_object_key"):
                cur.execute(
                    """
                    UPDATE database_export_attempt_objects
                    SET state = 'cleanup_pending',
                        cleanup_requested_at = COALESCE(cleanup_requested_at, now()),
                        updated_at = now()
                    WHERE job_id = %s AND claim_token = %s AND state = 'active'
                    """,
                    (job_id, target.get("claim_token")),
                )
        conn.commit()
    return "cancelled"


def _requeue_database_export_job_for_user(user: dict, job_id: str, request: Request | None) -> tuple[str | None, str]:
    """Queue a fresh attempt from a finished export's stored snapshot.

    Returns `(new_job_id, outcome)`. Authorization is re-evaluated from scratch —
    ownership, dataset access and `can_export_rows` are today's answers, not the
    answers that were true when the original job was queued — and the row count
    is recomputed so an old snapshot cannot carry a scope past a ceiling that is
    enforced now.

    A new row is inserted rather than the old one revived: the failed or expired
    record is history, and reviving it in place would let two workers believe
    they own one logical attempt.
    """
    user_id = str(user.get("user_id") or "")
    job = _get_database_export_job_for_user(job_id, user_id)
    if not job:
        return None, "not_found"
    if str(job.get("status") or "") not in DATABASE_EXPORT_REQUEUEABLE_STATUSES:
        return None, "not_requeueable"
    dataset = _get_portal_database_dataset_for_user(str(job.get("dataset_id") or ""), user_id)
    if not dataset or not dataset.get("can_export_rows"):
        return None, "not_authorized"
    columns = _get_portal_database_visible_columns(str(job.get("dataset_id") or ""))
    if not columns:
        return None, "dataset_unavailable"
    snapshot = _load_database_export_job_snapshot(job_id, user_id)
    if not snapshot:
        return None, "snapshot_unavailable"
    resolved_columns, column_error = _portal_database_columns_from_snapshot(columns, snapshot)
    if column_error or not resolved_columns:
        return None, "dataset_policy_changed"
    scope_params, replay_error = _portal_database_export_snapshot_params(dataset, columns, snapshot)
    if replay_error or scope_params is None:
        return None, "invalid_snapshot"
    try:
        total, state, count_error = _count_portal_database_rows(dataset, columns, scope_params)
    except Exception as exc:  # noqa: BLE001
        print(f"portal database export requeue count failed: {type(exc).__name__}")
        return None, "count_unavailable"
    if count_error:
        return None, "count_unavailable"
    if total > PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:
        return None, "over_ceiling"
    fresh, snapshot_state, error = _portal_database_canonical_export_snapshot(
        dataset,
        resolved_columns,
        scope_params,
        format_name=str(job.get("requested_format") or ""),
        row_scope=str(snapshot.get("row_scope") or PORTAL_DATABASE_EXPORT_DEFAULT_ROW_SCOPE),
        column_scope=str(snapshot.get("column_scope") or PORTAL_DATABASE_EXPORT_DEFAULT_COLUMN_SCOPE),
        expected_rows=total,
    )
    if error or fresh is None:
        return None, "invalid_snapshot"
    new_job_id = _enqueue_database_export_job(user, dataset, fresh, format_name=str(job.get("requested_format") or ""))
    _portal_audit_event_safe(
        event_type="database_export_job_requeued",
        actor_user_id=user_id or None,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=str(dataset.get("dataset_id") or "") or None,
        request=request,
        metadata_json=_portal_database_export_metadata(
            format_name=str(job.get("requested_format") or ""),
            row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
            row_count=total,
            params=scope_params,
            state=snapshot_state,
            extra={"job_id": new_job_id, "source_job_id": str(job_id), "path": "background"},
        ),
    )
    return new_job_id, "requeued"


def _load_database_export_job_snapshot(job_id: str, user_id: str) -> dict | None:
    """The stored validated snapshot for one owned job.

    Kept out of `_database_export_job_row` on purpose: the snapshot is execution
    state for the worker and for requeue, not something a rendered list needs.
    """
    if not job_id or not user_id:
        return None
    try:
        with db_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT request_snapshot_json
                    FROM database_export_jobs
                    WHERE job_id = %s AND requested_by_user_id = %s
                    LIMIT 1
                    """,
                    (job_id, user_id),
                )
                row = cur.fetchone()
    except Exception as exc:  # noqa: BLE001
        print(f"portal database export snapshot load failed: {type(exc).__name__}")
        return None
    if not row:
        return None
    snapshot = row.get("request_snapshot_json")
    if isinstance(snapshot, str):
        try:
            snapshot = json.loads(snapshot)
        except (ValueError, TypeError):
            return None
    return snapshot if isinstance(snapshot, dict) else None


def _database_export_object_key(job_id: str, extension: str, created_at: datetime, claim_token: str | None = None) -> str:
    dt = created_at.astimezone(timezone.utc)
    short_id = sanitize_artifact_component(str(job_id)[:8])
    claim_short = sanitize_artifact_component(str(claim_token or "no_claim")[:8])
    ext = str(extension or "bin").strip().lower().lstrip(".") or "bin"
    filename = f"database_export__{dt:%Y%m%dT%H%M%SZ}__{short_id}__{claim_short}__result.{ext}"
    return "/".join([
        "database_explorer",
        "exports",
        f"yyyy={dt:%Y}",
        f"mm={dt:%m}",
        f"dd={dt:%d}",
        f"export_job_id={sanitize_artifact_component(job_id)}",
        f"claim={claim_short}",
        filename,
    ])



def _database_export_artifact_record(
    *,
    job: dict,
    dataset: dict,
    file_path: str,
    format_name: str,
    row_count: int,
    completed_at: datetime,
    expires_at: datetime,
    storage_key: str,
) -> dict:
    ext = "xlsx" if format_name == "xlsx" else "csv"
    content_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" if ext == "xlsx" else "text/csv; charset=utf-8"
    artifact_id = uuid.uuid4()
    job_id = str(job.get("job_id"))
    owner_user_id = str(job.get("requested_by_user_id") or "")
    display_name = sanitize_artifact_display_filename(_portal_database_export_filename(dataset, ext), ext)
    sha = hashlib.sha256()
    size = 0
    with open(file_path, "rb") as handle:
        for chunk in iter(lambda: handle.read(8 * 1024 * 1024), b""):
            sha.update(chunk)
            size += len(chunk)
    metadata = {
        "export_job_id": job_id,
        "dataset_id": str(dataset.get("dataset_id") or ""),
        "dataset_name": str(dataset.get("dataset_name") or ""),
        "format": ext,
        "row_count": row_count,
        "completed_at": completed_at.isoformat(),
        "expires_at": expires_at.isoformat(),
        "retention_days": PORTAL_DATABASE_ASYNC_EXPORT_RETENTION_DAYS,
        "claim_token": str(job.get("claim_token") or ""),
    }
    for key, value in business_time_log_context(completed_at).items():
        metadata.setdefault(key, value)
    return {
        "artifact_id": str(artifact_id),
        "created_at": completed_at,
        "kind": "REPORT",
        "filename": display_name,
        "content_type": content_type,
        "size_bytes": size,
        "sha256": sha.hexdigest(),
        "storage_key": storage_key,
        "client_code": str(dataset.get("client_code") or "") or None,
        "display_filename": display_name,
        "original_filename": display_name,
        "file_ext": ext,
        "layout_version": LAYOUT_VERSION,
        "metadata_json": metadata,
        "owner_user_id": owner_user_id,
        "expires_at": expires_at,
    }

def _portal_database_export_response(
    user: dict,
    dataset_id: str,
    request: Request | None,
    *,
    format_name_override: str | None = None,
    params_override: dict[str, list[str]] | None = None,
):
    params = params_override if params_override is not None else _portal_database_query_params(request)
    format_name = (format_name_override or _portal_database_first_param(params, "format", "csv")).strip().lower() or "csv"
    actor_user_id = str(user.get("user_id") or "") or None
    if format_name not in {"csv", "xlsx"}:
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=format_name,
                row_limit=None,
                row_count=None,
                params=params,
                reason="unsupported_format",
                requested_dataset_id=dataset_id,
            ),
        )
        return _portal_database_export_error_response(user, {"dataset_name": "Database export"}, "Export format must be csv or xlsx.")
    dataset = _get_portal_database_dataset_for_user(dataset_id, str(user.get("user_id") or ""))
    if not dataset:
        _portal_audit_event_safe(
            event_type="database_export_denied",
            actor_user_id=actor_user_id,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=format_name,
                row_limit=None,
                row_count=None,
                params=params,
                reason="dataset_unavailable",
                requested_dataset_id=dataset_id,
            ),
        )
        return _portal_database_unavailable_response(user)
    if not dataset.get("can_export_rows"):
        _portal_audit_event_safe(
            event_type="database_export_denied",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=format_name,
                row_limit=None,
                row_count=None,
                params=params,
                reason="export_not_enabled",
            ),
        )
        return _portal_database_export_error_response(user, dataset, "Export is not enabled for your access to this dataset.", status_code=403)
    columns = _get_portal_database_visible_columns(dataset_id)
    if not columns:
        _portal_audit_event_safe(
            event_type="database_export_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=None, row_count=None, params=params, reason="no_visible_columns"),
        )
        return _portal_database_export_error_response(user, dataset, "This dataset has no visible columns configured.")
    # ------------------------------------------------------------- scopes --
    # Both scopes are re-derived here from the request, never trusted from it.
    # `screen` resolves through the same S5 layout resolver the sheet uses, so a
    # forged `cols`/`colorder` can rearrange or narrow approved columns and
    # nothing else.
    row_scope = _portal_database_export_row_scope(_portal_database_first_param(params, "row_scope", ""))
    column_scope = _portal_database_export_column_scope(_portal_database_first_param(params, "column_scope", ""))
    layout_columns = _portal_database_narrow_columns_for_export(params, columns)
    export_columns = _portal_database_export_columns(column_scope, columns, layout_columns)
    if not export_columns:
        export_columns = list(columns)
    scope_params = _portal_database_export_scope_params(row_scope, params)
    page, limit, limit_error = _portal_database_parse_export_limit(params)
    if limit_error:
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=limit, row_count=None, params=params, reason=limit_error),
        )
        return _portal_database_export_error_response(user, dataset, limit_error)
    offset = 0
    # ------------------------------------------------- selected-row scope --
    # Resolved before the count, because a selection is its own authoritative
    # row set: it is bounded by the page size and therefore always inside the
    # direct cap, which is exactly why it never needs a background job.
    selected_identities: list[str] = []
    identifier_column = None
    if row_scope == "selection":
        try:
            identifier_column = _get_portal_database_row_identity_column(dataset_id)
        except Exception as exc:  # noqa: BLE001 - fails closed to "no identity"
            print(f"portal database export row identity lookup failed: {type(exc).__name__}")
            identifier_column = None
        selected_identities, selection_error = _portal_database_export_selected_identities(
            dataset, params, identifier_column
        )
        if selection_error:
            _portal_audit_event_safe(
                event_type="database_export_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata_json=_portal_database_export_metadata(
                    format_name=format_name, row_limit=PORTAL_DATABASE_EXPORT_MAX_SELECTED_ROWS,
                    row_count=None, params=params, reason=selection_error,
                    extra={"row_scope": row_scope, "column_scope": column_scope},
                ),
            )
            return _portal_database_export_error_response(
                user, dataset, _portal_database_export_selection_message(selection_error)
            )
    try:
        if row_scope == "selection":
            total = len(selected_identities)
            state = {}
            count_error = None
        else:
            total, state, count_error = _count_portal_database_rows(dataset, columns, scope_params)
        if count_error:
            _portal_audit_event_safe(
                event_type="database_export_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=limit, row_count=None, params=params, state=state, reason=count_error),
            )
            return _portal_database_export_error_response(user, dataset, count_error)
        if total > PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:
            limit_message = f"Export matches {total:,} rows, which exceeds the maximum export limit of {PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:,}. Narrow the filters and try again."
            _portal_audit_event_safe(
                event_type="database_export_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP, row_count=total, params=params, state=state, reason="export_global_limit_exceeded"),
            )
            return _portal_database_export_error_response(user, dataset, limit_message)
        if total > PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP:
            limit_message = (
                f"Direct export is available for up to {PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP:,} rows. "
                f"Use Export report from the dataset page for {PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP + 1:,} to {PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:,} matching rows."
            )
            _portal_audit_event_safe(
                event_type="database_export_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata_json=_portal_database_export_metadata(
                    format_name=format_name,
                    row_limit=PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP,
                    row_count=total,
                    params=params,
                    state=state,
                    reason="direct_export_limit_exceeded",
                    extra={"async_export_limit": PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP},
                ),
            )
            return _portal_database_export_error_response(user, dataset, limit_message)
        if row_scope == "selection":
            rows, row_state, row_error = _portal_database_fetch_rows_by_identities(
                dataset,
                export_columns,
                str((identifier_column or {}).get("column_name") or ""),
                selected_identities,
                scope_params,
            )
        else:
            rows, row_state, row_error = _list_portal_database_rows(
                dataset, columns, scope_params, limit=limit, offset=offset, display_columns=export_columns
            )
        state.update(row_state)
        if row_error:
            _portal_audit_event_safe(
                event_type="database_export_validation_failed",
                actor_user_id=actor_user_id,
                client_code=str(dataset.get("client_code") or "") or None,
                dataset_id=str(dataset.get("dataset_id") or "") or None,
                request=request,
                metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=limit, row_count=None, params=params, state=state, reason=row_error),
            )
            return _portal_database_export_error_response(user, dataset, row_error)
    except Exception as exc:
        exc_name = type(exc).__name__
        print(f"portal database export query failed: {exc_name}: dataset_id={dataset_id} client_code={dataset.get('client_code')}")
        _portal_audit_event_safe(
            event_type="database_export_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=limit, row_count=None, params=params, reason=exc_name),
        )
        if exc_name in {"UndefinedTable", "UndefinedColumn"}:
            message = "This dataset is not currently available because its table or columns are not configured correctly."
        elif exc_name in {"PortalClientDatabaseConfigError", "PortalClientDatabaseConnectionError"}:
            message = "Client database is not available or not configured."
        else:
            message = "This export could not be created. Please contact an administrator."
        return _portal_database_export_error_response(user, dataset, message, status_code=502)
    try:
        if format_name == "xlsx":
            content = _portal_database_rows_to_xlsx(export_columns, rows)
            filename = _portal_database_export_filename(dataset, "xlsx")
            media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
        else:
            content = _portal_database_rows_to_csv(export_columns, rows)
            filename = _portal_database_export_filename(dataset, "csv")
            media_type = "text/csv; charset=utf-8"
        headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    except Exception as exc:
        exc_name = type(exc).__name__
        print(f"portal database export serialization failed: {exc_name}: dataset_id={dataset.get('dataset_id')} client_code={dataset.get('client_code')} format={format_name}")
        _portal_audit_event_safe(
            event_type="database_export_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=format_name, row_limit=limit, row_count=len(rows), params=params, state=state, reason=exc_name),
        )
        raise
    _portal_audit_event_safe(
        event_type="database_export_success",
        actor_user_id=actor_user_id,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=str(dataset.get("dataset_id") or "") or None,
        request=request,
        # Scope and column-scope names only. The opaque references the browser
        # posted are not recorded, and neither is any resolved identity.
        metadata_json=_portal_database_export_metadata(
            format_name=format_name, row_limit=limit, row_count=len(rows), params=params, state=state,
            extra={"row_scope": row_scope, "column_scope": column_scope, "export_column_count": len(export_columns), "path": "direct"},
        ),
    )
    return StreamingResponse(iter([content]), media_type=media_type, headers=headers)


def _database_export_schema_unavailable_response(user: dict, *, status_code: int = 303) -> HTMLResponse:
    return _artifact_explorer_redirect("/user/database?background_exports_unavailable=1")


def _portal_database_enqueue_export_response(
    user: dict,
    dataset_id: str,
    request: Request | None,
    *,
    format_name: str,
    row_scope: str | None = None,
    column_scope: str | None = None,
    row_references: list[str] | None = None,
) -> HTMLResponse:
    params = _portal_database_query_params(request)
    # The panel posts its choices in the form body while the validated query
    # state rides in the action URL. Merging them here keeps one parameter map
    # for the whole export path, and every one of these values is re-validated
    # below — the merge grants nothing.
    if row_scope is not None:
        params["row_scope"] = [str(row_scope)]
    if column_scope is not None:
        params["column_scope"] = [str(column_scope)]
    if row_references:
        params[PORTAL_DATABASE_EXPORT_ROW_FIELD] = [str(value) for value in row_references if str(value).strip()]
    fmt = str(format_name or "").strip().lower()
    actor_user_id = str(user.get("user_id") or "") or None
    if fmt not in {"csv", "xlsx"}:
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=fmt or "unknown",
                row_limit=None,
                row_count=None,
                params=params,
                reason="invalid_export_format",
                requested_dataset_id=dataset_id,
            ),
        )
        return _portal_database_export_error_response(user, {"dataset_name": "Database export"}, "Export format must be csv or xlsx.")
    dataset = _get_portal_database_dataset_for_user(dataset_id, str(user.get("user_id") or ""))
    if not dataset:
        _portal_audit_event_safe(
            event_type="database_export_denied",
            actor_user_id=actor_user_id,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=fmt or "unknown",
                row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
                row_count=None,
                params=params,
                reason="dataset_unavailable",
                requested_dataset_id=dataset_id,
            ),
        )
        return _portal_database_unavailable_response(user)
    if not dataset.get("can_export_rows"):
        _portal_audit_event_safe(
            event_type="database_export_denied",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=fmt,
                row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
                row_count=None,
                params=params,
                reason="export_not_enabled",
            ),
        )
        return _portal_database_export_error_response(user, dataset, "Export is not enabled for your access to this dataset.", status_code=403)
    columns = _get_portal_database_visible_columns(dataset_id)
    if not columns:
        _portal_audit_event_safe(
            event_type="database_export_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=fmt, row_limit=None, row_count=None, params=params, reason="no_visible_columns"),
        )
        return _portal_database_export_error_response(user, dataset, "This dataset has no visible columns configured.")
    # ------------------------------------------------------------- scopes --
    # Re-derived server-side. The panel names a scope; it never supplies the row
    # set, the column list or the count that decides the execution path.
    row_scope = _portal_database_export_row_scope(_portal_database_first_param(params, "row_scope", ""))
    column_scope = _portal_database_export_column_scope(_portal_database_first_param(params, "column_scope", ""))
    layout_columns = _portal_database_narrow_columns_for_export(params, columns)
    export_columns = _portal_database_export_columns(column_scope, columns, layout_columns) or list(columns)
    scope_params = _portal_database_export_scope_params(row_scope, params)
    if row_scope == "selection":
        # A selection is bounded by the page size and therefore structurally
        # below the direct cap: it is always a direct download, and no opaque
        # reference is ever persisted into background job state.
        return _portal_database_export_response(user, dataset_id, request, format_name_override=fmt, params_override=params)
    try:
        total, state, count_error = _count_portal_database_rows(dataset, columns, scope_params)
    except Exception as exc:
        exc_name = type(exc).__name__
        print(f"portal database export queue count failed: {exc_name}: dataset_id={dataset_id} client_code={dataset.get('client_code')}")
        _portal_audit_event_safe(
            event_type="database_export_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=fmt or "unknown", row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP, row_count=None, params=params, reason=exc_name),
        )
        return _portal_database_export_error_response(user, dataset, "This export could not be queued. Please contact an administrator.", status_code=502)
    if count_error:
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=fmt or "unknown", row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP, row_count=None, params=params, state=state, reason=count_error),
        )
        return _portal_database_export_error_response(user, dataset, count_error)
    if total <= PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP:
        return _portal_database_export_response(user, dataset_id, request, format_name_override=fmt, params_override=params)
    if total > PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:
        message = f"Export matches {total:,} rows, which exceeds the maximum export limit of {PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP:,}. Narrow the filters and try again."
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=fmt or "unknown", row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP, row_count=total, params=params, state=state, reason="export_global_limit_exceeded"),
        )
        return _portal_database_export_error_response(user, dataset, message)
    if not _database_export_schema_available():
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=fmt or "unknown",
                row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
                row_count=total,
                params=params,
                state=state,
                reason="async_export_schema_unavailable",
            ),
        )
        return _portal_database_row_browser_response(
            user,
            dataset_id,
            request,
            export_notice=ASYNC_DATABASE_EXPORT_SCHEMA_UNAVAILABLE_MESSAGE,
        )
    snapshot, snapshot_state, error = _portal_database_canonical_export_snapshot(
        dataset,
        export_columns,
        scope_params,
        format_name=fmt,
        row_scope=row_scope,
        column_scope=column_scope,
        expected_rows=total,
    )
    if error or snapshot is None:
        _portal_audit_event_safe(
            event_type="database_export_validation_failed",
            actor_user_id=actor_user_id,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=str(dataset.get("dataset_id") or "") or None,
            request=request,
            metadata_json=_portal_database_export_metadata(format_name=fmt, row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP, row_count=total, params=params, state=snapshot_state, reason=error or "invalid_export_request"),
        )
        return _portal_database_export_error_response(user, dataset, error or "This export request is invalid.")
    job_id = _enqueue_database_export_job(user, dataset, snapshot, format_name=fmt)
    _portal_audit_event_safe(
        event_type="database_export_job_queued",
        actor_user_id=actor_user_id,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=str(dataset.get("dataset_id") or "") or None,
        request=request,
        metadata_json=_portal_database_export_metadata(
            format_name=fmt,
            row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
            row_count=total,
            params=params,
            state=snapshot_state,
            extra={
                "job_id": job_id,
                "retention_days": PORTAL_DATABASE_ASYNC_EXPORT_RETENTION_DAYS,
                "direct_export_limit": PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP,
                "row_scope": row_scope,
                "column_scope": column_scope,
                "export_column_count": len(export_columns),
                "path": "background",
            },
        ),
    )
    query = urlencode({"export_job_queued": job_id})
    return _artifact_explorer_redirect(f"/user/database/exports?{query}")

def _database_export_lifecycle_notices(params: dict[str, list[str]], user_id: str) -> str:
    """Post-redirect-get feedback for the three lifecycle outcomes.

    Rendered as a polite live region so the outcome of `Anuluj` and
    `Zleć ponownie` is announced, not only drawn. Every notice is confirmed
    against a job the user actually owns before it is shown, so a crafted query
    string cannot make the page assert something that did not happen.
    """
    notices: list[str] = []

    def _confirmed(key: str) -> bool:
        job_id = _portal_database_first_param(params, key, "").strip()
        return bool(job_id and _get_database_export_job_for_user(job_id, user_id))

    if _confirmed("export_job_queued"):
        notices.append(("success", _tr("db.exports.queued_notice")))
    if _confirmed("export_job_cancelled"):
        notices.append(("", _tr("db.exports.cancelled_notice")))
    if _confirmed("export_job_requeued"):
        notices.append(("success", _tr("db.exports.requeued_notice")))
    if _portal_database_first_param(params, "export_cancel_refused", "").strip():
        notices.append(("", _tr("db.exports.cancel_refused")))
    if _portal_database_first_param(params, "export_requeue_refused", "").strip():
        notices.append(("", _tr("db.exports.requeue_refused")))
    if not notices:
        return (
            f'<div class="lp-visually-hidden" role="status" aria-live="polite" '
            f'aria-label="{_html(_tr("db.exports.status_aria"))}"></div>'
        )
    return (
        f'<div role="status" aria-live="polite" aria-label="{_html(_tr("db.exports.status_aria"))}">'
        + "".join(
            f'<div class="portal-callout {tone}">{_html(text)}</div>' for tone, text in notices
        )
        + "</div>"
    )


def _database_export_progress_html(job: dict) -> str:
    """Prepared-row count plus a progress bar (`DB-007`, in progress).

    Determinate when the job recorded how many rows it expected, indeterminate
    otherwise — a job queued before that was recorded has no honest denominator,
    and inventing one would draw a percentage the system does not know.
    """
    prepared = _database_export_int_or_none(job.get("row_count")) or 0
    expected = _database_export_int_or_none(job.get("expected_rows"))
    label = _tr("db.exports.prepared_rows", rows=_portal_database_group_digits(str(prepared)))
    if expected and expected > 0:
        percent = max(0, min(100, int(round((prepared / expected) * 100))))
        bar = (
            f'<div class="db-export-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" '
            f'aria-valuenow="{percent}" aria-label="{_html(_tr("db.exports.progress_aria"))}">'
            f'<span class="db-export-progress-fill" style="width:{percent}%"></span></div>'
        )
        label = (
            f"{label} / {_html(_portal_database_group_digits(str(expected)))} "
            f"{_html(_tr('db.export.rows'))}"
        )
        return f'<span class="db-export-progress-label">{label}</span>{bar}'
    bar = (
        f'<div class="db-export-progress is-indeterminate" role="progressbar" '
        f'aria-label="{_html(_tr("db.exports.progress_aria"))}">'
        '<span class="db-export-progress-fill"></span></div>'
    )
    return f'<span class="db-export-progress-label">{_html(label)}</span>{bar}'


def _database_export_reference_html(job: dict) -> str:
    """The copyable public reference (`DB-52`).

    The job id and nothing else: no storage key, no bucket, no claim token, no
    lease. It is the same identifier the queue redirect already puts in the URL,
    so it discloses nothing new.
    """
    reference = str(job.get("job_id") or "")
    if not reference:
        return ""
    return (
        '<span class="db-export-reference">'
        f'<span class="lp-mono" data-db-copy="{_html(reference)}">{_html(reference)}</span>'
        f'<button class="db-export-copy" type="button" data-db-export-copy="{_html(reference)}">'
        f'{_html(_tr("db.exports.action.copy_reference"))}</button>'
        "</span>"
    )


def _database_export_action_form(job_id: str, action: str, label: str, *, style: str = "secondary") -> str:
    """One state-changing action as a POST form.

    A POST, not a link: cancelling or requeueing must not be reachable by a
    prefetch, a crawler or a crafted `<img>`.
    """
    return (
        f'<form class="db-export-action" method="post" '
        f'action="/user/database/exports/{quote(str(job_id), safe="")}/{action}">'
        f'<button class="portal-button {style}" type="submit">{_html(label)}</button>'
        "</form>"
    )


def _database_export_download_href(job: dict, folder_id: str) -> str:
    """Where a ready export downloads from, or "" when it cannot.

    Two authorized routes exist, and which one applies is a deployment fact
    rather than a product choice: with the system-folder schema present the
    export lives in the user's `Eksporty danych` folder and downloads through
    the folder route; without it — a pre-044 deployment — the artifact-explorer
    route is the one that was already authorized for it. Both re-check ownership
    and expiry server-side; neither is offered for a job that is not currently
    downloadable.
    """
    artifact_id = str(job.get("artifact_id") or "")
    if not artifact_id or not _database_export_job_is_downloadable(job):
        return ""
    if folder_id:
        return f"/user/reports/database-exports/{quote(str(folder_id), safe='')}/artifacts/{quote(artifact_id, safe='')}/download"
    return f"/artifact-explorer/artifacts/{quote(artifact_id, safe='')}/download"


def _database_export_job_card(job: dict, folder_id: str) -> str:
    """One background export, showing only the actions its state can perform.

    `DB-50`: each of the four states has a different action set and none of them
    renders a greyed-out button. An action the backend would refuse is absent,
    not disabled.
    """
    state = _database_export_presentation_state(job)
    job_id = str(job.get("job_id") or "")
    title = (
        f'<div class="db-export-title"><strong>{_html(job.get("dataset_name"))}</strong>'
        f'<span class="portal-muted">{_html(job.get("client_code"))}</span>'
        f'<span class="lp-mono">{_html(str(job.get("requested_format") or "").upper())}</span></div>'
    )
    queued_at = str(job.get("queued_at") or "")[:16].replace("T", " ")
    meta_parts = [f'<span>{_html(_tr("db.exports.requested", date=queued_at))}</span>'] if queued_at else []
    detail = ""
    actions = ""
    if state == "running":
        detail = _database_export_progress_html(job)
        # `Dostępny do` is not known until the file exists.
        meta_parts.append(f'<span>{_html(_tr("db.exports.available_until"))}: \u2014</span>')
        actions = _database_export_action_form(job_id, "cancel", _tr("db.exports.action.cancel"))
    elif state == "ready":
        expires = str(job.get("artifact_expires_at") or job.get("expires_at") or "")[:16].replace("T", " ")
        rows = _database_export_int_or_none(job.get("row_count"))
        if expires:
            meta_parts.append(f'<span>{_html(_tr("db.exports.available_until"))}: {_html(expires)}</span>')
        if rows is not None:
            meta_parts.append(
                f'<span>{_html(_portal_database_group_digits(str(rows)))} {_html(_tr("db.export.rows"))}</span>'
            )
        href = _database_export_download_href(job, folder_id)
        if href:
            actions = (
                f'<a class="portal-button" href="{_html(href)}">'
                f'{_html(_tr("db.exports.action.download"))}</a>'
            )
    elif state == "expired":
        expires = str(job.get("artifact_expires_at") or job.get("expires_at") or "")[:16].replace("T", " ")
        if expires:
            meta_parts.append(f'<span>{_html(_tr("db.exports.available_until"))}: {_html(expires)}</span>')
        meta_parts.append(
            f'<span>{_html(_tr("db.exports.expired_note", days=PORTAL_DATABASE_ASYNC_EXPORT_RETENTION_DAYS))}</span>'
        )
        # No download action at all (`DB-51`) — not a disabled one.
        actions = _database_export_action_form(job_id, "requeue", _tr("db.exports.action.requeue"))
    else:  # failed
        # Only the sanitized message the worker stored; never an exception, a
        # query, a storage key or a traceback.
        detail = (
            f'<p class="db-export-failure">{_html(_database_export_safe_status_message(job))}</p>'
            + _database_export_reference_html(job)
        )
        actions = _database_export_action_form(job_id, "requeue", _tr("db.exports.action.requeue"))
    return (
        f'<li class="db-export-card" data-db-export-state="{_html(state)}">'
        f'<div class="db-export-head">{title}'
        f'<span class="db-export-badge is-{_html(state)}">{_html(_database_export_state_label(state))}</span></div>'
        + (f'<div class="db-export-meta">{"".join(meta_parts)}</div>' if meta_parts else "")
        + (f'<div class="db-export-detail">{detail}</div>' if detail else "")
        + (f'<div class="db-export-actions">{actions}</div>' if actions else "")
        + "</li>"
    )


def _database_export_state_list(folder: dict | None, jobs: list[dict]) -> str:
    """The approved four-state background export list (`DB-007`).

    Cancelled jobs are filtered out rather than given a fifth badge: the design
    defines four states, the user deliberately stopped this one, and it has no
    file, no progress and no action. The row itself stays in the database and in
    the audit trail, so the history is not lost.
    """
    folder_id = str((folder or {}).get("folder_id") or "")
    listed = [job for job in jobs if _database_export_presentation_state(job) != "cancelled"]
    strings = json.dumps(
        {
            "copied": _tr("db.exports.reference_copied"),
            "copyFailed": _tr("db.exports.reference_copy_failed"),
        },
        ensure_ascii=False,
    )
    # One polite live region for the copy-reference feedback, and the vocabulary
    # the module needs — the shipped JavaScript holds no Polish of its own.
    frame_open = (
        f'<div data-db-export-list data-db-export-strings="{_html(strings)}">'
        '<span class="lp-visually-hidden" role="status" aria-live="polite" data-db-export-status></span>'
    )
    if not listed:
        return (
            frame_open
            + '<div class="db-export-empty">'
            + f'<p><strong>{_html(_tr("db.exports.empty.title"))}</strong></p>'
            + '<p class="portal-muted">'
            + _html(_tr("db.exports.empty.body", limit=_portal_database_group_digits(str(PORTAL_DATABASE_DIRECT_EXPORT_ROW_CAP))))
            + "</p></div></div>"
        )
    cards = "".join(_database_export_job_card(job, folder_id) for job in listed)
    return frame_open + f'<ul class="db-export-list">{cards}</ul>' + "</div>"


def _database_export_folder_table(folder: dict | None, jobs: list[dict]) -> str:
    if not jobs:
        return _portal_empty_state("No database exports", "Async Database Explorer exports you queue will appear in this folder.")
    rows = []
    folder_id = str((folder or {}).get("folder_id") or "")
    for job in jobs:
        status = str(job.get("status") or "")
        downloadable = bool(folder_id and _database_export_job_is_downloadable(job))
        actions = ""
        if downloadable:
            actions = (
                f'<a class="portal-link" href="/user/reports/database-exports/{_html(folder_id)}/artifacts/{_html(job.get("artifact_id"))}/download">Download</a>'
            )
        message = _database_export_safe_status_message(job)
        timestamp = job.get("completed_at") or job.get("started_at") or job.get("queued_at") or ""
        rows.append(
            "<tr>"
            f"<td><strong>{_html(job.get('dataset_name'))}</strong><br><span class='portal-muted'>{_html(job.get('client_code'))}</span></td>"
            f"<td>{_html(str(job.get('requested_format') or '').upper())}</td>"
            f"<td>{_html(_database_export_status_label(status))}</td>"
            f"<td>{_html(job.get('row_count') if job.get('row_count') is not None else '')}</td>"
            f"<td>{_html(timestamp)}</td>"
            f"<td>{_html(job.get('expires_at') or '')}</td>"
            f"<td>{actions}{('<br><span class=\"portal-muted\">' + _html(message) + '</span>') if message else ''}</td>"
            "</tr>"
        )
    return (
        '<div class="portal-table-wrap"><table class="portal-table portal-table-dense"><thead><tr>'
        '<th>Dataset</th><th>Format</th><th>Status</th><th>Rows</th><th>Updated</th><th>Expires</th><th>Actions</th>'
        '</tr></thead><tbody>' + ''.join(rows) + '</tbody></table></div>'
    )


def _user_database_export_system_folder_response(
    user: dict,
    request: Request | None = None,
    *,
    folder_id: str | None = None,
) -> HTMLResponse:
    if not _database_export_schema_available():
        return _database_export_schema_unavailable_response(user)
    if not _database_export_system_folder_schema_available():
        return _user_database_exports_response(user, request, force_legacy=True)
    user_id = str(user.get("user_id") or "")
    folder = (
        _get_database_export_system_folder_for_user_by_id(user_id, folder_id)
        if folder_id
        else _get_database_export_system_folder_for_user(user_id)
    )
    if folder_id and not folder:
        return _portal_report_folder_unavailable_response(user)
    jobs = _list_database_export_jobs_for_user(user_id)
    if folder:
        jobs = [job for job in jobs if not job.get("system_folder_id") or job.get("system_folder_id") == folder.get("folder_id")]
    params = _portal_database_query_params(request)
    unavailable = ""
    if not folder:
        unavailable = '<div class="portal-callout">This system folder will be created automatically the first time you queue a background export.</div>'
    body = (
        _database_export_lifecycle_notices(params, user_id)
        + unavailable
        + '<section class="portal-panel db-export-panel-page">'
        + f'<h2>{_html(_tr("db.exports.recent"))}</h2>'
        + _database_export_state_list(folder, jobs)
        + '</section>'
    )
    return _portal_layout(
        _tr("db.exports.title"),
        body,
        user=user,
        portal_label="User Portal",
        active_key="reports",
        nav_items=_portal_user_nav(include_database_exports=True),
        description="Async Database Explorer export lifecycle for your account.",
        extra_assets=("css/data-grid.css", "js/data-grid-export.js"),
    )


def _database_export_artifact_access(user: dict, folder_id: str, artifact_id: str) -> tuple[dict, dict, dict] | None:
    folder = _get_database_export_system_folder_for_user_by_id(str(user.get("user_id") or ""), folder_id)
    if not folder:
        return None
    jobs = _list_database_export_jobs_for_user(str(user.get("user_id") or ""), limit=500)
    job = next(
        (
            item
            for item in jobs
            if item.get("system_folder_id") == folder.get("folder_id")
            and str(item.get("artifact_id") or "") == str(artifact_id)
            and _database_export_job_is_downloadable(item)
        ),
        None,
    )
    if not job:
        return None
    row = _get_artifact_browser_row(artifact_id)
    if not row:
        return None
    artifact = _artifact_browser_row(row)
    if not user_can_access_artifact(user, artifact, "download"):
        return None
    return folder, row, artifact


def _database_export_status_label(status: str | None) -> str:
    return {
        "queued": "Queued",
        "running": "Generating",
        "completed": "Ready",
        "failed": "Failed",
        "expired": "Expired",
    }.get(str(status or ""), str(status or "Unknown"))


def _user_database_exports_response(user: dict, request: Request | None = None, *, force_legacy: bool = False) -> HTMLResponse:
    if not _database_export_schema_available():
        return _database_export_schema_unavailable_response(user)
    if _database_export_system_folder_schema_available() and not force_legacy:
        folder = _get_database_export_system_folder_for_user(str(user.get("user_id") or ""))
        if folder:
            params = _portal_database_query_params(request)
            query = ""
            queued_job_id = _portal_database_first_param(params, "export_job_queued", "").strip()
            if queued_job_id:
                query = "?" + urlencode({"export_job_queued": queued_job_id})
            return _artifact_explorer_redirect(_database_export_folder_url(folder) + query)
        return _user_database_export_system_folder_response(user, request)
    params = _portal_database_query_params(request)
    user_id = str(user.get("user_id") or "")
    jobs = _list_database_export_jobs_for_user(user_id)
    folder_link = ""
    folder = None
    if _database_export_system_folder_schema_available():
        folder = _get_database_export_system_folder_for_user(user_id)
        folder_link = (
            '<div class="portal-actions"><a class="portal-button secondary" href="'
            + _html(_database_export_folder_url(folder))
            + '">' + _html(_tr("db.exports.title")) + '</a></div>'
        )
    body = (
        _database_export_lifecycle_notices(params, user_id)
        + folder_link
        + '<section class="portal-panel db-export-panel-page">'
        + f'<h2>{_html(_tr("db.exports.recent"))}</h2>'
        + _database_export_state_list(folder, jobs)
        + '</section>'
    )
    return _portal_layout(
        _tr("db.exports.title"),
        body,
        user=user,
        portal_label="User Portal",
        active_key="database-exports",
        nav_items=_portal_user_nav(include_database_exports=True),
        description="Large Database Explorer reports generated for your account.",
        extra_assets=("css/data-grid.css", "js/data-grid-export.js"),
    )

def _parse_portal_audit_page_params(params: dict[str, list[str]]) -> tuple[int, int, str | None]:
    page_raw = _portal_database_first_param(params, "page", "1")
    limit_raw = _portal_database_first_param(params, "limit", str(PORTAL_AUDIT_DEFAULT_PAGE_SIZE))
    try:
        page = int(page_raw)
    except ValueError:
        return 1, PORTAL_AUDIT_DEFAULT_PAGE_SIZE, "Page must be a whole number."
    try:
        limit = int(limit_raw)
    except ValueError:
        return 1, PORTAL_AUDIT_DEFAULT_PAGE_SIZE, "Limit must be a whole number."
    if page < 1:
        page = 1
    if limit < 1:
        limit = PORTAL_AUDIT_DEFAULT_PAGE_SIZE
    if limit > PORTAL_AUDIT_MAX_PAGE_SIZE:
        limit = PORTAL_AUDIT_MAX_PAGE_SIZE
    return page, limit, None


def _portal_audit_filters_from_request(request: Request | None) -> tuple[dict, int, int, str | None]:
    params = _portal_database_query_params(request)
    page, limit, page_error = _parse_portal_audit_page_params(params)
    if page_error:
        return {}, page, limit, page_error
    filters = {}
    event_type = _portal_database_first_param(params, "event_type", "").strip()
    if event_type:
        if not re.fullmatch(r"[A-Za-z0-9_:-]{1,128}", event_type):
            return {}, page, limit, "Event type must contain only letters, numbers, underscore, colon or dash."
        filters["event_type"] = event_type
    actor = _portal_database_first_param(params, "actor", "").strip()
    if actor:
        filters["actor"] = actor[:128]
    client_code = _portal_database_first_param(params, "client_code", "").strip()
    if client_code:
        filters["client_code"] = client_code[:128]
    for key, label in (("dataset_id", "Dataset ID"), ("report_folder_id", "Report folder ID")):
        value = _portal_database_first_param(params, key, "").strip()
        if value:
            normalized = _portal_uuid_or_none(value)
            if not normalized:
                return {}, page, limit, f"{label} must be a UUID."
            filters[key] = normalized
    for key, label in (("date_from", "Date from"), ("date_to", "Date to")):
        value, error = _portal_database_parse_iso(_portal_database_first_param(params, key, ""), label)
        if error:
            return {}, page, limit, error
        if value:
            filters[key] = value
    return filters, page, limit, None


def _portal_audit_url(filters: dict, *, page: int, limit: int) -> str:
    params = {key: value for key, value in filters.items() if value not in (None, "")}
    params["page"] = str(page)
    params["limit"] = str(limit)
    return "/admin/audit?" + urlencode(params)


def _search_portal_audit_events(filters: dict | None = None, *, page: int = 1, limit: int = 100) -> tuple[list[dict], int]:
    filters = filters or {}
    safe_page = max(1, int(page or 1))
    safe_limit = max(1, min(int(limit or PORTAL_AUDIT_DEFAULT_PAGE_SIZE), PORTAL_AUDIT_MAX_PAGE_SIZE))
    where = []
    values: list[Any] = []
    if filters.get("event_type"):
        where.append("pae.event_type = %s")
        values.append(filters["event_type"])
    if filters.get("actor"):
        where.append("(u.username ILIKE %s OR pae.actor_user_id::text = %s)")
        values.extend([f"%{filters['actor']}%", filters["actor"]])
    if filters.get("client_code"):
        where.append("pae.client_code = %s")
        values.append(filters["client_code"])
    if filters.get("dataset_id"):
        where.append("pae.dataset_id = %s")
        values.append(filters["dataset_id"])
    if filters.get("report_folder_id"):
        where.append("pae.report_folder_id = %s")
        values.append(filters["report_folder_id"])
    if filters.get("date_from"):
        where.append("pae.created_at >= %s")
        values.append(filters["date_from"])
    if filters.get("date_to"):
        where.append("pae.created_at <= %s")
        values.append(filters["date_to"])
    where_sql = " WHERE " + " AND ".join(where) if where else ""
    offset = (safe_page - 1) * safe_limit
    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(f"SELECT count(*) AS total FROM portal_audit_events pae LEFT JOIN artifact_users u ON u.user_id = pae.actor_user_id{where_sql}", values)
            total_row = cur.fetchone()
            total = int((total_row or {}).get("total") or 0)
            cur.execute(
                f"""
                SELECT pae.audit_id, pae.event_type, pae.actor_user_id, u.username AS actor_username,
                       pae.client_code, pc.display_name AS client_display_name,
                       pae.dataset_id, pdd.dataset_name,
                       pae.report_folder_id, prf.folder_name AS report_folder_name,
                       pae.artifact_id, pae.ip_address, pae.user_agent, pae.metadata_json, pae.created_at
                FROM portal_audit_events pae
                LEFT JOIN artifact_users u ON u.user_id = pae.actor_user_id
                LEFT JOIN portal_clients pc ON pc.client_code = pae.client_code
                LEFT JOIN portal_database_datasets pdd ON pdd.dataset_id = pae.dataset_id
                LEFT JOIN portal_report_folders prf ON prf.folder_id = pae.report_folder_id
                {where_sql}
                ORDER BY pae.created_at DESC
                LIMIT %s OFFSET %s
                """,
                values + [safe_limit, offset],
            )
            rows = cur.fetchall()
    events = _rows_to_dicts(rows)
    for event in events:
        event["audit_id"] = str(event.get("audit_id"))
        event["actor_user_id"] = str(event.get("actor_user_id")) if event.get("actor_user_id") else None
        event["dataset_id"] = str(event.get("dataset_id")) if event.get("dataset_id") else None
        event["report_folder_id"] = str(event.get("report_folder_id")) if event.get("report_folder_id") else None
        event["artifact_id"] = str(event.get("artifact_id")) if event.get("artifact_id") else None
    return events, total


def _list_portal_audit_events(limit: int = 100) -> list[dict]:
    events, _ = _search_portal_audit_events(page=1, limit=limit)
    return events


def _portal_audit_summary(metadata: Any) -> str:
    if not isinstance(metadata, dict):
        return ""
    parts = []
    for key in (
        "reason",
        "target_username",
        "target_user_id",
        "changed_fields",
        "client_code",
        "dataset_name",
        "folder_name",
        "format",
        "row_count",
        "row_limit",
        "page",
        "limit",
        "sort",
        "direction",
        "date_from",
        "date_to",
        "report_type",
        "file_ext",
    ):
        value = metadata.get(key)
        if value not in (None, "", []):
            if isinstance(value, list):
                value = ", ".join(str(item) for item in value)
            parts.append(f"{key}: {value}")
    filter_keys = metadata.get("filter_keys")
    if filter_keys:
        parts.append("filters: " + ", ".join(str(item) for item in filter_keys))
    return "; ".join(parts)


def _portal_audit_target_label(event: dict) -> str:
    if event.get("dataset_name") or event.get("dataset_id"):
        return str(event.get("dataset_name") or event.get("dataset_id"))
    if event.get("report_folder_name") or event.get("report_folder_id"):
        return str(event.get("report_folder_name") or event.get("report_folder_id"))
    if event.get("artifact_id"):
        return str(event.get("artifact_id"))
    metadata = event.get("metadata_json") if isinstance(event.get("metadata_json"), dict) else {}
    return str(metadata.get("target_username") or metadata.get("target_user_id") or "-")


