def _smart_criteria_preview_for_display(sq: dict | None) -> str:
    try:
        cleaned = _validate_smart_folder_search_query(dict(sq or {}))
        return json.dumps(cleaned, indent=2, ensure_ascii=False)
    except HTTPException:
        return json.dumps(sq or {}, indent=2, ensure_ascii=False)


