def _artifact_explorer_folder_membership_html(
    artifact_id: str,
    *,
    folders: list[dict],
    can_manage: bool,
    success_message: str | None = None,
    error_message: str | None = None,
) -> str:
    notices = ""
    if error_message:
        notices += f'<div class="notice error">{_html(error_message)}</div>'
    if success_message:
        notices += f'<div class="notice">{_html(success_message)}</div>'
    if folders:
        folder_items = []
        for folder in folders:
            mtype = folder.get("membership_type") or "manual"
            remove = ""
            if can_manage and mtype == "manual":
                remove = (
                    f'<form method="post" action="/artifact-explorer/artifacts/{_html(artifact_id)}/folders/{_html(folder["folder_id"])}/remove" style="display:inline;">'
                    '<button class="button small secondary" type="submit">Remove</button>'
                    "</form>"
                )
            smart_note = ""
            if mtype == "smart_dynamic":
                smart_note = ' <span class="subtle">(smart folder — matches saved search; not a manual assignment)</span>'
            folder_items.append(
                f'<li><a href="/artifact-explorer/folders/{_html(folder["folder_id"])}">{_html(folder.get("path") or folder["folder_name"])}</a>{smart_note} {remove}</li>'
            )
        memberships = "<ul>" + "".join(folder_items) + "</ul>"
    else:
        memberships = '<p class="subtle">This artifact is not assigned to any virtual folder.</p>'
    form = ""
    if can_manage:
        manual_folders = list_manual_virtual_folders_with_paths()
        options = "".join(
            f'<option value="{_html(folder["folder_id"])}">{_html(folder.get("path") or folder["folder_name"])}</option>'
            for folder in manual_folders
        )
        form = (
            f'<form method="post" action="/artifact-explorer/artifacts/{_html(artifact_id)}/folders" class="toolbar">'
            '<div style="min-width:280px;"><label for="folder_id">Add to manual folder</label>'
            f'<select id="folder_id" name="folder_id" required>{options}</select></div>'
            '<button type="submit">Add</button></form>'
            if options
            else '<p class="subtle">Create a manual virtual folder before assigning artifacts.</p>'
        )
    return '<section id="virtual-folders" class="panel"><h2>Virtual Folders</h2>' + notices + memberships + form + "</section>"


# ===========================================================================
# Approved stage S13 — server-side account preferences and saved views
#
# Three account-owned persistence surfaces, all defined by migration 066:
#
#   * the per-account theme override (`D-011`, `SH-8`);
#   * named saved Database Explorer views (`D-007`);
#   * named column sets (`DB-30`).
#
# Two rules run through everything below and are not restated at each function:
#
#   1. THE ACCOUNT COMES FROM THE SESSION. Every statement here scopes by the
#      `user_id` the caller resolved from the signed session cookie. No function
#      in this section accepts an owner identifier from a request, and object
#      ids are always resolved together with their owner in the same `WHERE`, so
#      another account's object is indistinguishable from one that never
#      existed.
#   2. A PERSISTED OBJECT IS NOT AN AUTHORIZATION GRANT. Saving state does not
#      freeze the authorization or catalog facts that were true when it was
#      written. Every open/apply re-resolves the dataset through
#      `_get_portal_database_dataset_for_user`, re-reads the approved column
#      universe through `_get_portal_database_visible_columns`, and re-parses the
#      stored state through the same S3/S5 parsers a URL goes through.
# ===========================================================================

# The approved theme vocabulary (`D-011`). AUTO is the absence of an override,
# and it is the default for an account that has never chosen. These are the
# repository's canonical identifiers, identical to `MODES` in `js/theme.js`.
PORTAL_THEME_MODES = ("auto", "light", "dark")
PORTAL_DEFAULT_THEME = "auto"

# Names are user-authored labels, not data. They are bounded, trimmed, and
# refused outright when they carry control characters; rendering escapes them
# like every other string, so a name can never become markup.
PORTAL_SAVED_OBJECT_NAME_MAX_CHARS = 80
# Bound on the persisted payload, mirrored by the migration's CHECK. The largest
# legitimate saved view — 128 layout entries plus a full filter set — is far
# below this; the bound exists so a crafted request cannot store an unbounded
# document.
#
# The unit is BYTES of UTF-8, not Unicode code points, and migration 067 states
# the same rule as `octet_length(...) <= 8192`. Counting code points here while
# calling the limit "8 KiB" made the two disagree for every non-ASCII document:
# 8192 Polish or CJK characters pass a code-point bound and occupy well over
# 8 KiB, so a payload the application accepted could be refused by the database.
# One unit, measured on the same encoded document both sides store.
PORTAL_SAVED_OBJECT_STATE_MAX_BYTES = 8192
# How many named objects one account may keep per dataset. The approved design
# states no number; this is a repository-consistent bound in the spirit of the
# other Database Explorer caps, and it is enforced with a message rather than by
# silently dropping the oldest.
PORTAL_SAVED_OBJECTS_PER_DATASET_MAX = 50
# Version stamp on every stored payload. It is what lets a later stage read an
# older document deliberately instead of guessing.
PORTAL_SAVED_STATE_VERSION = 1

# The saved-view reference parameter. It names which saved view the current
# sheet was opened from, so the selector can show its name and the `modified`
# state the approved component defines. It is a REFERENCE, never state: it
# selects nothing, filters nothing and reaches no query. An id that does not
# resolve for this account on this dataset is dropped before anything is
# rendered, so it can neither leak another account's object nor ride into a
# generated link.
PORTAL_DATABASE_SAVED_VIEW_PARAM = "view"

# THE RUNTIME-CRITICAL S13 SCHEMA CONTRACT, STATED AS DEFINITIONS.
#
# Names are not a schema contract. A relation can carry every expected column
# and a constraint carrying every expected NAME while the rule behind the name
# points at the wrong relation, covers the wrong columns, does not cascade,
# accepts a theme S13 cannot render, or bounds a payload in code points instead
# of bytes. The runtime probe therefore compares DEFINITIONS taken from the
# PostgreSQL catalogs against what migration 067 authorizes, because every one
# of these rules is something the application's own statements rely on:
# `ON CONFLICT (owner_user_id, dataset_id, view_name)` needs that exact
# uniqueness, an insert that omits `saved_view_id` needs that default, and
# owner-scoped authorization needs the cascade.
#
# `(format_type, NOT NULL, canonical default expression)` — the default is the
# EXACT expression `pg_get_expr(pg_attrdef.adbin, ...)` deparses to, and an
# empty string means the column must carry no default at all.
PORTAL_S13_REQUIRED_COLUMN_DEFINITIONS: dict[str, dict[str, tuple[str, bool, str]]] = {
    "portal_user_preferences": {
        "user_id": ("uuid", True, ""),
        "theme": ("text", True, "'auto'::text"),
        "created_at": ("timestamp with time zone", True, "now()"),
        "updated_at": ("timestamp with time zone", True, "now()"),
    },
    "portal_database_saved_views": {
        "saved_view_id": ("uuid", True, "gen_random_uuid()"),
        "owner_user_id": ("uuid", True, ""),
        "dataset_id": ("uuid", True, ""),
        "view_name": ("text", True, ""),
        "view_state_json": ("jsonb", True, ""),
        "created_at": ("timestamp with time zone", True, "now()"),
        "updated_at": ("timestamp with time zone", True, "now()"),
    },
    "portal_database_column_sets": {
        "column_set_id": ("uuid", True, "gen_random_uuid()"),
        "owner_user_id": ("uuid", True, ""),
        "dataset_id": ("uuid", True, ""),
        "set_name": ("text", True, ""),
        "layout_state_json": ("jsonb", True, ""),
        "created_at": ("timestamp with time zone", True, "now()"),
        "updated_at": ("timestamp with time zone", True, "now()"),
    },
}

# THE CHECK CONTRACT IS AN EXPRESSION, NOT A BAG OF TOKENS.
#
# Two earlier probes tried to recognise a CHECK by what its text CONTAINS —
# first the expected literal set, then required and forbidden fragments. Both
# accept the INVERTED rule, because an inverted rule is written with exactly the
# same tokens: `octet_length(state::text) >= 8192` contains `octet_length` and
# `8192`, `theme NOT IN ('auto','light','dark')` names all three approved
# themes, and `jsonb_typeof(state) <> 'object'` names `jsonb_typeof` and
# `'object'`. Presence of a token says nothing about the direction of the
# comparison it appears in, so no accumulation of substrings can ever settle
# the question.
#
# What settles it is comparing the WHOLE expression against the one canonical
# form the authorized migration produces. `<=` and `>=` are different strings in
# the same position; `= ANY (ARRAY[...])` and `<> ALL (ARRAY[...])` are
# different expressions; `char_length` standing where `octet_length` must stand
# fails; a fourth theme, a missing theme, a different bound and a different
# column each change the string.
#
# WHY THE CATALOG FORM IS A SEMANTIC FACT AND NOT SOURCE TEXT.
#   `pg_get_expr(pg_constraint.conbin, conrelid)` does not echo what an operator
#   typed. It DEPARSES the stored parse tree, so `theme IN ('auto','light',
#   'dark')`, `theme = ANY (ARRAY['auto','light','dark'])` and every casing,
#   whitespace and redundant-parenthesis variant of that rule collapse onto ONE
#   string, while a rule with different meaning cannot collapse onto it. Column
#   references are resolved to their real names, constants carry their real
#   type, and function and operator IDENTITY survives: a `public` function
#   shadowing a `pg_catalog` one deparses schema-qualified
#   (`public.octet_length(...)`), so a same-looking expression computed by a
#   different function is a different string here. The comparison is therefore
#   on the rule PostgreSQL will actually evaluate.
#
#   The cost of that strictness is a schema written differently but meaning the
#   same — `theme = 'auto' OR theme = 'light' OR theme = 'dark'` — being called
#   `incompatible`. That is the safe direction: S13 declines to activate against
#   a schema it did not authorize, and the authorized schema is exactly what
#   migrations 066 then 067 produce.
#
# The expected forms are GENERATED from the application's own bounds below, so
# the limit the server enforces and the limit the probe demands of the database
# cannot drift apart in a later edit.


def _portal_s13_theme_check_expression() -> str:
    """The approved theme enum, as PostgreSQL deparses `theme IN (...)`."""
    values = ", ".join(f"'{mode}'::text" for mode in PORTAL_THEME_MODES)
    return f"(theme = ANY (ARRAY[{values}]))"


def _portal_s13_name_check_expression(column: str) -> str:
    """Non-empty, and bounded in CHARACTERS — a name is a label, not a payload."""
    return f"(({column} <> ''::text) AND (char_length({column}) <= {PORTAL_SAVED_OBJECT_NAME_MAX_CHARS}))"


def _portal_s13_state_object_check_expression(column: str) -> str:
    """The payload is a JSON OBJECT. `<> 'object'` is a different string here."""
    return f"(jsonb_typeof({column}) = 'object'::text)"


def _portal_s13_state_bound_check_expression(column: str) -> str:
    """The payload bound, in UTF-8 BYTES, at most — migration 067's rule."""
    return f"(octet_length(({column})::text) <= {PORTAL_SAVED_OBJECT_STATE_MAX_BYTES})"


# `type` is the `pg_constraint.contype` letter. A foreign key states its target
