def _portal_unique_violation(exc: Exception) -> bool:
    """Whether a driver error is a unique-constraint violation (SQLSTATE 23505).

    Read from the SQLSTATE rather than from the message: the message is locale-
    and version-dependent, and a rename colliding with an existing name is an
    ordinary, expected outcome that must be reported as such rather than as a
    generic failure.
    """
    for attribute in ("sqlstate", "pgcode"):
        code = getattr(exc, attribute, None)
        if code and str(code) == "23505":
            return True
    diag = getattr(exc, "diag", None)
    if diag is not None and str(getattr(diag, "sqlstate", "") or "") == "23505":
        return True
    return type(exc).__name__ == "UniqueViolation"


# ---------------------------------------------------------------------------
# E. One-shot outcome notices
#
# Every S13 mutation is a POST that redirects, so its outcome travels back in
# the query string. The two parameters carry a KEY from a fixed allowlist, never
# a message and never anything the caller typed: a rejected name must not be
# reflected into the page that rejected it.
# ---------------------------------------------------------------------------

PORTAL_DATABASE_SAVED_NOTICE_PARAM = "saved_notice"
PORTAL_DATABASE_SAVED_ERROR_PARAM = "saved_error"

PORTAL_DATABASE_SAVED_NOTICE_KEYS = {
    "view_created": "db.saved.view_created",
    "view_updated": "db.saved.view_updated",
    "view_deleted": "db.saved.view_deleted",
    "set_created": "db.saved.set_created",
    "set_updated": "db.saved.set_updated",
    "set_deleted": "db.saved.set_deleted",
    "set_narrowed": "db.saved.set_narrowed",
}

PORTAL_DATABASE_SAVED_ERROR_KEYS = {
    "name_required": "db.saved.name_required",
    "name_too_long": "db.saved.name_too_long",
    "name_invalid": "db.saved.name_invalid",
    "state_invalid": "db.saved.state_invalid",
    "state_too_large": "db.saved.state_too_large",
    "duplicate": "db.saved.duplicate",
    "limit": "db.saved.limit",
    "failed": "db.saved.failed",
    "not_found": "db.saved.not_found",
    "stale": "db.saved.stale",
    "stale_column": "db.saved.stale_column",
    "filtering_revoked": "db.saved.filtering_revoked",
    "unavailable": "db.saved.unavailable",
}

# Parameters that describe an outcome or a reference rather than the view, and
# therefore never belong in a saved document or in the query a save is derived
# from.
PORTAL_DATABASE_NON_STATE_PARAMS = (
    PORTAL_DATABASE_SAVED_NOTICE_PARAM,
    PORTAL_DATABASE_SAVED_ERROR_PARAM,
    PORTAL_DATABASE_SAVED_VIEW_PARAM,
)


def _portal_database_saved_notice_html(params: dict[str, list[str]]) -> str:
    """Render and CONSUME the one-shot outcome notice.

    Consumed here, like the `colpanel` intent, so a reload or a copied address
    does not repeat "Zapisano widok" forever, and so the marker never rides into
    a generated link.
    """
    notice_key = str((params.pop(PORTAL_DATABASE_SAVED_NOTICE_PARAM, None) or [""])[0])
    error_key = str((params.pop(PORTAL_DATABASE_SAVED_ERROR_PARAM, None) or [""])[0])
    html = ""
    if error_key in PORTAL_DATABASE_SAVED_ERROR_KEYS:
        html += (
            '<div class="portal-callout" role="alert">'
            f'{_html(_tr(PORTAL_DATABASE_SAVED_ERROR_KEYS[error_key]))}</div>'
        )
    if notice_key in PORTAL_DATABASE_SAVED_NOTICE_KEYS:
        html += (
            '<div class="portal-callout success" role="status">'
            f'{_html(_tr(PORTAL_DATABASE_SAVED_NOTICE_KEYS[notice_key]))}</div>'
        )
    return html


def _portal_database_state_query(params: dict[str, list[str]]) -> str:
    """The current canonical view state as a query string, for a save action.

    A save POST carries no state document in its body. It posts to the sheet's
    own state expressed as ordinary query parameters, and the handler re-parses
    them through exactly the pipeline a page render uses. So "the state that was
    saved" is by construction "the state the server would have rendered", and
    nothing a caller invents can enter storage without surviving that pipeline.
    """
    payload = {
        key: list(values)
        for key, values in params.items()
        if values and key not in PORTAL_DATABASE_NON_STATE_PARAMS
    }
    return urlencode(payload, doseq=True)


def _portal_database_saved_action_url(dataset_id: str, suffix: str, params: dict[str, list[str]] | None = None) -> str:
    base = f"/user/database/datasets/{quote(str(dataset_id))}{suffix}"
    if params is None:
        return base
    query = _portal_database_state_query(params)
    return base + (f"?{query}" if query else "")


def _portal_database_sheet_return_path(dataset_id: str, params: dict[str, list[str]]) -> str:
    """Where a mutation returns to: this sheet, with this state.

    Server-generated from the dataset id the route already resolved and from
    parameters the sheet itself produced, then passed through the same
    `_safe_ui_next_path` allowlist every other portal redirect target uses. A
    saved view is never a stored URL and never a caller-supplied one, so there
    is no redirect target an attacker can choose.
    """
    return _safe_ui_next_path(_portal_database_url(dataset_id, params), default="/user/database")


# ---------------------------------------------------------------------------
# F. Saved-view and column-set markup
# ---------------------------------------------------------------------------


def _portal_database_saved_view_panel_html(
    dataset_id: str,
    params: dict[str, list[str]],
    views: list[dict],
    *,
    active_view: dict | None,
    modified: bool,
) -> str:
    """The `DB-003` saved-view selector, in the client context bar.

    A `<details>` over ordinary links and forms: opening a view is a GET to a
    server-generated URL, and saving, updating and deleting are POSTs. Nothing
    here needs scripting, and nothing here carries a state document.
    """
    return_path = _portal_database_sheet_return_path(dataset_id, params)
    entries = []
    for view in views:
        view_id = str(view.get("saved_view_id") or "")
        name = str(view.get("view_name") or "")
        is_active = bool(active_view and str(active_view.get("saved_view_id") or "") == view_id)
        open_action = _portal_database_saved_action_url(dataset_id, "/views/" + quote(view_id) + "/open")
        delete_action = _portal_database_saved_action_url(dataset_id, "/views/" + quote(view_id) + "/delete")
        entries.append(
            '<li class="db-views-item' + (" is-active" if is_active else "") + '">'
            + f'<a class="db-views-open" href="{_html(open_action)}" '
            + f'aria-label="{_html(_tr("db.saved.open_view_aria", name=name))}"'
            + (' aria-current="true"' if is_active else "")
            + f">{_html(name)}</a>"
            + f'<form class="db-views-delete" method="post" '
            + f'action="{_html(delete_action)}">'
            + f'<input type="hidden" name="next" value="{_html(return_path)}">'
            + f'<button class="db-views-action" type="submit" '
            + f'aria-label="{_html(_tr("db.saved.delete_view_aria", name=name))}">'
            + f'{_html(_tr("db.saved.delete"))}</button></form>'
            "</li>"
        )
    list_html = (
        f'<ul class="db-views-list">{"".join(entries)}</ul>'
        if entries
        else f'<p class="db-help">{_html(_tr("db.saved.views_none"))}</p>'
    )
    active_html = ""
    if active_view:
        active_name = str(active_view.get("view_name") or "")
        active_update_action = _portal_database_saved_action_url(
            dataset_id, "/views/" + quote(str(active_view.get("saved_view_id") or "")), params
        )
        active_html = (
            '<p class="db-views-active">'
            + _html(_tr("db.saved.active_view", name=active_name))
            + (
                f' <span class="db-views-modified">{_html(_tr("db.saved.modified"))}</span>'
                if modified
                else ""
            )
            + "</p>"
            + '<form class="db-views-update" method="post" '
            + f'action="{_html(active_update_action)}">'
            + f'<input type="hidden" name="next" value="{_html(return_path)}">'
            + f'<label class="lp-visually-hidden" for="db-view-rename">{_html(_tr("db.saved.view_name"))}</label>'
            + f'<input id="db-view-rename" class="db-views-name" type="text" name="view_name" '
            + f'maxlength="{PORTAL_SAVED_OBJECT_NAME_MAX_CHARS}" autocomplete="off" '
            + f'value="{_html(active_name)}">'
            + f'<button class="portal-button" type="submit">{_html(_tr("db.saved.save_changes"))}</button>'
            + "</form>"
        )
    save_html = (
        '<form class="db-views-save" method="post" '
        + f'action="{_html(_portal_database_saved_action_url(dataset_id, "/views", params))}">'
        + f'<input type="hidden" name="next" value="{_html(return_path)}">'
        + f'<label class="lp-visually-hidden" for="db-view-name">{_html(_tr("db.saved.view_name"))}</label>'
        + f'<input id="db-view-name" class="db-views-name" type="text" name="view_name" required '
        + f'maxlength="{PORTAL_SAVED_OBJECT_NAME_MAX_CHARS}" autocomplete="off" '
        + f'placeholder="{_html(_tr("db.saved.view_name"))}">'
        + f'<button class="portal-button" type="submit">{_html(_tr("db.saved.save_as_view"))}</button>'
        + "</form>"
    )
    summary = _tr("db.saved.views")
    if active_view:
        summary = str(active_view.get("view_name") or summary)
    return (
        '<details class="db-views" data-db-views>'
        + f'<summary class="portal-button secondary db-views-trigger">{_html(summary)}</summary>'
        + f'<div class="db-views-panel" role="group" aria-label="{_html(_tr("db.saved.views_aria"))}">'
        + active_html
        + list_html
        + save_html
        + "</div></details>"
    )


def _portal_database_column_sets_html(
    dataset_id: str,
    params: dict[str, list[str]],
    column_sets: list[dict],
    *,
    reset_url: str,
) -> str:
    """`Zestawy ▾` inside the `DB-008` column panel (`TGS` §5.2, §5.3).

    Rendered OUTSIDE the panel's own `<form>`, because saving and deleting a set
    are their own POSTs and a form cannot nest. `Domyślne kolumny` is listed here
    too, exactly as §5.3 requires — it is the existing column-layout reset, not a
    second reset model.
    """
    return_path = _portal_database_sheet_return_path(dataset_id, params)
    entries = [
        '<li class="db-colsets-item">'
        f'<a class="db-colsets-apply" href="{_html(reset_url)}">{_html(_tr("db.cols.reset"))}</a>'
        "</li>"
    ]
    for column_set in column_sets:
        set_id = str(column_set.get("column_set_id") or "")
        name = str(column_set.get("set_name") or "")
        apply_url = _portal_database_saved_action_url(
            dataset_id, "/column-sets/" + quote(set_id) + "/apply", params
        )
        set_delete_action = _portal_database_saved_action_url(
            dataset_id, "/column-sets/" + quote(set_id) + "/delete"
        )
        entries.append(
            '<li class="db-colsets-item">'
            + f'<a class="db-colsets-apply" href="{_html(apply_url)}" '
            + f'aria-label="{_html(_tr("db.saved.apply_set_aria", name=name))}">{_html(name)}</a>'
            + '<form class="db-colsets-delete" method="post" '
            + f'action="{_html(set_delete_action)}">'
            + f'<input type="hidden" name="next" value="{_html(return_path)}">'
            + f'<button class="db-colsets-action" type="submit" '
            + f'aria-label="{_html(_tr("db.saved.delete_set_aria", name=name))}">'
            + f'{_html(_tr("db.saved.delete"))}</button></form>'
            "</li>"
        )
    empty_html = (
        "" if column_sets else f'<p class="db-help">{_html(_tr("db.saved.sets_none"))}</p>'
    )
    return (
        '<details class="db-colsets" data-db-colsets>'
        + f'<summary class="db-colsets-trigger">{_html(_tr("db.saved.sets"))} &#9662;</summary>'
        + f'<div class="db-colsets-panel" role="group" aria-label="{_html(_tr("db.saved.sets_aria"))}">'
        + f'<ul class="db-colsets-list">{"".join(entries)}</ul>'
        + empty_html
        + '<form class="db-colsets-save" method="post" '
        + f'action="{_html(_portal_database_saved_action_url(dataset_id, "/column-sets", params))}">'
        + f'<input type="hidden" name="next" value="{_html(return_path)}">'
        + f'<label class="lp-visually-hidden" for="db-colset-name">{_html(_tr("db.saved.set_name"))}</label>'
        + f'<input id="db-colset-name" class="db-colsets-name" type="text" name="set_name" required '
        + f'maxlength="{PORTAL_SAVED_OBJECT_NAME_MAX_CHARS}" autocomplete="off" '
        + f'placeholder="{_html(_tr("db.saved.set_name"))}">'
        + f'<button class="portal-button" type="submit">{_html(_tr("db.saved.save_as_set"))}</button>'
        + "</form></div></details>"
    )


def _portal_database_catalogue_saved_view_chips(dataset_id: str, views: list[dict]) -> str:
    """`Zapisane widoki` chips on `DB-001` (`PBC` §2.1).

    Direct entry points: a chip is a link that opens the row sheet with that view
    applied. The list is the caller's already-authorized one, so a dataset the
    account cannot currently open contributes no chip, no name and no count —
    its saved views are not merely hidden, they were never queried.
    """
    if not views:
        return '<span class="db-cat-views-empty" aria-hidden="true">&#8212;</span>'
    chips = []
    for view in views:
        name = str(view.get("view_name") or "")
        href = _portal_database_saved_action_url(
            dataset_id, "/views/" + quote(str(view.get("saved_view_id") or "")) + "/open"
        )
        chips.append(
            f'<a class="db-cat-view-chip" href="{_html(href)}" '
            f'aria-label="{_html(_tr("db.saved.open_view_aria", name=name))}">{_html(name)}</a>'
        )
    chips = "".join(chips)
    return f'<span class="db-cat-views">{chips}</span>'


# ---------------------------------------------------------------------------
# G. Shared display-state resolution
#
# Extracted from the row browser so the sheet, a saved view and a column set all
# resolve `cols`, the S5 layout and the canonical parameters through ONE code
# path. If they did not, "the state that was saved" and "the state that renders"
# could drift, and the drift would land on the security-relevant side: the
# intersection with the approved column universe happens here.
# ---------------------------------------------------------------------------


def _portal_database_resolve_display_state(
    columns: list[dict], params: dict[str, list[str]]
) -> tuple[list[dict], list[dict], dict, bool, bool]:
    """``(visible_columns, display_columns, layout, cols_fell_back, cols_active)``.

    Mutates ``params`` into its canonical form, exactly as the sheet requires:
    rejected, unknown and unapproved identifiers are removed rather than carried,
    so nothing that failed validation can ride into a generated link, an export
    URL or a saved document.
    """
    display_columns, cols_fell_back = _portal_database_parse_cols(params, columns)
    if cols_fell_back or len(display_columns) >= len(columns):
        params.pop("cols", None)
    else:
        params["cols"] = [str(column.get("column_name")) for column in display_columns]
    cols_active = _portal_database_cols_active(params, columns, display_columns)
    _portal_database_drop_unapproved_column_params(
        params, {str(column.get("column_name") or "") for column in columns}
    )
    visible_columns = display_columns
    layout = _portal_database_resolve_column_layout(params, columns, display_columns)
    display_columns = layout["display_columns"]
    _portal_database_apply_layout_params(params, layout)
    return visible_columns, display_columns, layout, cols_fell_back, cols_active


def _portal_database_current_view_document(
    dataset: dict, columns: list[dict], params: dict[str, list[str]]
) -> tuple[dict | None, str | None]:
    """The canonical document for the state a request describes.

    Used by `Zapisz jako widok` and `Zapisz zmiany`. The parameters are put
    through the sheet's own resolution first, so what is stored is what the
    server would render, never what the caller sent.
    """
    visible_columns, _display_columns, layout, _fell_back, _active = _portal_database_resolve_display_state(
        columns, params
    )
    return _portal_database_canonical_view_state(dataset, columns, params, layout, visible_columns)


def _portal_database_current_layout_document(
    columns: list[dict], params: dict[str, list[str]]
) -> dict:
    """The canonical column-set document for the state a request describes.

    Column layout ONLY. Filters, search, sort, page and density are deliberately
    absent: a column set is a reusable layout, and one that silently carried a
    filter would change which rows a user sees when they only asked to change
    which columns they see.
    """
    visible_columns, _display_columns, layout, _fell_back, _active = _portal_database_resolve_display_state(
        columns, params
    )
    document = _portal_database_canonical_layout_state(layout, visible_columns)
    document["state_version"] = PORTAL_SAVED_STATE_VERSION
    return document


# ---------------------------------------------------------------------------
# H. Route responses
# ---------------------------------------------------------------------------


def _portal_database_saved_redirect(dataset_id: str, *, notice: str = "", error: str = "", next_path: str = "") -> HTMLResponse:
    """Back to the sheet with a one-shot outcome marker.

    The target is either the server-generated sheet URL for the dataset the
    route already resolved, or a `next` the caller supplied — and that one is
    passed through `_safe_ui_next_path`, so an absolute or foreign target
    degrades to the portal instead of being followed.
    """
    base = _safe_ui_next_path(next_path, default="") if next_path else ""
    if not base:
        base = f"/user/database/datasets/{quote(str(dataset_id))}"
    marker = {}
    if notice in PORTAL_DATABASE_SAVED_NOTICE_KEYS:
        marker[PORTAL_DATABASE_SAVED_NOTICE_PARAM] = notice
    if error in PORTAL_DATABASE_SAVED_ERROR_KEYS:
        marker[PORTAL_DATABASE_SAVED_ERROR_PARAM] = error
    if marker:
        separator = "&" if "?" in base else "?"
        base = base + separator + urlencode(marker)
    return _artifact_explorer_redirect(base)


def _portal_database_saved_object_context(
    user: dict, dataset_id: str, request: Request | None
) -> tuple[dict, list[dict], dict[str, list[str]]] | HTMLResponse:
    """Re-resolve dataset authorization and the approved columns, every time.

    This is the whole of rule 2 at the top of this section, in one place: no S13
    route trusts that a stored object's dataset is still readable, still active,
    still granted, or still has the columns the object names.
    """
    user_id = str(user.get("user_id") or "")
    dataset = _get_portal_database_dataset_for_user(dataset_id, user_id)
    if not dataset:
        _portal_audit_event_safe(
            event_type="database_dataset_access_denied",
            actor_user_id=user_id or None,
            request=request,
            metadata={"reason": "dataset_unavailable", "requested_dataset_id": str(dataset_id), "surface": "saved_object"},
        )
        return _portal_database_unavailable_response(user)
    columns = _get_portal_database_visible_columns(str(dataset.get("dataset_id") or dataset_id))
    if not columns:
        return _portal_database_invalid_view_response(user, dataset, reason="columns")
    params = _portal_database_query_params(request)
    for key in PORTAL_DATABASE_NON_STATE_PARAMS:
        params.pop(key, None)
    return dataset, columns, params


def _portal_database_saved_view_open_response(
    user: dict, dataset_id: str, saved_view_id: str, request: Request | None
) -> HTMLResponse:
    """`DB-001` chip and the row-sheet selector: open a saved view.

    Order: authenticate, re-authorize the dataset, resolve the object with the
    owner in the `WHERE`, re-parse the stored document, then emit a canonical
    URL. The redirect target is built by `_portal_database_url` from validated
    parameters, so it is always this route's own dataset on the Database
    Explorer path — a saved view can never become an open redirect, because no
    URL is ever stored and none is ever accepted.
    """
    context = _portal_database_saved_object_context(user, dataset_id, request)
    if isinstance(context, HTMLResponse):
        return context
    dataset, columns, _params = context
    user_id = str(user.get("user_id") or "")
    resolved_dataset_id = str(dataset.get("dataset_id") or dataset_id)
    if not _portal_preferences_schema_available():
        return _portal_database_saved_redirect(resolved_dataset_id, error="unavailable")
    saved = _get_portal_saved_view_for_user(saved_view_id, user_id, resolved_dataset_id)
    if not saved:
        # Identical for a view that never existed, a view belonging to another
        # account, and a malformed id. Nothing about another account's objects
        # is confirmed, denied or logged.
        _portal_audit_event_safe(
            event_type="database_saved_view_refused",
            actor_user_id=user_id or None,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=resolved_dataset_id,
            request=request,
            metadata={"object_type": "saved_view", "operation": "open", "outcome": "not_found"},
        )
        return _portal_database_saved_redirect(resolved_dataset_id, error="not_found")
    document = _portal_saved_state_document(saved.get("view_state_json"))
    if document is None:
        _portal_audit_event_safe(
            event_type="database_saved_view_refused",
            actor_user_id=user_id or None,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=resolved_dataset_id,
            request=request,
            metadata={"object_type": "saved_view", "operation": "open", "outcome": "malformed_state",
                      "saved_object_id": str(saved.get("saved_view_id") or "")},
        )
        return _portal_database_saved_redirect(resolved_dataset_id, error="stale")
    params, refusal = _portal_database_saved_view_params(dataset, columns, document)
    if params is None:
        _portal_audit_event_safe(
            event_type="database_saved_view_refused",
            actor_user_id=user_id or None,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=resolved_dataset_id,
            request=request,
            metadata={"object_type": "saved_view", "operation": "open", "outcome": str(refusal or "stale"),
                      "saved_object_id": str(saved.get("saved_view_id") or "")},
        )
        return _portal_database_saved_redirect(resolved_dataset_id, error=str(refusal or "stale"))
    params[PORTAL_DATABASE_SAVED_VIEW_PARAM] = [str(saved.get("saved_view_id") or "")]
    _portal_audit_event_safe(
        event_type="database_saved_view_opened",
        actor_user_id=user_id or None,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=resolved_dataset_id,
        request=request,
        metadata={
            "object_type": "saved_view",
            "operation": "open",
            "saved_object_id": str(saved.get("saved_view_id") or ""),
            "filter_count": len(document.get("filters") or []),
            "search_present": True if document.get("search") else None,
        },
    )
    return _artifact_explorer_redirect(_portal_database_url(resolved_dataset_id, params))


def _portal_database_save_view_response(
    user: dict, dataset_id: str, request: Request | None, *, view_name: str, next_path: str
) -> HTMLResponse:
    """`Zapisz jako widok` — create a named view from the current state."""
    context = _portal_database_saved_object_context(user, dataset_id, request)
    if isinstance(context, HTMLResponse):
        return context
    dataset, columns, params = context
    user_id = str(user.get("user_id") or "")
    resolved_dataset_id = str(dataset.get("dataset_id") or dataset_id)
    if not _portal_preferences_schema_available():
        return _portal_database_saved_redirect(resolved_dataset_id, error="unavailable", next_path=next_path)
    name, name_error = _portal_normalize_saved_object_name(view_name)
    if name_error:
        return _portal_database_saved_redirect(
            resolved_dataset_id, error=name_error.rsplit(".", 1)[-1], next_path=next_path
        )
    document, state_error = _portal_database_current_view_document(dataset, columns, params)
    if document is None:
        # The state the caller asked to save is state the sheet itself would
        # refuse to render. It is not stored, and the refusal message is the
        # generic one — the validator's text can name a column.
        return _portal_database_saved_redirect(resolved_dataset_id, error="state_invalid", next_path=next_path)
    encoded, encode_error = _portal_saved_state_json(document)
    if encoded is None:
        return _portal_database_saved_redirect(
            resolved_dataset_id, error=(encode_error or "db.saved.state_invalid").rsplit(".", 1)[-1], next_path=next_path
        )
    saved_id, outcome = _create_portal_saved_view(
        owner_user_id=user_id, dataset_id=resolved_dataset_id, view_name=name, state_json=encoded
    )
    _portal_audit_event_safe(
        event_type="database_saved_view_created" if outcome == "created" else "database_saved_view_refused",
        actor_user_id=user_id or None,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=resolved_dataset_id,
        request=request,
        metadata={
            "object_type": "saved_view",
            "operation": "create",
            "outcome": outcome,
            "saved_object_id": saved_id or None,
            "filter_count": len(document.get("filters") or []),
            "visible_column_count": len((document.get("layout") or {}).get("cols") or []),
        },
    )
    if outcome != "created":
        return _portal_database_saved_redirect(resolved_dataset_id, error=outcome, next_path=next_path)
    return _portal_database_saved_redirect(resolved_dataset_id, notice="view_created", next_path=next_path)


def _portal_database_update_view_response(
    user: dict, dataset_id: str, saved_view_id: str, request: Request | None, *, view_name: str, next_path: str
) -> HTMLResponse:
    """`Zapisz zmiany` — overwrite one owned view with the current state."""
    context = _portal_database_saved_object_context(user, dataset_id, request)
    if isinstance(context, HTMLResponse):
        return context
    dataset, columns, params = context
    user_id = str(user.get("user_id") or "")
    resolved_dataset_id = str(dataset.get("dataset_id") or dataset_id)
    if not _portal_preferences_schema_available():
        return _portal_database_saved_redirect(resolved_dataset_id, error="unavailable", next_path=next_path)
    saved = _get_portal_saved_view_for_user(saved_view_id, user_id, resolved_dataset_id)
    if not saved:
        _portal_audit_event_safe(
            event_type="database_saved_view_refused",
            actor_user_id=user_id or None,
            client_code=str(dataset.get("client_code") or "") or None,
            dataset_id=resolved_dataset_id,
            request=request,
            metadata={"object_type": "saved_view", "operation": "update", "outcome": "not_found"},
        )
        return _portal_database_saved_redirect(resolved_dataset_id, error="not_found", next_path=next_path)
    name, name_error = _portal_normalize_saved_object_name(view_name or saved.get("view_name"))
    if name_error:
        return _portal_database_saved_redirect(
            resolved_dataset_id, error=name_error.rsplit(".", 1)[-1], next_path=next_path
        )
    document, _state_error = _portal_database_current_view_document(dataset, columns, params)
    if document is None:
        return _portal_database_saved_redirect(resolved_dataset_id, error="state_invalid", next_path=next_path)
    encoded, encode_error = _portal_saved_state_json(document)
    if encoded is None:
        return _portal_database_saved_redirect(
            resolved_dataset_id, error=(encode_error or "db.saved.state_invalid").rsplit(".", 1)[-1], next_path=next_path
        )
    outcome = _update_portal_saved_view(
        saved_view_id=str(saved.get("saved_view_id") or ""),
        owner_user_id=user_id,
        dataset_id=resolved_dataset_id,
        view_name=name,
        state_json=encoded,
    )
    _portal_audit_event_safe(
        event_type="database_saved_view_updated" if outcome == "updated" else "database_saved_view_refused",
        actor_user_id=user_id or None,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=resolved_dataset_id,
        request=request,
        metadata={
            "object_type": "saved_view",
            "operation": "update",
            "outcome": outcome,
            "saved_object_id": str(saved.get("saved_view_id") or ""),
            "filter_count": len(document.get("filters") or []),
        },
    )
    if outcome != "updated":
        return _portal_database_saved_redirect(resolved_dataset_id, error=outcome, next_path=next_path)
    return _portal_database_saved_redirect(resolved_dataset_id, notice="view_updated", next_path=next_path)


