# ---------------------------------------------------------------------------
# I. Theme preference route response
# ---------------------------------------------------------------------------


def _portal_theme_wants_json(request: Request | None) -> bool:
    headers = getattr(request, "headers", None)
    if headers is None:
        return False
    try:
        accept = str(headers.get("accept") or "")
    except AttributeError:
        return False
    return "application/json" in accept.lower()


def _portal_theme_failure_response(user: dict, next_path: str, *, status_code: int) -> HTMLResponse:
    """The no-JavaScript failure page for a preference that was NOT stored.

    Deliberately a page rather than a silent redirect: `SH-8` promises the
    choice follows the account to another browser and another device, and a
    write that did not happen must not be presented as one that did.
    """
    safe_next = _safe_ui_next_path(next_path, default="/user")
    body = (
        '<section class="portal-panel">'
        f'<p class="portal-callout" role="alert">{_html(_tr("shell.theme.save_failed"))}</p>'
        f'<p><a class="portal-link" href="{_html(safe_next)}">{_html(_tr("db.catalog.back"))}</a></p>'
        "</section>"
    )
    return _portal_layout(
        _tr("shell.theme.group"),
        body,
        user=user,
        portal_label="User Portal",
        active_key="reports",
        nav_items=_portal_user_nav(),
        status_code=status_code,
    )


def _portal_theme_preference_response(
    user: dict, request: Request | None, *, theme: str, next_path: str
) -> HTMLResponse:
    """`D-011` / `SH-8`: persist the account theme override.

    The account is the session's, never a field: there is no owner parameter to
    forge, and a caller cannot address another account's preference at all.
    """
    user_id = str(user.get("user_id") or "")
    wants_json = _portal_theme_wants_json(request)
    normalized = _portal_normalize_theme(theme)
    if not normalized:
        _portal_audit_event_safe(
            event_type="portal_theme_preference_refused",
            actor_user_id=user_id or None,
            request=request,
            metadata={"outcome": "invalid_value"},
        )
        if wants_json:
            return _portal_json_response({"stored": False, "reason": "invalid"}, status_code=400)
        return _portal_theme_failure_response(user, next_path, status_code=400)
    stored = _set_portal_user_theme(user_id, normalized)
    _portal_audit_event_safe(
        event_type="portal_theme_preference_updated" if stored else "portal_theme_preference_refused",
        actor_user_id=user_id or None,
        request=request,
        metadata={"theme": normalized, "outcome": "stored" if stored else "not_stored"},
    )
    if wants_json:
        return _portal_json_response(
            {"stored": bool(stored), "theme": normalized}, status_code=200 if stored else 503
        )
    if not stored:
        return _portal_theme_failure_response(user, next_path, status_code=503)
    return _artifact_explorer_redirect(_safe_ui_next_path(next_path, default="/user"))


# ---------------- Endpoints ----------------
@app.get("/health")
def health():
    return {"ok": True}

@app.get("/secure/ping")
def secure_ping(authorization: str | None = Header(default=None)):
    require_token(authorization, "read")
    return {"ok": True, "mode": "read"}

# ---- Runs ----
#: P1-I. Once a run reaches one of these, its outcome is history. See
#: `update_run` for why re-terminalizing to a *different* one is refused.
TERMINAL_RUN_STATUSES = frozenset({"SUCCESS", "FAILED", "CANCELED"})


@app.patch("/runs/{run_id}")
def update_run(
    run_id: str,
    authorization: str | None = Header(default=None),
    status: str = Body(..., embed=True),
):
    """Move one run's lifecycle state.

    P1-I. Terminalization is one-way. The endpoint previously issued a bare
    `UPDATE runs SET status=...`, so any later call silently rewrote a settled
    outcome — a retry, a stray operator call, or a duplicated finalization
    could turn a recorded FAILED into SUCCESS with nothing left to show it had
    ever failed. `public.runs` is the record the watchdog and the operator
    tooling trust, so it must not be quietly rewritable.

    Re-sending the status a run already holds stays a success, because
    finalization is retried by clients and an idempotent repeat is not a
    conflict. Changing one terminal state into another is a 409 and leaves the
    row untouched.

    The compare-and-set lives in the UPDATE's own WHERE clause rather than in a
    read-then-write, so two concurrent finalizations cannot both observe
    RUNNING and both proceed.
    """
    require_token(authorization, "write")
    status = (status or "").upper()
    if status not in ALLOWED_RUN_STATUSES:
        raise HTTPException(status_code=400, detail=f"Invalid status: {status}")

    now = utcnow()

    with db_conn() as conn:
        with conn.cursor() as cur:
            if status in TERMINAL_RUN_STATUSES:
                cur.execute(
                    """
                    UPDATE runs SET status=%s, ended_at=%s
                    WHERE run_id=%s
                      AND (status IS NULL OR status NOT IN ('SUCCESS','FAILED','CANCELED') OR status=%s)
                    RETURNING run_id, status, ended_at
                    """,
                    (status, now, run_id, status),
                )
            else:
                cur.execute(
                    """
                    UPDATE runs SET status=%s
                    WHERE run_id=%s
                      AND (status IS NULL OR status NOT IN ('SUCCESS','FAILED','CANCELED'))
                    RETURNING run_id, status, ended_at
                    """,
                    (status, run_id),
                )
            row = cur.fetchone()
            if not row:
                # Either the run does not exist, or it is already terminal in a
                # state this call would have changed. Distinguish the two so an
                # operator is not told "not found" about a run that is right
                # there with a settled outcome.
                cur.execute("SELECT status FROM runs WHERE run_id=%s", (run_id,))
                existing = cur.fetchone()
                if existing:
                    current_status = (
                        existing["status"] if isinstance(existing, dict) else existing[0]
                    )
                    conn.rollback()
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            f"Run {run_id} is already terminal ({current_status}); "
                            f"refusing to overwrite it with {status}"
                        ),
                    )
        conn.commit()

    if not row:
        raise HTTPException(status_code=404, detail="run_id not found")

    return {"ok": True, **row}



@app.post("/runs")
def create_run(
    trigger: str = Form(...),
    source: str = Form(...),
    actor: Optional[str] = Form(None),
    params_json: str = Form("{}"),
    authorization: str | None = Header(default=None),
):
    require_token(authorization, "write")

    run_id = uuid.uuid4()
    started_at = utcnow()
    try:
        params = json.loads(params_json or "{}")
    except Exception:
        raise HTTPException(status_code=400, detail="params_json must be valid JSON")

    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO runs(run_id, started_at, status, trigger, source, actor, params)
                VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb)
                """,
                (run_id, started_at, "RUNNING", trigger, source, actor, json.dumps(params)),
            )
        conn.commit()

    return {"run_id": str(run_id), "started_at": started_at.isoformat(), "status": "RUNNING"}

# P1-I. A second `@app.patch("/runs/{run_id}")` used to live here. FastAPI
# resolves to the first matching route, so `update_run` above always served
# this path and this handler was unreachable — which was the only thing keeping
# it harmless. It took `status` as a form field with no membership check
# against ALLOWED_RUN_STATUSES and no terminal-state guard, so had route order
# ever changed, any string could have been written into `runs.status` and any
# settled outcome silently overwritten. Removed rather than fixed: one route,
# one contract.

@app.get("/runs")
def list_runs(
    authorization: str | None = Header(default=None),
    source: Optional[str] = None,
    status: Optional[str] = None,
    trigger: Optional[str] = None,
    actor: Optional[str] = None,
    limit: int = Query(100, ge=1, le=500),
):
    require_token(authorization, "read")

    where = []
    params = []
    if source:
        where.append("source=%s"); params.append(source)
    if status:
        where.append("status=%s"); params.append(status)
    if trigger:
        where.append("trigger=%s"); params.append(trigger)
    if actor:
        where.append("actor=%s"); params.append(actor)

    sql = "SELECT * FROM runs"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY started_at DESC LIMIT %s"
    params.append(limit)

    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, params)
            rows = cur.fetchall()

    # stringify UUID for JSON response
    for r in rows:
        r["run_id"] = str(r["run_id"])
    return {"items": rows}


@app.get("/runs")
def list_runs(
    authorization: str | None = Header(default=None),
    source: str | None = None,
    status: str | None = None,
    from_ts: str | None = None,
    to_ts: str | None = None,
    limit: int = 200,
):
    require_token(authorization, "read")
    limit = max(1, min(int(limit), 1000))

    where = []
    params = {}

    if source:
        where.append("source = %(source)s")
        params["source"] = source

    if status:
        where.append("status = %(status)s")
        params["status"] = status.upper()

    if from_ts:
        where.append("started_at >= %(from_ts)s")
        params["from_ts"] = from_ts

    if to_ts:
        where.append("started_at <= %(to_ts)s")
        params["to_ts"] = to_ts

    sql = "SELECT run_id, started_at, ended_at, status, trigger, source, actor, params FROM runs"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY started_at DESC LIMIT %(limit)s"
    params["limit"] = limit

    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, params)
            rows = cur.fetchall()

    return {"items": rows, "limit": limit}



# ---- Logs ----
@app.post("/logs")
def append_log(
    ts: Optional[str] = Form(None),
    level: str = Form(...),
    type: str = Form(...),  # SYSTEM or SCRIPT
    source: str = Form(...),
    message: str = Form(...),
    run_id: Optional[str] = Form(None),
    context_json: str = Form("{}"),
    error: Optional[str] = Form(None),
    authorization: str | None = Header(default=None),
):
    require_token(authorization, "write")

    dt = parse_iso_ts(ts) if ts else utcnow()
    try:
        context = json.loads(context_json or "{}")
    except Exception:
        raise HTTPException(status_code=400, detail="context_json must be valid JSON")
    if not isinstance(context, dict):
        context = {"context_value": context}
    for key, value in business_time_log_context(dt).items():
        context.setdefault(key, value)

    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO logs(ts, level, type, source, run_id, message, context, error)
                VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb, %s)
                RETURNING id
                """,
                (dt, level, type, source, run_id, message, json.dumps(context), error),
            )
            row = cur.fetchone()
        conn.commit()

    return {
        "id": row["id"],
        "ts": dt.isoformat(),
        "timestamp_local": format_business_timestamp(dt),
        "timezone": get_business_timezone_name(),
    }

@app.get("/logs")
def query_logs(
    authorization: str | None = Header(default=None),
    from_ts: Optional[str] = Query(None, alias="from"),
    to_ts: Optional[str] = Query(None, alias="to"),
    type: Optional[str] = None,
    level: Optional[str] = None,
    source: Optional[str] = None,
    run_id: Optional[str] = None,
    q: Optional[str] = None,
    limit: int = Query(200, ge=1, le=1000),
):
    require_token(authorization, "read")

    where = []
    params = []

    if from_ts:
        where.append("ts >= %s"); params.append(parse_iso_ts(from_ts))
    if to_ts:
        where.append("ts <= %s"); params.append(parse_iso_ts(to_ts))
    if type:
        where.append("type=%s"); params.append(type)
    if level:
        where.append("level=%s"); params.append(level)
    if source:
        where.append("source=%s"); params.append(source)
    if run_id:
        where.append("run_id=%s"); params.append(run_id)
    if q:
        where.append("(message ILIKE %s)"); params.append(f"%{q}%")

    sql = """
      SELECT id, ts, level, type, source, run_id, message, context, error
      FROM logs
    """
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY ts DESC LIMIT %s"
    params.append(limit)

    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, params)
            rows = cur.fetchall()

    for r in rows:
        if r["run_id"] is not None:
            r["run_id"] = str(r["run_id"])
    return {"items": rows}


# ---- Suspected bugs ----
@app.post("/suspected-bugs")
def report_suspected_bug_event(
    event_json: str = Form(...),
    authorization: str | None = Header(default=None),
):
    """Durable suspected_bug ingestion boundary.

    Writes the ERROR log (context.classification = suspected_bug), upserts the
    incident, appends the occurrence and enqueues at most one alert email — all in
    one transaction. Alert recipients and cooldown come from this process' own
    configuration; no recipient fallback exists.
    """
    require_token(authorization, "write")

    try:
        data = json.loads(event_json or "{}")
    except Exception:
        raise HTTPException(status_code=400, detail="event_json must be valid JSON")
    if not isinstance(data, dict):
        raise HTTPException(status_code=400, detail="event_json must be a JSON object")

    try:
        event = SuspectedBugEvent.from_dict(data)
        event.validate()
    except SuspectedBugContractError as exc:
        raise HTTPException(status_code=400, detail=str(exc))

    with db_conn() as conn:
        result = report_suspected_bug(conn, event)
    return result.to_dict()


# ---- Artifacts ----
_IDEMPOTENCY_FINGERPRINT_FIELDS = (
    "sha256", "kind", "content_type", "workflow_name", "stage_name",
    "artifact_role", "report_type", "client_code", "raw_file_id", "layout_version",
)


def _artifact_idempotency_compatible(existing: dict, expected: dict) -> bool:
    return all(existing[name] == expected[name] for name in _IDEMPOTENCY_FINGERPRINT_FIELDS)


@app.post("/artifacts/upload")
async def upload_artifact(
    authorization: str | None = Header(default=None),
    file: UploadFile = File(...),
    kind: str = Form("REPORT"),
    run_id: Optional[str] = Form(None),
    raw_file_id: Optional[str] = Form(None),
    workflow_name: Optional[str] = Form(None),
    stage_name: Optional[str] = Form(None),
    artifact_role: Optional[str] = Form(None),
    report_type: Optional[str] = Form(None),
    client_code: Optional[str] = Form(None),
    original_filename: Optional[str] = Form(None),
    display_filename: Optional[str] = Form(None),
    metadata_json: str = Form("{}"),
    idempotency_scope: Optional[str] = Form(None),
    idempotency_key: Optional[str] = Form(None),
):
    require_token(authorization, "write")

    if (idempotency_scope is None) != (idempotency_key is None):
        raise HTTPException(status_code=422, detail="idempotency_scope and idempotency_key must be supplied together")
    if idempotency_scope is not None:
        if not idempotency_scope.strip() or not idempotency_key.strip():
            raise HTTPException(status_code=422, detail="idempotency_scope and idempotency_key must not be blank")
        if len(idempotency_scope) > 128 or len(idempotency_key) > 256:
            raise HTTPException(status_code=422, detail="idempotency_scope or idempotency_key exceeds maximum length")

    try:
        metadata = json.loads(metadata_json or "{}")
    except Exception:
        raise HTTPException(status_code=400, detail="metadata_json must be valid JSON")
    if not isinstance(metadata, dict):
        raise HTTPException(status_code=400, detail="metadata_json must be a JSON object")

    raw_file_uuid: Optional[str] = None
    if raw_file_id is not None and raw_file_id.strip():
        try:
            raw_file_uuid = uuid.UUID(raw_file_id.strip())
        except ValueError:
            raise HTTPException(status_code=400, detail="raw_file_id must be a valid UUID")
        with db_conn() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT 1 FROM ingest.raw_file WHERE id = %s", (raw_file_uuid,))
                if cur.fetchone() is None:
                    raise HTTPException(status_code=400, detail="raw_file_id not found in ingest.raw_file")
        raw_file_uuid = str(raw_file_uuid)

    artifact_id = uuid.uuid4()
    created_at = utcnow()
    for key, value in business_time_log_context(created_at).items():
        metadata.setdefault(key, value)
    uploaded_filename = file.filename or "artifact"
    source_filename = original_filename or uploaded_filename
    ext = os.path.splitext(uploaded_filename)[1].lstrip(".")
    if not ext:
        ext = os.path.splitext(source_filename)[1].lstrip(".") or "bin"
    workflow_component = sanitize_artifact_component(workflow_name or UNKNOWN_WORKFLOW_NAME)
    stage_component = sanitize_artifact_component(stage_name or UNKNOWN_STAGE_NAME)
    role_component = sanitize_artifact_component(artifact_role or DEFAULT_ARTIFACT_ROLE)
    report_component = sanitize_artifact_component(report_type or UNKNOWN_REPORT_TYPE)
    client_code_value = client_code.strip() if client_code is not None and client_code.strip() else None
    display_name = sanitize_artifact_display_filename(
        display_filename
        or build_artifact_display_filename(
            report_type=report_component,
            created_at=created_at,
            raw_file_id=raw_file_uuid,
            artifact_role=role_component,
            ext=ext,
        ),
        ext,
    )
    storage_key = build_artifact_object_key(
        workflow_name=workflow_component,
        stage_name=stage_component,
        run_id=run_id or str(artifact_id),
        artifact_role=role_component,
        ext=ext,
        created_at=created_at,
        report_type=report_component if report_component != UNKNOWN_REPORT_TYPE else None,
        raw_file_id=raw_file_uuid,
        display_filename=display_name,
    )

    # Stream file into memory in chunks to compute hash and upload
    sha = hashlib.sha256()
    size = 0

    # We will upload to S3 using multipart-friendly approach: read all bytes is risky for 500MB.
    # Here: we stream into a temp file inside container.
    import tempfile
    with tempfile.NamedTemporaryFile(delete=True) as tmp:
        while True:
            chunk = await file.read(8 * 1024 * 1024)  # 8MB
            if not chunk:
                break
            tmp.write(chunk)
            sha.update(chunk)
            size += len(chunk)
        tmp.flush()
        sha256_hex = sha.hexdigest()
        content_type = file.content_type or "application/octet-stream"
        if idempotency_scope is not None:
            storage_key = build_idempotent_artifact_object_key(idempotency_scope, idempotency_key, ext)

        with db_conn() as conn:
            with conn.cursor() as cur:
                expected = None
                lock_digest = None
                if idempotency_scope is not None:
                    lock_digest = hashlib.sha256(f"{idempotency_scope}\0{idempotency_key}".encode()).digest()
                    lock_key = int.from_bytes(lock_digest[:8], "big", signed=True)
                    cur.execute("SELECT pg_advisory_xact_lock(%s)", (lock_key,))
                    cur.execute(
                        """SELECT * FROM artifacts
                             WHERE idempotency_scope = %s AND idempotency_key = %s""",
                        (idempotency_scope, idempotency_key),
                    )
                    existing = cur.fetchone()
                    expected = {
                        "sha256": sha256_hex, "kind": kind, "content_type": content_type,
                        "workflow_name": workflow_component, "stage_name": stage_component,
                        "artifact_role": role_component, "report_type": report_component,
                        "client_code": client_code_value,
                        "raw_file_id": uuid.UUID(raw_file_uuid) if raw_file_uuid else None,
                        "layout_version": LAYOUT_VERSION,
                    }
                    if existing is not None:
                        if not _artifact_idempotency_compatible(existing, expected):
                            print(f"artifact idempotency conflict scope={idempotency_scope} correlation={lock_digest.hex()[:12]}")
                            raise HTTPException(status_code=409, detail="Idempotency identity is already used by an incompatible artifact")
                        print(f"artifact idempotency reused artifact_id={existing['artifact_id']} scope={idempotency_scope} correlation={lock_digest.hex()[:12]}")
                        return {"artifact_id": str(existing["artifact_id"]), "idempotency_status": "reused"}

                s3.upload_file(tmp.name, MINIO_BUCKET, storage_key)
                cur.execute("SAVEPOINT artifact_idempotency_insert")
                try:
                    cur.execute(
                        """
                        INSERT INTO artifacts(artifact_id, run_id, created_at, kind, filename, content_type,
                                             size_bytes, sha256, storage_backend, storage_key, raw_file_id,
                                             workflow_name, stage_name, artifact_role, report_type, client_code,
                                             display_filename, original_filename, file_ext,
                                             layout_version, metadata_json, idempotency_scope, idempotency_key)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                                %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                        """,
                        (
                            artifact_id, run_id, created_at, kind, display_name, content_type,
                            size, sha256_hex, "S3", storage_key, raw_file_uuid,
                            workflow_component, stage_component, role_component, report_component,
                            client_code_value, display_name, source_filename, ext.lower(),
                            LAYOUT_VERSION, json.dumps(metadata), idempotency_scope, idempotency_key,
                        ),
                    )
                except psycopg.errors.UniqueViolation:
                    cur.execute("ROLLBACK TO SAVEPOINT artifact_idempotency_insert")
                    if idempotency_scope is None:
                        raise
                    cur.execute(
                        """SELECT * FROM artifacts
                             WHERE idempotency_scope = %s AND idempotency_key = %s""",
                        (idempotency_scope, idempotency_key),
                    )
                    existing = cur.fetchone()
                    if existing is not None and expected is not None and _artifact_idempotency_compatible(existing, expected):
                        print(f"artifact idempotency reused artifact_id={existing['artifact_id']} scope={idempotency_scope} correlation={lock_digest.hex()[:12]}")
                        return {"artifact_id": str(existing["artifact_id"]), "idempotency_status": "reused"}
                    raise HTTPException(status_code=409, detail="Idempotency identity is already used by an incompatible artifact")
                finally:
                    cur.execute("RELEASE SAVEPOINT artifact_idempotency_insert")
            conn.commit()

    result = {
        "artifact_id": str(artifact_id),
        "run_id": run_id,
        "created_at": created_at.isoformat(),
        "created_at_local": format_business_timestamp(created_at),
        "timezone": get_business_timezone_name(),
        "filename": display_name,
        "display_filename": display_name,
        "original_filename": source_filename,
        "size_bytes": size,
        "sha256": sha256_hex,
        "storage_key": storage_key,
        "workflow_name": workflow_component,
        "stage_name": stage_component,
        "artifact_role": role_component,
        "report_type": report_component,
        "client_code": client_code_value,
        "layout_version": LAYOUT_VERSION,
        "idempotency_status": "created",
    }
    if raw_file_uuid is not None:
        result["raw_file_id"] = raw_file_uuid
    return result

@app.get("/artifacts")
def list_artifacts(
    authorization: str | None = Header(default=None),
    run_id: Optional[str] = None,
    kind: Optional[str] = None,
    limit: int = Query(100, ge=1, le=500),
):
    require_token(authorization, "read")

    where = []
    params = []
    if run_id:
        where.append("run_id=%s"); params.append(run_id)
    if kind:
        where.append("kind=%s"); params.append(kind)

    sql = "SELECT * FROM artifacts"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY created_at DESC LIMIT %s"
    params.append(limit)

    with db_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, params)
            rows = cur.fetchall()

    for r in rows:
        r["artifact_id"] = str(r["artifact_id"])
        if r["run_id"] is not None:
            r["run_id"] = str(r["run_id"])
        if r.get("raw_file_id") is not None:
            r["raw_file_id"] = str(r["raw_file_id"])
    return {"items": rows}


