@app.post("/artifact-browser/virtual-folders")
def artifact_browser_create_virtual_folder(
    payload: dict = Body(...),
    authorization: str | None = Header(default=None),
):
    require_token(authorization, "write")
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="request body must be a JSON object")
    if "folder_name" not in payload:
        raise HTTPException(status_code=400, detail="folder_name is required")
    description = payload.get("description")
    if description is not None and not isinstance(description, str):
        raise HTTPException(status_code=400, detail="description must be a string or null")
    folder_type = payload.get("folder_type", "manual")
    search_query_json = payload.get("search_query_json", _UNSET)
    if folder_type == "manual" and search_query_json is _UNSET:
        search_payload = None
    else:
        search_payload = {} if search_query_json is _UNSET else search_query_json
    return _create_virtual_folder(
        parent_folder_id=payload.get("parent_folder_id"),
        folder_name=payload.get("folder_name"),
        description=description,
        folder_type=folder_type,
        search_query_json=search_payload,
        actor=_write_actor_from_token(),
    )


