@app.get("/artifact-browser/artifacts/{artifact_id}/preview")
def artifact_browser_preview_artifact(
    artifact_id: str,
    authorization: str | None = Header(default=None),
    rows_limit: Optional[int] = Query(None, ge=1, le=5000),
    sheet_name: Optional[str] = None,
    sheet_index: Optional[int] = Query(None, ge=0),
    text_chars_limit: Optional[int] = Query(None, ge=1, le=100000),
):
    require_token(authorization, "read")
    row = _get_artifact_browser_row(artifact_id)
    if not row:
        raise HTTPException(status_code=404, detail="artifact not found")

    artifact = _artifact_browser_row(row)
    ext = infer_preview_ext(artifact)
    if ext == "pdf":
        _ensure_artifact_object_exists(row)
        try:
            return build_preview(
                artifact,
                None,
                rows_limit=rows_limit,
                sheet_name=sheet_name,
                sheet_index=sheet_index,
                text_chars_limit=text_chars_limit,
            )
        except ArtifactPreviewError as exc:
            raise HTTPException(status_code=exc.status_code, detail=exc.detail)

    size_bytes = artifact.get("size_bytes")
    if size_bytes is not None and int(size_bytes) > ARTIFACT_PREVIEW_MAX_BYTES:
        return file_too_large_response(artifact, max_preview_bytes=ARTIFACT_PREVIEW_MAX_BYTES)

    data = _read_artifact_preview_bytes(row, max_bytes=ARTIFACT_PREVIEW_MAX_BYTES)
    if len(data) > ARTIFACT_PREVIEW_MAX_BYTES:
        artifact["size_bytes"] = size_bytes if size_bytes is not None else len(data)
        return file_too_large_response(artifact, max_preview_bytes=ARTIFACT_PREVIEW_MAX_BYTES)

    try:
        return build_preview(
            artifact,
            data,
            rows_limit=rows_limit,
            sheet_name=sheet_name,
            sheet_index=sheet_index,
            text_chars_limit=text_chars_limit,
        )
    except ArtifactPreviewError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail)


@app.get("/artifact-browser/artifacts/{artifact_id}/download")
def artifact_browser_download_artifact(
    artifact_id: str,
    authorization: str | None = Header(default=None),
    disposition: str = Query("attachment"),
):
    require_token(authorization, "read")
    if disposition not in {"attachment", "inline"}:
        raise HTTPException(status_code=400, detail="disposition must be attachment or inline")
    row = _get_artifact_browser_row(artifact_id)
    if not row:
        raise HTTPException(status_code=404, detail="artifact not found")
    return _stream_artifact_download(row, disposition=disposition)


