@app.get("/user/reports/artifacts/{artifact_id}/download")
def user_portal_report_artifact_download(
    artifact_id: str,
    request: Request,
    folder_id: str = Query(...),
    disposition: str = Query("attachment"),
):
    user = _require_portal_user(request)
    if isinstance(user, HTMLResponse):
        return user
    if disposition not in {"attachment", "inline"}:
        raise HTTPException(status_code=400, detail="disposition must be attachment or inline")
    access = _portal_report_artifact_access(user, folder_id, artifact_id, action="download")
    if not access:
        _portal_audit_event_safe(
            event_type="report_artifact_download_denied",
            actor_user_id=str(user.get("user_id") or "") or None,
            report_folder_id=folder_id,
            artifact_id=artifact_id,
            request=request,
            metadata={"reason": "artifact_or_folder_unavailable", "folder_id": folder_id, "artifact_id": artifact_id},
        )
        raise HTTPException(status_code=403, detail="report download access denied")
    folder, row, artifact = access
    _portal_audit_event_safe(
        event_type="report_artifact_download_success",
        actor_user_id=str(user.get("user_id") or "") or None,
        client_code=str(folder.get("client_code") or "") or None,
        report_folder_id=str(folder.get("folder_id") or "") or None,
        artifact_id=artifact_id,
        request=request,
        metadata=_portal_report_audit_metadata(folder, artifact_id=artifact_id, report_type=artifact.get("report_type"), file_ext=artifact.get("file_ext"), disposition=disposition),
    )
    return _stream_artifact_download(row, disposition=disposition)


