@app.post("/user/database/exports/{job_id}/cancel")
def user_portal_database_export_cancel(job_id: str, request: Request):
    """`Anuluj` on a queued or generating export (`DB-007`).

    Ownership is the WHERE clause, not a pre-check: another user's job simply
    matches no row, so a guessed job id is indistinguishable from a missing one.
    """
    user = _require_portal_user(request)
    if isinstance(user, HTMLResponse):
        return user
    if not _database_export_schema_available():
        return _database_export_schema_unavailable_response(user)
    user_id = str(user.get("user_id") or "")
    outcome = _cancel_database_export_job_for_user(job_id, user_id)
    _portal_audit_event_safe(
        event_type="database_export_job_cancelled" if outcome == "cancelled" else "database_export_cancel_refused",
        actor_user_id=user_id or None,
        request=request,
        metadata={"job_id": str(job_id), "outcome": outcome},
    )
    if outcome == "cancelled":
        query = urlencode({"export_job_cancelled": str(job_id)})
    elif outcome == "not_cancellable":
        query = urlencode({"export_cancel_refused": "1"})
    else:
        query = ""
    return _artifact_explorer_redirect("/user/database/exports" + (f"?{query}" if query else ""))


@app.post("/user/database/exports/{job_id}/requeue")
def user_portal_database_export_requeue(job_id: str, request: Request):
    """`Zleć ponownie` on a failed or expired export (`DB-007`).

    Re-authorizes from scratch — an account that lost `can_export_rows` or its
    dataset grant since the original export cannot requeue it — and recounts, so
    a stored snapshot cannot carry a scope past today's hard ceiling.
    """
    user = _require_portal_user(request)
    if isinstance(user, HTMLResponse):
        return user
    if not _database_export_schema_available():
        return _database_export_schema_unavailable_response(user)
    new_job_id, outcome = _requeue_database_export_job_for_user(user, job_id, request)
    if outcome != "requeued":
        _portal_audit_event_safe(
            event_type="database_export_requeue_refused",
            actor_user_id=str(user.get("user_id") or "") or None,
            request=request,
            metadata={"job_id": str(job_id), "outcome": outcome},
        )
        query = urlencode({"export_requeue_refused": "1"})
        return _artifact_explorer_redirect(f"/user/database/exports?{query}")
    query = urlencode({"export_job_requeued": str(new_job_id)})
    return _artifact_explorer_redirect(f"/user/database/exports?{query}")


@app.post("/user/database/datasets/{dataset_id}/exports")
def user_portal_database_dataset_enqueue_export(
    dataset_id: str,
    request: Request,
    format_name: str = Form(...),
    row_scope: str = Form(PORTAL_DATABASE_EXPORT_DEFAULT_ROW_SCOPE),
    column_scope: str = Form(PORTAL_DATABASE_EXPORT_DEFAULT_COLUMN_SCOPE),
    row_ref: list[str] = Form([]),
):
    user = _require_portal_user(request)
    if isinstance(user, HTMLResponse):
        params = _portal_database_query_params(request)
        _portal_audit_event_safe(
            event_type="database_export_denied",
            request=request,
            metadata_json=_portal_database_export_metadata(
                format_name=format_name or "unknown",
                row_limit=PORTAL_DATABASE_ASYNC_EXPORT_ROW_CAP,
                row_count=None,
                params=params,
                reason="unauthenticated",
                requested_dataset_id=dataset_id,
            ),
        )
        query = urlencode({key: values for key, values in params.items() if values}, doseq=True)
        next_path = f"/user/database/datasets/{quote(str(dataset_id), safe='')}" + (f"?{query}" if query else "")
        return _artifact_explorer_redirect(_artifact_explorer_login_url(next_path))
    return _portal_database_enqueue_export_response(
        user,
        dataset_id,
        request,
        format_name=format_name,
        row_scope=row_scope,
        column_scope=column_scope,
        row_references=list(row_ref or []),
    )


