@app.post("/admin/users/new")
def admin_portal_create_user(
    request: Request,
    username: str = Form(...),
    password: str = Form(...),
    confirm_password: str = Form(...),
    display_name: Optional[str] = Form(None),
    is_admin: Optional[str] = Form(None),
    role_ids: Optional[List[str]] = Form(None),
):
    user = _require_portal_admin(request)
    if isinstance(user, HTMLResponse):
        return user
    normalized_username = _normalize_portal_username(username)
    selected_role_ids = _portal_role_ids(role_ids)
    values = {
        "username": normalized_username,
        "display_name": display_name,
        "is_admin": is_admin,
        "role_ids": selected_role_ids,
    }
    roles = _list_portal_roles()
    if not normalized_username:
        return _portal_user_form_response(user, values=values, roles=roles, error="Username is required.", status_code=400)
    if not str(password or ""):
        return _portal_user_form_response(user, values=values, roles=roles, error="Password is required.", status_code=400)
    if password != confirm_password:
        return _portal_user_form_response(user, values=values, roles=roles, error="Password confirmation does not match.", status_code=400)
    if _portal_username_exists(normalized_username):
        return _portal_user_form_response(user, values=values, roles=roles, error="Username already exists.", status_code=400)
    try:
        new_user_id = _create_portal_user(
            username=normalized_username,
            display_name=display_name,
            password_hash=hash_artifact_password(password),
            is_admin=_portal_form_checked(is_admin),
            role_ids=selected_role_ids,
        )
    except ValueError as exc:
        return _portal_user_form_response(user, values=values, roles=roles, error=str(exc), status_code=400)
    _portal_audit_event_safe(
        event_type="admin_user_created",
        actor_user_id=str(user.get("user_id") or "") or None,
        request=request,
        metadata={"target_user_id": new_user_id, "target_username": normalized_username, "is_admin": _portal_form_checked(is_admin), "role_ids": selected_role_ids},
    )
    if _portal_form_checked(is_admin):
        _portal_audit_event_safe(
            event_type="admin_user_admin_flag_changed",
            actor_user_id=str(user.get("user_id") or "") or None,
            request=request,
            metadata={"target_user_id": new_user_id, "target_username": normalized_username, "is_admin": True},
        )
    return _artifact_explorer_redirect(f"/admin/users/{new_user_id}")


