@app.post("/admin/client-access/clients/new")
def admin_portal_create_client(
    request: Request,
    client_code: str = Form(...),
    display_name: str = Form(...),
    description: Optional[str] = Form(None),
    database_name: Optional[str] = Form(None),
    is_active: Optional[str] = Form(None),
):
    user = _require_portal_admin(request)
    if isinstance(user, HTMLResponse):
        return user
    normalized_code = _normalize_portal_client_code(client_code)
    values = {
        "client_code": normalized_code,
        "display_name": display_name,
        "description": description,
        "database_name": _normalize_portal_database_identifier(database_name),
        "is_active": _portal_form_checked(is_active),
    }
    error = _validate_portal_client_code(normalized_code)
    if error:
        return _portal_client_form_response(user, values=values, error=error, status_code=400)
    if not str(display_name or "").strip():
        return _portal_client_form_response(user, values=values, error="Display name is required.", status_code=400)
    database_error = _validate_portal_client_database_name(values["database_name"])
    if database_error:
        return _portal_client_form_response(user, values=values, error=database_error, status_code=400)
    if _portal_client_exists(normalized_code):
        return _portal_client_form_response(user, values=values, error="Client code already exists.", status_code=400)
    try:
        created_code = _create_portal_client(
            client_code=normalized_code,
            display_name=display_name,
            description=description,
            database_name=values["database_name"],
            is_active=_portal_form_checked(is_active),
        )
    except ValueError as exc:
        return _portal_client_form_response(user, values=values, error=str(exc), status_code=400)
    _portal_audit_event_safe(
        event_type="portal_client_created",
        actor_user_id=str(user.get("user_id") or "") or None,
        client_code=created_code,
        request=request,
        metadata={"client_code": created_code, "display_name": str(display_name or "").strip(), "database_name": values["database_name"] or None, "is_active": _portal_form_checked(is_active)},
    )
    return _artifact_explorer_redirect(f"/admin/client-access/clients/{created_code}")


