@app.post("/admin/client-access/database/{dataset_id}")
def admin_portal_update_database_dataset(
    dataset_id: str,
    request: Request,
    client_code: str = Form(...),
    dataset_name: str = Form(...),
    slug: str = Form(...),
    description: Optional[str] = Form(None),
    schema_name: str = Form(""),
    table_name: str = Form(""),
    schema_name_manual: Optional[str] = Form(None),
    table_name_manual: Optional[str] = Form(None),
    default_date_column: Optional[str] = Form(None),
    is_active: Optional[str] = Form(None),
):
    user = _require_portal_admin(request)
    if isinstance(user, HTMLResponse):
        return user
    dataset = _get_portal_database_dataset(dataset_id)
    if not dataset:
        return _portal_database_dataset_not_found_response(user)
    resolved_schema = _portal_database_resolve_selector_value(schema_name, schema_name_manual)
    resolved_table = _portal_database_resolve_selector_value(table_name, table_name_manual)
    values = dict(dataset)
    values.update({
        "client_code": _normalize_portal_client_code(client_code),
        "dataset_name": dataset_name,
        "slug": str(slug or "").strip().lower(),
        "description": description,
        "schema_name": _normalize_portal_database_identifier(resolved_schema),
        "table_name": _normalize_portal_database_identifier(resolved_table),
        "schema_name_manual": schema_name_manual,
        "table_name_manual": table_name_manual,
        "default_date_column": _normalize_portal_database_identifier(default_date_column),
        "is_active": _portal_form_checked(is_active),
    })
    error = _update_portal_database_dataset(
        dataset_id=dataset_id,
        client_code=values["client_code"],
        dataset_name=dataset_name,
        slug=values["slug"],
        description=description,
        schema_name=values["schema_name"],
        table_name=values["table_name"],
        default_date_column=values["default_date_column"],
        is_active=values["is_active"],
        actor_user_id=str(user.get("user_id") or "") or None,
    )
    if error:
        return _portal_database_dataset_form_response(user, dataset=dataset, values=values, error=error, status_code=400, request=request)
    changed_fields = _portal_changed_fields(dataset, values, ["client_code", "dataset_name", "slug", "description", "schema_name", "table_name", "default_date_column", "is_active"])
    _portal_audit_event_safe(
        event_type="database_dataset_updated",
        actor_user_id=str(user.get("user_id") or "") or None,
        client_code=values["client_code"],
        dataset_id=dataset_id,
        request=request,
        metadata=_portal_database_audit_metadata(values, changed_fields=changed_fields),
    )
    return _artifact_explorer_redirect(f"/admin/client-access/database/{dataset_id}")


