@app.post("/admin/client-access/database/{dataset_id}/columns")
def admin_portal_save_database_dataset_column(
    dataset_id: str,
    request: Request,
    column_name: str = Form(...),
    display_name: str = Form(...),
    data_type: Optional[str] = Form(None),
    display_order: int = Form(100),
    is_visible: Optional[str] = Form(None),
    is_filterable: Optional[str] = Form(None),
    is_sortable: Optional[str] = Form(None),
    is_default_date_column: Optional[str] = Form(None),
):
    user = _require_portal_admin(request)
    if isinstance(user, HTMLResponse):
        return user
    dataset = _get_portal_database_dataset(dataset_id)
    if not dataset:
        return _portal_database_dataset_not_found_response(user)
    normalized_column = _normalize_portal_database_identifier(column_name)
    try:
        existing_column = next((column for column in _list_portal_database_dataset_columns(dataset_id) if column.get("column_name") == normalized_column), None)
    except Exception as exc:
        print(f"portal audit column metadata lookup failed: {type(exc).__name__}: {exc}")
        existing_column = None
    error = _upsert_portal_database_dataset_column(
        dataset_id=dataset_id,
        column_name=column_name,
        display_name=display_name,
        data_type=_normalize_portal_database_data_type(data_type) if data_type and str(data_type).strip() else None,
        is_visible=_portal_form_checked(is_visible),
        is_filterable=_portal_form_checked(is_filterable),
        is_sortable=_portal_form_checked(is_sortable),
        is_default_date_column=_portal_form_checked(is_default_date_column),
        display_order=display_order,
    )
    if error:
        return _portal_database_dataset_form_response(user, dataset=dataset, error=error, status_code=400)
    _portal_audit_event_safe(
        event_type="database_dataset_column_updated" if existing_column else "database_dataset_column_added",
        actor_user_id=str(user.get("user_id") or "") or None,
        client_code=str(dataset.get("client_code") or "") or None,
        dataset_id=dataset_id,
        request=request,
        metadata=_portal_database_audit_metadata(dataset, column_name=normalized_column, is_visible=_portal_form_checked(is_visible), is_filterable=_portal_form_checked(is_filterable), is_sortable=_portal_form_checked(is_sortable), is_default_date_column=_portal_form_checked(is_default_date_column)),
    )
    return _artifact_explorer_redirect(f"/admin/client-access/database/{dataset_id}")


