@app.post("/admin/report-folders/new")
def admin_portal_create_report_folder(
    request: Request,
    client_code: str = Form(...),
    folder_name: str = Form(...),
    slug: str = Form(...),
    description: Optional[str] = Form(None),
    is_active: Optional[str] = Form(None),
    can_preview: Optional[str] = Form(None),
    can_download: Optional[str] = Form(None),
    workflow_name: Optional[str] = Form(None),
    stage_name: Optional[str] = Form(None),
    artifact_role: Optional[str] = Form(None),
    report_type: Optional[str] = Form(None),
    file_ext: Optional[str] = Form(None),
    tag: Optional[str] = Form(None),
    search: Optional[str] = Form(None),
    date_from: Optional[str] = Form(None),
    date_to: Optional[str] = Form(None),
):
    user = _require_portal_admin(request)
    if isinstance(user, HTMLResponse):
        return user
    values = {
        "client_code": _normalize_portal_client_code(client_code),
        "folder_name": folder_name,
        "slug": str(slug or "").strip().lower(),
        "description": description,
        "is_active": _portal_form_checked(is_active),
        "can_preview": _portal_form_checked(can_preview),
        "can_download": _portal_form_checked(can_download),
    }
    try:
        filters = _portal_report_folder_search_from_form(
            workflow_name=workflow_name,
            stage_name=stage_name,
            artifact_role=artifact_role,
            report_type=report_type,
            file_ext=file_ext,
            tag=tag,
            search=search,
            date_from=date_from,
            date_to=date_to,
        )
        values["search_query_json"] = filters
        folder_id = _create_portal_report_folder(
            client_code=values["client_code"],
            folder_name=folder_name,
            slug=values["slug"],
            description=description,
            search_query_json=filters,
            is_active=values["is_active"],
            can_preview=values["can_preview"],
            can_download=values["can_download"],
            actor_user_id=str(user.get("user_id") or "") or None,
        )
    except ValueError as exc:
        values.setdefault("search_query_json", _smart_search_dict_from_form(
            workflow_name=workflow_name,
            stage_name=stage_name,
            artifact_role=artifact_role,
            report_type=report_type,
            file_ext=file_ext,
            tag=tag,
            search=search,
            date_from=date_from,
            date_to=date_to,
        ))
        return _portal_report_folder_form_response(user, values=values, error=str(exc), status_code=400)
    _portal_audit_event_safe(
        event_type="report_folder_created",
        actor_user_id=str(user.get("user_id") or "") or None,
        client_code=values["client_code"],
        report_folder_id=folder_id,
        request=request,
        metadata={"folder_id": folder_id, "folder_name": folder_name, "client_code": values["client_code"], "slug": values["slug"], "filter_keys": sorted(filters.keys())},
    )
    return _artifact_explorer_redirect(f"/admin/report-folders/{folder_id}")


