def _artifact_explorer_login_page(*, next_path: str = "/artifact-explorer", error: str | None = None) -> HTMLResponse:
    warning = ""
    if not _SESSION_SECRET_FROM_ENV:
        warning = _portal_error_state(
            "Development session secret",
            "ARTIFACT_EXPLORER_SESSION_SECRET is not set; sessions use a process-local development "
            "secret and will be invalidated on restart. Since S6 the same secret also derives "
            "Database Explorer row references, so every copied row= URL stops resolving after a "
            "restart too. Production deployment must supply a stable value.",
        )
    error_html = _portal_error_state("Login failed", error) if error else ""
    # Standalone document: it renders outside the shared shell, so it links the
    # same token/stylesheet layer directly instead of inheriting it.
    _portal_head_assets = portal_assets.head_asset_tags()
    body = f'''
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Artifact Explorer Login</title>
  {_portal_head_assets}
</head>
<body>
  <main class="portal-login-shell">
    <section class="portal-login-panel">
      <div class="portal-login-brand">Log Platform</div>
      <h1 class="portal-title">Sign in</h1>
      <p class="portal-subtitle">Sign in to the Log Platform. One account continues to the User Portal, the Admin Portal, or the technical Artifact Explorer module.</p>
      {warning}
      {error_html}
      <form class="portal-form" method="post" action="/login">
        <input type="hidden" name="next" value="{_html(next_path)}">
        <div class="portal-field"><label for="username">Username</label><input class="portal-input" id="username" name="username" type="text" autocomplete="username" required></div>
        <div class="portal-field"><label for="password">Password</label><input class="portal-input" id="password" name="password" type="password" autocomplete="current-password" required></div>
        <div class="portal-actions"><button class="portal-button portal-btn portal-btn-primary" type="submit">Log in</button></div>
      </form>
    </section>
  </main>
</body>
</html>'''
    return HTMLResponse(body)


@app.get("/artifact-explorer/login")
def artifact_explorer_login_page(
    request: Request,
    next: str = Query("/artifact-explorer"),
):
    user = get_current_artifact_user(request)
    safe_next = _safe_ui_next_path(next)
    if user:
        return _artifact_explorer_redirect(safe_next)
    return _artifact_explorer_login_page(next_path=safe_next)


def artifact_explorer_login(
    username: str,
    password: str,
    next: str = "/artifact-explorer",
    request: Request | None = None,
):
    safe_next = _safe_ui_next_path(next)
    user = authenticate_artifact_user(username, password)
    if not user:
        _portal_audit_event_safe(
            event_type="auth_login_failed",
            request=request,
            metadata={"username_attempted": _normalize_portal_username(username), "next": safe_next},
        )
        return _artifact_explorer_login_page(next_path=safe_next, error="Invalid username or password.")
    _portal_audit_event_safe(
        event_type="auth_login_success",
        actor_user_id=str(user.get("user_id") or "") or None,
        request=request,
        metadata={"username": user.get("username"), "next": safe_next},
    )
    return _artifact_explorer_redirect(safe_next, session_user_id=user["user_id"])


def _artifact_explorer_logout_response(request: Request | None = None):
    user = get_current_artifact_user(request) if request is not None else None
    _portal_audit_event_safe(
        event_type="auth_logout",
        actor_user_id=str((user or {}).get("user_id") or "") or None,
        request=request,
        metadata={"username": (user or {}).get("username")},
    )
    return _artifact_explorer_redirect("/artifact-explorer/login", clear_session=True)


def artifact_explorer_logout_get(request: Request | None = None):
    return _artifact_explorer_logout_response(request)


def artifact_explorer_logout_post(request: Request | None = None):
    return _artifact_explorer_logout_response(request)


