@app.post("/artifact-explorer/folders")
def artifact_explorer_create_folder(
    folder_name: str = Form(...),
    description: Optional[str] = Form(None),
    parent_folder_id: Optional[str] = Form(None),
    folder_type: str = Form("manual"),
    workflow_name: Optional[str] = Form(None),
    stage_name: Optional[str] = Form(None),
    artifact_role: Optional[str] = Form(None),
    report_type: Optional[str] = Form(None),
    client_code: Optional[str] = Form(None),
    file_ext: Optional[str] = Form(None),
    layout_version: Optional[str] = Form(None),
    tag: Optional[str] = Form(None),
    search: Optional[str] = Form(None),
    date_from: Optional[str] = Form(None),
    date_to: Optional[str] = Form(None),
    kind: Optional[str] = Form(None),
    content_type: Optional[str] = Form(None),
    request: Request = None,
):
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    if not user.get("is_admin"):
        return _artifact_explorer_forbidden("Only Artifact Explorer admins can manage virtual folders.")
    parent_id = str(parent_folder_id or "").strip() or None
    ft = str(folder_type or "manual").strip().lower()
    search_payload: Any = None
    if ft == "smart":
        search_payload = _validate_smart_folder_search_query(
            _smart_search_dict_from_form(
                workflow_name=workflow_name,
                stage_name=stage_name,
                artifact_role=artifact_role,
                report_type=report_type,
                client_code=client_code,
                file_ext=file_ext,
                layout_version=layout_version,
                tag=tag,
                search=search,
                date_from=date_from,
                date_to=date_to,
                kind=kind,
                content_type=content_type,
            )
        )
    folder = _create_virtual_folder(
        parent_folder_id=parent_id,
        folder_name=folder_name,
        description=description,
        folder_type=ft,
        search_query_json=search_payload,
        actor=_ui_write_actor(user),
    )
    return _artifact_explorer_redirect(f"/artifact-explorer/folders/{folder['folder_id']}")


@app.get("/artifact-explorer/folders/{folder_id}")
def artifact_explorer_folder_detail(
    folder_id: str,
    request: Request = None,
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    sort: str = Query("created_at_desc"),
):
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    effective_sort = sort if sort in ARTIFACT_BROWSER_SORTS else "created_at_desc"
    error_html = (
        f'<div class="notice error">Invalid sort {_html(sort)}; showing newest artifacts first.</div>'
        if effective_sort != sort
        else ""
    )
    detail = _get_virtual_folder_detail(
        folder_id,
        sort=effective_sort,
        limit=limit,
        offset=offset,
        user=user,
        action="view",
    )
    folder = detail["folder"]
    artifacts = detail["artifacts"]
    path = f"/artifact-explorer/folders/{_html(folder_id)}"
    base_params = {"limit": limit, "offset": offset, "sort": effective_sort}
    ft = folder.get("folder_type") or "manual"
    empty_msg = (
        "No visible artifacts match this smart folder's search criteria."
        if ft == "smart"
        else "No visible artifacts are assigned to this folder."
    )
    table_html = _artifact_explorer_artifacts_table(
        artifacts["data"],
        user=user,
        current_sort=effective_sort,
        base_params=base_params,
        path=path,
        empty_message=empty_msg,
    )
    meta = artifacts["meta"]
    prev_link = ""
    next_link = ""
    if offset > 0:
        prev_params = dict(base_params)
        prev_params["offset"] = max(0, offset - limit)
        prev_link = f'<a class="button secondary" href="{_artifact_explorer_url(path, prev_params)}">Previous</a>'
    if offset + limit < meta["total"]:
        next_params = dict(base_params)
        next_params["offset"] = offset + limit
        next_link = f'<a class="button secondary" href="{_artifact_explorer_url(path, next_params)}">Next</a>'
    pagination = (
        '<div class="pagination">'
        f'<div class="subtle">Showing {_html(meta["count"])} of {_html(meta["total"])} visible artifacts. Offset {_html(meta["offset"])}.</div>'
        f'<div class="toolbar">{prev_link}{next_link}</div>'
        "</div>"
    )
    admin_html = ""
    if user.get("is_admin"):
        parent_id = folder.get("parent_folder_id")
        delete_target = f"/artifact-explorer/folders/{_html(parent_id)}" if parent_id else "/artifact-explorer/folders"
        smart_manage = ""
        if ft == "smart":
            smart_manage = (
                '<div class="notice" style="margin-top:12px;">Smart folder contents are generated from search criteria. '
                "Files are not physically moved or copied.</div>"
                '<p class="subtle" style="margin-top:10px;">Saved criteria (read-only snapshot):</p>'
                f'<pre style="white-space:pre-wrap;">{_html(_smart_criteria_preview_for_display(folder.get("search_query_json") or {}))}</pre>'
                + _artifact_explorer_smart_criteria_fields_html("edit", folder.get("search_query_json") or {})
            )
        admin_html = f'''
<section class="panel">
  <h2>Manage folder</h2>
  <form method="post" action="/artifact-explorer/folders/{_html(folder_id)}/metadata">
    <label for="folder_name_edit">Folder name</label>
    <input id="folder_name_edit" name="folder_name" type="text" value="{_html(folder.get("folder_name"))}" required>
    <label for="folder_description_edit" style="margin-top:10px;">Description</label>
    <textarea id="folder_description_edit" name="description">{_html(folder.get("description") or "")}</textarea>
    {smart_manage}
    <div class="toolbar" style="margin-top:10px;"><button type="submit">Save folder</button></div>
  </form>
  <form method="post" action="/artifact-explorer/folders/{_html(folder_id)}/delete" style="margin-top:14px;">
    <input type="hidden" name="redirect_to" value="{_html(delete_target)}">
    <button class="secondary" type="submit">Delete folder association tree only</button>
    <p class="subtle">Deleting this virtual folder removes child folder records and manual folder memberships only. It does not delete artifacts or MinIO objects.</p>
  </form>
</section>''' + _artifact_explorer_folder_create_form(folder_id)
    type_line = (
        '<p class="subtle">Type: <strong>Smart folder</strong> (saved search / dynamic contents).</p>'
        if ft == "smart"
        else '<p class="subtle">Type: <strong>Manual folder</strong> (explicit artifact assignments).</p>'
    )
    body = (
        '<div class="panel">'
        + _artifact_explorer_folder_breadcrumbs_html(detail["breadcrumbs"])
        + f'<h2>{_html(folder["folder_name"])}</h2>'
        + type_line
        + (f'<p>{_html(folder.get("description"))}</p>' if folder.get("description") else '<p class="subtle">No description.</p>')
        + '<p class="subtle">Folder records are metadata only; artifact storage keys are unchanged.</p>'
        + "</div>"
        + error_html
        + '<section class="panel"><h2>Child folders</h2>'
        + _artifact_explorer_folder_list_html(detail["child_folders"])
        + "</section>"
        + '<section class="panel"><h2>Artifacts</h2></section>'
        + _artifact_explorer_export_bar(
            export_path=f"/artifact-explorer/folders/{quote(str(folder_id), safe='')}/export",
            params={"sort": effective_sort},
            total=meta["total"],
        )
        + table_html
        + pagination
        + admin_html
    )
    return _artifact_explorer_layout(
        f"Folder {folder['folder_name']}",
        body,
        user=user,
        active_key="artifact-folders",
    )


@app.post("/artifact-explorer/folders/{folder_id}/metadata")
def artifact_explorer_update_folder(
    folder_id: str,
    folder_name: str = Form(...),
    description: Optional[str] = Form(None),
    workflow_name: Optional[str] = Form(None),
    stage_name: Optional[str] = Form(None),
    artifact_role: Optional[str] = Form(None),
    report_type: Optional[str] = Form(None),
    client_code: Optional[str] = Form(None),
    file_ext: Optional[str] = Form(None),
    layout_version: Optional[str] = Form(None),
    tag: Optional[str] = Form(None),
    search: Optional[str] = Form(None),
    date_from: Optional[str] = Form(None),
    date_to: Optional[str] = Form(None),
    kind: Optional[str] = Form(None),
    content_type: Optional[str] = Form(None),
    request: Request = None,
):
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    if not user.get("is_admin"):
        return _artifact_explorer_forbidden("Only Artifact Explorer admins can manage virtual folders.")
    current = _require_virtual_folder(folder_id)
    if current.get("folder_type") == "smart":
        validated = _validate_smart_folder_search_query(
            _smart_search_dict_from_form(
                workflow_name=workflow_name,
                stage_name=stage_name,
                artifact_role=artifact_role,
                report_type=report_type,
                client_code=client_code,
                file_ext=file_ext,
                layout_version=layout_version,
                tag=tag,
                search=search,
                date_from=date_from,
                date_to=date_to,
                kind=kind,
                content_type=content_type,
            )
        )
        _update_virtual_folder(
            folder_id,
            folder_name=folder_name,
            description=description,
            search_query_json=validated,
            actor=_ui_write_actor(user),
        )
    else:
        _update_virtual_folder(
            folder_id,
            folder_name=folder_name,
            description=description,
            actor=_ui_write_actor(user),
        )
    return _artifact_explorer_redirect(f"/artifact-explorer/folders/{folder_id}")


