@app.get("/artifact-explorer")
def artifact_explorer_index(
    request: Request = None,
    workflow_name: Optional[List[str]] = Query(None),
    stage_name: Optional[List[str]] = Query(None),
    artifact_role: Optional[List[str]] = Query(None),
    report_type: Optional[List[str]] = Query(None),
    original_filename: Optional[List[str]] = Query(None),
    display_filename: Optional[List[str]] = Query(None),
    file_ext: Optional[List[str]] = Query(None),
    client_code: Optional[List[str]] = Query(None),
    kind: Optional[List[str]] = Query(None),
    tag: Optional[List[str]] = Query(None),
    search: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    layout_version: Optional[List[str]] = Query(None),
    run_id: Optional[str] = None,
    raw_file_id: Optional[str] = None,
    workflow_name_search: Optional[str] = None,
    stage_name_search: Optional[str] = None,
    artifact_role_search: Optional[str] = None,
    report_type_search: Optional[str] = None,
    original_filename_search: Optional[str] = None,
    display_filename_search: Optional[str] = None,
    file_ext_search: Optional[str] = None,
    client_code_search: Optional[str] = None,
    kind_search: Optional[str] = None,
    tag_search: Optional[str] = None,
    layout_version_search: Optional[str] = None,
    run_id_search: Optional[str] = None,
    raw_file_id_search: Optional[str] = None,
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    sort: str = Query("created_at_desc"),
):
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    values = {
        "workflow_name": workflow_name,
        "stage_name": stage_name,
        "artifact_role": artifact_role,
        "report_type": report_type,
        "original_filename": original_filename,
        "display_filename": display_filename,
        "file_ext": file_ext,
        "client_code": client_code,
        "kind": kind,
        "tag": tag,
        "search": search,
        "date_from": date_from,
        "date_to": date_to,
        "layout_version": layout_version,
        "run_id": run_id,
        "raw_file_id": raw_file_id,
        "workflow_name_search": workflow_name_search,
        "stage_name_search": stage_name_search,
        "artifact_role_search": artifact_role_search,
        "report_type_search": report_type_search,
        "original_filename_search": original_filename_search,
        "display_filename_search": display_filename_search,
        "file_ext_search": file_ext_search,
        "client_code_search": client_code_search,
        "kind_search": kind_search,
        "tag_search": tag_search,
        "layout_version_search": layout_version_search,
        "run_id_search": run_id_search,
        "raw_file_id_search": raw_file_id_search,
        "limit": limit,
        "sort": sort,
    }
    error_html = ""
    facets = _get_artifact_browser_facets(user=user, action="view")
    effective_sort = sort
    if effective_sort not in ARTIFACT_BROWSER_SORTS:
        error_html = f'<div class="notice error">Invalid sort {_html(effective_sort)}; showing newest artifacts first.</div>'
        effective_sort = "created_at_desc"
        values["sort"] = effective_sort
    try:
        result = _list_artifact_browser_items(
            filters=_artifact_explorer_filters_from_values(values),
            sort=effective_sort,
            limit=limit,
            offset=offset,
            user=user,
            action="view",
        )
    except ValueError:
        result = {"data": [], "meta": {"limit": limit, "offset": offset, "count": 0, "total": 0}}
        error_html = '<div class="notice error">date_from/date_to must be ISO 8601 timestamps.</div>'

    base_params = {key: values.get(key) for key in ARTIFACT_EXPLORER_FILTER_FIELDS}
    for key in ARTIFACT_EXPLORER_SEARCH_PARAM_FIELDS:
        base_params[key] = values.get(key)
    base_params["limit"] = limit
    base_params["offset"] = offset
    base_params["sort"] = effective_sort

    table_html = _artifact_explorer_artifacts_table(
        result["data"],
        user=user,
        current_sort=effective_sort,
        base_params=base_params,
    )

    meta = result["meta"]
    prev_offset = max(0, offset - limit)
    next_offset = offset + limit
    prev_link = ""
    next_link = ""
    if offset > 0:
        prev_params = dict(base_params)
        prev_params["offset"] = prev_offset
        prev_link = f'<a class="button secondary" href="{_artifact_explorer_url("/artifact-explorer", prev_params)}">Previous</a>'
    if next_offset < meta["total"]:
        next_params = dict(base_params)
        next_params["offset"] = next_offset
        next_link = f'<a class="button secondary" href="{_artifact_explorer_url("/artifact-explorer", next_params)}">Next</a>'
    pagination = (
        '<div class="pagination">'
        f'<div class="subtle">Showing {_html(meta["count"])} of {_html(meta["total"])} artifacts. Offset {_html(meta["offset"])}.</div>'
        f'<div class="toolbar">{prev_link}{next_link}</div>'
        "</div>"
    )

    # `ART-001`: the kind rail is the module's own left navigation, next to the
    # table rather than above it. Its counts are resolved through the same
    # view-permission predicate as the rows, so it lists exactly the kinds this
    # account can actually browse and nothing else.
    rail_html = _artifact_explorer_kind_rail_html(
        _get_artifact_kind_counts(user=user, action="view"),
        base_params=base_params,
        active_kind=_artifact_explorer_active_kind(values),
    )
    body = (
        '<div class="art-catalogue">'
        + rail_html
        + '<div class="art-main">'
        + error_html
        + _artifact_explorer_filter_inputs(values, facets)
        + _artifact_explorer_export_bar(
            export_path="/artifact-explorer/export",
            params=base_params,
            total=meta["total"],
        )
        + table_html
        + pagination
        + "</div></div>"
    )
    return _artifact_explorer_layout(
        _tr("art.page.title"),
        body,
        user=user,
        active_key="files",
        # The context bar already carries `Artefakty` and the approved subtitle;
        # repeating them as an in-page title and description above the rail
        # would be the duplicate page chrome the approved hierarchy removes. The
        # `h1` remains, visually hidden, so the document still has one.
        content_class="lp-work-flush",
        header_actions=_artifact_explorer_refresh_action(
            _artifact_explorer_url("/artifact-explorer", base_params)
        ),
    )


def _artifact_explorer_detail_response(
    artifact_id: str,
    *,
    user: dict | None = None,
    error_message: str | None = None,
    success_message: str | None = None,
) -> HTMLResponse:
    user = user or _artifact_explorer_system_admin_user()
    row = _get_artifact_browser_row(artifact_id)
    if not row:
        raise HTTPException(status_code=404, detail="artifact not found")

    artifact = _artifact_browser_row(row)
    if not user_can_access_artifact(user, artifact, "view"):
        raise HTTPException(status_code=403, detail="artifact access denied")
    run = _get_run_summary(artifact.get("run_id"))
    raw_file = _get_raw_file_summary(artifact.get("raw_file_id"))
    virtual_folders = _get_artifact_virtual_folders(artifact_id)
    can_preview = user_can_access_artifact(user, artifact, "preview")
    can_download = user_can_access_artifact(user, artifact, "download")
    can_edit = user_can_access_artifact(user, artifact, "edit_annotations")
    preview = _artifact_explorer_preview_for_row(row, dict(artifact)) if can_preview else None

    download_url = f"/artifact-explorer/artifacts/{_html(artifact_id)}/download"
    download_button = f'<a class="button" href="{download_url}">Download</a>' if can_download else ""
    preview_button = '<a class="button secondary" href="#preview">Preview</a>' if can_preview else ""
    edit_button = '<a class="button secondary" href="#manual-metadata">Edit metadata</a>' if can_edit else ""
    metadata_items = [
        ("artifact_id", artifact.get("artifact_id")),
        ("created_at", artifact.get("created_at")),
        ("kind", artifact.get("kind")),
        ("workflow_name", artifact.get("workflow_name")),
        ("stage_name", artifact.get("stage_name")),
        ("artifact_role", artifact.get("artifact_role")),
        ("report_type", artifact.get("report_type")),
        ("client_code", artifact.get("client_code")),
        ("layout_version", _artifact_layout_label(artifact.get("layout_version"))),
        ("filename", artifact.get("filename")),
        ("display_filename", artifact.get("display_filename")),
        ("original_filename", artifact.get("original_filename")),
        ("file_ext", artifact.get("file_ext")),
        ("content_type", artifact.get("content_type")),
        ("size_bytes", artifact.get("size_bytes")),
        ("sha256", artifact.get("sha256")),
        ("bucket_name", artifact.get("bucket_name")),
        ("storage_key", artifact.get("storage_key")),
        ("run_id", artifact.get("run_id")),
        ("raw_file_id", artifact.get("raw_file_id")),
        ("system metadata_json", artifact.get("metadata_json")),
        ("owner_user_id", artifact.get("owner_user_id")),
        ("expires_at", artifact.get("expires_at")),
        ("expired_at", artifact.get("expired_at")),
        ("manual description", artifact.get("description")),
        ("manual metadata_json", artifact.get("manual_metadata_json")),
        ("tags", artifact.get("tags")),
    ]
    run_html = _artifact_explorer_kv_table(list((run or {}).items())) if run else '<div class="notice">No run summary is available for this artifact.</div>'
    raw_file_html = _artifact_explorer_kv_table(list((raw_file or {}).items())) if raw_file else '<div class="notice">No raw file summary is available for this artifact.</div>'

    body = (
        '<div class="toolbar panel">'
        '<a class="button secondary" href="/artifact-explorer">Back to list</a>'
        + download_button
        + preview_button
        + edit_button
        + "</div>"
        + '<div class="grid-2">'
        + '<section class="panel"><h2>Artifact Metadata</h2>'
        + _artifact_explorer_kv_table(metadata_items)
        + "</section>"
        + '<section class="panel"><h2>Lineage</h2><h3>Run</h3>'
        + run_html
        + '<h3 style="margin-top:16px;">Raw file</h3>'
        + raw_file_html
        + "</section>"
        "</div>"
        + _artifact_explorer_folder_membership_html(
            artifact_id,
            folders=virtual_folders,
            can_manage=bool(user.get("is_admin")),
        )
        + '<section id="manual-metadata">'
        + _artifact_explorer_annotation_forms(
            artifact,
            editable=can_edit,
            error_message=error_message,
            success_message=success_message,
        )
        + "</section>"
        + '<section id="preview" class="panel"><h2>Preview</h2>'
        + (_artifact_explorer_render_preview(preview, artifact_id=artifact_id, can_download=can_download) if preview else _artifact_explorer_preview_denied_html())
        + "</section>"
    )
    return _artifact_explorer_layout(
        f"Artifact {artifact_id}",
        body,
        user=user,
        active_key="files",
    )


@app.get("/artifact-explorer/export")
def artifact_explorer_export(
    request: Request = None,
    format: str = Query("xlsx"),
    sort: str = Query("created_at_desc"),
):
    """The `ART-001` catalogue as a spreadsheet, at the current filtration.

    It re-runs the table's own query — same filters, same validated sort, same
    `action="view"` permission predicate — and replaces pagination with the
    export ceiling. It reads no parameter the list route does not already
    declare, so a link the table wrote cannot ask for rows the table would not
    have shown.
    """
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    format_name = _artifact_explorer_export_format(format)
    effective_sort = sort if sort in ARTIFACT_BROWSER_SORTS else "created_at_desc"
    values = _artifact_explorer_values_from_request(request)
    try:
        filters = _artifact_explorer_filters_from_values(values)
    except ValueError:
        raise HTTPException(status_code=400, detail="date_from/date_to must be ISO 8601 timestamps")

    def fetch_page(offset: int, limit: int) -> dict:
        return _list_artifact_browser_items(
            filters=filters,
            sort=effective_sort,
            limit=limit,
            offset=offset,
            user=user,
            action="view",
        )

    artifacts, total = _artifact_explorer_collect_export_rows(fetch_page)
    if total > ARTIFACT_EXPLORER_MAX_EXPORT_ROWS:
        return _artifact_explorer_export_too_many_response(user, total)
    return _artifact_explorer_export_response(artifacts, format_name=format_name, stem="katalog")


@app.get("/artifact-explorer/folders/{folder_id}/export")
def artifact_explorer_folder_export(
    folder_id: str,
    request: Request = None,
    format: str = Query("xlsx"),
    sort: str = Query("created_at_desc"),
):
    """The same export for a virtual folder's table.

    Manual and smart folders take the branch `_get_virtual_folder_detail` takes,
    so a smart folder exports what its saved criteria currently resolve to —
    the same rows its page is showing — and never a stored snapshot of them.
    """
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    format_name = _artifact_explorer_export_format(format)
    effective_sort = sort if sort in ARTIFACT_BROWSER_SORTS else "created_at_desc"
    folder = _require_virtual_folder(folder_id)
    list_artifacts = (
        _list_smart_folder_artifacts
        if folder.get("folder_type") == "smart"
        else _list_folder_artifacts
    )

    def fetch_page(offset: int, limit: int) -> dict:
        return list_artifacts(
            folder_id,
            sort=effective_sort,
            limit=limit,
            offset=offset,
            user=user,
            action="view",
        )

    artifacts, total = _artifact_explorer_collect_export_rows(fetch_page)
    if total > ARTIFACT_EXPLORER_MAX_EXPORT_ROWS:
        return _artifact_explorer_export_too_many_response(user, total)
    return _artifact_explorer_export_response(
        artifacts, format_name=format_name, stem=str(folder.get("folder_name") or "folder")
    )


