@app.post("/artifact-explorer/artifacts/{artifact_id}/metadata")
def artifact_explorer_update_metadata(
    artifact_id: str,
    description: Optional[str] = Form(None),
    metadata_json: str = Form("{}"),
    request: Request = None,
):
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    row = _get_artifact_browser_row(artifact_id)
    if not row:
        raise HTTPException(status_code=404, detail="artifact not found")
    artifact = _artifact_browser_row(row)
    if not user_can_access_artifact(user, artifact, "edit_annotations"):
        raise HTTPException(status_code=403, detail="annotation edit access denied")
    try:
        parsed_metadata = json.loads(metadata_json or "{}")
        _upsert_artifact_metadata_override(
            artifact_id,
            description=description,
            metadata_json=_validate_manual_metadata(parsed_metadata),
            actor=_ui_write_actor(user),
        )
    except json.JSONDecodeError as exc:
        return _artifact_explorer_detail_response(
            artifact_id,
            user=user,
            error_message=f"Manual metadata JSON is invalid: {exc.msg}",
        )
    except HTTPException as exc:
        if exc.status_code == 400:
            return _artifact_explorer_detail_response(artifact_id, user=user, error_message=str(exc.detail))
        raise
    return _artifact_explorer_detail_response(artifact_id, user=user, success_message="Manual metadata saved.")


