@app.get("/artifact-explorer/artifacts/{artifact_id}/download")
def artifact_explorer_download_artifact(
    artifact_id: str,
    request: Request = None,
    disposition: str = Query("attachment"),
):
    user = _artifact_explorer_user_for_route(request)
    if isinstance(user, HTMLResponse):
        return user
    if disposition not in {"attachment", "inline"}:
        raise HTTPException(status_code=400, detail="disposition must be attachment or inline")
    row = _get_artifact_browser_row(artifact_id)
    if not row:
        raise HTTPException(status_code=404, detail="artifact not found")
    artifact = _artifact_browser_row(row)
    if not user_can_access_artifact(user, artifact, "download"):
        raise HTTPException(status_code=403, detail="download access denied")
    return _stream_artifact_download(row, disposition=disposition)


@app.get("/artifacts/{artifact_id}/download")
def download_artifact(
    artifact_id: str,
    authorization: str | None = Header(default=None),
    disposition: str = Query("attachment"),
):
    require_token(authorization, "read")
    if disposition not in {"attachment", "inline"}:
        raise HTTPException(status_code=400, detail="disposition must be attachment or inline")

    row = _get_artifact_browser_row(artifact_id)
    if not row:
        raise HTTPException(status_code=404, detail="artifact not found")
    return _stream_artifact_download(row, disposition=disposition)

@app.post("/maintenance/prune")
def maintenance_prune(
    authorization: str | None = Header(default=None),
    days: int = Query(60, ge=1, le=3650),
    dry_run: bool = Query(True),
):
    """Plans platform retention safely. Destructive execution is host-coordinated only."""
    require_token(authorization, "write")
    if not dry_run:
        raise HTTPException(
            status_code=409,
            detail="PRUNE_API_EXECUTION_DISABLED_USE_COORDINATED_HOST_COMMAND",
        )
    try:
        identity = load_runtime_identity()
        return run_prune(
            connection_factory=db_conn,
            s3_client=s3,
            bucket=MINIO_BUCKET,
            identity=identity,
            retention_days=days,
            dry_run=True,
        )
    except PlatformPruneError as exc:
        status_code = 423 if exc.code == "PRUNE_LOCKED" else 503
        raise HTTPException(status_code=status_code, detail=exc.code) from exc


